import { Input, Messages } from "ros";
import {
  getPathPrimitivesDebug,
  GlobalVariables,
  createDeleteCurrentTopicMarkers,
} from "@ares-utils";

export const inputs = ["/planning/planning_debug"];
export const output =
  "/studio_node/planning/path_generator/primitives/path_smoother/ray_casted_results/physical_ray_casted_points";

export const publisher = (
  messages: Record<string, Input<"/planning/planning_debug">>,
  globalVars: GlobalVariables,
): Messages.ares__VisualizationMarkerArray | undefined => {
  const message = messages[
    "/planning/planning_debug"
  ] as Input<"/planning/planning_debug">;
  if (!message) {
    return {
      markers: [],
    };
  }

  const {
    message: { behaviorReasonerDebug, pose },
    receiveTime,
  } = message;

  const pathPrimitivesDebug = getPathPrimitivesDebug(
    behaviorReasonerDebug as any,
    globalVars,
  );
  if (!pathPrimitivesDebug) {
    return {
      markers: [],
    };
  }

  const leftSegments =
    (
      pathPrimitivesDebug as unknown as Messages.planner__pb__DecoupledPathPrimitives
    ).pathBoundaryPrimitive?.semanticCorridor?.leftSegments?.physicalSegments ??
    [];
  const rightSegments =
    (
      pathPrimitivesDebug as unknown as Messages.planner__pb__DecoupledPathPrimitives
    ).pathBoundaryPrimitive?.semanticCorridor?.rightSegments
      ?.physicalSegments ?? [];

  const allSegments = [...leftSegments, ...rightSegments];

  if (allSegments.length === 0 || !pose) {
    return {
      markers: [],
    };
  }

  const markers: Messages.ares__VisualizationMarker[] = [
    createDeleteCurrentTopicMarkers(receiveTime),
  ];

  const rayCastingMarkers: Messages.ares__VisualizationMarker = {
    header: {
      frame_id: "world",
      seq: 0,
      stamp: receiveTime,
    },
    type: Messages.ares__VisualizationMarkerTypes.POINTS,
    id: `physical_ray_casted_points`,
    pose: {
      position: { x: 0, y: 0, z: 0 }, // 世界坐标系原点
    },
    points: allSegments.flatMap((segment) =>
      (segment.boundaryRayCastedPoints ?? []).map((ray_point) => {
        return {
          x: ray_point.x,
          y: ray_point.y,
          z: pose.z + 1,
        };
      }),
    ),
    color: {
      r: 1.0, // Red
      g: 0, // Green
      b: 1.0, // Blue
      a: 1, // 透明
    },
    pointMetadata: {
      radius: 2,
    },
  };

  markers.push(rayCastingMarkers);

  return {
    markers,
  };
};

export default publisher;

