/* eslint-disable @typescript-eslint/no-unnecessary-condition */
/* ares-expose-source-code */
import {
  GlobalVariables,
  DEFAULT_STUDIO_NODE_PREFIX,
  getTrajectoryMetaDebug,
} from "@ares-utils";
import { Input, Messages } from "@vitruvian/voyager-type";
import { concat, forEach } from "lodash";

export const inputs = ["/planning/planning_debug"];
export const config = {
  datatype: "voyager_data_msgs/CustomData",
  showOn3DPanel: false,
};
export const output = `${DEFAULT_STUDIO_NODE_PREFIX}planning/planning_data_transfer`;

/**
 * TODO 因为目前对offboard中conf配置文件的使用流程信息较少，用户方也不清楚，临时将配置数据直接copy过来，这个数据变化频率比较低，
 * 之后会结合所有团队的使用，设计一套pb格式conf配置文件的引入流程
 */
const trajectory_selection_config_weights = {
  speed_discomfort: 1.0,
  progress: 1.0,
  progress_efficiency: 1.0,
  routing: 1.0,
  lane_seq_flicker: 1.0,
  stuck_potential: 1.0,
  path_diff: 1.255,
  speed_diff: 0.2,
  lateral_discomfort: 1.5,
  short_path_cost: 2.0,
  longitudinal_discomfort: 0.2,
  last_path_cost: 1.0,
  collision_risk: 1.0,
  human_likeness_cost: 1.0,
  geometry_lane_marking: 1.0,
  geometry_hard_boundary: 1.0,
};

type ManeuverInfo = {
  type: Messages.planner__pb__ManeuverType;
  maneuverTransitionCheckPassed: boolean;
  runnableStatus: Messages.planner__pb__ManeuverRunnableStatus;
  evaluatePassed: string;
};

const candidateCostKeys: (keyof Messages.planner__pb__TrajectoryMetaDebug)[] = [
  "overallCost",
  "normalizedPathDiff",
  "laneSeqFlickerCost",
  "speedDiscomfort",
  "lateralDiscomfort",
  "longitudinalDiscomfort",
  "shortPathCost",
  "lastPathCost",
  "collisionRisk",
  "progressCost",
  "stuckPotential",
  "normalizedRoutingCost",
  "progressEfficiencyCost",
  "arrivalTime",
  "pathDiff",
  "routingCost",
  "progressInM",
  "isHomotopyFlickering",
  "unsafeReason",
  "humanLikenessCost",
  "humanLikenessScore",
  "humanLikenessRisk",
  "humanLikenessComfort",
  "humanLikenessProgress",
  "geometryLaneMarkingCost",
  "geometryCrossMarkingDist",
  "geometryCrossMarkingCnt",
  "geometryHardBoundaryCost",
  "geometryHardBoundaryDist",
];

export const publisher = (
  messages: Record<string, Input<"/planning/planning_debug">>,
  globalVariable: GlobalVariables,
): Messages.voyager_data_msgs__CustomData => {
  const planningDebugMessage = messages[
    "/planning/planning_debug"
  ] as Input<"/planning/planning_debug">;
  if (!planningDebugMessage) {
    return {};
  }

  const { behaviorReasonerDebug } = planningDebugMessage.message;
  const { maneuvers: oldManeuvers = [], decoupledManeuvers = [] } =
    behaviorReasonerDebug ?? {};
  const laneSequenceIndex =
    globalVariable.planning_lane_sequence_indexes as unknown as number;

  const trajectoryMetaDebug = getTrajectoryMetaDebug(
    behaviorReasonerDebug,
    globalVariable,
  );
  const trajectorySelectionDebug =
    decoupledManeuvers[0]?.trajectorySelectionDebug;

  const maneuvers: ManeuverInfo[] =
    concat(
      oldManeuvers.map((maneuver) => {
        return {
          type: maneuver.type,
          maneuverTransitionCheckPassed: maneuver.maneuverTransitionCheckPassed,
          runnableStatus: maneuver.runnableStatus,
          evaluatePassed: maneuver.evaluatePassed ? "Feasible" : "Not Feasible",
        };
      }),
      decoupledManeuvers.map((maneuver) => {
        return {
          type: maneuver.type,
          maneuverTransitionCheckPassed: false,
          runnableStatus: maneuver.runnableStatus,
          evaluatePassed: "Not Feasible",
        };
      }),
    ) ?? [];

  const singleIntentionPlanDebug =
    decoupledManeuvers[0]?.singleLaneSequencePlanDebug[laneSequenceIndex]
      ?.singleIntentionPlanDebug;

  const lastSelectorInfo = {
    "Last ManeuverType": trajectorySelectionDebug?.lastManeuverType,
    "Last IntentHomotopy": trajectorySelectionDebug?.lastIntentHomotopy,
  };

  let candidateCostData: Record<string, unknown>[] = [];
  candidateCostData = [
    { name: "SelectionScenarioType", Weight: "" },
    { name: "Cost:OverallCost", Weight: "" },
    {
