      Weight: trajectory_selection_config_weights.lateral_discomfort,
    },
    {
      name: "Cost:DiscomfortLongitudinal",
      Weight: trajectory_selection_config_weights.longitudinal_discomfort,
    },
    {
      name: "Cost:RiskShortPath",
      Weight: trajectory_selection_config_weights.short_path_cost,
    },
    {
      name: "Cost:LastPath",
      Weight: trajectory_selection_config_weights.last_path_cost,
    },
    {
      name: "Cost:RiskCollision",
      Weight: trajectory_selection_config_weights.collision_risk,
    },
    {
      name: "Cost:ProgressImmediate",
      Weight: trajectory_selection_config_weights.progress,
    },
    {
      name: "Cost:ProgressStuck",
      Weight: trajectory_selection_config_weights.stuck_potential,
    },
    {
      name: "Cost:ProgressRouting",
      Weight: trajectory_selection_config_weights.routing,
    },
    {
      name: "Cost:ProgressEfficiency",
      Weight: trajectory_selection_config_weights.progress_efficiency,
    },
    { name: "Cost:ArrivedTime", Weight: "" },
    { name: "PathDiff", Weight: "" },
    { name: "RoutingCost", Weight: "" },
    { name: "ProgressInM", Weight: "" },
    { name: "IsHomotopyFlickering", Weight: "" },
    { name: "Unsafe Reason", Weight: "" },
    {
      name: "Cost:HumanLikeness",
      Weight: trajectory_selection_config_weights.human_likeness_cost,
    },
    { name: "MLScore", Weight: "" },
    { name: "MLRisk", Weight: "" },
    { name: "MLComfort", Weight: "" },
    { name: "MLProgress", Weight: "" },
    {
      name: "Cost:GeometryLaneMarking",
      Weight: trajectory_selection_config_weights.geometry_lane_marking,
    },
    { name: "GeometryCrossMarkingDist", Weight: "" },
    { name: "GeometryCrossMarkingCnt", Weight: "" },
