  forEach(sortedTrajectoryMetaDebugs, (trajectory) => {
    if (!jumpOutCandidate && trajectory.isPullOutJumpOut) {
      jumpOutCandidate = trajectory;
    }
    const label = `${trajectory.label ? trajectory.label : trajectory.trajectoryType}${
      trajectory.isSelected ? "(Selected)" : ""
