function getPullOutDebugInfo(
  pullOutDebug?: Messages.planner__pb__PullOutJumpOutCostAdjustmentDebug,
  candidateInfo?: Messages.planner__pb__TrajectoryMetaDebug,
) {
  if (pullOutDebug && candidateInfo) {
    const speedDecay = pullOutDebug.progressRewardFactorWithSpeedDecay;
    const doesPullOutJumpOutHaveProgressAdvantage =
      pullOutDebug.pullOutJumpOutHaveProgressAdvantageDebug
        .doesPullOutJumpOutHaveProgressAdvantage;
    // 决策计算过程
    const progressCostAdjustment =
      (doesPullOutJumpOutHaveProgressAdvantage
        ? `${candidateInfo.progressCost / speedDecay} x ${speedDecay} = `
        : "") + String(candidateInfo.progressCost);
    const lateralDiscomfortCostAdjustment =
      (doesPullOutJumpOutHaveProgressAdvantage
        ? `${candidateInfo.lateralDiscomfort / speedDecay} x ${speedDecay} = `
        : "") + String(candidateInfo.lateralDiscomfort);
    const laneSeqFlickerCostGain = pullOutDebug.laneSeqFlickerCostGain;
    const laneSeqFlickerCostAdjustment =
      (!doesPullOutJumpOutHaveProgressAdvantage
        ? `${
            candidateInfo.laneSeqFlickerCost - laneSeqFlickerCostGain
          } + ${laneSeqFlickerCostGain} = `
        : "") + String(candidateInfo.laneSeqFlickerCost);
    const overAllCost = candidateInfo.overallCost;
    return {
      overAllCost,
      progressCostAdjustment,
      lateralDiscomfortCostAdjustment,
      laneSeqFlickerCostAdjustment,
    };
  }
  return undefined;
}

function getTrajectoryTypeLabel(
  trajectory_meta_debug: Messages.planner__pb__TrajectoryMetaDebug,
) {
  let trajectory_label = "";
  // Using short name for visual space is not enough.
  switch (trajectory_meta_debug.trajectoryType) {
    case "NOMINAL_TRAJECTORY":
      break;
    case "LAST_TRAJECTORY":
      trajectory_label += "LAST_";
      break;
    case "BACKUP_TRAJECTORY":
      trajectory_label += "BACKUP_";
      break;
    case "ML_TRAJECTORY":
      trajectory_label += "ML_BACKUP_";
      break;
    default:
      break;
  }

  switch (trajectory_meta_debug.laneSeqType) {
    case "LANE_FOLLOW":
    case "ALTERNATIVE_LANE_FOLLOW":
      trajectory_label += "LF";
      break;
    case "LANE_CHANGE":
    case "IMMEDIATE_LEFT_LANE_CHANGE":
    case "IMMEDIATE_RIGHT_LANE_CHANGE":
      trajectory_label += "LC";
      break;
    default:
      break;
  }
  trajectory_label += `${trajectory_meta_debug.laneSeqIx}_`;
  switch (trajectory_meta_debug.intentHomotopy) {
    case "IGNORE_ALL":
      trajectory_label += "IGNORE";
      break;
    case "PASS_FROM_LEFT":
      trajectory_label += "LEFT";
      break;
    case "PASS_FROM_RIGHT":
      trajectory_label += "RIGHT";
      break;
    case "PASS_THROUGH":
      trajectory_label += "THROUGH";
      break;
    case "XLANE_PASS_FROM_LEFT":
      trajectory_label += "XLANE_LEFT";
      break;
    case "XLANE_PASS_FROM_RIGHT":
      trajectory_label += "XLANE_RIGHT";
      break;
    default:
      break;
  }
  if (trajectory_meta_debug.isSelected) {
    trajectory_label += "[Selected]";
  }
  return trajectory_label;
}

function GetScenarioTypeString(
  scenarioType: Messages.planner__pb__SelectionScenarioType,
): string {
  if (!scenarioType) {
    return "UNKNOW";
  }
  switch (scenarioType) {
    case "SCENARIO_NORMAL":
      return "Normal";
    case "SCENARIO_UNSTUCK":
      return "Unstuck";
    case "SCENARIO_FORK_SELECTION":
      return "ForkSelection";
    case "SCENARIO_LANE_CHANGE":
      return "LaneChange";
    case "SCENARIO_PULL_OVER":
      return "PullOver";
    case "SCENARIO_PULL_OUT":
      return "PullOut";
    // https://kunpeng.xiaojukeji.com/view/revision/3896501
    case "SCENARIO_OPEN_SPACE":
      return "OpenSpace";
    default:
      return "UNKNOW";
  }
}

export function getFeatureDebug(
  trajectorySelectionDebug:
    | Messages.planner__pb__TrajectorySelectionDebug
    | undefined,
  trajectoryMetaDebug: Messages.planner__pb__TrajectoryMetaDebug | undefined,
): Record<string, unknown> {
  const featureDebug = {
    LateralDiscomfort: trajectoryMetaDebug?.lateralDiscomfort,
    LongitudinalDiscomfort: trajectoryMetaDebug?.longitudinalDiscomfort,
    Flicker: {
      raw_path_diff: trajectoryMetaDebug?.pathDiff,
      path_diff_adjust: trajectoryMetaDebug?.pathDiffAdjust,
      cross_lane_debug_str: (trajectoryMetaDebug as any)?.flickerDebugStr,
    },
    StuckPotential: {
      "blockage type": trajectoryMetaDebug?.blockageType,
      "blockage id": trajectoryMetaDebug?.blockageId,
      "effective blockage cycles": trajectoryMetaDebug?.effectiveBlockedCycles,
    },
    CollisionRisk: {
      "pose id of max risk": trajectoryMetaDebug?.maxRiskPoseIx,
      "agent id of max risk": trajectoryMetaDebug?.maxRiskAgent,
      "agent distance at max risk": trajectoryMetaDebug?.maxRiskAgentDist,
      risk_debug_str: trajectoryMetaDebug?.riskDebugStr,
      lead_agent_id: trajectoryMetaDebug?.leadAgentId,
      min_lead_dist_pose_ix: trajectoryMetaDebug?.minLeadDistPoseIx,
      lc_min_dist_to_lead_agent: trajectoryMetaDebug?.lcMinDistToLeadAgent,
      tail_agent_id: trajectoryMetaDebug?.tailAgentId,
      min_tail_dist_pose_ix: trajectoryMetaDebug?.minTailDistPoseIx,
      lc_min_dist_to_tail_agent: trajectoryMetaDebug?.lcMinDistToTailAgent,
      lc_rear_end_risk: trajectoryMetaDebug?.lcRearEndRisk,
      is_lane_change_ready: trajectoryMetaDebug?.isLaneChangeReady,
    },
    HumanTrajectory: trajectoryMetaDebug?.trajectory?.poses,
    AgentsInLaneSequence:
      trajectorySelectionDebug?.featureSample?.nearestAgentsInLaneSequence,
    HumanDrivingFeature: {
      RoundRobinScore: (
        trajectorySelectionDebug?.featureSample?.humanDrivingSample?.mlFeature
          ?.roundRobinRivals ?? []
      ).map((rival, index) => {
        const rival_candidate =
          trajectorySelectionDebug?.trajectoryMetaDebugs?.[rival];
        const rival_label = rival_candidate
          ? getTrajectoryTypeLabel(rival_candidate)
          : "";
        const rival_score =
          trajectoryMetaDebug?.mlFeature?.roundRobinScores[index]?.toFixed(6) ??
          "";
        return `${rival_label} ${rival_score}`;
      }),
      EarlyReturn:
        trajectorySelectionDebug?.featureSample?.humanDrivingSample?.mlFeature
          ?.humanlikenessEarlyReturnReason,
      extended_poses:
        trajectorySelectionDebug?.featureSample?.humanDrivingSample?.mlFeature
          ?.extendedPoses,
    },
    HumanLikeness: {
      RoundRobinScore: (
        trajectoryMetaDebug?.mlFeature?.roundRobinRivals ?? []
      ).map((rival, index) => {
        const rival_candidate =
          trajectorySelectionDebug?.trajectoryMetaDebugs?.[rival];
        const rival_label = rival_candidate
          ? getTrajectoryTypeLabel(rival_candidate)
          : "";
        const rival_score =
          trajectoryMetaDebug?.mlFeature?.roundRobinScores[index]?.toFixed(6) ??
          "";
        return `${rival_label} ${rival_score}`;
      }),
      EarlyReturn:
        trajectoryMetaDebug?.mlFeature?.humanlikenessEarlyReturnReason,
      extended_poses: trajectoryMetaDebug?.mlFeature?.extendedPoses,
    },
    DebugInfo: trajectorySelectionDebug?.debugInfo,
  };
  return featureDebug;
}

// 保留4位小数 @ivymeng
function transformCostValue(value: unknown) {
  if (typeof value === "number") {
    return Math.round(value * 10000) / 10000;
  }
  return value;
}

function sortTrajectoryMetaDebugs(
  trajectoryMetaDebugs: Messages.planner__pb__TrajectoryMetaDebug[],
) {
  const index = trajectoryMetaDebugs.findIndex(
    (trajectoryMetaDebug) => trajectoryMetaDebug.isSelected,
  );
  if (index === -1) {
    return trajectoryMetaDebugs;
  }
  const selectedTrajectoryMetaDebug = trajectoryMetaDebugs[index]!;
  trajectoryMetaDebugs.splice(index, 1);
  trajectoryMetaDebugs.unshift(selectedTrajectoryMetaDebug);
  return trajectoryMetaDebugs;
}

function putSelectedTrajectoryFirst(trajectoriesDebugInfo: any[]) {
  const index = trajectoriesDebugInfo.findIndex(
    (trajectoryDebugInfo) => trajectoryDebugInfo.isSelected,
  );
  if (index === -1) {
    return trajectoriesDebugInfo;
  }
  const selectedTrajectoryMetaDebug = trajectoriesDebugInfo[index]!;
  trajectoriesDebugInfo.splice(index, 1);
  trajectoriesDebugInfo.unshift(selectedTrajectoryMetaDebug);
  return trajectoriesDebugInfo;
}

function rearrangeSubCostOrders(subCostsInfo: any[]) {
  const rearrangedSubCosts1 = moveCostItemToFrontByDisplayName(
    subCostsInfo,
    "OverallCost",
  );
  const rearrangedSubCosts2 = moveCostItemToFrontByDisplayName(
    rearrangedSubCosts1,
    "ScenarioType",
  );

  return rearrangedSubCosts2;
}

function moveCostItemToFrontByDisplayName(
  subCostsInfo: any[],
  displayName: string,
) {
  const index = subCostsInfo.findIndex(
    (subCostInfo) => subCostInfo.name == displayName,
  );
  if (index === -1) {
    return subCostsInfo;
  }
  const scenarioTypeSubCostInfo = subCostsInfo[index]!;
  subCostsInfo.splice(index, 1);
  subCostsInfo.unshift(scenarioTypeSubCostInfo);
  return subCostsInfo;
}

function generateCostDebugTable(costDebugTable: any) {
  const costNameAndTrajectoryNameMap = new Map<string, Map<string, unknown>>();
  const costNames = new Set<string>();
  const auxiliaryDebugFieldNames = new Set<string>();
  const trajectoryNames = [];
  const sortedTrajectoriesDebugInfo = putSelectedTrajectoryFirst(
    costDebugTable?.trajectoriesDebugInfo ?? [],
  );

  forEach(sortedTrajectoriesDebugInfo, (trajectory) => {
    const trajectoryName = `${trajectory.trajectoryName}${trajectory.isSelected ? "(Selected)" : ""}`;
    trajectoryNames.push(trajectoryName);

    forEach(trajectory?.subCostsInfo, (subCostInfo) => {
      const costName =
        subCostInfo.displayName == ""
          ? `${"Cost:"}${subCostInfo.costType}`
          : subCostInfo.displayName;
      if (
        typeof subCostInfo.costType === "string" &&
        subCostInfo.costType.toUpperCase() === "UNSPECIFIED"
      ) {
        auxiliaryDebugFieldNames.add(costName);
      } else {
        costNames.add(costName);
      }
      const weight = subCostInfo.costWeight;
      const content =
        subCostInfo.debugMessage == ""
          ? `${transformCostValue(subCostInfo.costValue)}`
          : subCostInfo.debugMessage;

      const trajectoryMap = costNameAndTrajectoryNameMap.get(costName);
      if (trajectoryMap) {
        trajectoryMap.set(trajectoryName, { Weight: weight, Content: content });
      } else {
        const newTrajectoryMap = new Map<string, unknown>();
        newTrajectoryMap.set(trajectoryName, {
          Weight: weight,
          Content: content,
        });
        costNameAndTrajectoryNameMap.set(costName, newTrajectoryMap);
      }
    });
  });

  const candidateCostData = convertToRecordTable(
    costNameAndTrajectoryNameMap,
    trajectoryNames,
    Array.from(costNames),
    Array.from(auxiliaryDebugFieldNames),
  );

  return candidateCostData;
}

function convertToRecordTable(
  costDataMap: any | undefined,
  trajectoryNames: string[],
  costNames: string[],
  auxiliaryDebugFieldNames: string[],
): Record<string, unknown>[] {
  let candidateCostData: Record<string, unknown>[] = [];
  costNames.sort();
  auxiliaryDebugFieldNames.sort();
  const displayNames = [...costNames, ...auxiliaryDebugFieldNames];

  forEach(displayNames, (displayName) => {
    const trajectoryMap = costDataMap.get(displayName);
    if (trajectoryMap) {
      let entry: Record<string, unknown> = { name: displayName, Weight: null };
      forEach(trajectoryNames, (trajectoryName) => {
        const trajectorySubcost = trajectoryMap.get(trajectoryName);
        if (trajectorySubcost) {
          entry[trajectoryName] = (trajectorySubcost as any).Content;
          entry.Weight = (trajectorySubcost as any).Weight;
        } else {
          entry[trajectoryName] = null;
        }
      });
      candidateCostData.push(entry);
    }
  });
  // move ScenarioType and OverallCost to the top
  candidateCostData = rearrangeSubCostOrders(candidateCostData);
  return candidateCostData;
}

function isNewCostDebugDataReady(trajectorySelectionDebug: any | undefined) {
  const subCostsInfo =
    trajectorySelectionDebug?.costDebugTable?.trajectoriesDebugInfo[0]
      ?.subCostsInfo;
  if (!subCostsInfo) {
    return false;
  }
  const index = subCostsInfo.findIndex(
    (subCostInfo) => subCostInfo.displayName == "OverallCost",
  );
  if (index === -1) {
    return false;
  }
  // make sure new layout includes filtered out unsafe trajectories
  if (
    trajectorySelectionDebug?.trajectoryMetaDebugs.length >
    trajectorySelectionDebug?.costDebugTable?.trajectoriesDebugInfo.length
  ) {
    return false;
  }

  return true;
}

