import { Input, Messages } from "@vitruvian/voyager-type";
import {
  GlobalVariables,
  ScriptConfig,
  MemoryCacheBlock,
  createDeleteCurrentTopicMarkers,
  getIntentionPlanDebug,
  getSpeedSolverDebugIndex,
} from "@ares-utils";

// These are the topics your script "subscribes" to. Ares will invoke your publisher function
// When any message is received on these topics.
// e.g. export const inputs: string[] = ["/pose", "/perception/tracked_object_list"]
export const inputs = ["/planning/planning_debug", "/pose", "/simulation/pose"];

// The name of the topic published
// When data is rendered in ImagePanel, the name must start with "/image_marker/"
// When data is rendered in 3DPanel, the name must start with "/studio_node/"
export const output: `/${"studio_node" | "image_marker"}/${string}` =
  "/studio_node/efs_result";

// Configure the input and output when the code is executed
export const config: ScriptConfig = {};

/**
 * This function is called with messages from your input topics.
 * The first argument is an event with the topic, receive time, and message.

 * @param messages According to the topic subscribed by "inputs", pass in the message corresponding to the topic.
 * @remarks Use the `Input<topicName>` helper to get the correct event type for your input topic messages.
 * @example
 * message: {
 *   "/pose": Input<"/pose">,
 *   "/perception/tracked_object_list": Input<"/perception/tracked_object_list">
 * }
 *
 * @param globalVariables Variables that can be accessed anywhere in the program, based on which the interactivity of the visual content can be configured
 * @see {@link https://cooper.didichuxing.com/knowledge/2199628491086/2199761277479} for more information
 *
 * @param blocks According to the topic subscribed by "inputs", all the messages of the corresponding topic in the bag are passed in
 *
 * @return the return format of the data is based on datatype
 */
const publisher = (
  messages: Record<
    string,
    | Input<"/planning/planning_debug">
    | Input<"/pose">
    | Input<"/simulation/pose">
  >,
  globalVars: GlobalVariables,
  blocks: readonly (MemoryCacheBlock | undefined)[],
): Messages.ares__VisualizationMarkerArray => {
  const planningDebugMessage = messages[
    "/planning/planning_debug"
  ] as Input<"/planning/planning_debug">;
  const poseMessage = messages["/pose"] as Input<"/pose">;
  const simPoseMessage = messages[
    "/simulation/pose"
  ] as Input<"/simulation/pose">;

  let poseToUse, poseReceiveTime;
  if (simPoseMessage) {
    poseToUse = simPoseMessage.message;
    poseReceiveTime = simPoseMessage.receiveTime;
  } else {
    poseToUse = poseMessage.message;
    poseReceiveTime = poseMessage.receiveTime;
  }

  const behaviorReasonerDebug =
    planningDebugMessage?.message?.behaviorReasonerDebug;

  const intentionPlanDebug = getIntentionPlanDebug(
    behaviorReasonerDebug,
    globalVars,
  );

  const speedGeneratorDebug =
    intentionPlanDebug?.speedGeneratorDebug as Messages.planner__speed__pb__SpeedGeneratorDebug;

  const speedSolverDebugIndex = getSpeedSolverDebugIndex(
    behaviorReasonerDebug,
    globalVars,
  );

  const searchDebug =
    speedGeneratorDebug?.speedSolverDebugs[speedSolverDebugIndex]?.searchDebug;

  // For backward compatibility, we need to check both `searchResult` and
  // `conflictResolvingType`.
  const searchResult = searchDebug?.searchResult;

  const conflictResolvingType = searchDebug?.conflictResolvingType;

  const markers: Messages.ares__VisualizationMarker[] = [
    createDeleteCurrentTopicMarkers(poseReceiveTime),
  ];
  if (
    searchResult == "CONFLICT_RESOLVING" &&
    conflictResolvingType == "EXTRA_FULL_STOP_PROFILE"
  ) {
    const marker: Messages.ares__VisualizationMarker = {
      header: {
        frame_id: "world",
        seq: 0,
        stamp: { sec: poseReceiveTime, nsec: 0 },
      },
      type: Messages.ares__VisualizationMarkerTypes.TEXT,
      ns: "efs_result",
      id: "efs_result",
      pose: {
        position: {
          x: poseToUse.x,
          y: poseToUse.y,
          z: poseToUse.z,
        },
        orientation: { x: 0, y: 0, z: 0.64, w: 2 },
      },
      color: { r: 0, g: 0, b: 0, a: 1 },
      textMetadata: {
        text: "EFS",
        convertType: Messages.ares__TextConvertType.TEXT3D,
        textStyle: {
          background: "yellow",
          lineHeight: "20px",
          padding: "2px 2px",
        },
      },
    };

    markers.push(marker);
  }

  return {
    markers,
  };
};

export default publisher;

