    return { markers };
  }

  const unstuckDebug = singleLaneSequencePlanDebug?.unstuckDebug;
  const stuckRegions = unstuckDebug?.stuckRegions ?? [];
  if (stuckRegions.length === 0) {
    return { markers };
  }

  const mainStuckRegionPolygonPoints = (
    singleLaneSequencePlanDebug.unstuckDebug.stuckRegions[0] as
      | Messages.planner__pb__StuckRegion
      | undefined
  )?.contour;
  const stuckRegionFillColor = { r: 1.0, g: 0.4, b: 0.4, a: 0.5 };
  const stuckRegionEdgeColor = { r: 1.0, g: 0, b: 0, a: 1.0 };
  let stuckRegionPolygonZ = pose.z + 5.0;
  const stuckRegionMarker: Messages.ares__VisualizationMarker = {
    header: {
      stamp: planningDebug.receiveTime,
      frame_id: "world",
      seq: 0,
    },
    id: "xlane_stuck_region_polygon",
    type: Messages.ares__VisualizationMarkerTypes.SHAPE,
    points: mainStuckRegionPolygonPoints.map((point) => {
      return { ...point, z: stuckRegionPolygonZ };
    }),
    color: stuckRegionFillColor,
    edgeColor: stuckRegionEdgeColor,
    pose: { position: { x: 0.0, y: 0.0, z: stuckRegionPolygonZ } },
    fill: true,
    edge: true,
  };

  markers.push(stuckRegionMarker);
  return {
    markers: markers,
  };
};

