6008587e-42f3-4caf-80bc-35fdd30e6da6.sourceCode:
/* eslint-disable @foxglove/no-boolean-parameters */
/* eslint-disable @foxglove/strict-equality */
/* eslint-disable @typescript-eslint/no-unnecessary-condition */
/* ares-expose-source-code */
import {
  getIntentionPlanDebug,
  radian2Degree,
  populateStartXAndEndXFromConstraintState,
  getSpeedSolverDebugIndex,
  isGapAlignSuccessResult,
  getObjectId,
  getDiscomfortVarying,
  getConstraints,
  GlobalVariables,
  DEFAULT_STUDIO_NODE_PREFIX,
  getOverlapRegionUniqueId,
  getPerDiscomfortDebug,
} from "@ares-utils";
import { Input, Messages } from "@vitruvian/voyager-type";
import { Messages as rosMessages } from "ros";
import {
  map,
  last,
  upperFirst,
  toInteger,
  isUndefined,
  forEach,
  cloneDeep,
} from "lodash";

enum GapAlignType {
  NGA = "NGA",
  GA = "GA",
}
// 对constraint.settings的值进行覆盖
const PLANNING_CONSTRAINT_SETTINGS_UPDATE_KEYS = [
  "passRequiredLatGap",
  "yieldRequiredLatGap",
  "requiredLatGap",
  "passExtraTime",
  "yieldExtraTime",
  "passExtraDistance",
  "yieldExtraDistance",
  "passStopRange",
  "yieldStopRange",
  "passHeadway",
  "yieldHeadway",
  "passUncertaintySdFactor",
  "yieldUncertaintySdFactor",
  "reactionTimes.pass",
  "reactionTimes.yield",
  "slowDownParams.pass.accel",
  "slowDownParams.pass.maxSpeedReduction",
  "slowDownParams.yield.accel",
  "slowDownParams.yield.maxSpeedReduction",
  "shiftParams.pass.steeringRate",
  "shiftParams.yield.steeringRate",
  "shiftReactionTimes.pass",
  "shiftReactionTimes.yield",
  "discomfortVarYieldMinV",
  "discomfortVarYieldMinA",
  "discomfortVarYieldMinJ",
  "discomfortVarPassMaxV",
  "discomfortVarPassMaxA",
  "discomfortVarPassMaxJ",
];

export const inputs = ["/planning/planning_debug"];

export const output = `${DEFAULT_STUDIO_NODE_PREFIX}planning/speed_table_raw`;
export const config = {
  datatype: "voyager_data_msgs/CustomData",
  showOn3DPanel: false,
};

export const publisher = (
  messages: Record<string, Input<"/planning/planning_debug">>,
  globalVars: GlobalVariables,
): Record<string, Messages.voyager_data_msgs__CustomData> => {
  const planningEnableOverlapV2 =
    globalVars.planning_enable_overlap_v2 ?? false;
  const message_p = messages[
    "/planning/planning_debug"
  ] as Input<"/planning/planning_debug">;

  const message = message_p.message;

  if (!message) {
    return {};
  }

  const behaviorReasonerDebug = message?.behaviorReasonerDebug;
  const plannerObjectDebug = message?.worldModelDebug?.plannerObjectDebug;

  const intentionPlanDebug = getIntentionPlanDebug(
    behaviorReasonerDebug,
    globalVars,
  );
  const planningConstraintId = globalVars.planning_constraint_id;
  const curGlobalDiscomfortLevel = globalVars.planning_speed_discomforts_level;
  const speedGeneratorDebug =
    intentionPlanDebug?.speedGeneratorDebug as Messages.planner__speed__pb__SpeedGeneratorDebug;

  const speedSolverDebugIndex = getSpeedSolverDebugIndex(
    behaviorReasonerDebug,
    globalVars,
  );

  const speedSolverDebug =
    speedGeneratorDebug?.speedSolverDebugs?.[speedSolverDebugIndex];
  const searchDebug =
    speedSolverDebug?.searchDebug as Messages.planner__speed__pb__SpeedSearchDebug;

  const { discomfortsTable, discomfortsLevel } = getDiscomfortsInfo(
    searchDebug,
    speedGeneratorDebug,
  );

  return {
    constraintId: getConstraintId(
      getConstraints(searchDebug, speedGeneratorDebug),
    ),
    dominantConstraint: getDominantConstraint(searchDebug, speedGeneratorDebug),
    discomfortsTable,
    discomfortsLevel,
    constraintStateValue: getConstraintStateValue(
      searchDebug,
      speedGeneratorDebug,
      planningConstraintId,
    ),
    constraintSettings: getConstraintSettings(
      searchDebug,
      speedGeneratorDebug,
      planningConstraintId,
    ),
    initialDecision: getInitialDecision(
      searchDebug,
      speedGeneratorDebug,
      planningConstraintId,
      curGlobalDiscomfortLevel,
    ),
    pathInfo: {
      inputPath: speedGeneratorDebug?.inputPath,
      extendedPath: speedGeneratorDebug?.extendedPath,
    },
    searchDebug: getSearchDebug(
      speedGeneratorDebug,
      speedSolverDebug as Messages.planner__speed__pb__SpeedSolverDebug,
    ),
    overlapIdList: getOverlapIdList(speedGeneratorDebug),
    overlapIdTable: getOverlapIdTable(
      speedGeneratorDebug,
      plannerObjectDebug,
      planningEnableOverlapV2,
      globalVars.planning_overlap_index,
    ),
    proximityID: getProximityID(speedGeneratorDebug?.proximityInfo),
    proximityInfoTable: getProximityInfoTable(
      speedGeneratorDebug,
      globalVars.planning_proximity_id,
    ),
  };
};

function getDominantConstraint(
  searchDebug: Messages.planner__speed__pb__SpeedSearchDebug,
  speedGeneratorDebug: Messages.planner__speed__pb__SpeedGeneratorDebug,
) {
  const dominantConstraintIx = searchDebug?.dominantConstraintIx;
  const gapAlignSuccess = isGapAlignSuccessResult(searchDebug?.searchResult);
  const gapAlignStr = gapAlignSuccess ? "Gap align." : "Non gap align.";
  let outputString = "No dominant constraint.";
  const constraints = getConstraints(searchDebug, speedGeneratorDebug);
  if (
    (dominantConstraintIx >= 0 && dominantConstraintIx < constraints?.length) ??
    0
  ) {
    outputString = `Dominant constraint: ${constraints?.[dominantConstraintIx]?.uniqueConstraintId}, Object id: ${searchDebug?.dominantConstraintObjId}.`;
  }
  const earliestBrakeTimeIxStr = `Earliest search brake time ix: ${searchDebug?.earliestBrakeTimeIx}`;
  return `${gapAlignStr} ${outputString} ${earliestBrakeTimeIxStr}`;
}

type PerDiscomfortInfo = {
  "Discomfort idx": number;
  "Discomfort level": number;
  "Diversity option": string;
  "Dominant constraint id": string;
  Success: string;
  "Should accept": string;
  "Reason for fail": Messages.planner__speed__pb__PerDiscomfortDebug__DiscomfortIncreaseSource;
  "AdjustForPass earliest accel time index": number;
};

function getPerDiscomfortInfo(
  discomfortDebug: Messages.planner__speed__pb__PerDiscomfortDebug,
  constraints:
    | Messages.planner__speed__pb__Constraint[]
    | Messages.planner__speed__pb__PrimitiveConstraint[],
  isGapAlign: boolean,
): PerDiscomfortInfo {
  const dominantConstraintIx = discomfortDebug?.dominantConstraintIx;
  let dominantConstraintId = "No dominant constraint";
  if (
    dominantConstraintIx >= 0 &&
    dominantConstraintIx < (constraints?.length ?? 0)
  ) {
    dominantConstraintId =
      constraints?.[dominantConstraintIx]?.uniqueConstraintId ??
      "No dominant constraint";
  }
  return {
    "Discomfort idx": discomfortDebug?.discomfortIdx,
    "Discomfort level": discomfortDebug?.discomfortLevel,
    "Diversity option": discomfortDebug?.diversityOption as string,
    "Dominant constraint id": dominantConstraintId,
    Success: `${discomfortDebug?.success ? "True" : "False"}(${
      isGapAlign ? "Gap align" : "Non gap align"
    })`,
    "Should accept": (discomfortDebug as any)?.shouldAccept ? "True" : "False",
    "Reason for fail": discomfortDebug?.discomfortIncreaseSource,
    "AdjustForPass earliest accel time index":
      discomfortDebug?.earliestAccelTimeIxForAdjustForPass,
  };
}

function getDiscomfortsInfo(
  searchDebug: Messages.planner__speed__pb__SpeedSearchDebug,
  speedGeneratorDebug: Messages.planner__speed__pb__SpeedGeneratorDebug,
): {
  discomfortsTable: PerDiscomfortInfo[];
  discomfortsLevel: string[];
} {
  const constraints = getConstraints(searchDebug, speedGeneratorDebug);
  const discomfortsTableData: PerDiscomfortInfo[] = [];
  const discomfortsLevelData: string[] = [];

  forEach(searchDebug?.discomforts, (discomfort) => {
    discomfortsTableData.push(
      getPerDiscomfortInfo(discomfort, constraints, false),
    );
    // NGA: Non gap align
    if (!isUndefined(discomfort?.discomfortLevel)) {
      discomfortsLevelData.push(
        `${discomfort.discomfortLevel}-${GapAlignType.NGA}`,
      );
    }
  });

  forEach(searchDebug?.gapAlignDiscomforts, (gapAlignDiscomfort) => {
    discomfortsTableData.push(
      getPerDiscomfortInfo(gapAlignDiscomfort, constraints, true),
    );
    // GA: gap align
    if (!isUndefined(gapAlignDiscomfort?.discomfortLevel)) {
      discomfortsLevelData.push(
        `${gapAlignDiscomfort.discomfortLevel}-${GapAlignType.GA}`,
      );
    }
  });
  return {
    discomfortsTable: discomfortsTableData,
    discomfortsLevel: discomfortsLevelData,
  };
}

function getConstraintStateValue(
  searchDebug: Messages.planner__speed__pb__SpeedSearchDebug,
  speedGeneratorDebug: Messages.planner__speed__pb__SpeedGeneratorDebug,
  planningConstraintId?: string,
) {
  if (planningConstraintId === undefined) {
    return {};
  }
  const indexByNew = speedGeneratorDebug?.primitiveConstraints?.findIndex(
    (constraint) => constraint?.uniqueConstraintId === planningConstraintId,
  );
  const index = searchDebug?.constraints?.findIndex(
    (constraint) => constraint?.uniqueConstraintId === planningConstraintId,
  );
  if (indexByNew === -1 && index === -1) {
    return {};
  }
  const finalIndex = indexByNew > -1 ? indexByNew : index;
  const constraintByNew =
    speedGeneratorDebug?.primitiveConstraints?.[indexByNew];
  const constraint = searchDebug?.constraints?.[finalIndex];
  const curConstraint = {
    type:
      constraintByNew?.type ??
      (constraint?.type as Messages.planner__speed__pb__Constraint__Type),
    fenceType: constraintByNew?.fenceType ?? constraint?.type,
    generatingReasonerId:
      constraintByNew?.generatingReasonerId ?? constraint?.generatingReasonerId,
    objId: constraintByNew?.objId ?? constraint?.objId,
    uniquePredTrajId:
      constraintByNew?.uniquePredTrajId ?? constraint?.uniquePredTrajId,
    uniqueOverlapId:
      constraintByNew?.uniqueOverlapId ?? constraint?.uniqueOverlapId,
    uniqueConstraintId:
      constraintByNew?.uniqueConstraintId ?? constraint?.uniqueConstraintId,
    settings: constraintByNew?.settings ?? constraint?.settings,
    standoffs: constraintByNew?.standoffs ?? constraint?.standoffs,
    states: constraint?.states,
    selectedDiscomfort: constraint?.selectedDiscomfort as number,
    adjustedTrajectoryAtSelectedDiscomfort:
      constraint?.adjustedTrajectoryAtSelectedDiscomfort as Messages.prediction__pb__PredictedTrajectory,
    isModifiedBySoft: constraint?.isModifiedBySoft,
    isUsingRlgVarStates: (constraint as any)?.isUsingRlgVarStates,
  };
  const curConstraintInfo: Record<string, unknown> = {
    "Constraint Type": curConstraint?.type,
    "Fence Type": curConstraint?.fenceType,
    "Generating Reasoner ID": curConstraint?.generatingReasonerId,
    "Object ID": curConstraint?.objId,
    "Unique Pred Traj ID": curConstraint?.uniquePredTrajId,
    "Selected Discomfort": curConstraint?.selectedDiscomfort,
  };

  const initialDecision =
    searchDebug?.initialDecisionProviderDebug?.initialDecisionDebugs?.[
      finalIndex
    ]?.initialDecision;

  if (!isUndefined(initialDecision)) {
    curConstraintInfo["Initial Decision"] = initialDecision;
  }

  curConstraintInfo["Decision"] = searchDebug?.decisions?.[finalIndex];

  if (curConstraint?.states?.length) {
    const startXAndEndXFromConstraintState =
      populateStartXAndEndXFromConstraintState(
        curConstraint
          ?.states?.[0] as unknown as Messages.planner__speed__pb__ConstraintState,
        curConstraint?.selectedDiscomfort,
      );
    curConstraintInfo["First State start x"] =
      startXAndEndXFromConstraintState?.startX?.toFixed(3);
    curConstraintInfo["First State end x"] =
      startXAndEndXFromConstraintState?.endX?.toFixed(3);
    curConstraintInfo["First State start time"] =
      curConstraint?.states?.[0]?.startTime;
    curConstraintInfo["First State end time"] =
      curConstraint?.states?.[0]?.endTime;
    curConstraintInfo["Modified by Agent Reaction"] =
      curConstraint?.adjustedTrajectoryAtSelectedDiscomfort?.trajPoses?.length >
      0
        ? "True"
        : "False";
    curConstraintInfo["Modified by Soft"] =
      curConstraint?.isModifiedBySoft === true ? "True" : "False";
    curConstraintInfo["Using Rlg Var States"] =
      curConstraint?.isUsingRlgVarStates === true ? "True" : "False";
    curConstraintInfo["Standoff"] = getStandoff(curConstraint.standoffs ?? []);
  }

  return Object.entries(curConstraintInfo).map((info) => ({
    state: info[0],
    value: info[1],
  }));
}

function updateSettingsValue(
  constraintSettings:
    | Messages.planner__speed__pb__DiscomfortVarying
    | undefined,
  selectedDiscomfort: number | undefined,
) {
  if (isUndefined(constraintSettings)) {
    return;
  }
  if (!isUndefined(constraintSettings["selectedDiscomfort"])) {
    constraintSettings["selectedDiscomfort"] = selectedDiscomfort as number;
  }
  if (!isUndefined(constraintSettings["valueAtSelectedDiscomfort"])) {
    constraintSettings["valueAtSelectedDiscomfort"] = getDiscomfortVarying(
      constraintSettings,
      selectedDiscomfort as number,
    );
  }
}

function updateConstraintSettingsDebug(
  constraintSettings: Record<string, unknown>,
  selectedDiscomfort: number | undefined,
): void {
  if (isUndefined(constraintSettings)) {
    return undefined;
  }
  PLANNING_CONSTRAINT_SETTINGS_UPDATE_KEYS.forEach((key) => {
    if (key.includes(".")) {
      let settings = constraintSettings;
      const keysArr = key.split(".");
      keysArr.forEach((childKey: string) => {
        settings = settings?.[childKey] as Record<string, unknown>;
      });
      updateSettingsValue(
        settings as unknown as Messages.planner__speed__pb__DiscomfortVarying,
        selectedDiscomfort,
      );
    } else if (constraintSettings?.[key]) {
      updateSettingsValue(
        constraintSettings?.[
          key
        ] as Messages.planner__speed__pb__DiscomfortVarying,
        selectedDiscomfort,
      );
    }
  });
}

function getConstraintSettings(
  searchDebug: Messages.planner__speed__pb__SpeedSearchDebug,
  speedGeneratorDebug: Messages.planner__speed__pb__SpeedGeneratorDebug,
  planningConstraintId?: string,
) {
  const constraints = getConstraints(searchDebug, speedGeneratorDebug);
  const indexByNew = constraints?.findIndex(
    (constraint) => constraint.uniqueConstraintId === planningConstraintId,
  );
  const index = searchDebug?.constraints?.findIndex(
    (constraint) => constraint.uniqueConstraintId === planningConstraintId,
  );
  const constraint =
    indexByNew > -1 ? constraints[indexByNew] : searchDebug?.constraints[index];
  const constraintInSearch =
    indexByNew > -1
      ? searchDebug?.constraints[indexByNew]
      : searchDebug?.constraints[index];
  const settings = cloneDeep(constraint?.settings);
  const selectedDiscomfort = constraintInSearch?.selectedDiscomfort;
  updateConstraintSettingsDebug(
    settings as unknown as Record<string, unknown>,
    selectedDiscomfort,
  );
  return settings;
}

function getStandoff(standoffs: Messages.planner__speed__pb__Standoff[]) {
  return standoffs?.map((standoff, index) => {
    let str = `${standoff.name}: [${standoff.startTime?.toFixed(
      2,
    )}, ${standoff.endTime?.toFixed(2)}]`;
    const discomfort = standoff.yieldX;
    if (discomfort?.values?.length > 0) {
      str += `[${discomfort?.values?.[0]}, ${last(discomfort?.values)}]`;
    }
    return {
      [`Standoff ${index}`]: str,
    };
  });
}
function searchDebugRawAddValue(
  globalSpeedSolverSettings: Messages.planner__speed__pb__GlobalSpeedSolverSettings,
  searchDebugRaw: Record<string, unknown>,
) {
  if (globalSpeedSolverSettings) {
    Object.entries(globalSpeedSolverSettings).forEach(([key, value]) => {
      searchDebugRaw[upperFirst(camelToSpace(key))] = value;
    });
  }
}

function getSearchDebug(
  speedGeneratorDebug: Messages.planner__speed__pb__SpeedGeneratorDebug,
  speedSolverDebug: Messages.planner__speed__pb__SpeedSolverDebug,
) {
  const searchDebug = speedSolverDebug?.searchDebug;
  const searchDebugRaw: Record<string, unknown> = {
    "Search result": searchDebug?.searchResult,
  };
  searchDebugRaw["Conflict resolving type"] =
    `${searchDebug?.conflictResolvingType}`;

  if (speedSolverDebug?.warmStartDebug) {
    searchDebugRaw["Opt uses warm start"] = `${
      speedSolverDebug?.warmStartDebug?.isUseWarmStart
    }(${speedSolverDebug?.warmStartDebug?.warmStartProfileCost?.toFixed(
      6,
    )} < ${speedSolverDebug?.warmStartDebug?.searchProfileCost?.toFixed(6)})`;
  }

  if (speedSolverDebug?.optDebug) {
    searchDebugRaw["Opt result"] =
      `${speedSolverDebug?.optDebug?.optimizationResult}`;
  }

  searchDebugRaw["Speed solver overall result"] =
    speedSolverDebug?.solverResult;
  searchDebugRaw["Is coming to stop"] = (searchDebug as any)?.isComingToStop;
  searchDebugRaw["Stay stop debug str"] = (
    searchDebug as any
  )?.stayStopDebugStr;

  if (searchDebug?.selectedReference) {
    searchDebugRaw["Global discomfort value"] =
      searchDebug?.selectedReference?.discomfortValue?.toFixed(2);
  }

  searchDebugRaw["Tree search type"] = searchDebug?.treeSearchType;
  searchDebugRaw["Tree switch time ix"] = searchDebug?.treeSwitchTimeIx;
  if (searchDebug?.riskMitigationDebug) {
    searchDebugRaw["Risk discomfort"] =
      searchDebug.riskMitigationDebug.riskDiscomfort?.toFixed(2);
    searchDebugRaw["Risk mitigation active"] = searchDebug.riskMitigationDebug
      .riskMitigationActive
      ? "true"
      : "false";
  }

  searchDebugRaw["Diversity option"] = searchDebug?.diversityOption;
  searchDebugRawAddValue(
    searchDebug?.globalSpeedSolverSettings,
    searchDebugRaw,
  );
  searchDebugRaw["Proximity count"] =
    speedGeneratorDebug?.proximityInfo?.length;

  if (speedGeneratorDebug?.inputPath?.poses?.length) {
    searchDebugRaw["Input path length"] = last(
      speedGeneratorDebug?.inputPath?.poses,
    )?.odom?.toFixed(2);
  }

  searchDebugRaw["Extended path range"] =
    `${-speedGeneratorDebug?.planInitRaArcLengthOnExtendedPath?.toFixed(2)}, ${(
      speedGeneratorDebug?.extendedPathLength -
      speedGeneratorDebug?.planInitRaArcLengthOnExtendedPath
    )?.toFixed(2)}`;

  searchDebugRaw["Selected longitudinal kinematic limits"] =
    searchDebug?.selectedLongitudinalKinematicLimits;

  searchDebugRaw["Selected min range"] = searchDebug?.minRange;

  const lcGuideSeed = searchDebug?.lcGuideSeed;
  if (lcGuideSeed) {
    searchDebugRaw["is_valid"] = lcGuideSeed?.isValid ? "true" : "false";
    searchDebugRaw["tree_switch_time_ix"] = lcGuideSeed?.treeSwitchTimeIx;
    searchDebugRaw["tail obj id"] = lcGuideSeed?.tailObjId;
    searchDebugRaw["lead obj id"] = lcGuideSeed?.leadObjId;
    searchDebugRaw["lc_start_arc_length"] =
      lcGuideSeed?.lcStartArcLength?.toFixed(2);
    searchDebugRaw["lc_end_arc_length"] =
      lcGuideSeed?.lcEndArcLength?.toFixed(2);
    searchDebugRaw["lc_ref_end_arc_length"] =
      lcGuideSeed?.lcRefEndArcLength?.toFixed(2);
  }
  return searchDebugRaw;
}

function getOverlapIdList(
  speedGeneratorDebug: Messages.planner__speed__pb__SpeedGeneratorDebug,
) {
  return map(speedGeneratorDebug?.overlapRegions, (overlapRegion) => {
    const value = getOverlapRegionUniqueId(overlapRegion);
    return {
      title: value,
      value,
      key: value,
      connectKey:
        overlapRegion?.objectId !== undefined
          ? String(overlapRegion?.objectId)
          : undefined,
    };
  });
}

type LongitudinalRangeToQString = {
  slice: Messages.planner__speed__pb__OverlapSlice;
  isStrict?: boolean;
  useOriginal?: boolean;
  planningEnableOverlapV2?: boolean;
};

function hasStrictOverlap({
  slice,
  useOriginal,
  planningEnableOverlapV2,
}: Omit<LongitudinalRangeToQString, "isStrict">) {
  if (planningEnableOverlapV2) {
    return slice.egoMovingDistanceStrict;
  }

  if (useOriginal) {
    return slice.raArcLengthStrictOriginal;
  }

  return slice.raArcLengthStrict;
}

function hasPaddedOverlap({
  slice,
  useOriginal,
  planningEnableOverlapV2,
}: Omit<LongitudinalRangeToQString, "isStrict">) {
  if (planningEnableOverlapV2) {
    return slice.egoMovingDistancePadded;
  }

  if (useOriginal) {
    return slice.raArcLengthPaddedOriginal;
  }

  return slice.raArcLengthPadded;
}

function getStrictOverlap({
  slice,
