      if (planningEnableOverlapV2) {
        result["Padded ego moving distance"] = longitudinalRangeToQString({
          slice: overlapSlice,
          isStrict: false,
          planningEnableOverlapV2,
        });
        result["Strict ego moving distance"] = longitudinalRangeToQString({
          slice: overlapSlice,
          isStrict: true,
          planningEnableOverlapV2,
        });
      } else {
        result["Padded Arc Length"] = longitudinalRangeToQString({
          slice: overlapSlice,
          isStrict: false,
          planningEnableOverlapV2,
        });
        result["Original Padded Arc Length"] = longitudinalRangeToQString({
          slice: overlapSlice,
          isStrict: false,
          useOriginal: true,
          planningEnableOverlapV2,
        });
        result["Strict Arc Length"] = longitudinalRangeToQString({
          slice: overlapSlice,
          isStrict: true,
          planningEnableOverlapV2,
        });
        result["Original Strict Arc Length"] = longitudinalRangeToQString({
          slice: overlapSlice,
          isStrict: true,
          useOriginal: true,
          planningEnableOverlapV2,
        });
      }
      result["Relative Heading (deg)"] = radian2Degree(
        overlapSlice?.relativeHeading ?? 0,
      )?.toFixed(3);
      result["Motion Type"] = overlapSlice?.motionType;
      result["Left Encroachment Distance (m)"] = (
        overlapSlice?.encroachmentInfo?.leftEncroachmentDist ?? 0
      )?.toFixed(3);
      result["Right Encroachment Distance (m)"] = (
        overlapSlice?.encroachmentInfo?.rightEncroachmentDist ?? 0
      )?.toFixed(3);
      return result;
    },
  );
}

function getObjectProximityInfoUniqueId(
  info: Messages.planner__speed__pb__ObjectProximityInfo,
) {
  if (info.isConstructionZone) {
    return `cz-${info.constructionZoneId}`;
  }
  return `obj-${info.objectId}`;
}

function getProximityID(
  proximityInfo: Messages.planner__speed__pb__ObjectProximityInfo[] = [],
) {
  return map(proximityInfo, (info) => {
    const value = getObjectProximityInfoUniqueId(info);
    return {
      title: value,
      value,
      key: value,
      connectKey:
        info?.objectId !== undefined ? String(info?.objectId) : undefined,
    };
  });
}

function getProximityInfoTable(
  speedGeneratorDebug: Messages.planner__speed__pb__SpeedGeneratorDebug,
  planningProximityId?: string,
) {
  const proximityInfo = speedGeneratorDebug?.proximityInfo?.find(
    (proximity) =>
      getObjectProximityInfoUniqueId(proximity) === planningProximityId,
  );
  const projectedRaArcLength = proximityInfo?.projectedRaArcLength;
  if (proximityInfo) {
    const proximityInfoObj = {
      "Signed lateral gap": proximityInfo?.signedLateralGap?.toFixed(5),
      "Signed lateral speed": proximityInfo?.signedLateralSpeed?.toFixed(5),
      "Signed longitudinal speed":
        proximityInfo?.signedLongitudinalSpeed?.toFixed(5),
      "Signed longitudinal acceleration":
        proximityInfo?.signedLongitudinalAcceleration?.toFixed(5),
      "Signed lateral acceleration":
        proximityInfo?.signedLateralAcceleration?.toFixed(5),
      "Relative box heading": proximityInfo?.relativeBoxHeading?.toFixed(5),
      "Projected ra arc length": `[${projectedRaArcLength?.start?.toFixed(
        2,
      )}, ${projectedRaArcLength?.end?.toFixed(2)}]`,
      "Out of range": proximityInfo.outOfPathRange ? "True" : "False",
    };
    return Object.entries(proximityInfoObj).map((info) => ({
      state: info[0],
      value: info[1],
    }));
  }
  return [];
}

function getConstraintId(
  constraints:
    | Messages.planner__speed__pb__Constraint[]
    | Messages.planner__speed__pb__PrimitiveConstraint[],
) {
  return map(constraints, (constraint) => ({
    title: constraint?.uniqueConstraintId,
    value: constraint?.uniqueConstraintId,
    key: constraint?.uniqueConstraintId,
    connectKey: getObjectId(constraint?.uniqueConstraintId),
  }));
}

