/* eslint-disable @foxglove/no-boolean-parameters */
/* eslint-disable no-restricted-syntax */
/* eslint-disable @typescript-eslint/no-unnecessary-condition */
/* ares-expose-source-code */
import {
  GlobalVariables,
  DEFAULT_STUDIO_NODE_PREFIX,
  getIntentionPlanDebug,
} from "@ares-utils";
import { Input, Messages } from "@vitruvian/voyager-type";
import { chain, forEach, filter } from "lodash";

export const inputs = ["/planning/planning_debug"];

export const output = `${DEFAULT_STUDIO_NODE_PREFIX}planning/speed_reasoning`;
export const config = {
  datatype: "voyager_data_msgs/CustomData",
  showOn3DPanel: false,
};

type SpeedReasoningDebug = {
  hallucinatedAgentManagerDebug;
};

export const publisher = (
  messages: Record<string, Input<"/planning/planning_debug">>,
  globalVariables: GlobalVariables,
): Messages.voyager_data_msgs__CustomData => {
  const planningDebugMessage = messages[
    "/planning/planning_debug"
  ] as Input<"/planning/planning_debug">;
  if (!planningDebugMessage) {
    return {};
  }

  const { behaviorReasonerDebug } = planningDebugMessage.message;

  const pathPlannerDebug = getIntentionPlanDebug(
    behaviorReasonerDebug,
    globalVariables,
  );
  if (!pathPlannerDebug) {
    return {};
  }

  /**
   * 这里的逻辑多为字段和值的重命名，没有任何运算和匹配逻辑，类似下面trafficLight这种形式，
   * 和PM和用户沟通后，其他的数组暂不需要进行转换，待后续planning新架构稳定数据结构后，有时间确定是否需要转化
   */
  const speedReasoningDebug = (
    pathPlannerDebug?.speedGeneratorDebug as Messages.planner__speed__pb__SpeedGeneratorDebug
  )?.speedReasoningDebug;
  if (!speedReasoningDebug) {
    return {};
  }

  const {
    tracked_object_selections,
    planning_hide_ignored_object: isFilterIgnoredAgent = false,
    planning_reasoning_agent_selected = "Show All",
  } = globalVariables;

  const selectedObjectId = tracked_object_selections?.[0] ?? 0;

  const isShowAllStatus = planning_reasoning_agent_selected === "Show All";
  const isSelectedStatus =
    planning_reasoning_agent_selected === "Selected Object";

  const reasonerDebug = speedReasoningDebug?.reasonerDebug;

  const showAgents = {
    agents: chain(speedReasoningDebug.predictionDecisionDebug)
      .filter((agent) => {
        const isSelected =
          isSelectedStatus && `${agent.objectId}` === selectedObjectId;
        const isIgnored = isFilterIgnoredAgent && agent.ignoreReason !== "NA";
        return (isShowAllStatus || isSelected) && !isIgnored;
      })
      .value(),
    ReasonersDebug: getReasonersDebug(
      reasonerDebug,
      isShowAllStatus,
      Number(selectedObjectId),
    ),
    ReasoningInputDebug: getReasoningInputDebug(
      speedReasoningDebug?.inputDebug,
      isShowAllStatus,
      Number(selectedObjectId),
    ),
    WorldContextDebug: speedReasoningDebug?.worldContext,
    TrajectoryInfoDebug: speedReasoningDebug?.trajectoryInfo,
    HallucinatedAgentManagerDebug: (
      speedReasoningDebug as unknown as SpeedReasoningDebug
    )?.hallucinatedAgentManagerDebug,
  };

  const trafficLightInfo =
    speedReasoningDebug?.reasonerDebug.trafficLightReasoner.trafficLightInfo ??
    [];
  const trafficLight: Record<string, unknown> = {};
  forEach(trafficLightInfo, (debug) => {
    if (!debug) {
      return;
    }
    const key = `light_id: ${debug.trafficLightId} lane_id: ${debug.controlledLaneId}`;
    trafficLight[key] = debug;
    trafficLight[key] = {
      Color: debug.color,
      "Pre Color": debug.preColor,
      "Is Flashing": debug.isFlashing ? "Yes" : "No",
      "Is Occluded": debug.isOccluded ? "Yes" : "No",
      "Is Broken": debug.isBroken ? "Yes" : "No",
      "Watch Line": debug.useWatchLine ? "Used" : "Not Used",
      "debug str": debug.debugStr,
      "Spatial Info": {
        "Stop Line Start Arclength":
          debug.trafficLightSpatialInfo?.stopLineStartRaArclength ?? null,
        "Conflicting Zone Arclength Start":
          debug.trafficLightSpatialInfo?.conflictingZoneRaArclength?.startPos ??
          null,
        "Conflicting Zone Arclength End":
          debug.trafficLightSpatialInfo?.conflictingZoneRaArclength?.endPos ??
          null,
        "Watch Line Arclength":
          debug.trafficLightSpatialInfo?.watchLineRaArclength ?? null,
        "Crosswalk Arclength Start":
          debug.trafficLightSpatialInfo?.crosswalkRaArclength?.startPos ?? null,
        "Crosswalk Arclength End":
          debug.trafficLightSpatialInfo?.crosswalkRaArclength?.endPos ?? null,
      },
      "Temporal Info": {
        "Green Light Start":
          debug.trafficLightTemporalInfoCommon?.greenTemporalRange?.start ??
          null,
        "Green Light End":
          debug.trafficLightTemporalInfoCommon?.greenTemporalRange?.end ?? null,
        "Green Light Flashing Start":
          debug.trafficLightTemporalInfoCommon?.greenFlashingTemporalRange
            ?.start ?? null,
        "Green Light Flashing End":
          debug.trafficLightTemporalInfoCommon?.greenFlashingTemporalRange
            ?.end ?? null,
        "Yellow Light Start":
          debug.trafficLightTemporalInfoCommon?.yellowTemporalRange?.start ??
          null,
        "Yellow Light End":
          debug.trafficLightTemporalInfoCommon?.yellowTemporalRange?.end ??
          null,
        "Red Light Start":
          debug.trafficLightTemporalInfoCommon?.redTemporalRange?.start ?? null,
        "Red Light End":
          debug.trafficLightTemporalInfoCommon?.redTemporalRange?.end ?? null,
        "Unknown Light Start":
          debug.trafficLightTemporalInfoCommon?.unknownTemporalRange?.start ??
          null,
        "Unknown Light End":
          debug.trafficLightTemporalInfoCommon?.unknownTemporalRange?.end ??
          null,
      },
    };
  });

  const cautiousDriving =
    speedReasoningDebug?.reasonerDebug?.cautiousDrivingReasoner?.agents;

  const occlusion =
    speedReasoningDebug?.reasonerDebug?.occlusionReasoner?.hallucinatedAgents;

  const hallucinatedAgentManager = (
    speedReasoningDebug as unknown as SpeedReasoningDebug
  )?.hallucinatedAgentManagerDebug;

  return {
    showAgents,
    trafficLight,
    cautiousDriving,
    occlusion,
    hallucinatedAgentManager,
  };
};

function getReasoningInputDebug(
  reasonerDebug: Messages.planner__speed__pb__ReasoningInputDebug,
  isShowAllStatus: boolean,
  selectedObjectId: number,
) {
  if (isShowAllStatus) {
    return reasonerDebug;
  }

  if (reasonerDebug.reasoningObjects) {
    return {
      ...reasonerDebug,
      reasoningObjects: filter(
        reasonerDebug.reasoningObjects ?? [],
        (reasoningObject) => reasoningObject.objectId === selectedObjectId,
      ),
    };
  }

  return reasonerDebug;
}

function getReasonersDebug(
  reasonerDebug: Messages.planner__speed__pb__ReasonersDebug,
  isShowAllStatus: boolean,
  selectedObjectId: number,
) {
  if (isShowAllStatus) {
    return reasonerDebug;
  }
  return {
    ...reasonerDebug,
    cautiousDrivingReasoner: {
      ...reasonerDebug?.cautiousDrivingReasoner,
      agents: filter(
        reasonerDebug?.cautiousDrivingReasoner?.agents ?? [],
        (agent) => agent.objectId === selectedObjectId,
      ),
    },
    crossAgentReasoner: {
      ...reasonerDebug?.crossAgentReasoner,
      agents: filter(
        reasonerDebug?.crossAgentReasoner?.agents ?? [],
        (agent) => agent.objectId === selectedObjectId,
      ),
    },
    laneChangeSpeedReasoner: {
      ...reasonerDebug?.laneChangeSpeedReasoner,
      interestedObjects: filter(
        reasonerDebug?.laneChangeSpeedReasoner?.interestedObjects ?? [],
        (id) => id === selectedObjectId,
      ),
    },
    leadAndMergeReasoner: {
      ...reasonerDebug?.leadAndMergeReasoner,
      agents: filter(
        reasonerDebug?.leadAndMergeReasoner?.agents ?? [],
        (agent) => agent.objectId === selectedObjectId,
      ),
    },
    oncomingAgentReasoner: {
      ...reasonerDebug?.oncomingAgentReasoner,
      agents: filter(
        reasonerDebug?.oncomingAgentReasoner?.agents ?? [],
        (agent) => agent.objectId === selectedObjectId,
      ),
    },
    tailgaterReasoner: {
      ...reasonerDebug?.tailgaterReasoner,
      agents: filter(
        reasonerDebug?.tailgaterReasoner?.agents ?? [],
        (agent) => agent.agentId === selectedObjectId,
      ),
    },
    vruReasoner: {
      ...reasonerDebug?.vruReasoner,
      agentDebugs: filter(
        reasonerDebug?.vruReasoner?.agentDebugs ?? [],
        (agent) => agent.objectId === selectedObjectId,
      ),
    },
  };
}

