978bff8a-df7e-4943-a85b-2b0db8e992ef.sourceCode:
/**
 * @file https://cooper.didichuxing.com/docs2/document/2202547566417
 * @remark refactor by jinfangfang
 */
/* eslint-disable @typescript-eslint/no-unnecessary-condition */
import {
  createDeleteAllActionMarker,
  AresMarker,
  AresMarkerTypes,
  createAresMarker,
  Point,
} from "@ares-utils";
import { Input, Messages } from "@vitruvian/voyager-type";
import { Messages as rosMessages } from "ros";

type Inputs = {
  "/planning/planning_debug": Input<"/planning/planning_debug">;
};

type Output = Messages.visualization_msgs__MarkerArray;

type SpeedReasoningDebug = {
  hallucinatedAgentManagerDebug: {
    occlusionAreas: {
      contour: Point[];
      occludedPoints: Point[];
    }[];
  };
};

export const inputs = ["/planning/planning_debug"];
export const config = {
  datatype: "visualization_msgs/MarkerArray",
};

export const output = "/studio_node/planning/occlusion/occlusion_areas_all";

const topicKey = "/planning/planning_debug";
export const publisher = (messages: Inputs): Output => {
  const message = messages[topicKey];
  const {
    receiveTime,
    message: { pose, behaviorReasonerDebug },
  } = message;
  const occlusion_area_markers: AresMarker[] = [
    createDeleteAllActionMarker(receiveTime),
  ];

  if (!message) {
    return {
      markers: occlusion_area_markers,
    };
  }

  const speedGeneratorDebug = behaviorReasonerDebug?.decoupledManeuvers?.[0]
    ?.singleLaneSequencePlanDebug[0]?.singleIntentionPlanDebug?.[0]
    ?.speedGeneratorDebug as rosMessages.speed__pb__SpeedGeneratorDebug;

  const occlusion_areas =
    (speedGeneratorDebug?.speedReasoningDebug as unknown as SpeedReasoningDebug)
      ?.hallucinatedAgentManagerDebug?.occlusionAreas ?? [];

  occlusion_areas.forEach((occlusion_area, idx) => {
    if (!occlusion_area) {
      return;
    }

    const borders = createAresMarker({
      header: {
        frame_id: "world",
        stamp: receiveTime,
        seq: 0,
      },
      type: AresMarkerTypes.LINE_STRIP,
      action: 0,
      flattenedPoints: getLoopedFlattenedPoints(occlusion_area.contour, pose.z),
      color: {
        r: 1,
        g: 0,
        b: 1,
        a: 1.0,
      },
      id: `occlusion_area_all_border_${idx}`,
    });
    const lineMetadata: Messages.ares__LineMetadata = {
      lineWidth: 0.3,
      lineType: Messages.ares__LineType.Tube,
    };
    Object.assign(borders, { lineMetadata }); // Close the loop of the

    // Merge the occlusion area border maker to occlusion area markers.
    occlusion_area_markers.push(borders);

    // Create the marker list in POINT for the occluded points in the
    // occlusion area. The occluded points shown are those may place
    // hallucinated agents.
    const occluded_point_markers: AresMarker[] =
      occlusion_area.occludedPoints.map((point, index) => {
        return createAresMarker({
          header: {
            frame_id: "world",
            stamp: receiveTime,
            seq: 0,
          },
          type: AresMarkerTypes.POINT,
          action: 0,
          pose: {
            position: { x: point.x, y: point.y, z: pose.z },
            orientation: { x: 0, y: 0, z: 0, w: 0 },
          },
          ns: "occluded_points_all",
          id: `occluded_points_all_${10000 * idx + index}`,
          color: {
            r: 1,
            g: 0,
            b: 1,
            a: 1.0,
          },
          metadata: { pointRadius: 0.3 },
        });
      });

    // Merge occluded point markers to occlusion area markers.
    Array.prototype.push.apply(occlusion_area_markers, occluded_point_markers);
  });

  return {
    markers: occlusion_area_markers,
  };
};

export function getLoopedFlattenedPoints(
  points: { x: number; y: number; z?: number }[],
  overrideZ?: number,
): Float32Array {
  const vertexCount =
    points.length >= 3 ? Number(points.length) + 1 : points.length;
