import {
  createDeleteCurrentTopicMarkers,
  DEFAULT_STUDIO_NODE_PREFIX,
  LidarDetectedMapElementType,
} from "@ares-utils";
import { Input, Messages } from "@vitruvian/voyager-type";
import { Point2D } from "./types";

export const inputs = ["/mapping/map_change_area_list"];
export const output = "/studio_node/map/change_area_fuser/map_change_area";
export const config = {
  needFrameData: false,
};

const COLOR_1 = {
  a: 0.75,
  r: 0,
  g: 0.62,
  b: 1,
};

const COLOR_2 = {
  a: 1,
  r: 1,
  g: 0, // 0.5
  b: 0, // 0.5
};

const kOutputCZFillColor = { r: 1.0, g: 0.6, b: 0.2, a: 0.0 }; // a 0.3

const publisher = (
  messages: Record<string, Input<"/mapping/map_change_area_list">>,
): Messages.ares__VisualizationMarkerArray | undefined => {
  const message = messages["/mapping/map_change_area_list"];
  if (!message) {
    return undefined;
  }

  const {
    receiveTime,
    message: {
      constructionZonesRealTimeMap,
      carPose: { z },
    },
  } = message;

  const markers: Messages.ares__VisualizationMarker[] =
    constructionZonesRealTimeMap.flatMap((constructionZone) => {
      const id = `map_change_area_${constructionZone.id}`;
      const zoneTypeText =
        constructionZone.spaceType === "OCCUPANCY"
          ? constructionZone.semanticType === "NOT_GIVEN"
            ? ""
            : `, ${constructionZone.semanticType}`
          : "";

      return [
        {
          header: { frame_id: "world", seq: 0, stamp: receiveTime },
          type: Messages.ares__VisualizationMarkerTypes.SHAPE,
          ns: "construction_zone",
          id,
          points: constructionZone.zone.points.map((point) => {
            return { ...point, z: 0.0 };
          }),
          fill: true,
          color: COLOR_1,
          edge: true,
          edgeColor: COLOR_2,
          enableInteraction: true,
        },
        {
          header: { frame_id: "world", seq: 0, stamp: receiveTime },
          type: Messages.ares__VisualizationMarkerTypes.TEXT,
          ns: "understanding_occupancy_space",
          id: `understanding_occupancy_space_zone_source_${constructionZone.id}` as any,
          pose: {
            position: {
              ...getPointsCenter2D(constructionZone.zone.points),
              z,
            },
            orientation: { x: 0, y: 0, z: 0, w: 1 },
          },
          color:
            constructionZone.spaceType === "CONSTRUCTION_ZONE"
              ? kOutputCZFillColor
              : { r: 0.5, g: 0.84, b: 0.0, a: 0.0 },
          textMetadata: {
            text: `${
              ZONE_SOURCES[
                constructionZone.zoneSource as keyof typeof ZONE_SOURCES
              ]
            }, rtmap id: ${constructionZone.originalRtmId}`,
            textStyle: {
              transform: "scale(0.8)",
              lineHeight: "10px",
            },
          },
        },
      ];
    });

  markers.unshift(createDeleteCurrentTopicMarkers(receiveTime));

  return {
    markers,
  };
};

export default publisher;

/**
 * zoneSource 对应的 text 映射表
 * http://git.xiaojukeji.com/av/voyager/blob/master/onboard/common/voy_protos/construction_zones.proto
 */
const ZONE_SOURCES = {
  ONBOARD_PERCEPTION_ONLY: "MapCA Onboard",
  REAL_TIME_MAP_ONLY: "MapCA RTM",
  FUSED: "MapCA Fused",
};

function getPointsCenter2D(points: Point2D[]): Point2D {
  const x = sum(points.map((point) => point.x)) / points.length;
  const y = sum(points.map((point) => point.y)) / points.length;
  return { x, y };
}

function sum(list: number[]): number {
  return list.reduce((s, n) => s + n);
}

