// This Source Code Form is subject to the terms of the Mozilla Public
// License, v2.0. If a copy of the MPL was not distributed with this
// file, You can obtain one at http://mozilla.org/MPL/2.0/

/* ares-expose-source-code */
import {
  GlobalVariables,
  DEFAULT_STUDIO_NODE_PREFIX,
  getSingleLaneSequencePlanDebug,
} from "@ares-utils";
import { Input, Messages } from "ros";
import { forEach } from "lodash";

export const inputs = ["/planning/planning_debug"];
export const config = {
  datatype: "voyager_data_msgs/CustomData",
  showOn3DPanel: false,
};
export const output = `${DEFAULT_STUDIO_NODE_PREFIX}planning/planning_debug/super_nudge`;

export const publisher = (
  messages: Record<string, Input<"/planning/planning_debug">>,
  globalVars: GlobalVariables,
): Messages.voyager_data_msgs__CustomData => {
  const message_p = messages[
    "/planning/planning_debug"
  ] as Input<"/planning/planning_debug">;

  const {
    message: { behaviorReasonerDebug },
  } = message_p;

  const singleLaneSequencePlanDebug = getSingleLaneSequencePlanDebug(
    behaviorReasonerDebug,
    globalVars,
  );

  if (!singleLaneSequencePlanDebug) {
    return {};
  }

  const unstuckDebug = singleLaneSequencePlanDebug?.unstuckDebug;
  const stuckRegions = unstuckDebug?.stuckRegions ?? [];

  return {
    unstuckStates: getUnstuckStates(unstuckDebug),
    stuckRegions: getStuckRegions(stuckRegions),
    xLaneNudgeStates: getXLaneNudgeStates(unstuckDebug),
  };
};

function getXLaneNudgeSideVotes(
  voteDebug: Messages.planner__pb__XLaneNudgeSideVoterDebug,
) {
  let left_total_vote_num = 0;
  let right_total_vote_num = 0;
  if (voteDebug && voteDebug?.voteResults) {
    voteDebug.voteResults.forEach((judgeVote) => {
      left_total_vote_num += judgeVote.leftSideVoteCount;
      right_total_vote_num += judgeVote.rightSideVoteCount;
    });
  }
  return {
    leftTotalVoteNum: left_total_vote_num,
    rightTotalVoteNum: right_total_vote_num,
  };
}

function getXLaneNudgeStates(unstuckDebug: Messages.planner__pb__UnstuckDebug) {
  if (
    !unstuckDebug?.leftXlaneNudgeDebug &&
    !unstuckDebug.rightXlaneNudgeDebug
  ) {
    return [];
  }
  const leftLabel = "Left-Side";
  const rightLabel = "Right-Side";
  let states = [
    { " ": "Overtake Mode", [leftLabel]: "", [rightLabel]: "" },
    { " ": "Trigger Status", [leftLabel]: "", [rightLabel]: "" },
    { " ": "Required Offset", [leftLabel]: "", [rightLabel]: "" },
    { " ": "Trimmable", [leftLabel]: "", [rightLabel]: "" },
    { " ": "Overtake Policy", [leftLabel]: "", [rightLabel]: "" },
    { " ": "Votes", [leftLabel]: "", [rightLabel]: "" },
  ];
  const voteResult = getXLaneNudgeSideVotes(
    unstuckDebug?.xlaneNudgeSideVoterDebug,
  );
  if (unstuckDebug.leftXlaneNudgeDebug) {
    states[0]![leftLabel] = unstuckDebug.leftXlaneNudgeDebug.mode;
    states[1]![leftLabel] = `${unstuckDebug.leftXlaneNudgeDebug.type}`;
    states[2]![leftLabel] =
      `${unstuckDebug.leftXlaneNudgeDebug.requiredOffset}`;
    states[3]![leftLabel] =
      `${unstuckDebug.leftXlaneNudgeDebug?.couldBeTrimmed ?? ""}`;
    states[4]![leftLabel] =
      `${unstuckDebug.leftXlaneNudgeDebug?.policy ?? "None"}`;
    states[5]![leftLabel] = `${voteResult.leftTotalVoteNum}`;
  }
  if (unstuckDebug.rightXlaneNudgeDebug) {
    states[0]![rightLabel] = unstuckDebug.rightXlaneNudgeDebug.mode;
    states[1]![rightLabel] = `${unstuckDebug.rightXlaneNudgeDebug.type}`;
    states[2]![rightLabel] =
      `${unstuckDebug.rightXlaneNudgeDebug.requiredOffset}`;
    states[3]![rightLabel] =
      `${unstuckDebug.rightXlaneNudgeDebug?.couldBeTrimmed ?? ""}`;
    states[4]![rightLabel] =
      `${unstuckDebug.rightXlaneNudgeDebug?.policy ?? "None"}`;
    states[5]![rightLabel] = `${voteResult.rightTotalVoteNum}`;
  }

  // Append judge vote details.
  if (
    unstuckDebug?.xlaneNudgeSideVoterDebug &&
    unstuckDebug.xlaneNudgeSideVoterDebug?.voteResults
  ) {
    unstuckDebug?.xlaneNudgeSideVoterDebug.voteResults.forEach((judgeDebug) => {
      if (
        judgeDebug.leftSideVoteCount !== 0 ||
        judgeDebug.rightSideVoteCount !== 0
      ) {
        states.push({
          " ": `${judgeDebug.judgeName}`,
          [leftLabel]: `${judgeDebug.leftSideVoteCount}`,
          [rightLabel]: `${judgeDebug.rightSideVoteCount}`,
        });
      }
    });
  }
  return states;
}

function getUnstuckStates(unstuckDebug: Messages.planner__pb__UnstuckDebug) {
  const unstuckStates = [];
  const wasEgoStuckText = "Was ego stuck";
  const wasEgoStuck = unstuckDebug?.wasEgoStuck ? "true" : "false";
  unstuckStates.push({
    [wasEgoStuckText]: "Was x-lane nudging",
    [wasEgoStuck]: unstuckDebug?.wasXlaneNudging ? "true" : "false",
  });
  unstuckStates.push({
    [wasEgoStuckText]: "Is boundary extended",
    [wasEgoStuck]: unstuckDebug?.isBoundaryExtended ? "true" : "false",
  });

  return unstuckStates;
}

function getStuckRegions(stuckRegions: Messages.planner__pb__StuckRegion[]) {
  const stuckRegionsData: Record<string, string | number>[] = [];
  forEach(stuckRegions, (stuckRegion) => {
    forEach(stuckRegion.stuckObjects, (stuchObject) => {
      stuckRegionsData.push({
        "Object Id": stuchObject.objectId,
        "Object Type": stuchObject.objectType,
      });
    });
  });
  return stuckRegionsData;
}

