import {
  GlobalVariables,
  DEFAULT_STUDIO_NODE_PREFIX,
  getIntentionPlanDebug,
  getSpeedSolverDebugIndex,
} from "@ares-utils";
import { Input, Messages } from "@vitruvian/voyager-type";
import { forEach } from "lodash";

export const inputs = ["/planning/planning_debug"];
export const config = {
  datatype: "voyager_data_msgs/CustomData",
  showOn3DPanel: false,
};
export const output = `${DEFAULT_STUDIO_NODE_PREFIX}planning/speed_optimizer`;

export const publisher = (
  messages: Record<string, Input<"/planning/planning_debug">>,
  globalVariables: GlobalVariables,
): Messages.voyager_data_msgs__CustomData => {
  const planningDebugMessage = messages[
    "/planning/planning_debug"
  ] as Input<"/planning/planning_debug">;
  if (!planningDebugMessage) {
    return {};
  }

  const { behaviorReasonerDebug } = planningDebugMessage.message;

  const intentionPlanDebug = getIntentionPlanDebug(
    behaviorReasonerDebug,
    globalVariables,
  );
  if (!intentionPlanDebug) {
    return {};
  }

  const speedGeneratorDebug =
    intentionPlanDebug?.speedGeneratorDebug as Messages.planner__speed__pb__SpeedGeneratorDebug;

  const speedSolverDebugIndex = getSpeedSolverDebugIndex(
    behaviorReasonerDebug,
    globalVariables,
  );

  const speedSolverDebug =
    speedGeneratorDebug?.speedSolverDebugs[speedSolverDebugIndex];

  if (!speedSolverDebug) {
    return {};
  }
  const { optDebug: speedOptDebug } = speedSolverDebug;
  let optimizerIteration: Record<string, unknown> = { " ": "NoOpt" };

  let optimizationStates = [];

  let optimizationCost: Record<string, number[]> = {
    totalCost: [],
    stateBarrierCost: [],
    stateStaticRangeCost: [],
    accelBarrierCost: [],
    jerkBarrierCost: [],
    minSpeedBarrierCost: [],
    maxSpeedBarrierCost: [],
    maxSpeedRepellerCost: [],
    accelEffortCost: [],
    jerkEffortCost: [],
    lateralAccelEffortCost: [],
    lateralJerkRepellerCost: [],
    speedAttractorCost: [],
    lengthAttractorCost: [],
    followerAttractorCost: [],
    jerkAttractorCost: [],
    dynamicRangeCost: [],
    proximitySpeedCost: [],
    passDynamicRangeCost: [],
  };

  if (!speedOptDebug) {
    for (const key in optimizationCost) {
      optimizationCost[key] = [-1];
    }
    return {
      optimizerIteration,
      optimizationStates,
      optimizationCost,
      optDebug: speedOptDebug,
    };
  }

  optimizationStates = speedOptDebug?.optimizedProfile?.states ?? [];

  optimizerIteration[" "] = `Optimization ${
    speedOptDebug.optimizationResult === "kConverge" ? "converged" : "failed"
  } after ${speedOptDebug.allIterCosts.length} iterations`;

  const showWarmStartCost =
    globalVariables.planning_speed_profile_show_warm_start_cost;

  forEach(
    showWarmStartCost
      ? (speedOptDebug?.warmStartDebug?.warmStartCosts ?? [])
      : (speedOptDebug?.allIterCosts ?? []),
    (iteration, index) => {
      optimizerIteration[`Iteration ${index + 1}`] = iteration;
      Object.keys(iteration).forEach((attribute) => {
        const cost =
          iteration[
            attribute as keyof Messages.planner__speed__pb__SingleIterationCost
          ];
        if (attribute in optimizationCost) {
          optimizationCost[attribute]!.push(cost);
        }
      });
    },
  );

  return {
    optimizerIteration,
    optimizationStates,
    optimizationCost,
    optDebug: speedOptDebug,
  };
};

