/* ares-expose-source-code */
/* eslint-disable @typescript-eslint/no-unnecessary-condition */
import {
  GlobalVariables,
  DEFAULT_STUDIO_NODE_PREFIX,
  getIntentionPlanDebug,
  getGroupsValues,
  transGroupName,
  getTrajectoryCostingProtoColors,
  TrajectoryCostingProto,
  getTrajectoryCostingProto,
} from "@ares-utils";
import { Input, Messages } from "@vitruvian/voyager-type";

// onboard/common/voy_protos/control_util.proto
// 过滤掉了部分枚举字段，原因是不用了，但是proto没有废弃 @caohuanhui
// 该枚举定义在featureCosting中也有，为保持featureCosting和featureTotalCosting的plot的参数的一致性，如需修改需同时修改
export const trajectoryCostingProtoArr: TrajectoryCostingProto[] = [
  // Constraint-related features.
  {
    name: "CONSTRAINT_KAPPA",
    value: 0,
  },
  {
    name: "CONSTRAINT_ETA",
    value: 1,
  },
  {
    name: "CONSTRAINT_GAMMA",
    value: 17,
  },
  {
    name: "CONSTRAINT_APPROXIMATE_LATERAL_ACCEL",
    value: 10,
  },
  {
    name: "CONSTRAINT_APPROXIMATE_LATERAL_JERK",
    value: 35,
  },
  {
    name: "CONSTRAINT_TERMINAL_HEADING",
    value: 42,
  },
  {
    name: "CONSTRAINT_APPROXIMATE_STEERING_ACCEL",
    value: 43,
  },
  {
    name: "CONSTRAINT_APPROXIMATE_STEERING_RATE",
    value: 45,
  },
  // Effort-related features.
  {
    name: "EFFORT_KAPPA",
    value: 2,
  },
  {
    name: "EFFORT_ETA",
    value: 3,
  },
  {
    name: "EFFORT_GAMMA",
    value: 16,
  },
  {
    name: "EFFORT_APPROXIMATE_LATERAL_ACCEL",
    value: 11,
  },
  {
    name: "EFFORT_APPROXIMATE_LATERAL_JERK",
    value: 34,
  },
  {
    name: "EFFORT_APPROXIMATE_STEERING_RATE",
    value: 37,
  },
  {
    name: "EFFORT_APPROXIMATE_STEERING_ACCEL",
    value: 36,
  },
  {
    name: "PRIMITIVE_VIOLATION_LEFT_NUDGE_CORRIDOR",
    value: 7,
  },
  {
    name: "PRIMITIVE_VIOLATION_RIGHT_NUDGE_CORRIDOR",
    value: 8,
  },
  // Semantic corridor violation primitive.
  {
    name: "PRIMITIVE_VIOLATION_LEFT_PHYSICAL_BOUNDARY",
    value: 26,
  },
  {
    name: "PRIMITIVE_VIOLATION_RIGHT_PHYSICAL_BOUNDARY",
    value: 27,
  },
  {
    name: "PRIMITIVE_VIOLATION_LEFT_VIRTUAL_HARD_BOUNDARY",
    value: 28,
  },
  {
    name: "PRIMITIVE_VIOLATION_RIGHT_VIRTUAL_HARD_BOUNDARY",
    value: 29,
  },
  {
    name: "PRIMITIVE_VIOLATION_LEFT_VIRTUAL_SOFT_BOUNDARY",
    value: 30,
  },
  {
    name: "PRIMITIVE_VIOLATION_RIGHT_VIRTUAL_SOFT_BOUNDARY",
    value: 31,
  },
  {
    name: "PRIMITIVE_VIOLATION_LEFT_PURE_VIRTUAL_BOUNDARY",
    value: 32,
  },
  {
    name: "PRIMITIVE_VIOLATION_RIGHT_PURE_VIRTUAL_BOUNDARY",
    value: 33,
  },
  // Primitive soft features.
  {
    name: "PRIMITIVE_SOFT_NOMINAL_PATH_ATTRACTION",
    value: 6,
  },
  {
    name: "PRIMITIVE_SOFT_NOMINAL_PATH_HEADING_ATTRACTION",
    value: 46,
  },
  {
    name: "PRIMITIVE_SOFT_NOMINAL_PATH_CURVATURE_ATTRACTION",
    value: 47,
  },
  {
    name: "PRIMITIVE_SOFT_LEFT_NUDGE_CORRIDOR",
    value: 21,
  },
  {
    name: "PRIMITIVE_SOFT_RIGHT_NUDGE_CORRIDOR",
    value: 22,
  },
  {
    name: "PRIMITIVE_SOFT_LEFT_RISK_PHYSICAL_BOUNDARY",
    value: 40,
  },
  {
    name: "PRIMITIVE_SOFT_RIGHT_RISK_PHYSICAL_BOUNDARY",
    value: 41,
  },
  {
    name: "PRIMITIVE_SOFT_ATTRACTION_SEGMENTS",
    value: 44,
  },
];

export const inputs = ["/planning/planning_debug"];

export const output = `${DEFAULT_STUDIO_NODE_PREFIX}planning/path_smoother/feature_total_costing`;

export const config = {
  datatype: "voyager_data_msgs/CustomData",
  showOn3DPanel: false,
};

export const publisher = (
  messages: Record<string, Input<"/planning/planning_debug">>,
  globalVars: GlobalVariables,
): Messages.voyager_data_msgs__CustomData => {
  const message = messages[
    "/planning/planning_debug"
  ] as Input<"/planning/planning_debug">;
  const {
    message: { behaviorReasonerDebug },
  } = message;

  const TRAJECTORY_COSTING_PROTO_COLORS = getTrajectoryCostingProtoColors(
    trajectoryCostingProtoArr,
  );

  const intentionPlanDebug = getIntentionPlanDebug(
    behaviorReasonerDebug,
    globalVars,
  );

  const iterations =
    intentionPlanDebug?.pathPlannerDebug?.pathSmootherDebug?.pathSolverDebug
      ?.iterations ?? [];

  const trajectoryCostingProto = getTrajectoryCostingProto(
    trajectoryCostingProtoArr,
  );

  const featureTotalCosting: Record<string, number[]> = {};

  iterations.forEach((iteration, index) => {
    const featuresTotalCostMap = iteration.solution.costing
      ?.featuresTotalCostMap as unknown as Record<string, number>;
    Object.entries(featuresTotalCostMap ?? {}).forEach(([costIndex, cost]) => {
      const featuresTotalCostKey = trajectoryCostingProto[costIndex];
      if (featuresTotalCostKey) {
        if (!featureTotalCosting[featuresTotalCostKey]) {
          featureTotalCosting[featuresTotalCostKey] = [];
        }
        featureTotalCosting[featuresTotalCostKey]![index] = cost;
      }
    });
  });

  // NOTE(path): huanhui comment: Add warmstart total cost into |featureTotalCosting|, it always corresponds to the cost of iterations[0]. Since we haven't stored these costs in iterations[0] repeatedly, so we visualize them using warmstart debug info.
  const warmstart_candidates =
    intentionPlanDebug?.pathPlannerDebug?.pathSmootherDebug
      ?.pathWarmstarterDebug?.candidates ?? [];
  const warmstart_best_type =
    intentionPlanDebug?.pathPlannerDebug?.pathSmootherDebug
      ?.pathWarmstarterDebug?.bestType;
  for (const candidate of warmstart_candidates) {
    if (candidate.type === warmstart_best_type) {
      const featuresTotalCostMap = candidate.solution.costing
        ?.featuresTotalCostMap as unknown as Record<string, number>;
      Object.entries(featuresTotalCostMap ?? {}).forEach(
        ([costIndex, cost]) => {
          const featuresTotalCostKey = trajectoryCostingProto[costIndex];
          if (featuresTotalCostKey) {
            if (!featureTotalCosting[featuresTotalCostKey]) {
              featureTotalCosting[featuresTotalCostKey] = [];
            }
            featureTotalCosting[featuresTotalCostKey]![0] = cost;
          }
        },
      );
      break;
    }
  }

  const validFeatureTotalCosting: Record<string, number[]> = {};

  Object.entries(featureTotalCosting).forEach(([key, values]) => {
    const newValues = Array(values.length).fill(NaN);
    values.forEach((value, index) => {
      newValues[index] = value;
    });
    validFeatureTotalCosting[key] = newValues;
  });

  const groupsValues = getGroupsValues(validFeatureTotalCosting);

  const validGroupsValues = transGroupName(groupsValues);

  const featureTotalCostingPlotValue = Object.assign(validGroupsValues, {
    color: TRAJECTORY_COSTING_PROTO_COLORS,
  });
  return featureTotalCostingPlotValue;
};

