/* eslint-disable @typescript-eslint/no-unnecessary-condition */
// This Source Code Form is subject to the terms of the Mozilla Public
// License, v2.0. If a copy of the MPL was not distributed with this
// file, You can obtain one at http://mozilla.org/MPL/2.0/

import {
  getIntentionPlanDebug,
  GlobalVariables,
  DEFAULT_STUDIO_NODE_PREFIX,
} from "@ares-utils";
import { Input, Messages } from "@vitruvian/voyager-type";
import { forEach } from "lodash";

export const inputs = ["/planning/planning_debug"];
export const output = `${DEFAULT_STUDIO_NODE_PREFIX}planning/sl_drivable_space_plot`;
export const config = {
  datatype: "voyager_data_msgs/CustomData",
  showOn3DPanel: false,
};

export const publisher = (
  messages: Record<string, Input<"/planning/planning_debug">>,
  globalVars: GlobalVariables,
): Messages.voyager_data_msgs__CustomData | undefined => {
  const message_p = messages[
    "/planning/planning_debug"
  ] as Input<"/planning/planning_debug">;

  const message = message_p.message;
  if (!message) {
    return;
  }

  const pathPlannerDebug = getIntentionPlanDebug(
    message.behaviorReasonerDebug,
    globalVars,
  );

  if (!pathPlannerDebug) {
    return;
  }

  return getSLDrivableSpacePlotConfig(pathPlannerDebug);
};

type SLDrivableSpacePlot = {
  solutionsLines: Messages.ares__CustomizationPlotData["lines"];
  baseLayerLines: Messages.ares__CustomizationPlotData["lines"];
  borderRegionLines: Messages.ares__CustomizationPlotData["lines"];
  drivableRangesLines: Messages.ares__CustomizationPlotData["lines"];
  clearanceRangeLines: Messages.ares__CustomizationPlotData["lines"];
  sampleRangeLines: Messages.ares__CustomizationPlotData["lines"];
};

export function getSLDrivableSpacePlot(
  pathPlannerDebug: Messages.planner__pb__IntentionPlanDebug,
): SLDrivableSpacePlot {
  const stateLatticeDrivableSpaceDebug =
    pathPlannerDebug?.pathPlannerDebug?.pathSearcherDebug
      ?.stateLatticeSearchDebug.stateLatticeDrivableSpaceDebug;

  const pathSolutions =
    pathPlannerDebug?.pathPlannerDebug?.pathSearcherDebug
      ?.stateLatticeSearchDebug?.stateLatticeSearcherDebug.pathSolution;

  const lateralInfoDebugs =
    stateLatticeDrivableSpaceDebug?.lateralInfoDebugs ?? [];
  const maxLateralHorizonInMeter =
    stateLatticeDrivableSpaceDebug?.maxLateralHorizonInMeter;

  const baseLayerLines: Messages.ares__CustomizationPlotData["lines"] = [];
  const borderRegionLines: Messages.ares__CustomizationPlotData["lines"] = [];
  const drivableRangesLines: Messages.ares__CustomizationPlotData["lines"] = [];
  const clearanceRangeLines: Messages.ares__CustomizationPlotData["lines"] = [];
  const sampleRangeLines: Messages.ares__CustomizationPlotData["lines"] = [];

  forEach(lateralInfoDebugs, (debug) => {
    const {
      longitudinalSampleArcLength,
      leftBoundaryProximityDebug,
      rightBoundaryProximityDebug,
      feasibleRangesDebugs,
      latticeSampleRangeDebug,
    } = debug as any;

    const factorLeft = leftBoundaryProximityDebug?.boundaryProjScalingFactor;
    if (factorLeft < 1.0) {
      const distance = (factorLeft - 1.0) * 2 * maxLateralHorizonInMeter;
      borderRegionLines.push({
        line: [
          {
            x: longitudinalSampleArcLength,
            y: maxLateralHorizonInMeter + distance,
          },
          { x: longitudinalSampleArcLength, y: maxLateralHorizonInMeter },
        ],
      });
    }

    const factorRight = rightBoundaryProximityDebug?.boundaryProjScalingFactor;
    if (factorRight < 1.0) {
      const distance = (factorRight - 1.0) * 2 * maxLateralHorizonInMeter;
      borderRegionLines.push({
        line: [
          { x: longitudinalSampleArcLength, y: -maxLateralHorizonInMeter },
          {
            x: longitudinalSampleArcLength,
            y: -maxLateralHorizonInMeter - distance,
          },
        ],
      });
    }

    const yellowLine = [
      { x: longitudinalSampleArcLength, y: -maxLateralHorizonInMeter },
      { x: longitudinalSampleArcLength, y: maxLateralHorizonInMeter },
    ];
    baseLayerLines.push({
      line: yellowLine,
    });

    forEach(feasibleRangesDebugs, (feasibleDebug) => {
      const { rangeStartPosPt, rangeEndPosPt } = feasibleDebug;
      const {
        distToRayStart: startToRayStart,
        criticalRequiredLatGap: startGap,
      } = rangeStartPosPt;
      const { distToRayStart: endToRayStart, criticalRequiredLatGap: endGap } =
        rangeEndPosPt;

      const signed_rg_start = startToRayStart - maxLateralHorizonInMeter;
      const signed_rg_end = endToRayStart - maxLateralHorizonInMeter;

      const blueLine = [
        { x: longitudinalSampleArcLength, y: signed_rg_start },
        { x: longitudinalSampleArcLength, y: signed_rg_end },
      ];
      drivableRangesLines.push({
        line: blueLine,
      });

      const magentaLineStart = [
        { x: longitudinalSampleArcLength, y: signed_rg_start },
        { x: longitudinalSampleArcLength, y: signed_rg_start + startGap },
      ];
      clearanceRangeLines.push({
        line: magentaLineStart,
      });

      const magentaLineEnd = [
        { x: longitudinalSampleArcLength, y: signed_rg_end },
        { x: longitudinalSampleArcLength, y: signed_rg_end - endGap },
      ];

      clearanceRangeLines.push({
        line: magentaLineEnd,
      });
    });

    if (latticeSampleRangeDebug) {
      const { rangeStartPosPt, rangeEndPosPt } = latticeSampleRangeDebug;
      const {
        distToRayStart: startToRayStart,
        criticalRequiredLatGap: startGap,
      } = rangeStartPosPt;
      const { distToRayStart: endToRayStart, criticalRequiredLatGap: endGap } =
        rangeEndPosPt;

      const signed_rg_start = startToRayStart - maxLateralHorizonInMeter;
      const signed_rg_end = endToRayStart - maxLateralHorizonInMeter;

      const blueLine = [
        { x: longitudinalSampleArcLength, y: signed_rg_start },
        { x: longitudinalSampleArcLength, y: signed_rg_end },
      ];
      sampleRangeLines.push({
        line: blueLine,
      });
    }
  });

  const solutionsLines: Messages.ares__CustomizationPlotLine["line"] = [];
  forEach(pathSolutions, (solution) => {
    const { s, l } = solution;
    solutionsLines.push({ x: s, y: l - maxLateralHorizonInMeter });
  });

  return {
    solutionsLines: [
      {
        line: solutionsLines,
      },
    ],
    baseLayerLines,
    borderRegionLines,
    drivableRangesLines,
    clearanceRangeLines,
    sampleRangeLines,
  };
}

export function getSLDrivableSpacePlotConfig(
  pathPlannerDebug: Messages.planner__pb__IntentionPlanDebug,
): Record<keyof SLDrivableSpacePlot, Messages.ares__CustomizationPlotData> {
  const {
    solutionsLines,
    baseLayerLines,
    borderRegionLines,
    drivableRangesLines,
    clearanceRangeLines,
    sampleRangeLines,
  } = getSLDrivableSpacePlot(pathPlannerDebug);

  return {
    solutionsLines: {
      borderColor: "green",
      pointBackgroundColor: "green",
      pointRadius: 0,
      borderWidth: 2,
      lines: solutionsLines,
    },
    baseLayerLines: {
      borderColor: "white",
      pointBackgroundColor: "white",
      pointRadius: 0,
      lines: baseLayerLines,
    },
    borderRegionLines: {
      borderColor: "blue",
      pointBackgroundColor: "blue",
      pointRadius: 0,
      lines: borderRegionLines,
    },
    drivableRangesLines: {
      borderColor: "green",
      pointBackgroundColor: "green",
      pointRadius: 0,
      lines: drivableRangesLines,
    },
    clearanceRangeLines: {
      borderColor: "magenta",
      pointBackgroundColor: "magenta",
      pointRadius: 0,
      lines: clearanceRangeLines,
    },
    sampleRangeLines: {
      borderColor: "yellow",
      pointBackgroundColor: "yellow",
      pointRadius: 0,
      lines: sampleRangeLines,
    },
  };
}

