import { getPathPrimitivesDebug } from "@ares-utils";

type Output = string | undefined;
type GlobalVariables = { id: number };
type ScriptConfig = {
  // description: "Set whether to use all frame data"
  // tips: "Using all frame data will greatly affect the performance. Please use 'frontFrameLength' and 'behindFrameLength' to limit the data size"
  // default: true
  needFrameData?: boolean;

  // description: "set how many frames before the current frame will be transmitted"
  frontFrameLength?: number;
  // description: "set how many frames after the current frame will be transmitted"
  behindFrameLength?: number;
  // Whether this topic should be displayed on the switch tree of 3dPanel.
  showOn3DPanel?: boolean;
};
export const inputs = ["/planning/planning_debug"];
