import {
  GlobalVariables,
  DEFAULT_STUDIO_NODE_PREFIX,
  createDeleteCurrentTopicMarkers,
  COLOR_DEEP_SKY_BLUE,
  getSingleLaneSequencePlanDebug,
  getMarkersBySegments,
  variableConcat,
} from "@ares-utils";
import { Messages as rosMessages } from "ros";
import { Input, Messages } from "@vitruvian/voyager-type";
import { isNil } from "lodash";

export const inputs = ["/planning/planning_debug"];
export const output = `${DEFAULT_STUDIO_NODE_PREFIX}planning/behavior/agent_intention/narrow_meeting_road_boundary`;
export const config = {
  datatype: "ares/VisualizationMarkerArray",
};

export const publisher = (
  messages: Record<string, Input<"/planning/planning_debug">>,
  globalVars: GlobalVariables,
): Messages.ares__VisualizationMarkerArray | undefined => {
  const message = messages[
    "/planning/planning_debug"
  ] as Input<"/planning/planning_debug">;
  if (!message) {
    return;
  }
  const {
    message: { timestamp, behaviorReasonerDebug, pose },
  } = message;
  const singleLaneSequencePlanDebug = getSingleLaneSequencePlanDebug(
    behaviorReasonerDebug,
    globalVars,
  );

  // 如果没有 lane sequence 或者 pose 数据，直接返回
  if (!singleLaneSequencePlanDebug || isNil(pose)) {
    return;
  }

  const narrow_meeting_debug = (
    singleLaneSequencePlanDebug?.intentionGeneratorDebug
      ?.semanticContextDebug as
      | rosMessages.planner__pb__SemanticContextDebug
      | undefined
  )?.narrowMeetingDebug;

  const markers: Messages.ares__VisualizationMarker[] = [
    createDeleteCurrentTopicMarkers(message.receiveTime),
  ];
  if (!narrow_meeting_debug || isNil(pose)) {
    return {
      markers,
    };
  }

  const z = pose.z;

  const leftHardBoundaryMarkers = narrow_meeting_debug.leftBoundary
    ? getMarkersBySegments({
        segments: narrow_meeting_debug.leftBoundary.segments ?? [],
        id: `planning_behavior_agent_intention_left_hard_boundary`,
        timestamp,
        z,
        color: COLOR_DEEP_SKY_BLUE,
        lineWidth: 0.2,
      })
    : [];

  const rightHardBoundaryMarkers = narrow_meeting_debug.rightBoundary
    ? getMarkersBySegments({
        segments: narrow_meeting_debug.rightBoundary.segments ?? [],
        id: `planning_behavior_agent_intention_right_hard_boundary`,
        timestamp,
        z,
        color: COLOR_DEEP_SKY_BLUE,
        lineWidth: 0.2,
      })
    : [];

  return {
    markers: variableConcat(
      markers,
      leftHardBoundaryMarkers,
      rightHardBoundaryMarkers,
    ),
  };
};

