import { Input, Messages } from "ros";
import {
  GlobalVariables,
  ScriptConfig,
  MemoryCacheBlock,
  createDeleteCurrentTopicMarkers,
  getSingleLaneSequencePlanDebug,
} from "@ares-utils";

// These are the topics your script "subscribes" to. Ares will invoke your publisher function
// When any message is received on these topics.
// e.g. export const inputs: string[] = ["/pose", "/perception/tracked_object_list"]
export const inputs: string[] = ["/planning/planning_debug"];

// The name of the topic published
// When data is rendered in ImagePanel, the name must start with "/image_marker/"
// When data is rendered in 3DPanel, the name must start with "/studio_node/"
export const output: `/${"studio_node" | "image_marker"}/${string}` =
  "/studio_node/planning/behavior/agent_intention/narrow_meeting_feasible_regions";

// Configure the input and output when the code is executed
export const config: ScriptConfig = {};

/**
 * This function is called with messages from your input topics.
 * The first argument is an event with the topic, receive time, and message.

 * @param messages According to the topic subscribed by "inputs", pass in the message corresponding to the topic.
 * @remarks Use the `Input<topicName>` helper to get the correct event type for your input topic messages.
 * @example
 * message: {
 *   "/pose": Input<"/pose">,
 *   "/perception/tracked_object_list": Input<"/perception/tracked_object_list">
 * }
 *
 * @param globalVariables Variables that can be accessed anywhere in the program, based on which the interactivity of the visual content can be configured
 * @see {@link https://cooper.didichuxing.com/knowledge/2199628491086/2199761277479} for more information
 *
 * @param blocks According to the topic subscribed by "inputs", all the messages of the corresponding topic in the bag are passed in
 *
 * @return the return format of the data is based on datatype
 */
export const publisher = (
  messages: {
    "/planning/planning_debug": Input<"/planning/planning_debug">;
  },
  globalVars: GlobalVariables,
  blocks: readonly (MemoryCacheBlock | undefined)[],
): Messages.ares__VisualizationMarkerArray => {
  const planningDebug = messages["/planning/planning_debug"];
  const markers: Messages.ares__VisualizationMarker[] = [
    createDeleteCurrentTopicMarkers(planningDebug.receiveTime),
  ];
  if (!planningDebug) {
    return { markers };
  }

  const pose = planningDebug.message.pose;
  const singleLaneSequencePlanDebug = getSingleLaneSequencePlanDebug(
    planningDebug.message.behaviorReasonerDebug as any,
    globalVars,
  );
  if (!singleLaneSequencePlanDebug) {
    return { markers };
  }

  const narrow_meeting_debug = (
    singleLaneSequencePlanDebug?.intentionGeneratorDebug
      ?.semanticContextDebug as
      | Messages.planner__pb__SemanticContextDebug
      | undefined
  )?.narrowMeetingDebug;

  const feasible_regions = narrow_meeting_debug?.feasibleRegions ?? [];
  const optimal_feasible_region = narrow_meeting_debug?.optimalFeasibleRegion;
  const optimal_restricted_feasible_region =
    narrow_meeting_debug?.optimalFeasibleRegion.restrictedPolygon;

  if (feasible_regions.length === 0 && !optimal_feasible_region) {
    return { markers };
  }

  // purple
  const feasibleRegionFillColor = { r: 0.8, g: 0.6, b: 0.9, a: 0.5 };
  const feasibleRegionEdgeColor = { r: 0.5, g: 0.0, b: 0.5, a: 1.0 };
  // green
  const optimalRegionFillColor = { r: 0.4, g: 1.0, b: 0.4, a: 0.5 };
  const optimalRegionEdgeColor = { r: 0, g: 1.0, b: 0, a: 1.0 };
  let feasibleRegionPolygonZ = pose.z + 5.0;

  // Visualize all feasible regions except the optimal one
  feasible_regions.forEach((region, index) => {
    if (region.lonRange.startPos === optimal_feasible_region.lonRange.startPos)
      return; // Skip optimal region

    const polygonPoints = region.polygon.map((point) => ({
      ...point,
      z: feasibleRegionPolygonZ,
    }));

    const feasibleRegionMarker: Messages.ares__VisualizationMarker = {
      header: {
        stamp: planningDebug.receiveTime,
        frame_id: "world",
        seq: index,
      },
      id: `feasible_region_polygon_${index}`,
      type: Messages.ares__VisualizationMarkerTypes.SHAPE,
      points: polygonPoints,
      color: feasibleRegionFillColor,
      edgeColor: feasibleRegionEdgeColor,
      pose: { position: { x: 0.0, y: 0.0, z: feasibleRegionPolygonZ } },
      fill: true,
      edge: true,
    };

    markers.push(feasibleRegionMarker);
  });

  // Visualize the optimal feasible region
  if (optimal_feasible_region) {
    const optimalPolygonPoints = optimal_feasible_region.polygon.map(
      (point) => ({
        ...point,
        z: feasibleRegionPolygonZ,
      }),
    );

    const optimalRegionMarker: Messages.ares__VisualizationMarker = {
      header: {
        stamp: planningDebug.receiveTime,
        frame_id: "world",
        seq: feasible_regions.length, // Ensure unique sequence number
      },
      id: "optimal_feasible_region_polygon",
      type: Messages.ares__VisualizationMarkerTypes.SHAPE,
      points: optimalPolygonPoints,
      color: { r: 0, g: 0, b: 0, a: 0 }, // No fill color
      edgeColor: optimalRegionEdgeColor,
      pose: { position: { x: 0.0, y: 0.0, z: feasibleRegionPolygonZ } },
      fill: true,
      edge: true,
    };

    markers.push(optimalRegionMarker);
  }

  // Visualize the optimal restricted feasible region with fill color only
  if (optimal_restricted_feasible_region) {
    const restrictedPolygonPoints = optimal_restricted_feasible_region.map(
      (point) => ({
        ...point,
        z: feasibleRegionPolygonZ,
      }),
    );

    const restrictedRegionFillMarker: Messages.ares__VisualizationMarker = {
      header: {
        stamp: planningDebug.receiveTime,
        frame_id: "world",
        seq: feasible_regions.length + 1, // Ensure unique sequence number
      },
      id: "optimal_restricted_feasible_region_fill",
      type: Messages.ares__VisualizationMarkerTypes.SHAPE,
      points: restrictedPolygonPoints,
      color: optimalRegionFillColor, // Fill color
      edgeColor: { r: 0, g: 0, b: 0, a: 0 }, // No edge color
      pose: { position: { x: 0.0, y: 0.0, z: feasibleRegionPolygonZ } },
      fill: true, // Fill
      edge: false, // No edge
    };

    markers.push(restrictedRegionFillMarker);
  }

  return {
    markers,
  };
};

