import { Input, Messages } from "ros";
import {
  createDeleteCurrentTopicMarkers,
  GlobalVariables,
  ScriptConfig,
  MemoryCacheBlock,
} from "@ares-utils";

// These are the topics your script "subscribes" to. Ares will invoke your publisher function
// When any message is received on these topics.
// e.g. export const inputs: string[] = ["/pose", "/perception/tracked_object_list"]
export const inputs: string[] = ["/planning/planning_debug", "/pose"];

// The name of the topic published
// When data is rendered in ImagePanel, the name must start with "/image_marker/"
// When data is rendered in 3DPanel, the name must start with "/studio_node/"
export const output: `/${"studio_node" | "image_marker"}/${string}` =
  "/studio_node/planning/pull_out_target_lane_blocking_state";

// Configure the input and output when the code is executed
export const config: ScriptConfig = {};

// Draw looped contour as the LINE_LOOP seems not work.
function drawContour(
  points: Messages.voy__Point2d[],
  pose_z: number,
): Messages.ares__Vec3[] {
  const vis_points: Messages.ares__Vec3[] = [];
  for (let i = 0; i < points.length; i++) {
    vis_points.push({ x: points[i].x, y: points[i].y, z: pose_z });
  }
  vis_points.push({ x: points[0].x, y: points[0].y, z: pose_z });
  return vis_points;
}

function generateContourMarker(
  contour: Messages.voy__Polygon2d,
  pose_input: Messages.ares__Pose,
  id: any,
  type: Messages.ares__VisualizationMarkerTypes,
  color: Messages.ares__Color,
  line_width: number,
  z_buffer: number,
  receiveTime: Messages.ares__Time,
): Messages.ares__VisualizationMarker | undefined {
  if (contour === undefined) {
    return undefined;
  }
  return {
    header: {
      frame_id: "world",
      stamp: receiveTime,
      seq: 0,
    },
    id: id,
    type: type,
    action: 0,
    pose: {
      position: {
        x: pose_input.position.x,
        y: pose_input.position.y,
        z: pose_input.position.z + z_buffer,
      },
    },
    points: drawContour(contour.points, pose_input.position.z + z_buffer),
    color: color,
    lineMetadata: {
      lineWidth: line_width,
    },
  };
}

/**
 * This function is called with messages from your input topics.
 * The first argument is an event with the topic, receive time, and message.

 * @param messages According to the topic subscribed by "inputs", pass in the message corresponding to the topic.
 * @remarks Use the `Input<topicName>` helper to get the correct event type for your input topic messages.
 * @example
 * message: {
 *   "/pose": Input<"/pose">,
 *   "/perception/tracked_object_list": Input<"/perception/tracked_object_list">
 * }
 *
 * @param globalVariables Variables that can be accessed anywhere in the program, based on which the interactivity of the visual content can be configured
 * @see {@link https://cooper.didichuxing.com/knowledge/2199628491086/2199761277479} for more information
 *
 * @param blocks According to the topic subscribed by "inputs", all the messages of the corresponding topic in the bag are passed in
 *
 * @return the return format of the data is based on datatype
 */
const publisher = (
  messages: Record<string, Input<"/planning/planning_debug"> | Input<"/pose">>,
): Messages.ares__VisualizationMarkerArray => {
  const message_debug = messages[
    "/planning/planning_debug"
  ] as Input<"/planning/planning_debug">;
  const message_pose = messages["/pose"] as Input<"/pose">;
  if (!message_debug || !message_pose) {
    return undefined;
  }

  const trajectory_selection_debug =
    message_debug.message.behaviorReasonerDebug.decoupledManeuvers[0]
      .trajectorySelectionDebug;
  if (trajectory_selection_debug === null) {
    return undefined;
  }

  if (trajectory_selection_debug.pullOutMetaDataDebug === null) {
    return undefined;
  }

  const target_lane_blocking_state_debug =
    trajectory_selection_debug.pullOutMetaDataDebug
      .targetLaneBlockingStateDebug;

  if (target_lane_blocking_state_debug === null) {
    return undefined;
  }

  const region_debug = target_lane_blocking_state_debug.regionDebug;

  const pose: Messages.ares__Pose = {
    position: {
      x: message_pose.message.x,
      y: message_pose.message.y,
      z: message_pose.message.z,
    },
  };

  const {
    receiveTime,
    message: {},
  } = message_debug;

  const markers: Messages.ares__VisualizationMarker[] = [
    createDeleteCurrentTopicMarkers(receiveTime),
  ];

  // Draw range contours.
  const blockage_querying_region:
    | Messages.ares__VisualizationMarker
    | undefined = generateContourMarker(
    region_debug.blockageQueryingContour,
    pose,
    "blockage_querying_region",
    Messages.ares__VisualizationMarkerTypes.LINE_STRIP,
    { r: 0.0, g: 0.0, b: 0.7, a: 1.0 },
    0.4,
    0.0,
    receiveTime,
  );
  if (blockage_querying_region !== undefined) {
    markers.push(blockage_querying_region);
  }

  const jump_out_possible_region:
    | Messages.ares__VisualizationMarker
    | undefined = generateContourMarker(
    region_debug.jumpOutPossibleContour,
    pose,
    "jump_out_possible_region",
    Messages.ares__VisualizationMarkerTypes.LINE_STRIP,
    { r: 1.0, g: 0.5, b: 0.0, a: 1.0 },
    0.3,
    0.1,
    receiveTime,
  );
  if (jump_out_possible_region !== undefined) {
    markers.push(jump_out_possible_region);
  }

  const free_range_valid_flags = region_debug.freeRangeValidationResults;
  region_debug.freeRangeContours.forEach((contour, idx) => {
    // Draw free range boundary.
    const free_region_boundary: Messages.ares__VisualizationMarker | undefined =
      generateContourMarker(
        contour,
        pose,
        "free_region_" + idx,
        Messages.ares__VisualizationMarkerTypes.LINE_STRIP,
        {
          r: 0.0,
          g: 1.0,
          b: 0,
          a: 1.0,
        },
        0.2,
        0.2,
        receiveTime,
      );
    if (free_region_boundary !== undefined) {
      markers.push(free_region_boundary);
    }
    // Fill free range.
    const fill_color = free_range_valid_flags[idx]
      ? { r: 0.0, g: 1.0, b: 0.0, a: 0.5 }
      : { r: 1.0, g: 0.0, b: 0.0, a: 0.5 };

    const free_region_face: Messages.ares__VisualizationMarker | undefined =
      generateContourMarker(
        contour,
        pose,
        "free_region_face" + idx,
        Messages.ares__VisualizationMarkerTypes.SHAPE,
        fill_color,
        0.5,
        0.2,
        receiveTime,
      );
    if (free_region_face !== undefined) {
      markers.push(free_region_face);
    }
  });

  const blockage_group_debugs =
    target_lane_blocking_state_debug.blockageGroupDebugs;

  blockage_group_debugs.forEach((blockage_group_debug, group_idx) => {
    // Show group contour.
    const group_region: Messages.ares__VisualizationMarker | undefined =
      generateContourMarker(
        blockage_group_debug.groupContour,
        pose,
        "blockage_group_" + group_idx,
        Messages.ares__VisualizationMarkerTypes.SHAPE,
        { r: 0.0, g: 0.0, b: 1.0, a: 1.0 },
        0.3,
        0.3,
        receiveTime,
      );
    if (group_region !== undefined) {
      markers.push(group_region);
    }

    // Show blockage contours.
    blockage_group_debug.blockageDebugs.forEach(
      (blockage_debug, blockage_idx) => {
        const blockage_region: Messages.ares__VisualizationMarker | undefined =
          generateContourMarker(
            blockage_debug.contour,
            pose,
            "blockage_" + group_idx + "_" + blockage_idx,
            Messages.ares__VisualizationMarkerTypes.SHAPE,
            { r: 0.1, g: 0.5, b: 0.7, a: 0.9 },
            0.3,
            0.4,
            receiveTime,
          );
        if (blockage_region !== undefined) {
          markers.push(blockage_region);
        }
      },
    );
  });

  return { markers };
};

export default publisher;

