/* eslint-disable @typescript-eslint/no-unnecessary-condition */
/* ares-expose-source-code */
import { Input, Messages } from "ros";
import { Messages as StaticVoyagerType } from "@vitruvian/voyager-type";
import {
  GlobalVariables,
  DEFAULT_STUDIO_NODE_PREFIX,
  getIntentionPlanDebug,
  getSpeedSolverDebugIndex,
  getConstraints,
} from "@ares-utils";
import { isUndefined, forEach, max, min, map } from "lodash";

export const inputs = ["/planning/planning_debug"];
export const output = `${DEFAULT_STUDIO_NODE_PREFIX}planning/planning_debug/proximity_speed_debug`;

export const publisher = (
  messages: Record<string, Input<"/planning/planning_debug">>,
  globalVariables: GlobalVariables,
): Messages.ares__CustomizationPlot => {
  const message = messages[
    "/planning/planning_debug"
  ] as Input<"/planning/planning_debug">;
  // proximity speed curves
  const proximitySpeedCurvesConfig: Messages.ares__CustomizationPlotData = {
    lines: [],
    borderColor: "white",
    borderWidth: 0.5,
    pointBackgroundColor: "white",
    pointRadius: 1.0,
  };

  // proximity speed curves valid
  const proximitySpeedCurvesValidConfig: Messages.ares__CustomizationPlotData =
    {
      lines: [],
      borderColor: "#ff32b4",
      borderWidth: 1.5,
      pointBackgroundColor: "#ff32b4",
      pointRadius: 1.0,
    };

  // proximity speed limits
  const proximitySpeedLimitsConfig: Messages.ares__CustomizationPlotData = {
    lines: [],
    borderColor: "#ff32b4",
    borderWidth: 1.0,
    borderDash: [1, 1],
  };
  const behaviorReasonerDebug = (message.message?.behaviorReasonerDebug ??
    {}) as unknown as StaticVoyagerType.planner__pb__BehaviorReasonersDebug;

  const intentionPlanDebug = getIntentionPlanDebug(
    behaviorReasonerDebug,
    globalVariables,
  );

  const speedGeneratorDebug =
    intentionPlanDebug?.speedGeneratorDebug as Messages.speed__pb__SpeedGeneratorDebug;

  const speedSolverDebugIndex = getSpeedSolverDebugIndex(
    behaviorReasonerDebug,
    globalVariables,
  );

  const solverDebug =
    speedGeneratorDebug?.speedSolverDebugs[speedSolverDebugIndex];
  const showVTCurve = globalVariables.planning_speed_profile_vt_curve;
  if (!message) {
    return {
      data: [
        proximitySpeedCurvesConfig,
        proximitySpeedCurvesValidConfig,
        proximitySpeedLimitsConfig,
      ],
    };
  }

  if (solverDebug) {
    const proximitySpeedConstraintsMap: Map<
      string,
      Messages.speed__pb__ProximitySpeedConstraintDebug
    > = new Map();
    solverDebug?.optDebug?.potentialDebug?.proximitySpeedConstraints?.forEach(
      (proximitySpeedConstraint) => {
        proximitySpeedConstraintsMap.set(
          proximitySpeedConstraint.uniqueConstraintId,
          proximitySpeedConstraint,
        );
      },
    );

    const primitiveConstraints =
      speedGeneratorDebug?.primitiveConstraints ?? [];
    const constraints = solverDebug?.searchDebug?.constraints;

    // Get proximity speed constraint states for constraint plot.
    for (
      let constraint_idx = 0;
      constraint_idx < constraints.length;
      constraint_idx++
    ) {
      let constraint = constraints[constraint_idx];
      let uniqueId = constraint?.uniqueConstraintId;
      let constraintType = constraint?.type;
      let proximitySpeedParams =
        constraint?.settings?.proximitySpeedParams ??
        ({} as Messages.planner__speed__pb__ProximitySpeedParams);
      if (primitiveConstraints.length > 0) {
        const primitiveConstraint = primitiveConstraints[constraint_idx];
        uniqueId = primitiveConstraint?.uniqueConstraintId;
        constraintType = primitiveConstraint?.type;
        proximitySpeedParams =
          primitiveConstraint?.settings?.proximitySpeedParams;
      }

      if (
        constraintType != "PROXIMITY_SPEED" ||
        !proximitySpeedConstraintsMap.has(uniqueId)
      ) {
        continue;
      }

      // Constraint Info
      const proximitySpeedStartCurvesLine: Messages.ares__CustomizationPlotLine =
        {
          line: [],
        };

      const proximitySpeedEndCurvesLine: Messages.ares__CustomizationPlotLine =
        {
          line: [],
        };

      const proximitySpeedConstraintId: Messages.ares__CustomizationPlotLine = {
        line: [],
      };

      // Proximity Speed Info
      const proximitySpeedStartValidCurvesLine: Messages.ares__CustomizationPlotLine =
        {
          line: [],
        };

      const proximitySpeedEndValidCurvesLine: Messages.ares__CustomizationPlotLine =
        {
          line: [],
        };

      // Speed Limit
      const proximitySpeedLimitsLine: Messages.ares__CustomizationPlotLine = {
        line: [],
      };

      const constraintStates = constraint?.states ?? [];
      const proximitySpeedConstraintDebug = proximitySpeedConstraintsMap.get(
        uniqueId,
      ) as Messages.speed__pb__ProximitySpeedConstraintDebug | undefined;
      const proximitySpeedStates = (
        proximitySpeedConstraintDebug as unknown as any
      )?.states;
      if (
        (proximitySpeedConstraintDebug as unknown as any)?.states == undefined
      ) {
        const currentProximitySpeedConstraint =
          proximitySpeedConstraintsMap.get(
            constraint?.uniqueConstraintId ?? "",
          );
        const yieldBufferDist =
          (currentProximitySpeedConstraint as unknown as any)
            ?.yieldBufferDist ?? 0;
        const passBufferDist =
          (currentProximitySpeedConstraint as unknown as any)?.passBufferDist ??
          0;

        constraintStates.forEach((state) => {
          const startTime = state.startTime;
          const startX = state.discomfortVarStartX.values[0] - yieldBufferDist;
          const endX = state.discomfortVarEndX.values[0] + passBufferDist;

          proximitySpeedStartCurvesLine.line.push({ x: startTime, y: startX });
          proximitySpeedEndCurvesLine.line.push({ x: startTime, y: endX });
          if (state.absLatGap <= proximitySpeedParams.maxLatGap) {
            proximitySpeedStartValidCurvesLine.line.push({
              x: startTime,
              y: startX,
            });
            proximitySpeedEndValidCurvesLine.line.push({
              x: startTime,
              y: endX,
            });
          }

          let speedLimit = 0.0;
          if (proximitySpeedParams.maxAllowedSpeed > 0.0) {
            speedLimit = proximitySpeedParams.maxAllowedSpeed;
          } else {
            speedLimit =
              state.signedLongitudinalSpeed +
              proximitySpeedParams.maxAllowedRelSpeed;
          }
          proximitySpeedLimitsLine.line.push({ x: startTime, y: speedLimit });
        });
      } else {
        constraintStates.forEach((state) => {
          const startTime = state.startTime;
          const startX = state.discomfortVarStartX.values[0];
          const endX = state.discomfortVarEndX.values[0];

          proximitySpeedStartCurvesLine.line.push({ x: startTime, y: startX });
          proximitySpeedEndCurvesLine.line.push({ x: startTime, y: endX });
        });

        proximitySpeedStates.forEach((state) => {
          const dt = 0.1;
          const startTime = state.timeIx * dt;
          const startX = state.startX;
          const endX = state.endX;
          const speedLimit = state.speedLimit;

          proximitySpeedStartValidCurvesLine.line.push({
            x: startTime,
            y: startX,
          });
          proximitySpeedEndValidCurvesLine.line.push({ x: startTime, y: endX });
          proximitySpeedLimitsLine.line.push({ x: startTime, y: speedLimit });
        });
      }

      const curve_length = proximitySpeedEndCurvesLine.line.length;
      proximitySpeedConstraintId.line.push({
        x: proximitySpeedStartCurvesLine.line[curve_length - 1].x,
        y: proximitySpeedStartCurvesLine.line[curve_length - 1].y,
        label: uniqueId,
        labelColor: "white",
        labelSize: 12,
      });
      proximitySpeedCurvesConfig.lines.push(
        proximitySpeedStartCurvesLine,
        proximitySpeedEndCurvesLine,
        proximitySpeedConstraintId,
      );
      proximitySpeedCurvesValidConfig.lines.push(
        proximitySpeedStartValidCurvesLine,
        proximitySpeedEndValidCurvesLine,
      );
      if (showVTCurve) {
        proximitySpeedLimitsConfig.lines.push(proximitySpeedLimitsLine);
      }
    }
  }

  return {
    data: [
      proximitySpeedCurvesConfig,
      proximitySpeedCurvesValidConfig,
      proximitySpeedLimitsConfig,
    ],
  };
};

