// This example shows how to use nodePlayground to simply perform data processing for use by Plot of customization mode.
// @see {@link https://cooper.didichuxing.com/knowledge/share/page/SociEekW3kHl} for more information
import { Input, Messages } from "ros";
import {
  GlobalVariables,
  MemoryCacheBlock,
  scatterColorMap,
  Color,
  scatterColorMapLen,
} from "@ares-utils";

function GetCost(
  cost: Messages.planner__pb__JumpInCurveCostingInfoDebug,
  cost_type: keyof Messages.planner__pb__JumpInCurveCostingInfoDebug,
): any {
  return cost?.[cost_type];
}
const lastColor = scatterColorMap[scatterColorMapLen - 1] as Color;
const firstColor = scatterColorMap[0] as Color;
const getColor = (
  value: number,
  maxCost: number,
  minCost: number,
  alpha: number,
) => {
  if (maxCost === minCost) {
    return `rgb(${firstColor.r},${firstColor.g},${firstColor.b}, ${alpha})`;
  }
  const colorVal =
    ((value - minCost) / (maxCost - minCost)) * scatterColorMapLen;
  if (colorVal >= scatterColorMapLen) {
    return `rgb(${lastColor.r},${lastColor.g},${lastColor.b}, ${alpha})`;
  }
  if (colorVal === 0) {
    return `rgb(${firstColor.r},${firstColor.g},${firstColor.b}, ${alpha} )`;
  }
  if (Math.ceil(colorVal) === scatterColorMapLen) {
    return `rgb(${lastColor.r},${lastColor.g},${lastColor.b}, ${alpha} )`;
  }
  const preColor = scatterColorMap?.[Math.floor(colorVal)] as Color;
  const nextColor = scatterColorMap?.[Math.ceil(colorVal)] as Color;
  const r = (preColor.r + nextColor?.r) / 2;
  const g = (preColor.g + nextColor?.g) / 2;
  const b = (preColor.b + nextColor?.b) / 2;
  return `rgb(${r}, ${g}, ${b}, ${alpha})`;
};
// These are the topics your script "subscribes" to. Ares will invoke your publisher function
// when any message is received on these topics.
// e.g. export const inputs: string[] = ["/pose", "/perception/tracked_object_list"]
export const inputs: string[] = ["/planning/planning_debug"];
// The name of the topic published
// When data is rendered in ImagePanel, the name must start with "/image_marker/"
// When data is rendered in 3DPanel, the name must start with "/studio_node/"
export const output: `/${"studio_node" | "image_marker"}/${string}` =
  "/studio_node/jump_in_curve_cost_plot";
/**
This function is called with messages from your input topics.
The first argument is an event with the topic, receive time, and message.
@param messages According to the topic subscribed by "inputs", pass in the message corresponding to the topic.
@remarks Use the Input<...> helper to get the correct event type for your input topic messages.
@example
message: {
"/pose": Input<"/pose">,
"/perception/tracked_object_list": Input<"/perception/tracked_object_list">
} *
@param globalVariables
@see {@link https://cooper.didichuxing.com/knowledge/2199628491086/2199761277479} for more information *
@param blocks According to the topic subscribed by "inputs", all the messages of the corresponding topic in the bag are passed in */
const publisher = (
  message: { "/planning/planning_debug": Input<"/planning/planning_debug"> },
  globalVars: GlobalVariables,
  blocks: readonly (MemoryCacheBlock | undefined)[],
): Messages.ares__CustomizationPlot => {
  const debug_message = message["/planning/planning_debug"];
  if (!debug_message) {
    return { data: [] };
  }
  const jump_in_guidance_message =
    debug_message.message.behaviorReasonerDebug.decoupledManeuvers[0]
      .pullOverInfoDebug.jumpInGuidanceDebug;

  if (!jump_in_guidance_message) {
    return { data: [] };
  }

  // You can write code here to process the data
  const plotData: Messages.ares__CustomizationPlot = { data: [] };

  // Get cost type to show.
  const cost_type =
    globalVars.jump_in_curve_cost_type as keyof Messages.planner__pb__JumpInCurveCostingInfoDebug;

  // Get highlight curve config.
  var highlight_lowest_n_total_cost_jump_in_curves =
    globalVars.highlight_lowest_n_total_cost_jump_in_curves as number;

  // Estimate min max cost.
  var max_cost = 0.0;
  var min_cost = Number.MAX_VALUE;
  jump_in_guidance_message.curves.forEach((curve) => {
    const cost = GetCost(curve.costDebug, cost_type);
    if (cost > max_cost && cost < 100) {
      max_cost = cost;
    }
    if (cost < min_cost && cost >= 0) {
      min_cost = cost;
    }
  });

  jump_in_guidance_message.curves.forEach((curve, index) => {
    const points = curve.curve.segments[0].points;
    const cost_val = GetCost(curve.costDebug, cost_type).toFixed(3);
    const alpha =
      index < highlight_lowest_n_total_cost_jump_in_curves ? 1.0 : 0.3;
    const cost_color = getColor(cost_val, max_cost, min_cost, alpha);

    const CurveConfig: Messages.ares__CustomizationPlotData = {
      lines: [],
      borderColor: cost_color,
      borderWidth: 3,
      pointRadius: 3,
      pointBackgroundColor: cost_color,
    };
    const plotLine: Messages.ares__CustomizationPlotLine = {
      line: points.map((point) => {
        return {
          x: point.x,
          y: point.y,
          value: GetCost(curve.costDebug, cost_type),
        };
      }),
    };
    const plotText: Messages.ares__CustomizationPlotLine = {
      line: [
        {
          x: points[Math.floor(points.length / 2)].x,
          y: points[Math.floor(points.length / 2)].y,
          label: cost_val,
          labelColor: `rgb(255, 255, 255, ${alpha})`,
          labelSize: 14,
        },
      ],
    };

    if (curve.isSelectedCandidate) {
      const BestCurveConfig: Messages.ares__CustomizationPlotData = {
        lines: [],
        borderColor: "#FFFF00",
        borderWidth: 6,
        borderDash: [10, 10],
        pointRadius: 7,
        pointBackgroundColor: "#FFFF00",
      };
      const BestplotLine: Messages.ares__CustomizationPlotLine = {
        line: points.map((point) => {
          return {
            x: point.x,
            y: point.y,
            value: GetCost(curve.costDebug, cost_type),
          };
        }),
      };
      BestCurveConfig.lines.push(BestplotLine);
      plotData.data.push(BestCurveConfig);
    }

    CurveConfig.lines.push(plotLine);
    CurveConfig.lines.push(plotText);
    plotData.data.push(CurveConfig);
  });

  const SourceLineJumpInCurvePlotDataConfig: Messages.ares__CustomizationPlotData =
    {
      lines: [],
      borderColor: "#0000EE",
      borderWidth: 7,
    };

  const sourceLine: Messages.ares__CustomizationPlotLine = {
    line: jump_in_guidance_message.sourceLine.segments[0].points.map(
      (point) => {
        return { x: point.x, y: point.y };
      },
    ),
  };

  SourceLineJumpInCurvePlotDataConfig.lines.push(sourceLine);

  const TargetLineJumpInCurvePlotDataConfig: Messages.ares__CustomizationPlotData =
    {
      lines: [],
      borderColor: "#00EE00",
      borderWidth: 7,
    };

  plotData.data.push(SourceLineJumpInCurvePlotDataConfig);

  const targetLine: Messages.ares__CustomizationPlotLine = {
    line: jump_in_guidance_message.targetLine.segments[0].points.map(
      (point) => {
        return { x: point.x, y: point.y };
      },
    ),
  };

  TargetLineJumpInCurvePlotDataConfig.lines.push(targetLine);

  plotData.data.push(TargetLineJumpInCurvePlotDataConfig);
  return plotData;
};
export default publisher;

