import { Input, Messages } from "ros";
import {
  GlobalVariables,
  ScriptConfig,
  MemoryCacheBlock,
  createDeleteCurrentTopicMarkers,
} from "@ares-utils";

// These are the topics your script "subscribes" to. Ares will invoke your publisher function
// When any message is received on these topics.
// e.g. export const inputs: string[] = ["/pose", "/perception/tracked_object_list"]
export const inputs: string[] = ["/planning/planning_debug", "/planning/seed"];

// The name of the topic published
// When data is rendered in ImagePanel, the name must start with "/image_marker/"
// When data is rendered in 3DPanel, the name must start with "/studio_node/"
export const output: `/${"studio_node" | "image_marker"}/${string}` =
  "/studio_node/planning/dry_steering_circle";

// Configure the input and output when the code is executed
export const config: ScriptConfig = {};

const xc_90_length = 4.953;
const xc_90_width = 1.958;
const xc_90_wheel_base = 2.984;
const xc_90_rear_axle_to_rear_bumper = 1.0867;
const xc_90_rear_axle_to_front_bumper =
  xc_90_length - xc_90_rear_axle_to_rear_bumper;

interface Vector2D {
  x: number;
  y: number;
}

function rotateVector2D(vector: Vector2D, angle: number): Vector2D {
  const cosθ = Math.cos(angle);
  const sinθ = Math.sin(angle);
  return {
    x: vector.x * cosθ - vector.y * sinθ,
    y: vector.x * sinθ + vector.y * cosθ,
  };
}

// Corner points for XC90
const left_front_vec: Vector2D = {
  x: xc_90_rear_axle_to_front_bumper,
  y: xc_90_width * 0.5,
};
const right_front_vec: Vector2D = {
  x: xc_90_rear_axle_to_front_bumper,
  y: -(xc_90_width * 0.5),
};
const left_rear_vec: Vector2D = {
  x: -xc_90_rear_axle_to_rear_bumper,
  y: xc_90_width * 0.5,
};
const right_rear_vec: Vector2D = {
  x: -xc_90_rear_axle_to_rear_bumper,
  y: -(xc_90_width * 0.5),
};
const drySteeringCircleColor = [
  { r: 0.55, g: 0.99, b: 0.99, a: 1.0 },
  { r: 0.0, g: 0.99, b: 0.52, a: 1.0 },
];
const drySteeringCircleCenterColor = { r: 1.0, g: 0.0, b: 0.0, a: 1.0 };

// Function to generates circle points.
function generateCirclePoints(
  circleCenterPoint: Vector2D,
  radius: number,
  radianIncrement: number,
  cornerPointVec: Vector2D,
  ego_heading: number,
  ego_pos: Vector2D,
): Vector2D[] {
  const points: Vector2D[] = [];
  const step_num = (2 * Math.PI) / radianIncrement;
  const init_theta = Math.atan2(
    ego_pos.y - circleCenterPoint.y,
    ego_pos.x - circleCenterPoint.x,
  );
  for (let i = 0; i <= step_num; ++i) {
    const theta = i * radianIncrement;
    const corner_pt_vec = rotateVector2D(cornerPointVec, ego_heading + theta);
    const x =
      circleCenterPoint.x +
      radius * Math.cos(theta + init_theta) +
      corner_pt_vec.x;
    const y =
      circleCenterPoint.y +
      radius * Math.sin(theta + init_theta) +
      corner_pt_vec.y;
    points.push({ x, y });
  }
  points.push(points[0]);
  return points;
}

/**
 * This function is called with messages from your input topics.
 * The first argument is an event with the topic, receive time, and message.

 * @param messages According to the topic subscribed by "inputs", pass in the message corresponding to the topic.
 * @remarks Use the `Input<topicName>` helper to get the correct event type for your input topic messages.
 * @example
 * message: {
 *   "/pose": Input<"/pose">,
 *   "/perception/tracked_object_list": Input<"/perception/tracked_object_list">
 * }
 *
 * @param globalVariables Variables that can be accessed anywhere in the program, based on which the interactivity of the visual content can be configured
 * @see {@link https://cooper.didichuxing.com/knowledge/2199628491086/2199761277479} for more information
 *
 * @param blocks According to the topic subscribed by "inputs", all the messages of the corresponding topic in the bag are passed in
 *
 * @return the return format of the data is based on datatype
 */
const publisher = (
  messages: {
    "/planning/planning_debug": Input<"/planning/planning_debug">;
    "/planning/seed": Input<"/planning/seed">;
  },
  globalVars: GlobalVariables,
  blocks: readonly (MemoryCacheBlock | undefined)[],
): Messages.ares__VisualizationMarkerArray => {
  const markers: Messages.ares__VisualizationMarker[] = [];
  const planningDebug = messages["/planning/planning_debug"];
  const planningSeed = messages["/planning/seed"];
  if (!planningDebug || !planningSeed) {
    return { markers };
  }
  const planning_init_state =
    planningDebug.message.replanLocatorDebug.planInitState;
  const dry_steering_target_angle =
    planningSeed.message.worldModelSeed.drySteeringTargetAngle;

  if (
    planning_init_state.type !== "DRY_STEERING" ||
    !dry_steering_target_angle
  ) {
    return { markers };
  }

  const ego_x = planning_init_state.state.xPos;
  const ego_y = planning_init_state.state.yPos;
  const ego_heading = planning_init_state.state.theta;

  const dry_steering_circle_radius = Math.abs(
    xc_90_wheel_base / Math.tan(dry_steering_target_angle),
  );
  const circle_center_orientation =
    ego_heading +
    (dry_steering_target_angle > 0 ? 0.5 * Math.PI : 0.5 * -Math.PI);
  const circle_center_pt: Vector2D = {
    x: Math.cos(circle_center_orientation) * dry_steering_circle_radius + ego_x,
    y: Math.sin(circle_center_orientation) * dry_steering_circle_radius + ego_y,
  };

  // Show drysteering circle based on the target direction.
  let corner_points: Vector2D[] = [];
  if (dry_steering_target_angle > 0) {
    corner_points.push(right_front_vec);
    corner_points.push(right_rear_vec);
  } else {
    corner_points.push(left_front_vec);
    corner_points.push(left_rear_vec);
  }

  corner_points.forEach((corner_point, index) => {
    const circle_points = generateCirclePoints(
      circle_center_pt,
      dry_steering_circle_radius,
      /*radianIncrement=*/ 0.1,
      corner_point,
      ego_heading,
      { x: ego_x, y: ego_y },
    );
    markers.push({
      header: {
        stamp: planningDebug.receiveTime,
        frame_id: "world",
        seq: 0,
      },
      id: `dry_steering_circle_shape_${index}`,
      type: Messages.ares__VisualizationMarkerTypes.LINE_STRIP,
      points: circle_points.map((point) => ({
        ...point,
        z: 1.5,
      })),
      color: drySteeringCircleColor[index],
      lineMetadata: {
        lineWidth: 0.15,
        frustumCulled: false,
        sizeAttenuation: false,
      },
    });
  });

  markers.push({
    header: {
      stamp: planningDebug.receiveTime,
      frame_id: "world",
      seq: 0,
    },
    id: `dry_steering_circle_shape_center_point`,
    type: Messages.ares__VisualizationMarkerTypes.POINT,
    action: Messages.ares__VisualizationMarkerAction.ADD,
    lifetime: { sec: 0, nsec: 0 },
    pose: {
      position: {
        x: circle_center_pt.x,
        y: circle_center_pt.y,
        z: 1.5,
      },
    },
    color: drySteeringCircleCenterColor,
    pointMetadata: {
      sizeAttenuation: false,
      radius: 0.3,
    },
  });

  return {
    markers,
  };
};

export default publisher;

