import {
  createDeleteCurrentTopicMarkers,
  COLOR_YELLOW,
  MemoryCacheBlock,
} from "@ares-utils";
import { Input, Messages } from "ros";

export const inputs = ["/mapping/map_change_area_list"];
export const output = "/studio_node/map/change_area_fuser/reference_line";
export const config = {
  datatype: "ares/VisualizationMarkerArray",
};

export const publisher = (
  message: {
    "/mapping/map_change_area_list": Input<"/mapping/map_change_area_list">;
  },
  _globalVars: unknown,
  blocks: readonly (MemoryCacheBlock | undefined)[],
): Messages.ares__VisualizationMarkerArray | undefined => {
  const messageMapChangeArea = message["/mapping/map_change_area_list"];

  const markers: Messages.ares__VisualizationMarker[] = [
    createDeleteCurrentTopicMarkers(messageMapChangeArea.receiveTime),
  ];

  for (const constructionZone of messageMapChangeArea.message
    .constructionZonesRealTimeMap) {
    if (constructionZone.referenceLineInfos.length === 0) {
      continue;
    }
    for (const reference_line_info of constructionZone.referenceLineInfos) {
      const id = `reference_line_${constructionZone.id}_${reference_line_info.id}`;
      markers.push({
        header: {
          frame_id: "world",
          seq: 0,
          stamp: messageMapChangeArea.receiveTime,
        },
        id: id as any,
        type: Messages.ares__VisualizationMarkerTypes.LINE_STRIP,
        points: reference_line_info.fusedLine.points.map((point) => {
          return { ...point, z: 0 };
        }),
        color: COLOR_YELLOW,
        lineMetadata: {
          lineWidth: 0.1,
          frustumCulled: false,
          sizeAttenuation: false,
        },
        renderOrder: 1,
      });
    }
  }

  return {
    markers,
  };
};

