/* ares-expose-source-code */
import {
  GlobalVariables,
  DEFAULT_STUDIO_NODE_PREFIX,
  getIntentionPlanDebug,
  getSpeedSolverDebugIndex,
  getSignalParams,
} from "@ares-utils";
import { Input, Messages } from "@vitruvian/voyager-type";
import { forEach, isNil } from "lodash";

export const inputs = ["/planning/planning_debug", "/gateway", "/mrc/mrc_request"];
export const output = `${DEFAULT_STUDIO_NODE_PREFIX}planning/planning_debug/signal`;
export const config = {
  datatype: "voyager_data_msgs/CustomData",
  showOn3DPanel: false,
  executeScriptWhenAnyMessageReceived: true,
};

// Cache the correct data in scenarios where data alignment is required.
let prevPlanningDebugMessage: Input<"/planning/planning_debug">;
let prevCanbusMessage: Input<"/gateway">;
let prevMrcMessage: Input<"/mrc/mrc_request">;

export const publisher = (
  messages: Record<
    string,
    Input<"/planning/planning_debug"> | Input<"/gateway"> | Input<"/mrc/mrc_request">
  >,
  globalVars: GlobalVariables,
): Messages.voyager_data_msgs__CustomData => {
  const planningDebugMessage = messages[
    "/planning/planning_debug"
  ] as Input<"/planning/planning_debug">;
  if (planningDebugMessage) {
    prevPlanningDebugMessage = planningDebugMessage;
  }
  if (!prevPlanningDebugMessage) {
    return {};
  }

  const canbusMessage = messages["/gateway"] as Input<"/gateway">;
  if (canbusMessage) {
    prevCanbusMessage = canbusMessage;
  }

  const mrcMessage = messages["/mrc/mrc_request"] as Input<"/mrc/mrc_request">;
  if (mrcMessage) {
    prevMrcMessage = mrcMessage;
  }

  let disengageType = "Override Type: ";
  if (prevCanbusMessage && prevCanbusMessage.message.overrideModule.length > 0) {
    forEach(prevCanbusMessage.message.overrideModule, (module) => {
      disengageType += String(module) + " ";
    });
  } else {
    disengageType += "None ";
  }

  const {
    message: { behaviorReasonerDebug, worldModelDebug },
  } = prevPlanningDebugMessage;
  if (isNil(behaviorReasonerDebug) || isNil(worldModelDebug)) {
    return {
      [`${DEFAULT_STUDIO_NODE_PREFIX}planning/planning_debug/signal`]: [],
    };
  }
  const { executingDecoupledArchTrajectory, selectedManeuverType, egoStuckDebug } =
    behaviorReasonerDebug;
  const { waypointAssistDebug, pullOutConfirmDebug, immediatePullOverDebug } = worldModelDebug;
  const { isConfirmed = false, isReadyToGo = false } = pullOutConfirmDebug?.seedDebug ?? {};

  const intentionPlanDebug = getIntentionPlanDebug(behaviorReasonerDebug, globalVars);

  const speedGeneratorDebug =
    intentionPlanDebug?.speedGeneratorDebug as Messages.planner__speed__pb__SpeedGeneratorDebug;

  const speedSolverDebugIndex = getSpeedSolverDebugIndex(behaviorReasonerDebug, globalVars);

  const searchDebug = speedGeneratorDebug?.speedSolverDebugs[speedSolverDebugIndex]?.searchDebug;

  const useTrajectoryGuiderOutputForSpeed =
    searchDebug?.speedLimiters?.isUsingTrajectoryGuiderLimiter ?? false;
  const diversityOption = searchDebug?.diversityOption;

  const {
    trajectoryType,
    globalDisComfort,
    behaviorType,
    isXLaneNudgeSelected,
    useTrajectoryGuiderOutputForPath,
    ifFireRiskSignal,
  } = getSignalParams(
    behaviorReasonerDebug.decoupledManeuvers,
    behaviorReasonerDebug.executingDecoupledArchTrajectory,
  );

  let decoupledShowInfo = selectedManeuverType;
  if (executingDecoupledArchTrajectory) {
    const isXLaneNudge = isXLaneNudgeSelected ? " (XLANE) " : "";
    decoupledShowInfo = `@${globalDisComfort.toFixed(2)} DECOUPLED ${behaviorType}${isXLaneNudge}`;
  }

  let trajectoryShowInfo = "NOT USING ML PLANNER OUTPUT";
  if (useTrajectoryGuiderOutputForPath && useTrajectoryGuiderOutputForSpeed) {
    trajectoryShowInfo = "ML PLANNER IN PATH AND IN SPEED";
  } else if (useTrajectoryGuiderOutputForPath) {
    trajectoryShowInfo = "ML PLANNER IN PATH（ML1.0）";
  } else if (useTrajectoryGuiderOutputForSpeed) {
    trajectoryShowInfo = "ML PLANNER IN SPEED";
  }

  let trajectoryTypeShowInfo = "";
  switch (trajectoryType) {
    case "LAST_TRAJECTORY":
      trajectoryTypeShowInfo = "USING LAST PATH";
      break;
    case "BACKUP_TRAJECTORY":
      trajectoryTypeShowInfo = "USING BACKUP PATH";
      break;
    case "ML_BACKUP_TRAJECTORY":
      trajectoryTypeShowInfo = "USING ML BACKUP PATH";
      break;
    case "ML_PATH":
      trajectoryTypeShowInfo = "USING ML PATH（ML2.0）";
      break;
    case "ML_TRAJECTORY":
      trajectoryTypeShowInfo = "USING ML TRAJECTORY（ML3.0）";
      break;
    default:
      trajectoryTypeShowInfo = "USING NOMINAL PATH";
      break;
  }

  const pulloutIsConfort = isConfirmed ? true : false;
  const pulloutIsReadyToGo = isReadyToGo ? true : false;

  const riskSignalShowInfo = ifFireRiskSignal ? "RISK SIGNAL FIRED" : "RISK SIGNAL NOT FIRED";

  const resForSignalTable = [
    decoupledShowInfo,
    trajectoryShowInfo,
    trajectoryTypeShowInfo,
    waypointAssistDebug?.assistManeuverPhase ?? "",
    `PULL_OUT IS_COMFIRMED: ${pulloutIsConfort}`,
    `PULL_OUT IS_READY_TO_GO: ${pulloutIsReadyToGo}`,
    diversityOption,
    riskSignalShowInfo,
    egoStuckDebug?.unstuckStatus ?? "",
    disengageType,
    `immediatePulloverState: ${immediatePullOverDebug?.immediatePulloverState}`,
    `triggerSource: ${immediatePullOverDebug?.triggerSource}`,
    `mrc_type: ${prevMrcMessage?.message.mrmType}`,
    `mrm_progress: ${prevMrcMessage?.message.mrmProgress}`,
  ].map((item) => ({
    "Planning Signal": item,
  }));

  return resForSignalTable;
};

