/* ares-expose-source-code */
// Minimal demo: visualize /planning/remote_assist_model_debug -> assistResponseFromRaVnode.referencePoints
import {
  DEFAULT_STUDIO_NODE_PREFIX,
  COLOR_GRASS_GREEN,
  COLOR_PINK,
  MemoryCacheBlock,
  euler2Quaternions,
} from "@ares-utils";
import { Input, Messages } from "@vitruvian/voyager-type";

// 新增：定义灰粉和灰绿（调整了 RGB 和透明度 a）
const COLOR_MUTED_PINK = { r: 0.85, g: 0.53, b: 0.65, a: 0.65 }; // 灰粉色
const COLOR_MUTED_GREEN = { r: 0.55, g: 0.71, b: 0.55, a: 0.95 }; // 灰绿色
const COLOR_GRAY = { r: 0.6, g: 0.6, b: 0.6, a: 0.9 };

export const inputs = ["/planning/remote_assist_model_debug", "/pose"];
export const output = `${DEFAULT_STUDIO_NODE_PREFIX}planning/assist/unstuck_nominal_path`;
export const config = {
  datatype: "ares/VisualizationMarkerArray",
};

export const publisher = (
  messages: Record<string, Input<"/planning/assist_response"> | Input<"/pose">>,
  _globalVars: unknown,
  _blocks: readonly (MemoryCacheBlock | undefined)[],
): Messages.ares__VisualizationMarkerArray | undefined => {
  const msg = messages["/planning/remote_assist_model_debug"];
  const pose_msg = messages["/pose"] as Input<"/pose">;
  if (!msg || !pose_msg) {
    return;
  }
  const { receiveTime } = msg;
  const pose_z: number = pose_msg.message.z;

  // 获取消息
  const root: any = msg.message;
  const swag_debug = root?.waypointAutoGenerationModelDebug;

  const markers: Messages.ares__VisualizationMarker[] = [];

  // ==========================================
  // 1) 绘制原始基线轨迹 (Raw Baseline Nominal Path)
  // ==========================================
  // const refPts: Array<{ x: number; y: number }> | undefined =
  //   swag_debug?.unstuckNominalPath?.points;

  // if (refPts && refPts.length > 0) {
  //   const points: Messages.ares__Vec3[] = refPts.map((p) => ({
  //     x: p.x,
  //     y: p.y,
  //     z: 15.0,
  //   }));

  //   markers.push({
  //     header: { frame_id: "world", seq: 0, stamp: receiveTime },
  //     id: "ra-waypoints-line",
  //     ns: "nominal_path",
  //     type: Messages.ares__VisualizationMarkerTypes.LINE_STRIP,
  //     action: Messages.ares__VisualizationMarkerAction.ADD,
  //     points,
  //     color: COLOR_GRASS_GREEN, // 保持原有的草绿色
  //     lifetime: { sec: 2, nsec: 0 },
  //     lineMetadata: {
  //       lineWidth: 0.2,
  //       frustumCulled: false,
  //       sizeAttenuation: false,
  //     },
  //   });

  //   refPts.forEach((p, index) => {
  //     markers.push({
  //       header: { frame_id: "world", seq: 0, stamp: receiveTime },
  //       id: `ra-waypoints-point-${index}`,
  //       ns: "nominal_path_points",
  //       type: Messages.ares__VisualizationMarkerTypes.POINT,
  //       action: Messages.ares__VisualizationMarkerAction.ADD,
  //       lifetime: { sec: 2, nsec: 0 },
  //       pose: {
  //         position: { x: p.x, y: p.y, z: 15.1 },
  //         orientation: euler2Quaternions({ yaw: 0, pitch: 0, roll: 0 }),
  //       },
  //       scale: { x: 0.3, y: 0, z: 0 },
  //       color: COLOR_GRASS_GREEN,
  //     });
  //   });
  // }

  // ==========================================
  // 2) 绘制 Top-K 采样后的轨迹 (Sampled Nominal Paths)
  // ==========================================
  const selectedIndex = swag_debug?.selectedNominalPathCandidateIndex;
  const candidates = swag_debug?.nominalPathCandidateDebugs;

  // 判断是否包含多条候选轨迹
  if (Array.isArray(candidates) && candidates.length > 0) {
    candidates.forEach((candidate) => {
      const sampledPoints =
        candidate?.postProcessingDebug?.sampledNominalPath?.points;
      if (!sampledPoints || sampledPoints.length === 0) return;

      // 判断当前遍历的轨迹是否是被选中的那条
      const isSelected = candidate.index === selectedIndex;

      // 样式区分：选中的用原粉色，没选中的用灰粉色（你也可以改成 COLOR_MUTED_GREEN）
      const color = isSelected ? COLOR_PINK : COLOR_GRAY;
      const zOffset = isSelected ? pose_z + 1.0 : pose_z + 0.5; // 稍微降低高度避免 Z-fighting 闪烁
      const lineWidth = isSelected ? 0.2 : 0.15;
      const pointScale = isSelected ? 0.25 : 0.2;
      const nsPrefix = isSelected
        ? "sampled_path_selected"
        : `sampled_path_candidate_${candidate.index}`;

      const sampled_points: Messages.ares__Vec3[] = sampledPoints.map(
        (p: any) => ({
          x: p.x,
          y: p.y,
          z: zOffset,
        }),
      );

      // A. 采样轨迹线
      markers.push({
        header: { frame_id: "world", seq: 0, stamp: receiveTime },
        id: `ra-waypoints-sampled-line-${candidate.index}`,
        ns: nsPrefix,
        type: Messages.ares__VisualizationMarkerTypes.LINE_STRIP,
        action: Messages.ares__VisualizationMarkerAction.ADD,
        points: sampled_points,
        lifetime: { sec: 2, nsec: 0 },
        color: color,
        lineMetadata: {
          lineWidth: lineWidth,
          frustumCulled: false,
          sizeAttenuation: false,
        },
      });

      // B. 采样轨迹点
      sampledPoints.forEach((p: any, pIdx: number) => {
        markers.push({
          header: { frame_id: "world", seq: 0, stamp: receiveTime },
          id: `ra-waypoints-sampled-point-${candidate.index}-${pIdx}`,
          ns: `${nsPrefix}_points`,
          type: Messages.ares__VisualizationMarkerTypes.POINT,
          action: Messages.ares__VisualizationMarkerAction.ADD,
          lifetime: { sec: 2, nsec: 0 },
          pose: {
            position: { x: p.x, y: p.y, z: zOffset },
            orientation: euler2Quaternions({ yaw: 0, pitch: 0, roll: 0 }),
          },
          scale: { x: pointScale, y: 0, z: 0 },
          color: color,
        });
      });
    });
  } else {
    // ==========================================
    // 3) 兼容老版本：单条采样轨迹的逻辑
    // ==========================================
    const oldSampledPoints =
      swag_debug?.nominalPathPostProcessingDebug?.sampledNominalPath?.points;
    if (Array.isArray(oldSampledPoints) && oldSampledPoints.length > 0) {
      const sampled_points: Messages.ares__Vec3[] = oldSampledPoints.map(
        (p) => ({
          x: p.x,
          y: p.y,
          z: 15.2,
        }),
      );

      markers.push({
        header: { frame_id: "world", seq: 0, stamp: receiveTime },
        id: "ra-waypoints-sampled-line",
        ns: "sampled_path",
        type: Messages.ares__VisualizationMarkerTypes.LINE_STRIP,
        action: Messages.ares__VisualizationMarkerAction.ADD,
        points: sampled_points,
        lifetime: { sec: 2, nsec: 0 },
        color: COLOR_PINK,
        lineMetadata: {
          lineWidth: 0.15,
          frustumCulled: false,
          sizeAttenuation: false,
        },
      });

      oldSampledPoints.forEach((p, index) => {
        markers.push({
          header: { frame_id: "world", seq: 0, stamp: receiveTime },
          id: `ra-waypoints-sampled-point-${index}`,
          ns: "sampled_path_points",
          type: Messages.ares__VisualizationMarkerTypes.POINT,
          action: Messages.ares__VisualizationMarkerAction.ADD,
          lifetime: { sec: 2, nsec: 0 },
          pose: {
            position: { x: p.x, y: p.y, z: 15.2 },
            orientation: euler2Quaternions({ yaw: 0, pitch: 0, roll: 0 }),
          },
          scale: { x: 0.2, y: 0, z: 0 },
          color: COLOR_PINK,
        });
      });
    }
  }

  return { markers };
};

