import { Input, Messages } from "ros";
import {
  GlobalVariables,
  ScriptConfig,
  MemoryCacheBlock,
  createDeleteCurrentTopicMarkers,
  COLOR_GREEN,
  COLOR_ORANGE,
  COLOR_GRAY,
  Color,
} from "@ares-utils";

// These are the topics your script "subscribes" to. Ares will invoke your publisher function
// When any message is received on these topics.
// e.g. export const inputs: string[] = ["/pose", "/perception/tracked_object_list"]
export const inputs: string[] = ["/planning/seed", "/pose"];

// The name of the topic published
// When data is rendered in ImagePanel, the name must start with "/image_marker/"
// When data is rendered in 3DPanel, the name must start with "/studio_node/"
export const output: `/${"studio_node" | "image_marker"}/${string}` =
  "/studio_node/assist/scenario_dnn/agent";

// Configure the input and output when the code is executed
export const config: ScriptConfig = {};

// Used to overlap region upon other shapes.
const z_buffer = 0.1;

/**
 * This function is called with messages from your input topics.
 * The first argument is an event with the topic, receive time, and message.

 * @param messages According to the topic subscribed by "inputs", pass in the message corresponding to the topic.
 * @remarks Use the `Input<topicName>` helper to get the correct event type for your input topic messages.
 * @example
 * message: {
 *   "/pose": Input<"/pose">,
 *   "/perception/tracked_object_list": Input<"/perception/tracked_object_list">
 * }
 *
 * @param globalVariables Variables that can be accessed anywhere in the program, based on which the interactivity of the visual content can be configured
 * @see {@link https://cooper.didichuxing.com/knowledge/2199628491086/2199761277479} for more information
 *
 * @param blocks According to the topic subscribed by "inputs", all the messages of the corresponding topic in the bag are passed in
 *
 * @return the return format of the data is based on datatype
 */
const publisher = (
  messages: Record<string, Input<"/planning/seed"> | Input<"/pose">>,
  globalVars: GlobalVariables,
): Messages.ares__VisualizationMarkerArray | undefined => {
  const message_debug = messages["/planning/seed"] as Input<"/planning/seed">;
  const message_pose = messages["/pose"] as Input<"/pose">;
  if (!message_debug || !message_pose) {
    return undefined;
  }

  const tensorDict = message_debug.message.behaviorSeed.assistStuckSeed
    .assistStuckModelOutput.tensorDict as unknown as Record<
    string,
    Messages.planner__pb__RATensor
  >;

  if (tensorDict == null) {
    return undefined;
  }
  const pose_z = message_pose.message.z + z_buffer;

  const {
    receiveTime,
    message: {},
  } = message_debug;

  const markers: Messages.ares__VisualizationMarker[] = [
    createDeleteCurrentTopicMarkers(receiveTime),
  ];

  if (!tensorDict["agent_geometric"] || !tensorDict["agent_valid_history"]) {
    return undefined;
  }
  const agent_geometric = tensorDict["agent_geometric"].floatVals;
  const agent_valid_history = tensorDict["agent_valid_history"].intVals;
  const coordinate_x = message_pose.message.x;
  const coordinate_y = message_pose.message.y;
  const coordinate_yaw = message_pose.message.yaw;
  if (!agent_geometric || !agent_valid_history) {
    return undefined;
  }

  const agent_num = 50;
  const time_steps = 30;
  const points_per_box = 5;

  // 计算旋转矩阵的三角函数值
  const cosYaw = Math.cos(coordinate_yaw);
  const sinYaw = Math.sin(coordinate_yaw);

  // 遍历每个智能体
  for (let agent_idx = 0; agent_idx < agent_num; agent_idx++) {
    const valid_time_steps = agent_valid_history[agent_idx];

    // 如果该智能体没有有效时间步，跳过
    if (valid_time_steps <= 0) continue;

    const trajectory_points = [];

    // 遍历每个有效时间步
    for (let time_idx = 0; time_idx < valid_time_steps; time_idx++) {
      // 计算当前时间步在展平数组中的起始索引
      const time_start_index =
        agent_idx * time_steps * points_per_box * 2 +
        time_idx * points_per_box * 2;

      // 提取box的前4个点来计算中心点
      let sum_x = 0;
      let sum_y = 0;
      let valid_points = 0;

      for (let point_idx = 0; point_idx < 4; point_idx++) {
        // 只取前4个点
        const point_start_index = time_start_index + point_idx * 2;
        const local_x = agent_geometric[point_start_index];
        const local_y = agent_geometric[point_start_index + 1];

        sum_x += local_x;
        sum_y += local_y;
        valid_points++;
      }

      // 如果找到有效点，计算中心点并转换到世界坐标
      if (valid_points > 0) {
        const center_local_x = sum_x / valid_points;
        const center_local_y = sum_y / valid_points;

        // 应用旋转矩阵：将局部坐标旋转到世界坐标系方向
        const rotated_x = center_local_x * cosYaw - center_local_y * sinYaw;
        const rotated_y = center_local_x * sinYaw + center_local_y * cosYaw;

        // 应用平移：将旋转后的坐标平移到世界坐标系位置
        const world_x = rotated_x + coordinate_x;
        const world_y = rotated_y + coordinate_y;

        trajectory_points.push({
          x: world_x,
          y: world_y,
          z: pose_z - z_buffer - 0.8, // 略高于车道线，避免重叠
        });
      }
    }

    // 如果轨迹点数量不足2个，无法形成线段，跳过
    if (trajectory_points.length < 2) continue;

    // 创建轨迹线的marker
    const trajectory_marker = {
      header: {
        frame_id: "world",
        stamp: receiveTime,
        seq: 0,
      },
      id: "agent_trajectory_" + agent_idx,
      type: Messages.ares__VisualizationMarkerTypes.LINE_STRIP,
      action: 0,
      points: trajectory_points,
      color: {
        r: 1.0, // 红色表示轨迹
        g: 0.4,
        b: 0.0,
        a: 0.8, // 半透明
      },
      lineMetadata: {
        lineWidth: 0.5, // 轨迹线宽度
        closed: false, // 不闭合
      },
    };

    markers.push(trajectory_marker);
  }

  return {
    markers,
  };
};

export default publisher;

