// Minimal demo: visualize /planning/remote_assist_model_debug -> assistResponseFromRaVnode.referencePoints
import {
  GlobalVariables,
  createDeleteCurrentTopicMarkers,
  DEFAULT_STUDIO_NODE_PREFIX,
  COLOR_GRASS_GREEN,
  COLOR_PINK,
  COLOR_ORANGE,
  MemoryCacheBlock,
  euler2Quaternions,
} from "@ares-utils";
import { Input, Messages } from "@vitruvian/voyager-type";

export const inputs = ["/planning/customer_monitor_visual", "/pose"];
export const output = `${DEFAULT_STUDIO_NODE_PREFIX}planning/customer_monitor_visual/lane_boundary`;
export const config = {
  datatype: "ares/VisualizationMarkerArray",
};

export const publisher = (
  messages: Record<
    string,
    Input<"/planning/customer_monitor_visual"> | Input<"/pose">
  >,
  _globalVars: GlobalVariables,
  _blocks: readonly (MemoryCacheBlock | undefined)[],
): Messages.ares__VisualizationMarkerArray | undefined => {
  const msg = messages[
    "/planning/customer_monitor_visual"
  ] as Input<"/planning/customer_monitor_visual">;
  const pose_msg = messages["/pose"] as Input<"/pose">;
  if (!msg || !pose_msg) {
    return;
  }
  const { receiveTime } = msg;
  const pose_z: number = pose_msg.message.z;

  // 左侧点
  const leftPts: Array<{ x: number; y: number }> | undefined =
    msg.message?.leftLaneBoundary;
  if (!leftPts || leftPts.length === 0) {
    return { markers: [createDeleteCurrentTopicMarkers(receiveTime)] };
  }

  // z 统一设为 0
  const points: Messages.ares__Vec3[] = leftPts.map((p) => ({
    x: p.x,
    y: p.y,
    z: pose_z + 1.0,
  }));

  const markers: Messages.ares__VisualizationMarker[] = [
    // 清理当前 topic 的旧标记：只显示一帧
    createDeleteCurrentTopicMarkers(receiveTime),
    // 1) 折线（和你第一段风格一致）
    {
      header: { frame_id: "world", seq: 0, stamp: receiveTime },
      id: "ra-waypoints-line",
      type: Messages.ares__VisualizationMarkerTypes.LINE_STRIP,
      points,
      color: COLOR_GRASS_GREEN,
      lineMetadata: {
        lineWidth: 0.1,
        frustumCulled: false,
        sizeAttenuation: false,
      },
    },
  ];

  // 2) 逐点 POINT
  leftPts.forEach((p, index) => {
    markers.push({
      header: { frame_id: "world", seq: 0, stamp: receiveTime },
      id: `ra-waypoints-point-${index}`,
      type: Messages.ares__VisualizationMarkerTypes.POINT,
      action: Messages.ares__VisualizationMarkerAction.ADD,
      lifetime: { sec: 0, nsec: 0 },
      pose: {
        position: { x: p.x, y: p.y, z: pose_z + 1.1 },
        orientation: euler2Quaternions({ yaw: 0, pitch: 0, roll: 0 }),
      },
      // 和示例保持一致：用 scale.x 控制点大小，
      scale: { x: 0.2, y: 0, z: 0 },
      color: COLOR_GRASS_GREEN,
      // pointMetadata: { autoScale: true },
    });
  });

  // 右侧点
  const rightPts: Array<{ x: number; y: number }> | undefined =
    msg.message?.rightLaneBoundary;
  if (!rightPts || rightPts.length === 0) {
    return { markers: [createDeleteCurrentTopicMarkers(receiveTime)] };
  }

  // z 统一设为 0
  const sampled_points: Messages.ares__Vec3[] = rightPts.map((p) => ({
    x: p.x,
    y: p.y,
    z: pose_z + 1.0,
  }));

  // 折线
  markers.push({
    header: { frame_id: "world", seq: 0, stamp: receiveTime },
    id: "ra-waypoints-sampled-line",
    type: Messages.ares__VisualizationMarkerTypes.LINE_STRIP,
    points: sampled_points,
    color: COLOR_GRASS_GREEN, // 如需区分颜色，可改成 COLOR_PINK（若有）
    lineMetadata: {
      lineWidth: 0.1, // 比原始路径更细
      frustumCulled: false,
      sizeAttenuation: false,
    },
  });

  // 逐点（可选）
  rightPts.forEach((p, index) => {
    markers.push({
      header: { frame_id: "world", seq: 0, stamp: receiveTime },
      id: `ra-waypoints-sampled-point-${index}`,
      type: Messages.ares__VisualizationMarkerTypes.POINT,
      action: Messages.ares__VisualizationMarkerAction.ADD,
      lifetime: { sec: 0, nsec: 0 },
      pose: {
        position: { x: p.x, y: p.y, z: pose_z + 1.1 },
        orientation: euler2Quaternions({ yaw: 0, pitch: 0, roll: 0 }),
      },
      scale: { x: 0.2, y: 0, z: 0 }, // 稍小于原始点
      color: COLOR_GRASS_GREEN,
    });
  });

  return { markers };
};

