import { Input, Messages } from "ros";
import {
  GlobalVariables,
  ScriptConfig,
  createDeleteCurrentTopicMarkers,
} from "@ares-utils";

// In simulation, Planning builds the tensor from /simulation/pose rather than
// /pose. Keep both streams: simulation pose has priority and /pose is used on
// road-test bags where /simulation/pose is absent.
export const inputs: string[] = ["/planning/seed", "/pose", "/simulation/pose"];

export const output: `/${"studio_node" | "image_marker"}/${string}` =
  "/studio_node/assist/scenario_dnn/drivable_space";

export const config: ScriptConfig = {};

const NUM_CANDIDATES = 10;
const GEOMETRIC_POINTS = 80;
const TRAJECTORY_POINTS = 80;
const TENSOR_TO_METERS = 10.0;

// The VNode output is normally only one or a few planning cycles old.  Do not
// draw if the matching pose is missing: a current-pose fallback is misleading.
const MAX_POSE_HISTORY_MS = 10_000;
const MAX_POSE_ALIGNMENT_ERROR_MS = 150;

type PoseSample = {
  timeMs: number;
  x: number;
  y: number;
  z: number;
  yaw: number;
};

// Module state is preserved while an Ares script is running.
const localizationPoseHistory: PoseSample[] = [];
const simulationPoseHistory: PoseSample[] = [];

type PoseInput = Input<"/pose"> | Input<"/simulation/pose">;

const numberValue = (value: unknown): number | undefined => {
  if (typeof value === "number") {
    return Number.isFinite(value) ? value : undefined;
  }
  if (typeof value === "bigint") {
    return Number(value);
  }
  if (typeof value === "string") {
    const parsed = Number(value);
    return Number.isFinite(parsed) ? parsed : undefined;
  }
  return undefined;
};

// Ares/ROS versions serialize receiveTime either as epoch milliseconds,
// nanoseconds, or {sec, nsec}.  Normalize all supported forms to epoch ms.
const toEpochMs = (time: unknown): number | undefined => {
  const direct = numberValue(time);
  if (direct != null) {
    const abs = Math.abs(direct);
    if (abs >= 1e17) return direct / 1e6; // nanoseconds
    if (abs >= 1e14) return direct / 1e3; // microseconds
    if (abs >= 1e11) return direct; // milliseconds
    if (abs >= 1e8) return direct * 1e3; // seconds since epoch
    return direct;
  }

  if (time == null || typeof time !== "object") {
    return undefined;
  }
  const record = time as Record<string, unknown>;
  const sec = numberValue(record.sec ?? record.secs ?? record.seconds);
  const nsec = numberValue(
    record.nsec ?? record.nsecs ?? record.nanosec ?? record.nanoseconds,
  );
  if (sec == null) {
    return undefined;
  }
  return sec * 1e3 + (nsec ?? 0) / 1e6;
};

const recordPose = (poseInput: PoseInput, history: PoseSample[]): void => {
  // SnapshotTaker indexes its planner pose buffer by pose.timestamp().
  // receiveTime is only a fallback because it can be a different clock in Ares.
  const timeMs =
    toEpochMs(poseInput.message.timestamp) ?? toEpochMs(poseInput.receiveTime);
  if (timeMs == null) {
    return;
  }

  const lastSample = history[history.length - 1];
  if (lastSample != null && lastSample.timeMs === timeMs) {
    return;
  }

  history.push({
    timeMs,
    x: poseInput.message.x,
    y: poseInput.message.y,
    z: poseInput.message.z,
    yaw: poseInput.message.yaw,
  });

  const firstValidTime = timeMs - MAX_POSE_HISTORY_MS;
  while (history.length > 0 && history[0].timeMs < firstValidTime) {
    history.shift();
  }
};

const findClosestPose = (
  history: PoseSample[],
  targetTimeMs: number,
): PoseSample | undefined => {
  let closest: PoseSample | undefined;
  let smallestError = Number.POSITIVE_INFINITY;

  for (const sample of history) {
    const error = Math.abs(sample.timeMs - targetTimeMs);
    if (error < smallestError) {
      closest = sample;
      smallestError = error;
    }
  }

  return smallestError <= MAX_POSE_ALIGNMENT_ERROR_MS ? closest : undefined;
};

const publisher = (
  messages: Record<
    string,
    Input<"/planning/seed"> | Input<"/pose"> | Input<"/simulation/pose">
  >,
  _globalVars: GlobalVariables,
): Messages.ares__VisualizationMarkerArray | undefined => {
  const localizationPoseInput = messages["/pose"] as Input<"/pose">;
  if (localizationPoseInput != null) {
    recordPose(localizationPoseInput, localizationPoseHistory);
  }
  const simulationPoseInput = messages[
    "/simulation/pose"
  ] as Input<"/simulation/pose">;
  if (simulationPoseInput != null) {
    recordPose(simulationPoseInput, simulationPoseHistory);
  }

  const seed = messages["/planning/seed"] as Input<"/planning/seed">;
  if (seed == null) {
    return undefined;
  }

  const { receiveTime } = seed;
  const markers: Messages.ares__VisualizationMarker[] = [
    createDeleteCurrentTopicMarkers(receiveTime),
  ];

  const modelOutput =
    seed.message.behaviorSeed.assistStuckSeed.assistStuckModelOutput;
  if (modelOutput == null) {
    return { markers };
  }

  // TensorDict was produced for the timestamp recorded by PlanningSpeedVNode,
  // not necessarily the timestamp of this /planning/seed message.
  const featureTimeMs = toEpochMs(modelOutput.previousTimestamp);
  if (featureTimeMs == null) {
    return { markers };
  }
  // Planning uses /simulation/pose as RobotState.current_state_snapshot() in
  // InteractiveDataSim. Falling back to /pose is only for road-test bags.
  const alignedPose =
    findClosestPose(simulationPoseHistory, featureTimeMs) ??
    findClosestPose(localizationPoseHistory, featureTimeMs);
  if (alignedPose == null) {
    return { markers };
  }

  const tensorDict = modelOutput.tensorDict as unknown as Record<
    string,
    Messages.planner__pb__RATensor
  >;
  const geometric = tensorDict["drivable_space_geometric"]?.floatVals;
  const validGeometric = tensorDict["drivable_space_valid_geometric"]?.intVals;
  const trajectory = tensorDict["drivable_space_trajectory"]?.floatVals;
  const validTrajectory =
    tensorDict["drivable_space_valid_trajectory"]?.intVals;
  const validHistory = tensorDict["drivable_space_valid_history"]?.intVals;
  const selected = tensorDict["drivable_space_discrete"]?.intVals;

  if (geometric == null || validGeometric == null) {
    return { markers };
  }

  const cosYaw = Math.cos(alignedPose.yaw);
  const sinYaw = Math.sin(alignedPose.yaw);
  const polygonZ = alignedPose.z - 0.8;

  // Inverse of ConstructTensors():
  // local = 0.1 * R(-ego_yaw) * (world - ego_position).
  const toWorld = (localX: number, localY: number) => ({
    x:
      localX * TENSOR_TO_METERS * cosYaw -
      localY * TENSOR_TO_METERS * sinYaw +
      alignedPose.x,
    y:
      localX * TENSOR_TO_METERS * sinYaw +
      localY * TENSOR_TO_METERS * cosYaw +
      alignedPose.y,
  });

  for (let candidate = 0; candidate < NUM_CANDIDATES; ++candidate) {
    if ((validHistory?.[candidate] ?? 0) <= 0) {
      continue;
    }

    const isSelected = selected?.[candidate] === 1;
    const polygonColor = isSelected
      ? { r: 0.1, g: 1.0, b: 0.25, a: 1.0 } // selected: green
      : { r: 0.35, g: 0.75, b: 1.0, a: 0.4 }; // unselected: light blue
    const pathColor = isSelected
      ? { r: 0.55, g: 1.0, b: 0.65, a: 1.0 }
      : { r: 0.65, g: 0.88, b: 1.0, a: 0.45 };

    // geometric shape: [1, 10, 1, 81, 2].  The 81st point is a duplicated
    // first point for closure; validGeometric itself is capped at 80.
    const polygonCount = Math.min(
      validGeometric[candidate] ?? 0,
      GEOMETRIC_POINTS,
    );
    const polygonBase = candidate * (GEOMETRIC_POINTS + 1) * 2;
    const polygonPoints: { x: number; y: number; z: number }[] = [];

    for (let point = 0; point < polygonCount; ++point) {
      const offset = polygonBase + point * 2;
      const world = toWorld(geometric[offset], geometric[offset + 1]);
      polygonPoints.push({ ...world, z: polygonZ });
    }

    if (polygonPoints.length >= 3) {
      markers.push({
        header: { frame_id: "world", stamp: receiveTime, seq: 0 },
        id: `drivable_space_polygon_${candidate}`,
        type: Messages.ares__VisualizationMarkerTypes.LINE_STRIP,
        action: 0,
        points: polygonPoints,
        color: polygonColor,
        lineMetadata: {
          lineWidth: isSelected ? 0.45 : 0.25,
          closed: true,
        },
      });
    }

    // trajectory shape: [1, 10, 1, 80, 4], with each point laid out as
    // [x, y, heading, speed].  Only x/y are meaningful in this CR.
    const trajectoryCount = Math.min(
      validTrajectory?.[candidate] ?? 0,
      TRAJECTORY_POINTS,
    );
    const trajectoryBase = candidate * TRAJECTORY_POINTS * 4;
    const trajectoryPoints: { x: number; y: number; z: number }[] = [];

    if (trajectory != null) {
      for (let point = 0; point < trajectoryCount; ++point) {
        const offset = trajectoryBase + point * 4;
        const world = toWorld(trajectory[offset], trajectory[offset + 1]);
        trajectoryPoints.push({
          ...world,
          // Keep the reference line above the map and polygon.
          z: alignedPose.z + 0.5,
        });
      }
    }

    if (trajectoryPoints.length >= 2) {
      markers.push({
        header: { frame_id: "world", stamp: receiveTime, seq: 0 },
        id: `drivable_space_reference_path_${candidate}`,
        type: Messages.ares__VisualizationMarkerTypes.LINE_STRIP,
        action: 0,
        points: trajectoryPoints,
        color: pathColor,
        lineMetadata: {
          lineWidth: isSelected ? 1.0 : 0.25,
          closed: false,
        },
      });
    }
  }

  return { markers };
};

export default publisher;

