/* ares-expose-source-code */
// visualize /planning/customer_monitor_visual -> raPathInfo.{left,right}PathBoundary
// 用左右 boundary 拼出一个黄绿色半透明的带状 path
import {
  DEFAULT_STUDIO_NODE_PREFIX,
  MemoryCacheBlock,
  euler2Quaternions,
} from "@ares-utils";
import { Input, Messages } from "@vitruvian/voyager-type";

// 黄绿色 (yellow-green)
const COLOR_BAND_FILL = { r: 0.65, g: 0.75, b: 0.2, a: 0.2 }; // 半透明填充
const COLOR_BAND_EDGE = { r: 0.6, g: 0.7, b: 0.15, a: 0.6 }; // 边界线（更实一点）

export const inputs = ["/planning/customer_monitor_visual", "/pose"];
export const output = `${DEFAULT_STUDIO_NODE_PREFIX}planning/assist/swag/ra_monitor_path`;
export const config = {
  datatype: "ares/VisualizationMarkerArray",
};

export const publisher = (
  messages: Record<string, Input<"/planning/assist_response"> | Input<"/pose">>,
  _globalVars: unknown,
  _blocks: readonly (MemoryCacheBlock | undefined)[],
): Messages.ares__VisualizationMarkerArray | undefined => {
  const msg = messages["/planning/customer_monitor_visual"];
  const pose_msg = messages["/pose"] as Input<"/pose">;
  if (!msg || !pose_msg) return;

  const { receiveTime } = msg;
  const zOffset = pose_msg.message.z + 0.5;

  const raPathInfo: any = (msg.message as any)?.raPathInfo;
  const left = raPathInfo?.leftPathBoundary;
  const right = raPathInfo?.rightPathBoundary;

  const markers: Messages.ares__VisualizationMarker[] = [];
  if (
    !Array.isArray(left) ||
    left.length === 0 ||
    !Array.isArray(right) ||
    right.length === 0
  ) {
    return { markers };
  }

  const n = Math.min(left.length, right.length);

  // ---- 1) shape填充 ----
  const shapeRing: Messages.ares__Vec3[] = [];
  for (let i = 0; i < n; i++)
    shapeRing.push({ x: left[i].x, y: left[i].y, z: zOffset });
  for (let i = n - 1; i >= 0; i--)
    shapeRing.push({ x: right[i].x, y: right[i].y, z: zOffset });

  markers.push({
    header: { frame_id: "world", seq: 0, stamp: receiveTime },
    id: "ra-path-band-shape",
    ns: "ra_path_band_shape",
    type: Messages.ares__VisualizationMarkerTypes.SHAPE,
    action: Messages.ares__VisualizationMarkerAction.ADD,
    points: shapeRing,
    lifetime: { sec: 2, nsec: 0 },
    color: COLOR_BAND_FILL,
  });

