import { Input, Messages } from "ros";
import {
  EgoStore,
  euler2Quaternions,
  createDeleteCurrentTopicMarkers,
} from "@ares-utils";

export const inputs = ["/dpe/cat_hm_pose_01"];
export const output = "/studio_node/cat_human_model/hm_pose_01";
export const config = {};
const COLOR = {
  a: 0.75,
  r: 1,
  g: 0.27,
  b: 0.055,
};

const publisher = (
  messages: Record<string, Input<"/dpe/cat_hm_pose_01">>,
): Messages.ares__VisualizationMarkerArray => {
  const msg = messages["/dpe/cat_hm_pose_01"];
  if (!msg) {
    return {
      markers: [],
    };
  }

  const { receiveTime, message } = msg;

  const markers: Messages.ares__VisualizationMarker[] = [
    createDeleteCurrentTopicMarkers(receiveTime),
  ];
  markers.push({
    header: {
      frame_id: "world",
      stamp: receiveTime,
      seq: 0,
    },
    type: Messages.ares__VisualizationMarkerTypes.CUBE,
    id: `hm_cube_01`,
    action: Messages.ares__VisualizationMarkerAction.ADD,
    lifetime: { sec: 0, nsec: 0 },
    edge: false,
    fill: true,
    pose: {
      position: {
        x: message.x,
        y: message.y,
        z: message.z,
      },
      orientation: euler2Quaternions({
        yaw: message.yaw,
        pitch: 0,
        roll: 0,
      }),
    },
    scale: {
      x: EgoStore.getEgoSize().length,
      y: EgoStore.getEgoSize().width,
      z: EgoStore.getEgoSize().height,
    },
    color: COLOR,
  });

  return {
    markers,
  };
};

export default publisher;

