import {
  createPoseHistoryMarkers,
  createDeleteCurrentTopicMarkers,
  MemoryCacheBlock,
  variableConcat,
} from "@ares-utils";
import { Input, Messages } from "@vitruvian/voyager-type";

export const inputs = ["/dpe/cat_hm_pose_01"];
export const output = "/studio_node/cat_human_model/hm_pose_01_traj";

export const config = {
  datatype: "ares/VisualizationMarkerArray",
};
const COLOR = {
  a: 0.75,
  r: 1,
  g: 0.27,
  b: 0.055,
};
export const publisher = (
  messages: Record<string, Input<"/pose">>,
  _globalVars: unknown,
  blocks: readonly (MemoryCacheBlock | undefined)[],
): Messages.ares__VisualizationMarkerArray | undefined => {
  const messagePose = messages["/dpe/cat_hm_pose_01"];
  if (!messagePose) {
    return;
  }
  const { receiveTime } = messagePose;
  const markers = createPoseHistoryMarkers({
    name: "cat_hm_pose_01",
    topicPath: "/dpe/cat_hm_pose_01",
    blocks,
    receiveTime,
    poseColor: COLOR,
  });
  if (!markers.length) {
    return;
  }
  return {
    markers: variableConcat(
      [createDeleteCurrentTopicMarkers(receiveTime)],
      markers,
    ),
  };
};

