import { Input, Messages } from "@vitruvian/voyager-type";
import { getIntentionPlanDebug } from "@ares-utils";

type Output = string | undefined;
type GlobalVariables = { id: number };
type ScriptConfig = {
  // description: "Set whether to use all frame data"
  // tips: "Using all frame data will greatly affect the performance. Please use 'frontFrameLength' and 'behindFrameLength' to limit the data size"
  // default: true
  needFrameData?: boolean;

  // description: "set how many frames before the current frame will be transmitted"
  frontFrameLength?: number;
  // description: "set how many frames after the current frame will be transmitted"
  behindFrameLength?: number;
  // Whether this topic should be displayed on the switch tree of 3dPanel.
  showOn3DPanel?: boolean;
};
export const inputs = ["/planning/planning_debug"];
export const config: ScriptConfig = {
  needFrameData: false,
  showOn3DPanel: false,
};

// If this value is the same as a built-in output topic, the built-in output topic will be overwrite.
// You can get all the built-in output topic names in 'builtin-nodes.json' file on the left toolbar.
export const output = "/studio_node/planning/path_smoother/boundary_ray_infos";

// Populate 'Input' with a parameter to properly type your inputs, e.g. 'Input<"/your_input_topic">'
export const publisher = (
  messages: Record<string, Input<"/planning/planning_debug">>,
  globalVars: GlobalVariables,
): Record<string, Messages.voyager_data_msgs__CustomData> => {
  const message = messages[
    "/planning/planning_debug"
  ] as Input<"/planning/planning_debug">;
  const {
    message: { behaviorReasonerDebug },
  } = message;
  const intentionPlanDebug = getIntentionPlanDebug(
    behaviorReasonerDebug,
    globalVars,
  );

  const raysWithInfos =
    intentionPlanDebug?.pathPlannerDebug?.pathConstraintDebug
      ?.physicalBoundaryClearance ?? [];
  if (!raysWithInfos) {
    return {
      physicalRaysWithInfos: {},
    };
  }
  // Return the CustomData object
  return {
    physicalRaysWithInfos: raysWithInfos,
  };
};

export default publisher;

