import { Input, Messages } from "ros";
import {
  getIntentionPlanDebug,
  GlobalVariables,
  createDeleteCurrentTopicMarkers,
} from "@ares-utils";
import { Messages as StaticVoyagerType } from "@vitruvian/voyager-type";

export const inputs = ["/planning/planning_debug"];
export const output =
  "/studio_node/planning/path_generator/primitives/path_smoother/physical_rays_slider";

type Point = { x: number; y: number };

//==========util function=============
// Helper function to compute the ray endpoint.
const computeRayEndpoint = (
  reference: Point[],
  arclength: number,
  clearanceDistance: number,
  poseZ: number,
) => {
  const [rayStart, direction] = GetInterpPointAndDeriv(reference, arclength);
  const normalDir = { x: -direction.y, y: direction.x }; // 法向量

  const rayEnd = {
    x: rayStart.x + normalDir.x * clearanceDistance,
    y: rayStart.y + normalDir.y * clearanceDistance,
    z: poseZ + 1, // Adjust Z for visualization
  };
  return { rayStart, rayEnd };
};

// Function to get interpolated point and direction based on arc length.
const GetInterpPointAndDeriv = (
  reference: Point[],
  arclength: number,
): [Point, Point] => {
  let accumulatedLength = 0;
  let prevPoint = reference[0];

  // Calculate the total path length (arc length)
  for (let i = 1; i < reference.length; i++) {
    const currentPoint = reference[i];
    const segmentLength = Math.sqrt(
      Math.pow(currentPoint.x - prevPoint.x, 2) +
        Math.pow(currentPoint.y - prevPoint.y, 2),
    );
    accumulatedLength += segmentLength;
    prevPoint = currentPoint;
  }

  // If arclength is greater than or equal to total length, return last point and direction.
  if (arclength >= accumulatedLength) {
    const lastPoint = reference[reference.length - 1];
    const dx =
      reference[reference.length - 1].x - reference[reference.length - 2].x;
    const dy =
      reference[reference.length - 1].y - reference[reference.length - 2].y;

    // Calculate the magnitude of the direction vector
    const magnitude = Math.sqrt(dx * dx + dy * dy);

    // Normalize the direction vector to get the unit vector
    const direction =
      magnitude > 0 ? { x: dx / magnitude, y: dy / magnitude } : { x: 0, y: 0 };

    return [lastPoint, direction];
  }

  // Find the segment corresponding to the given arclength.
  let currentLength = 0;
  for (let i = 1; i < reference.length; i++) {
    const currentPoint = reference[i];
    const segmentLength = Math.sqrt(
      Math.pow(currentPoint.x - reference[i - 1].x, 2) +
        Math.pow(currentPoint.y - reference[i - 1].y, 2),
    );

    if (currentLength + segmentLength >= arclength) {
      const interpolationFactor = (arclength - currentLength) / segmentLength;
      const prevPoint = reference[i - 1];

      // Linear interpolation for point.
      const interpPoint: Point = {
        x: prevPoint.x + (currentPoint.x - prevPoint.x) * interpolationFactor,
        y: prevPoint.y + (currentPoint.y - prevPoint.y) * interpolationFactor,
      };

      // Direction (切线).
      const dx = currentPoint.x - prevPoint.x;
      const dy = currentPoint.y - prevPoint.y;
      const magnitude = Math.sqrt(dx * dx + dy * dy);
      const direction =
        magnitude > 0
          ? { x: dx / magnitude, y: dy / magnitude }
          : { x: 0, y: 0 };

      return [interpPoint, direction];
    }

    currentLength += segmentLength;
  }

  // If no suitable segment found, return last point and direction.
  const lastPoint = reference[reference.length - 1];
  const dx =
    reference[reference.length - 1].x - reference[reference.length - 2].x;
  const dy =
    reference[reference.length - 1].y - reference[reference.length - 2].y;

  // Calculate the magnitude of the direction vector.
  const magnitude = Math.sqrt(dx * dx + dy * dy);

  // Normalize the direction vector to get the unit vector.
  const direction =
    magnitude > 0 ? { x: dx / magnitude, y: dy / magnitude } : { x: 0, y: 0 };
  return [lastPoint, direction];
};
//========================================================

//===========create ray casting segment markers.===============
const createRayMarkers = (
  reference: Point[],
  clearanceData: any[],
  pose: any,
  receiveTime: any,
  resolution: number,
  arclengthRange: any,
  currentIndex: any,
  left: boolean,
) => {
  const markers: Messages.ares__VisualizationMarker[] = [];

  if (currentIndex >= 0 && currentIndex < clearanceData.length && pose) {
    const rayInfo = clearanceData[currentIndex];
    const { rayStart, rayEnd } = computeRayEndpoint(
      reference,
      currentIndex * resolution + arclengthRange.startPos,
      rayInfo.dilatedDistance,
      pose.z,
    );

    // Ray Segment。
    markers.push({
      header: {
        frame_id: "world",
        seq: 0,
        stamp: receiveTime,
      },
      type: Messages.ares__VisualizationMarkerTypes.LINE_STRIP,
      ns: "planning_debug_ray_casting_segments",
      id: `ray_casting_segments_${currentIndex}_${left}`,
      points: [
        { x: rayStart.x, y: rayStart.y, z: pose.z },
        { x: rayEnd.x, y: rayEnd.y, z: pose.z },
      ],
      lineMetadata: {
        lineWidth: 0.15,
      },
      color: { r: 0.8, g: 0.2, b: 0.2, a: 1.0 },
      scale: { x: 0.1, y: 0, z: 0 },
      renderOrder: 0,
    });

    // lateral gasp info.
    markers.push({
      header: { frame_id: "world", seq: 0, stamp: receiveTime },
      type: Messages.ares__VisualizationMarkerTypes.TEXT,
      ns: "lateral_gap",
      id: `lateral_gap_text_${currentIndex}_${left}`,
      pose: {
        position: {
          x: rayEnd.x,
          y: rayEnd.y,
          z: pose.z + 1,
        },
      },
      color: { r: 0.5, g: 0.84, b: 0.0, a: 1.0 },
      textMetadata: {
        text: `critical_${rayInfo.criticalRequiredLateralGap.toFixed(2)}_comfort_${rayInfo.comfortRequiredLateralGap.toFixed(2)}`,
        convertType: Messages.ares__TextConvertType.TEXT,
        textStyle: {
          transform: "scale(0.8)",
          lineHeight: "10px",
        },
      },
    });
  }
  return markers;
};
//===============================================

//==========publisher settings================
export const publisher = (
  messages: Record<string, Input<"/planning/planning_debug">>,
  globalVars: GlobalVariables,
): Messages.ares__VisualizationMarkerArray | undefined => {
  const message = messages[
    "/planning/planning_debug"
  ] as Input<"/planning/planning_debug">;
  if (!message) {
    return {
      markers: [],
    };
  }

  const {
    message: { pose },
    receiveTime,
  } = message;

  const behaviorReasonerDebug = (message.message?.behaviorReasonerDebug ??
    {}) as unknown as StaticVoyagerType.planner__pb__BehaviorReasonersDebug;

  const intentionPlanDebug = getIntentionPlanDebug(
    behaviorReasonerDebug,
    globalVars,
  );

  const pathSmootherDebug =
    intentionPlanDebug?.pathPlannerDebug?.pathSmootherDebug;
  const pathConstraintDebug =
    intentionPlanDebug?.pathPlannerDebug?.pathConstraintDebug;

  const reference =
    pathSmootherDebug?.decoupledPathPrimitivesDebug?.pathHeuristicPrimitive
      ?.referenceCurve.curve.segments[0].points;
  const physicalBoundaryClearance =
    pathConstraintDebug?.physicalBoundaryClearance;
  if (physicalBoundaryClearance == undefined) {
    return {
      markers: [],
    };
  }
  const resolution = physicalBoundaryClearance?.resolution;
  const arclengthRange = physicalBoundaryClearance?.effectiveReferenceRange;

  const leftClearanceData = physicalBoundaryClearance?.leftClearanceData ?? [];
  const rightClearanceData =
    physicalBoundaryClearance?.rightClearanceData ?? [];

  //  滑动条变量
  let currentIndex = globalVars.physical_ray_idx;

  //============= draw markers.===================

  if (
    (leftClearanceData.length === 0 && rightClearanceData.length === 0) ||
    !pose
  ) {
    return {
      markers: [],
    };
  }

  const rayCastingMarkers: Messages.ares__VisualizationMarker[] = [
    createDeleteCurrentTopicMarkers(receiveTime),
  ];

  // Process left clearance data
  rayCastingMarkers.push(
    ...createRayMarkers(
      reference,
      leftClearanceData,
      pose,
      receiveTime,
      resolution,
      arclengthRange,
      currentIndex,
      /*is_left=*/ true,
    ),
  );

  // Process right clearance data
  rayCastingMarkers.push(
    ...createRayMarkers(
      reference,
      rightClearanceData,
      pose,
      receiveTime,
      resolution,
      arclengthRange,
      currentIndex,
      /*is_left=*/ false,
    ),
  );

  return {
    markers: rayCastingMarkers,
  };
};

export default publisher;

