/* eslint-disable @typescript-eslint/no-unnecessary-condition */
/* ares-expose-source-code */
import { Input, Messages } from "ros";
import { Messages as StaticVoyagerType } from "@vitruvian/voyager-type";
import {
  GlobalVariables,
  DEFAULT_STUDIO_NODE_PREFIX,
  getIntentionPlanDebug,
  getSpeedSolverDebugIndex,
} from "@ares-utils";
import { isUndefined, forEach, max, min, map } from "lodash";

export const inputs = ["/planning/planning_debug"];
export const output = `${DEFAULT_STUDIO_NODE_PREFIX}planning/planning_debug/static_range_debug`;

export const publisher = (
  messages: Record<string, Input<"/planning/planning_debug">>,
  globalVariables: GlobalVariables,
): Messages.ares__CustomizationPlot => {
  const message = messages[
    "/planning/planning_debug"
  ] as Input<"/planning/planning_debug">;

  // Static Range Data
  const passStaticRangeCurvesConfig: Messages.ares__CustomizationPlotData = {
    lines: [],
    borderColor: "#00bfff",
    borderWidth: 1.5,
    borderDash: [8, 8],
    pointBackgroundColor: "#00bfff",
    pointRadius: 1.0,
  };

  const yieldStaticRangeCurvesConfig: Messages.ares__CustomizationPlotData = {
    lines: [],
    borderColor: "#00bfff",
    borderWidth: 1.5,
    pointBackgroundColor: "#00bfff",
    pointRadius: 1.0,
  };

  const branchPassStaticRangeCurvesConfig: Messages.ares__CustomizationPlotData =
    {
      lines: [],
      borderColor: "#0080ff",
      borderWidth: 1.5,
      borderDash: [8, 8],
      pointBackgroundColor: "#0080ff",
      pointRadius: 1.0,
    };

  const branchYieldStaticRangeCurvesConfig: Messages.ares__CustomizationPlotData =
    {
      lines: [],
      borderColor: "#0080ff",
      borderWidth: 1.5,
      pointBackgroundColor: "#0080ff",
      pointRadius: 1.0,
    };

  const behaviorReasonerDebug = (message.message?.behaviorReasonerDebug ??
    {}) as unknown as StaticVoyagerType.planner__pb__BehaviorReasonersDebug;

  const intentionPlanDebug = getIntentionPlanDebug(
    behaviorReasonerDebug,
    globalVariables,
  );

  const speedGeneratorDebug =
    intentionPlanDebug?.speedGeneratorDebug as Messages.speed__pb__SpeedGeneratorDebug;

  const speedSolverDebugIndex = getSpeedSolverDebugIndex(
    behaviorReasonerDebug,
    globalVariables,
  );

  const solverDebug =
    speedGeneratorDebug?.speedSolverDebugs[speedSolverDebugIndex];
  const kDt = 0.1;

  const passStaticRangeCurvesLine: Messages.ares__CustomizationPlotLine = {
    line: [],
  };

  const yieldStaticRangeCurvesLine: Messages.ares__CustomizationPlotLine = {
    line: [],
  };

  const branchPassStaticRangeCurvesLine: Messages.ares__CustomizationPlotLine =
    {
      line: [],
    };

  const branchYieldStaticRangeCurvesLine: Messages.ares__CustomizationPlotLine =
    {
      line: [],
    };

  if (solverDebug) {
    const staticRanges = solverDebug?.optDebug?.potentialDebug?.staticRanges;
    const branchStaticRanges = (
      solverDebug?.optDebug?.potentialDebug as undefined as any
    )?.branchStaticRanges;

    if (staticRanges != undefined) {
      for (let stateIx = 0; stateIx < staticRanges.length; stateIx++) {
        const staticRange = staticRanges[stateIx];

        for (let ix = 0; ix < staticRange.passX.length; ix++) {
          passStaticRangeCurvesLine.line.push({
            x: stateIx * kDt,
            y: staticRange?.passX[ix],
          });
        }

        for (let ix = 0; ix < staticRange.yieldX.length; ix++) {
          yieldStaticRangeCurvesLine.line.push({
            x: stateIx * kDt,
            y: staticRange?.yieldX[ix],
          });
        }
      }
    }

    if (branchStaticRanges != undefined) {
      for (let stateIx = 0; stateIx < branchStaticRanges.length; stateIx++) {
        const branchStaticRange = branchStaticRanges[stateIx];

        for (let ix = 0; ix < branchStaticRange.passX.length; ix++) {
          branchPassStaticRangeCurvesLine.line.push({
            x: stateIx * kDt,
            y: branchStaticRange?.passX[ix],
          });
        }

        for (let ix = 0; ix < branchStaticRange.yieldX.length; ix++) {
          branchYieldStaticRangeCurvesLine.line.push({
            x: stateIx * kDt,
            y: branchStaticRange?.yieldX[ix],
          });
        }
      }
    }
  }

  passStaticRangeCurvesConfig.lines.push(passStaticRangeCurvesLine);
  yieldStaticRangeCurvesConfig.lines.push(yieldStaticRangeCurvesLine);
  branchPassStaticRangeCurvesConfig.lines.push(branchPassStaticRangeCurvesLine);
  branchYieldStaticRangeCurvesConfig.lines.push(
    branchYieldStaticRangeCurvesLine,
  );

  return {
    data: [
      passStaticRangeCurvesConfig,
      yieldStaticRangeCurvesConfig,
      branchPassStaticRangeCurvesConfig,
      branchYieldStaticRangeCurvesConfig,
    ],
  };
};

