/* eslint-disable @foxglove/no-boolean-parameters */
/* eslint-disable no-case-declarations */
/* eslint-disable @typescript-eslint/no-non-null-asserted-optional-chain */
/* eslint-disable @foxglove/strict-equality */
/* eslint-disable @typescript-eslint/no-unnecessary-condition */
/* ares-expose-source-code */
import {
  getIntentionPlanDebug,
  populateStartXAndEndXFromConstraintState,
  getSpeedSolverDebugIndex,
  getObjectId,
  getConstraints,
  GlobalVariables,
  DEFAULT_STUDIO_NODE_PREFIX,
  getOverlapRegionUniqueId,
  getQPointsFromProfileForAresPlot,
  getCurvePointForAresPlot,
  addSpeedProfileForAresPlot,
  getSpeedProfileForAresPlot,
  GetSpeedProfile,
  getPerDiscomfortDebug,
  DropdownOption,
} from "@ares-utils";
import { Input, Messages } from "@vitruvian/voyager-type";
import { last, forEach, forIn, isUndefined, map } from "lodash";

import { filterMap } from "@foxglove/den/collection";

const kStPlotTimeHorizonInSec = 10.0;
const kStPlotMinDistanceInM = -50;
const kStPlotMaxDistanceInM = 120;

const softBorderDash: [number, number] = [9, 9];
const borderDash: [number, number] = [3, 3];

const kSelectAllConstraintsLabel = "Select All Constraints";

const GAP_ALIGN = "GAP_ALIGN";

export const inputs = ["/planning/planning_debug"];

export const output = `${DEFAULT_STUDIO_NODE_PREFIX}planning/multi_st_plot`;
export const config = {
  datatype: "voyager_data_msgs/CustomData",
  showOn3DPanel: false,
};

export const publisher = (
  messages: Record<string, Input<"/planning/planning_debug">>,
  globalVars: GlobalVariables,
): Messages.voyager_data_msgs__CustomData | undefined => {
  const planningEnableOverlapV2 =
    globalVars.planning_enable_overlap_v2 ?? false;
  const message_p = messages[
    "/planning/planning_debug"
  ] as Input<"/planning/planning_debug">;
  const message = message_p.message;

  if (!message) {
    return {};
  }

  const intentionPlanDebug = getIntentionPlanDebug(
    message.behaviorReasonerDebug,
    globalVars,
  );

  const speedGeneratorDebug =
    intentionPlanDebug?.speedGeneratorDebug as Messages.planner__speed__pb__SpeedGeneratorDebug;

  const speedSolverDebugIndex = getSpeedSolverDebugIndex(
    message.behaviorReasonerDebug,
    globalVars,
  );

  const speedSolverDebug =
    speedGeneratorDebug?.speedSolverDebugs[speedSolverDebugIndex];
  const searchDebug = speedSolverDebug?.searchDebug;

  // Show a-t curve (dash dot line) for speed profile
  const showAtCurve = !!globalVars.planning_show_at_curve;
  // Show v-t curve (dash line) for speed profile
  const showVtCurve = !!globalVars.planning_show_vt_curve;
  const showRiskTimeMap = !!globalVars.planning_show_risk_time_map;

  const planInitTimeInSec = speedSolverDebug?.planInitTimeInSec as number;
  const constraints = getConstraints(
    searchDebug,
    speedGeneratorDebug,
  ) as Messages.planner__speed__pb__Constraint[];

  const singleConstraintSelectors =
    (globalVars.planning_constraint_selectors as string[]) ?? [];
  const fuzzyConstraintSelectors =
    globalVars.planning_fuzzy_constraint_selectors ?? [];
  const allSelectedConstraintIds = filterSelectedItems(
    constraints,
    singleConstraintSelectors,
    fuzzyConstraintSelectors,
    globalVars,
  );

  const dominantConstraintId = constraints?.[
    searchDebug?.dominantConstraintIx as number
  ]?.uniqueConstraintId as string;

  const dominantConstraintLabel =
    getDominantConstraintLabel(dominantConstraintId);

  const discomfortValue = searchDebug?.selectedReference?.discomfortValue;

  const overlapRegion: Messages.ares__CustomizationPlot = getOverlapRegion({
    searchDebug,
    allSelectedConstraintIds,
    dominantConstraintId,
    dominantConstraintLabel,
    speedGeneratorDebug,
    planningEnableOverlapV2,
  });

  const forIntermediateResult = isForIntermediateResult(
    globalVars?.planning_speed_discomforts_level,
    globalVars?.planning_speed_discomforts_iteration,
  );

  const perDiscomfortDebug = getPerDiscomfortDebug(
    searchDebug,
    globalVars?.planning_speed_discomforts_level,
  );
  const decisions =
    perDiscomfortDebug?.iterativeProfiles?.[
      Number(globalVars?.planning_speed_discomforts_iteration)
    ]?.currDecisions;

  const constraint = getConstraint(
    searchDebug?.constraints ?? [],
    searchDebug,
    allSelectedConstraintIds,
    dominantConstraintId,
    dominantConstraintLabel,
    forIntermediateResult,
    decisions,
    speedGeneratorDebug?.primitiveConstraints ?? [],
  );

  // cn9081552
  // cn9081214
  const { gapAlignActiveTimeData, gapAlignMaxActiveTimeData } =
    getGapAlignActiveTime({
      searchDebug,
      planInitTimeInSec,
      allSelectedConstraintIds,
      dominantConstraintId,
      dominantConstraintLabel,
      showVtCurve,
      showAtCurve,
      constraints,
    });

  const intentionSelectedProfileStates = map(
    speedSolverDebug?.intentionSelectedProfile?.states,
    (state) => ({
      ...state,
      x:
        state.x -
        (speedSolverDebug?.intentionSelectedProfile?.states[0]?.x ?? 0),
    }),
  );

  return {
    // Overlap Region (dashed-white-padded, solid-white-strict)
    overlapRegion,
    // Time Map  (red-yield, green-pass)
    timeMap: addTimeMaps({
      searchDebug,
      speedGeneratorDebug,
      allSelectedConstraintIds,
      dominantConstraintId,
      dominantConstraintLabel,
      perDiscomfortDebug,
      forIntermediateResult,
      decisions,
      constraints: getConstraints(searchDebug, speedGeneratorDebug),
      showRiskTimeMap,
    }),
    // Init Gap Align Active Time (cyan-yield, cyan-pass)
    gapAlignActiveTime: gapAlignActiveTimeData,
    // Init max Gap Align Active Time (cyan-yield, cyan-pass)
    gapAlignMaxActiveTime: gapAlignMaxActiveTimeData,
    // Selected Reference
    selectedReference: getSpeedProfileForAresPlot({
      profile: searchDebug?.selectedReference?.profile,
      planInitTimeInSec,
      color: "blue",
      showAtCurve,
      showVtCurve,
      lineType: "solid",
    }),
    // Final Profile
    finalProfile: getSpeedProfileForAresPlot({
      profile: speedSolverDebug?.finalProfile,
      planInitTimeInSec,
      color: "green",
      showAtCurve,
      showVtCurve,
      lineType: "solid",
    }),
    // Gap ALign Overlap Region (dashed-gray-padded, solid-gray-strict)
    gapALignOverlapRegion: getGapAlignOverlapRegion({
      searchDebug,
      allSelectedConstraintIds,
      dominantConstraintId,
      dominantConstraintLabel,
      speedGeneratorDebug,
      planningEnableOverlapV2,
    }),
    // Search Profile
    // cn9980994(时间戳 1700208951279 左右)
    searchProfile: getSearchProfile({
      searchDebug,
      planInitTimeInSec,
      color: "yellow",
      showAtCurve,
      showVtCurve,
      discomfortValue,
      lineType: "solid",
    }),
    // Min Profile(dotted)
    minProfile: getSpeedProfileForAresPlot({
      profile: searchDebug?.minSpeedProfile,
      planInitTimeInSec,
      color: "blue",
      showAtCurve,
      showVtCurve,
      lineType: "solid",
    }),
    // Constraint (yellow-yield, cyan-pass)
    constraint,
    // Optimized Profile
    optimizedProfile: getSpeedProfileForAresPlot({
      profile: speedSolverDebug?.optDebug?.optimizedProfile,
      planInitTimeInSec,
      color: "pink",
      showAtCurve,
      showVtCurve,
      lineType: "solid",
    }),
    // Intention Profile
    intentionProfile: getSpeedProfileForAresPlot({
      profile: {
        ...speedSolverDebug?.intentionSelectedProfile,
        states: intentionSelectedProfileStates,
      },
      planInitTimeInSec,
      color: "white",
      showAtCurve,
      showVtCurve,
      lineType: "solid",
    }),
    allScrCandidates: getAllSCRCandidates({
      searchDebug,
      planInitTimeInSec,
      color: "gray",
      showAtCurve,
      showVtCurve,
      lineType: "solid",
    }),
  };
};

function filterSelectedItems(
  allConstraints: Messages.planner__speed__pb__Constraint[],
  singleSelectedConstraintIds: string[],
  fuzzySelectedConstraintIds: string[],
  globalVars: GlobalVariables,
): string[] {
  const regexRules: { pattern: RegExp; original: string }[] = [];

  for (const fuzzyRule of fuzzySelectedConstraintIds) {
    try {
      regexRules.push({
        pattern: new RegExp(fuzzyRule),
        original: fuzzyRule,
      });
    } catch (e) {
      console.warn(`invalid RegExp: ${fuzzyRule}`, e);
    }
  }

  const selectedIds = new Set(singleSelectedConstraintIds);
  const selectedConstraints = allConstraints.filter((constraint) => {
    const id = (constraint as undefined as any)?.uniqueConstraintId as string;
    if (selectedIds.has(id)) return true;
    if (
      regexRules.some((rule) =>
        constraintsFromObj(constraint, rule.pattern, globalVars),
      )
    ) {
      return true;
    }
    return false;
  });

  let selectedConstraintIds = [];
  forEach(selectedConstraints, (constraint, index) => {
    const uniqueConstraintId = (constraint as undefined as any)
      ?.uniqueConstraintId as string;
    selectedConstraintIds.push(uniqueConstraintId);
  });

  return selectedConstraintIds;
}

function constraintsFromObj(
  constraint: Messages.planner__speed__pb__Constraint,
  rule: RegExp,
  globalVars: GlobalVariables,
): boolean {
  const id = (constraint as undefined as any)?.uniqueConstraintId as string;
  if (!rule.test(id)) {
    return false;
  }
  if (globalVars.planning_constraint_selector_any) {
    return true;
  }

  // Is nominal.
  if (
    globalVars.planning_constraint_selector_is_nominal &&
    ["HARD", "NA"].includes(
      (constraint?.settings as unknown as any)?.passOption as string,
    ) &&
    ["HARD", "NA"].includes(
      (constraint?.settings as unknown as any)?.yieldOption as string,
    )
  ) {
    return true;
  }

  // Is soft yield.
  if (
    globalVars.planning_constraint_selector_is_soft_yield &&
    ((constraint?.settings as unknown as any)?.yieldOption as string) === "SOFT"
  ) {
    return true;
  }

  // Is New YAP
  if (
    globalVars.planning_constraint_selector_is_new_yap &&
    ((constraint?.settings as unknown as any)?.yieldOption as string) ===
      "YIELD_ALWAYS_POSSIBLE"
  ) {
    return true;
  }

  // Is start to move.
  const startToMoveRegex = /pred-999(?=$|[-_])/;
  if (
    globalVars.planning_constraint_selector_is_start_to_move &&
    startToMoveRegex.test(id)
  ) {
    return true;
  }

  // Is yield always possible.
  if (
    globalVars.planning_constraint_selector_is_yield_always_possible &&
    (constraint?.settings as unknown as any)?.hardYieldWithMinAccel
  ) {
    return true;
  }

  // Is creep.
  if (
    globalVars.planning_constraint_selector_is_creep &&
    (constraint?.settings as unknown as any)?.isCreep
  ) {
    return true;
  }

  // Is gap align.
  if (
    globalVars.planning_constraint_selector_is_gap_align &&
    (constraint?.type as string) === "GAP_ALIGN"
  ) {
    return true;
  }

  return false;
}

function getConstraint(
  constraints: Messages.planner__speed__pb__Constraint[],
  searchDebug: Messages.planner__speed__pb__SpeedSearchDebug | undefined,
  allSelectedConstraintIds: string[] = [],
  dominantConstraintId: string = "",
  dominantConstraintLabel: string = "",
  forIntermediateResult = false,
  decisions: Messages.planner__speed__pb__SpeedDecision[] = [],
  primitiveConstraints: Messages.planner__speed__pb__PrimitiveConstraint[] = [],
): Messages.ares__CustomizationPlot {
  const constraintConfig: Messages.ares__CustomizationPlotData[] = filterMap(
    constraints,
    (constraint, index) => {
      const uniqueConstraintId =
        (primitiveConstraints?.[index] ?? constraints[index])
          ?.uniqueConstraintId ?? "";
      if (
        isConstraintSelected(
          uniqueConstraintId,
          dominantConstraintId,
          dominantConstraintLabel,
          allSelectedConstraintIds,
        )
      ) {
        constraint.uniqueConstraintId = uniqueConstraintId;
        const decision = forIntermediateResult
          ? decisions?.[index]
          : searchDebug?.decisions?.[index];
        return addConstraint(constraint, decision);
      }
      return undefined;
    },
  );
  return {
    data: constraintConfig,
  };
}

function isConstraintSelected(
  uniqueConstraintId: string = "",
  dominantConstraintId: string = "",
  dominantConstraintLabel: string = "",
  allSelectedConstraintIds: string[] = [],
) {
  // 未选
  if (!allSelectedConstraintIds.length) {
    return false;
  }
  // 全选
  if (allSelectedConstraintIds.includes(kSelectAllConstraintsLabel)) {
    return true;
  }

  if (
    allSelectedConstraintIds.includes(dominantConstraintLabel) &&
    uniqueConstraintId === dominantConstraintId
  ) {
    return true;
  }

  return allSelectedConstraintIds.includes(uniqueConstraintId);
}

function addConstraint(
  constraint: Messages.planner__speed__pb__Constraint,
  decision: Messages.planner__speed__pb__SpeedDecision = "",
): Messages.ares__CustomizationPlotData {
  const discomfort = constraint?.selectedDiscomfort;
  const constraintIntervalSamples: Samples[] = [];
  forEach(constraint?.states, (state) => {
    if (
      state?.startTime !== undefined &&
      state?.startTime <= kStPlotTimeHorizonInSec
    ) {
      const { startX, endX } = populateStartXAndEndXFromConstraintState(
        state,
        discomfort,
      );
      constraintIntervalSamples.push({
        x: state?.startTime,
        y1: startX,
        y2: endX,
      });
      constraintIntervalSamples.push({
        x: Math.min(state.endTime, kStPlotTimeHorizonInSec),
        y1: startX,
        y2: endX,
      });
    }
  });
  if (!constraintIntervalSamples.length) {
    return { lines: [] };
  }

  let color = "";
  if (decision === "YIELD") {
    color = "yellow";
  } else if (decision === "PASS") {
    color = "cyan";
  } else {
    color = "gray";
  }

  // const pointsBySample = getPointsBySample(constraintIntervalSamples);
  const pointsBySample = getPointsBySample(constraintIntervalSamples);
  const constraintPoint: Messages.ares__CustomizationPlotData["lines"] = [
    {
      line: pointsBySample,
    },
  ];
  // const constraintPoint = transOverlapRegion([pointsBySample]);
  // const lastPonit = last(constraintPoint)?.[0] as CustomPlotPoint;
  const lastPoint = last(pointsBySample);
  constraintPoint.push({
    line: [
      {
        label: constraint?.uniqueConstraintId,
        x: (lastPoint?.x ?? 0) - 1,
        y: lastPoint?.y ?? 0,
        labelColor: "white",
      },
    ],
  });
  return {
    lines: constraintPoint,
    pointBackgroundColor: color,
    borderColor: color,
  };
}

type Samples = {
  x: number;
  y1: number;
  y2: number;
};

const nullPoint = {
  x: NaN,
  y: NaN,
};

function getPointsBySample(
  samples: Samples[] = [],
): Messages.ares__CustomizationPlotLine["line"] {
  const topLine: Messages.ares__CustomizationPlotLine["line"] = [];
  const bottomLine: Messages.ares__CustomizationPlotLine["line"] = [];
  const midLine: Messages.ares__CustomizationPlotLine["line"] = [];
  forEach(samples, (sample) => {
    topLine.push({
      x: sample.x,
      y: sample.y1,
    });
    bottomLine.push({
      x: sample.x,
      y: sample.y2,
    });
    midLine.push(
      {
        x: sample.x,
        y: sample.y1,
      },
      {
        x: sample.x,
        y: sample.y2,
      },
      nullPoint,
    );
  });
  return topLine
    .concat([nullPoint])
    .concat(midLine)
    .concat([nullPoint])
    .concat(bottomLine);
}

