function addOverlapRegionPointsBySample(
  region: Messages.planner__speed__pb__OverlapRegion,
  planningEnableOverlapV2: boolean,
): {
  paddedInterval: Messages.ares__CustomizationPlotLine["line"];
  strictInterval: Messages.ares__CustomizationPlotLine["line"];
  paddedIntervalSamples: Samples | undefined;
} {
  const paddedIntervalSamples: Samples[] = [];
  const strictIntervalSamples: Samples[] = [];
  forEach(region?.overlapSlices, (overlapSlice) => {
    if (hasPaddedOverlap({ slice: overlapSlice, planningEnableOverlapV2 })) {
      paddedIntervalSamples.push({
        x: overlapSlice.relativeTimeInSec,
        y1: getPaddedOverlapStart({
          slice: overlapSlice,
          planningEnableOverlapV2,
        }),
        y2: getPaddedOverlapEnd({
          slice: overlapSlice,
          planningEnableOverlapV2,
        }),
      });
      if (hasStrictOverlap({ slice: overlapSlice, planningEnableOverlapV2 })) {
        strictIntervalSamples.push({
          x: overlapSlice.relativeTimeInSec,
          y1: getStrictOverlapStart({
            slice: overlapSlice,
            planningEnableOverlapV2,
          }),
          y2: getStrictOverlapEnd({
            slice: overlapSlice,
            planningEnableOverlapV2,
          }),
        });
      }
    }
  });
  return {
    paddedInterval: getPointsBySample(paddedIntervalSamples),
    strictInterval: getPointsBySample(strictIntervalSamples),
    paddedIntervalSamples: last(paddedIntervalSamples),
  };
}

type ConstraintSelectorParams = {
  speedGeneratorDebug: Messages.planner__speed__pb__SpeedGeneratorDebug;
  searchDebug: Messages.planner__speed__pb__SpeedSearchDebug | undefined;
  allSelectedConstraintIds: string[];
  dominantConstraintId: string;
  dominantConstraintLabel: string;
  planningEnableOverlapV2?: boolean;
};

function getOverlapToAddMap({
  speedGeneratorDebug,
  searchDebug,
  allSelectedConstraintIds,
  dominantConstraintId,
  dominantConstraintLabel,
}: ConstraintSelectorParams) {
  const selectedConstraintsMap: Map<string, boolean> = new Map();
  const constraints = getConstraints(searchDebug, speedGeneratorDebug);
  forEach(constraints, (constraint, index) => {
    if (
      isConstraintSelected(
        constraints?.[index]?.uniqueConstraintId,
        dominantConstraintId,
        dominantConstraintLabel,
        allSelectedConstraintIds,
      )
    ) {
      selectedConstraintsMap.set(constraint.uniqueOverlapId, true);
    }
  });
  return selectedConstraintsMap;
}

function getOverlapRegion({
  searchDebug,
  allSelectedConstraintIds,
  dominantConstraintId,
  dominantConstraintLabel,
  speedGeneratorDebug,
  planningEnableOverlapV2,
}: ConstraintSelectorParams): Messages.ares__CustomizationPlot {
  const overlapRegions = speedGeneratorDebug?.overlapRegions ?? [];
  const paddedIntervalRegion: Messages.ares__CustomizationPlotData["lines"] =
    [];
  const strictIntervalRegion: Messages.ares__CustomizationPlotData["lines"] =
    [];
  const overlapRegionText: Messages.ares__CustomizationPlotData["lines"] = [];
  const overlapToAddMap = getOverlapToAddMap({
    searchDebug,
    allSelectedConstraintIds,
    dominantConstraintId,
    dominantConstraintLabel,
    speedGeneratorDebug,
  });

  forEach(overlapRegions, (overlapRegion) => {
    const uniqueOverlapId = getOverlapRegionUniqueId(overlapRegion);
    if (
      allSelectedConstraintIds.includes(kSelectAllConstraintsLabel) ||
      overlapToAddMap.get(uniqueOverlapId)
    ) {
      const overlapSamples = addOverlapRegionPointsBySample(
        overlapRegion,
        !!planningEnableOverlapV2,
      );
      paddedIntervalRegion.push({
        line: overlapSamples.paddedInterval,
      });
      strictIntervalRegion.push({
        line: overlapSamples.strictInterval,
      });
      const textLine = getOverlapRegionText(
        overlapSamples.paddedIntervalSamples,
        overlapRegion,
      );
      if (textLine) {
        overlapRegionText.push({
          line: textLine,
        });
      }
    }
  });
  return {
    data: [
      {
        borderDash,
        borderColor: "white",
        pointBackgroundColor: "white",
        lines: paddedIntervalRegion,
      },
      {
        borderColor: "white",
        pointBackgroundColor: "white",
        lines: strictIntervalRegion,
      },
      {
        lines: overlapRegionText,
      },
    ],
  };
}

function getOverlapRegionText(
  samples: Samples | undefined,
  region: Messages.planner__speed__pb__OverlapRegion,
): Messages.ares__CustomizationPlotLine["line"] | undefined {
  if (samples) {
    return [
      {
        x: samples?.x - 1,
        y: samples.y2,
        label: `${getOverlapRegionUniqueId(region)}\n${region.motionType}`,
        labelColor: "white",
      },
    ];
  }
  return undefined;
}

function getGapAlignOverlapRegion({
  searchDebug,
  allSelectedConstraintIds,
  dominantConstraintId,
  dominantConstraintLabel,
  speedGeneratorDebug,
  planningEnableOverlapV2,
}: ConstraintSelectorParams): Messages.ares__CustomizationPlot {
  const gapAlignOverlapRegions =
    speedGeneratorDebug?.speedReasoningDebug?.reasonerDebug
      ?.laneChangeSpeedReasoner?.gapAlignOverlapRegions ?? [];

  const overlapRegions = speedGeneratorDebug?.overlapRegions ?? [];

  const gapAlignOverlapRegionsConfig: Messages.ares__CustomizationPlot = {
    data: [],
  };
  const constraints = getConstraints(searchDebug, speedGeneratorDebug);
  const overlapToAddMap = getOverlapToAddMap({
    searchDebug,
    allSelectedConstraintIds,
    dominantConstraintId,
    dominantConstraintLabel,
    speedGeneratorDebug,
  });

  forEach(overlapRegions, (overlapRegion) => {
    const uniqueOverlapId = getOverlapRegionUniqueId(overlapRegion);
    if (overlapToAddMap.has(uniqueOverlapId)) {
      const validConstraint = constraints.find(
        (constraint) =>
          constraint.uniqueOverlapId === uniqueOverlapId &&
          constraint.type === GAP_ALIGN,
      );
      if (validConstraint) {
        const overlapRegionPlot = addOverlapRegion(
          overlapRegion,
          "gray",
          !!planningEnableOverlapV2,
        );
        gapAlignOverlapRegionsConfig.data.push(...overlapRegionPlot.data);
      }
    }
  });

  forEach(gapAlignOverlapRegions, (gapAlignOverlapRegion) => {
    const uniqueOverlapId = getOverlapRegionUniqueId(gapAlignOverlapRegion);
    if (overlapToAddMap.has(uniqueOverlapId)) {
      const gapOverlapRegionPlot = addOverlapRegion(
        gapAlignOverlapRegion,
        "gray",
        !!planningEnableOverlapV2,
      );
      gapAlignOverlapRegionsConfig.data.push(...gapOverlapRegionPlot.data);
    }
  });

  return gapAlignOverlapRegionsConfig;
}

type AllConstraints = {
  yieldPoints: { x: number; y: number }[];
  passPoints: { x: number; y: number }[];
};

function getDominantConstraintLabel(dominantConstraintId = "") {
  return `Dominant Constraint(${dominantConstraintId})`;
}

type AddTimeMaps = {
  searchDebug: Messages.planner__speed__pb__SpeedSearchDebug | undefined;
  speedGeneratorDebug:
    | Messages.planner__speed__pb__SpeedGeneratorDebug
    | undefined;
  allSelectedConstraintIds: string[];
  dominantConstraintId: string;
  dominantConstraintLabel: string;
  discomfortsLevel?: string;
  discomfortsIteration?: string;
  forIntermediateResult: boolean;
  perDiscomfortDebug?: Messages.planner__speed__pb__PerDiscomfortDebug;
  decisions?: Messages.planner__speed__pb__SpeedDecision[];
  showRiskTimeMap: boolean;
  constraints:
    | Messages.planner__speed__pb__Constraint[]
    | Messages.planner__speed__pb__PrimitiveConstraint[];
};

function getImmutableTimeConfig(
  timeMap: Messages.planner__speed__pb__TimeMap,
): Messages.ares__CustomizationPlotData | undefined {
  const immutableTime = timeMap.immutableTime ?? 0;
  let immutableTimePointConfig:
    | Messages.ares__CustomizationPlotData
    | undefined = undefined;
  if (immutableTime !== 0) {
    immutableTimePointConfig = {
      pointBackgroundColor: "yellow",
      borderColor: "yellow",
      borderDash,
      lines: [
        {
          line: [
            {
              x: immutableTime,
              y: 0,
            },
            {
              x: immutableTime,
              y: kStPlotMaxDistanceInM,
            },
          ],
        },
      ],
    };
  }
  return immutableTimePointConfig;
}

function addConstraintPoints(
  timeMap: Messages.planner__speed__pb__TimeMap,
  type: "yield" | "pass",
  allConstraints: AllConstraints[],
) {
  const isPass = type === "pass";
  const timeMapEntries = isPass ? timeMap.passEntries : timeMap.yieldEntries;
  const dt = timeMap.dt;
  const immutableTime = Number(timeMap.immutableTime ?? 0);

  forIn(timeMapEntries, (entries: { entries: unknown }, timeIx: string) => {
    const t = Number(timeIx) * dt + immutableTime;
    forEach(
      (entries?.entries as Messages.planner__speed__pb__TimeMap__Entry[]) ?? [],
      (entry) => {
        const cIx = entry?.constraintIx;
        if (cIx >= 0 && cIx < allConstraints.length) {
          const point = {
            x: t,
            y: entry.startOrEndX,
          };
          if (isPass) {
            allConstraints[cIx]!.passPoints.push(point);
          } else {
            allConstraints[cIx]!.yieldPoints.push(point);
          }
        }
      },
    );
  });
}

function getYieldEntryPointColor(
  decision: Messages.planner__speed__pb__SpeedDecision,
) {
  return decision === "YIELD" ? "red" : "gray";
}

/*
 * Gets color to display pass entry time map of a constraint given its current decision.
 */
function getPassEntryPointColor(
  decision: Messages.planner__speed__pb__SpeedDecision,
) {
  if (decision === "PASS") {
    return "green";
  }
  // It is possible that in intermediate search result, we have
  // NOT_DECIDED decision for a constraint.
  if (decision === "NOT_DECIDED") {
    return "yellow";
  }
  return "gray";
}

function addTimeMaps({
  searchDebug,
  speedGeneratorDebug,
  allSelectedConstraintIds,
  dominantConstraintId = "",
  dominantConstraintLabel = "",
  forIntermediateResult = false,
  perDiscomfortDebug,
  decisions = [],
  constraints = [],
  showRiskTimeMap,
}: AddTimeMaps) {
  if (!searchDebug) {
    return [];
  }

  const hasRiskTimeMap = showRiskTimeMap && searchDebug.riskMitigationDebug;

  const timeMap = hasRiskTimeMap
    ? searchDebug.riskMitigationDebug.riskTimeMap
    : forIntermediateResult
      ? perDiscomfortDebug?.timeMap
      : searchDebug?.timeMap;

  if (timeMap == null) {
    return [];
  }

  const allConstraints: AllConstraints[] = new Array(
    searchDebug.decisions.length ?? 0,
  )
    .fill(0)
    .map((_) => ({
      yieldPoints: [],
      passPoints: [],
    }));

  addConstraintPoints(timeMap, "yield", allConstraints);
  addConstraintPoints(timeMap, "pass", allConstraints);

  const finalResult: Messages.ares__CustomizationPlot = {
    data: [],
  };
  const immutableTimeConfig = getImmutableTimeConfig(timeMap);

  if (immutableTimeConfig) {
    finalResult.data.push(immutableTimeConfig);
  }

  forEach(allConstraints, (constraint, index) => {
    if (
      isConstraintSelected(
        constraints?.[index]?.uniqueConstraintId,
        dominantConstraintId,
        dominantConstraintLabel,
        allSelectedConstraintIds,
      )
    ) {
      const decision = (
        hasRiskTimeMap
          ? searchDebug.riskMitigationDebug.riskDecisions?.[index]
          : forIntermediateResult
            ? decisions?.[index]
            : searchDebug?.decisions?.[index]
      ) as Messages.planner__speed__pb__SpeedDecision;

      let yieldPoints = constraint?.yieldPoints ?? [];
      let passPoints = constraint?.passPoints ?? [];
      switch (searchDebug?.constraints?.[index]?.type) {
        case "STOP_POINT":
        case "NO_BLOCK":
          if (yieldPoints.length > 0) {
            finalResult.data.push(
              extendPointToLineAndAddTimeMap(
                yieldPoints[0]!,
                searchDebug?.constraints?.[index]!,
                decision,
              ),
            );
          }
          break;

        case "AVOID_REGION":
          const avoidRegionTimeMap = addAvoidRegionTimeMap(
            constraint,
            decision,
          );
          if (avoidRegionTimeMap) {
            finalResult.data.push(avoidRegionTimeMap);
          }
          break;

        default:
          // Sort yield and pass points in ascending order of their x.
          // This can be replaced as a DCHECK if the time_map class sorts them.
          yieldPoints = yieldPoints.sort((p1, p2) => (p1.x - p2.x ? -1 : 1));
          passPoints = passPoints.sort((p1, p2) => (p1.x - p2.x ? -1 : 1));

          if (yieldPoints.length > 0) {
            const yieldEntryPointColor = getYieldEntryPointColor(decision);
            const shouldUseDash =
              speedGeneratorDebug?.primitiveConstraints?.[index]?.settings
                ?.yieldOption == "SOFT";
            finalResult.data.push({
              pointBackgroundColor: yieldEntryPointColor,
              borderColor: yieldEntryPointColor,
              borderDash: shouldUseDash ? softBorderDash : undefined,
              lines: [
                {
                  line: yieldPoints,
                },
              ],
            });
          }
          if (passPoints.length > 0) {
            const passEntryPointColor = getPassEntryPointColor(decision);
            const shouldUseDash =
              speedGeneratorDebug?.primitiveConstraints?.[index]?.settings
                ?.passOption == "SOFT";
            finalResult.data.push({
              pointBackgroundColor: passEntryPointColor,
              borderColor: passEntryPointColor,
              borderDash: shouldUseDash ? softBorderDash : undefined,
              lines: [
                {
                  line: passPoints,
                },
              ],
            });
          }

          // Add dashed gray lines to connect the starting points and ending
          // points of the yield and pass entries.
          if (yieldPoints.length > 0 && passPoints.length > 0) {
            finalResult.data.push({
              pointBackgroundColor: "gray",
              borderColor: "gray",
              borderDash,
              lines: [
                {
                  line: [yieldPoints[0]!, passPoints[0]!],
                },
              ],
            });
            finalResult.data.push({
              pointBackgroundColor: "gray",
              borderColor: "gray",
              borderDash,
              lines: [
                {
                  line: [last(yieldPoints)!, last(passPoints)!],
                },
              ],
            });
          }
      }

      if (yieldPoints.length > 0 || passPoints.length > 0) {
        const point = last(
          yieldPoints.length > 0 ? yieldPoints : passPoints,
        ) as {
          x: number;
          y: number;
        };
        finalResult.data.push({
          lines: [
            {
              line: [
                {
                  x: point?.x - 1,
                  y: point?.y,
                  label: constraints?.[index]?.uniqueConstraintId,
                  labelColor: "white",
                },
              ],
            },
          ],
        });
      }
    }
  });

  return finalResult;
}

function getColorForTimeMapBasedOnDecision(
  decision: Messages.planner__speed__pb__SpeedDecision,
) {
  if (decision === "PASS") {
    return "green";
  }
  if (decision === "YIELD") {
    return "red";
  }
  if (decision === "NOT_DECIDED") {
    return "yellow";
  }
  return "gray";
}

function extendPointToLineAndAddTimeMap(
  yieldPoints: { x: number; y: number },
  constraint: Messages.planner__speed__pb__Constraint,
  decision: Messages.planner__speed__pb__SpeedDecision,
): Messages.ares__CustomizationPlotData {
  const color = getColorForTimeMapBasedOnDecision(decision);
  return {
    pointBackgroundColor: color,
    borderColor: color,
    borderDash,
    lines: [
      {
        line: [
          yieldPoints,
          {
            x: constraint?.states?.[0]?.startTime as number,
            y: yieldPoints.y,
          },
        ],
      },
    ],
  };
}

function addAvoidRegionTimeMap(
  constraint: AllConstraints,
  decision: Messages.planner__speed__pb__SpeedDecision,
): Messages.ares__CustomizationPlotData | undefined {
  const yieldPoints = constraint?.yieldPoints;
  const passPoints = constraint?.passPoints;
  if (yieldPoints.length && passPoints.length) {
    const color = getColorForTimeMapBasedOnDecision(decision) as string;
    const upperLeft = passPoints[0]!;
    const bottomRight = yieldPoints[0]!;
    const bottomLeft = {
      x: passPoints[0]!.x,
      y: yieldPoints[0]!.y,
    };
    const upperRight = {
      x: yieldPoints[0]!.x,
      y: passPoints[0]!.y,
    };
    return {
      borderColor: color,
      pointBackgroundColor: color,
      lines: [
        {
          line: [bottomLeft, upperLeft, upperRight, bottomRight, bottomLeft],
        },
      ],
    };
  }
  return undefined;
}

type GapAlignActiveTime = {
  searchDebug: Messages.planner__speed__pb__SpeedSearchDebug | undefined;
  planInitTimeInSec: number;
  allSelectedConstraintIds: string[];
  dominantConstraintId: string;
  dominantConstraintLabel: string;
  showVtCurve: boolean;
  showAtCurve: boolean;
  constraints:
    | Messages.planner__speed__pb__PrimitiveConstraint[]
    | Messages.planner__speed__pb__Constraint[];
};

function getGapAlignActiveTime({
  searchDebug,
  planInitTimeInSec,
  allSelectedConstraintIds = [],
  dominantConstraintId = "",
  dominantConstraintLabel = "",
  showVtCurve,
  showAtCurve,
  constraints,
}: GapAlignActiveTime): {
  gapAlignActiveTimeData: Messages.ares__CustomizationPlotData[];
  gapAlignMaxActiveTimeData: Messages.ares__CustomizationPlotData[];
} {
  if (!searchDebug) {
    return {
      gapAlignActiveTimeData: [],
      gapAlignMaxActiveTimeData: [],
    };
  }

  const gapAlignActiveTimeData: Messages.ares__CustomizationPlotData[] = [];
  const gapAlignMaxActiveTimeData: Messages.ares__CustomizationPlotData[] = [];

  const initialDecisionDebugs =
    searchDebug?.initialDecisionProviderDebug?.initialDecisionDebugs ?? [];

  for (let index = 0, len = constraints?.length ?? 0; index < len; index++) {
    const constraint = constraints?.[index];

    if (constraint?.type !== GAP_ALIGN) {
      continue;
    }

    const initialDecisionDebug = initialDecisionDebugs?.[index];

    const uniqueConstraintId = constraint?.uniqueConstraintId;
    const isSelected = isConstraintSelected(
      uniqueConstraintId,
      dominantConstraintId,
      dominantConstraintLabel,
      allSelectedConstraintIds,
    );

    if (!isSelected) {
      continue;
    }

    if (
      initialDecisionDebug &&
      !isUndefined(initialDecisionDebug?.yieldProfile) &&
      !isUndefined(initialDecisionDebug.gapAlignInfo?.yieldActiveTimeIx)
    ) {
      const yieldActiveTimeIx = addSpeedProfileForGapAlignConstraint({
        profile: initialDecisionDebug.yieldProfile,
        activeTimeIx: initialDecisionDebug.gapAlignInfo.yieldActiveTimeIx,
        planInitTimeInSec,
        color: "magenta",
        showAtCurve,
        showVtCurve,
      });
      gapAlignActiveTimeData.push(...yieldActiveTimeIx.data);
    }

    if (
      initialDecisionDebug &&
      !isUndefined(initialDecisionDebug?.passProfile) &&
      !isUndefined(initialDecisionDebug.gapAlignInfo?.passActiveTimeIx)
    ) {
      const passActiveTimeIx = addSpeedProfileForGapAlignConstraint({
        profile: initialDecisionDebug.passProfile,
        activeTimeIx: initialDecisionDebug.gapAlignInfo.passActiveTimeIx,
        planInitTimeInSec,
        color: "cyan",
        showAtCurve,
        showVtCurve,
      });
      gapAlignActiveTimeData.push(...passActiveTimeIx.data);
    }

    const gapAlignYieldMaxActiveTimeData = drawPassYieldMaxActiveTime(
      initialDecisionDebug?.gapAlignPassMaxActiveTime!,
      "cyan",
    );

    const gapAlignPassMaxActiveTimeData = drawPassYieldMaxActiveTime(
      initialDecisionDebug?.gapAlignYieldMaxActiveTime!,
      "magenta",
    );

    gapAlignMaxActiveTimeData.push(
