}): Messages.ares__CustomizationPlot {
  const speedProfileData: Messages.ares__CustomizationPlot = {
    data: [],
  };
  if (isUndefined(searchDebug)) {
    return {
      data: [],
    };
  }
  const isConflictResolving = searchDebug.searchResult == "CONFLICT_RESOLVING";
  const speedProfile = addSpeedProfileForAresPlot({
    profile: searchDebug.searchProfile,
    planInitTimeInSec,
    color,
    showAtCurve,
    showVtCurve,
    customLabel: isConflictResolving ? "SCR" : undefined,
    discomfortValue: isConflictResolving ? undefined : discomfortValue,
    lineType,
