  if (speedProfile.data.length) {
    speedProfileData.data.push(...speedProfile.data);
  }
  const treeProfile = searchDebug?.lcGuideSeed?.treeProfile;
  const treeSwitchTimeIx = searchDebug?.lcGuideSeed?.treeSwitchTimeIx;
  if (treeSwitchTimeIx >= 0 && treeSwitchTimeIx < treeProfile?.states?.length) {
    const policyProfileData = addSpeedProfileForAresPlot({
      profile: treeProfile,
      planInitTimeInSec,
      color: "yellow",
      showAtCurve,
      showVtCurve,
      discomfortValue,
      lineType: "dash",
    });
    if (policyProfileData.data.length) {
      speedProfileData.data.push(...policyProfileData.data);
    }
    speedProfileData.data.push({
      lines: [
        {
          line: [
            {
              x: treeSwitchTimeIx * 0.1,
              y: treeProfile?.states?.[treeSwitchTimeIx]?.x as number,
              label: "*",
              labelColor: "red",
              labelSize: 20,
            },
          ],
        },
      ],
    });
  }

  return speedProfileData;
}

function getAllSCRCandidates({
  searchDebug,
  planInitTimeInSec,
  color,
  showAtCurve,
  showVtCurve,
  lineType,
}: Omit<GetSpeedProfile, "profile" | "discomfortValue"> & {
  searchDebug?: Messages.planner__speed__pb__SpeedSearchDebug;
}): Messages.ares__CustomizationPlot {
  const allPlotData: Messages.ares__CustomizationPlotData[] = [];

  // Use as any to avoid TS errors if types are stale
  const candidates = (searchDebug?.conflictResolverDebug as any)?.candidates;

  if (!candidates || candidates.length === 0) {
    return { data: [] };
  }

  candidates.forEach((candidate: any) => {
    const profile = candidate.profile;
    const candidateType = candidate.candidateType; // e.g. "FS", "EB"

    if (!profile) return;

    const candidatePlot = addSpeedProfileForAresPlot({
      profile,
      planInitTimeInSec,
      color,
      showAtCurve,
      showVtCurve,
      lineType,
      customLabel: candidateType,
    });

    if (candidatePlot.data) {
      allPlotData.push(...candidatePlot.data);
    }
  });

  return { data: allPlotData };
}

function isForIntermediateResult(
  discomfortsLevel = "",
  discomfortsIteration = "",
) {
  return discomfortsLevel !== "" && discomfortsIteration !== "";
}

