        colors: colors,
        lineMetadata: {
          lineWidth: 0.2,
          frustumCulled: false,
        },
      };
      markers.push(lane_border_marker);
    } else {
      // Fill edge points list and create a edge marker for start & end point.
      const edgeColors: Messages.ares__Color[] = [];
      const edgePoints: Messages.ares__Vec3[] = [];
      waypoint?.edgePoints.forEach((point) => {
        edgeColors.push(kDefaultColorSetting);
        edgePoints.push({ x: point.x, y: point.y, z: z });
      });
      const edge_marker: Messages.ares__VisualizationMarker = {
        header: {
          frame_id: "world",
          seq: 0,
          stamp: messageDebug.receiveTime,
        },
        id: `${prefix}_edges`,
        type: Messages.ares__VisualizationMarkerTypes.LINE_STRIP,
        points: edgePoints,
        colors: edgeColors,
        lineMetadata: {
          lineWidth: 0.2,
          frustumCulled: false,
        },
      };
      markers.push(edge_marker);
      const edge_start_point_marker: Messages.ares__VisualizationMarker = {
        header: {
          frame_id: "world",
          seq: 0,
          stamp: messageDebug.receiveTime,
        },
        id: `${prefix}_edge_start_point`,
        type: Messages.ares__VisualizationMarkerTypes.POINT,
        pose: {
          position: { ...edgePoints[0]!, z },
          orientation: { x: 0, y: 0, z: 0, w: 0 },
        },
        color: kedgePointColorSetting,
        pointMetadata: { sizeAttenuation: true, radius: 0.3 },
      };
      markers.push(edge_start_point_marker);
      const edge_end_point_marker: Messages.ares__VisualizationMarker = {
        header: {
          frame_id: "world",
          seq: 0,
          stamp: messageDebug.receiveTime,
        },
        id: `${prefix}_edge_end_point`,
        type: Messages.ares__VisualizationMarkerTypes.POINT,
        pose: {
          position: { ...edgePoints[edgePoints.length - 1]!, z },
          orientation: { x: 0, y: 0, z: 0, w: 0 },
        },
        color: kedgePointColorSetting,
        pointMetadata: { sizeAttenuation: true, radius: 0.3 },
      };
      markers.push(edge_end_point_marker);
    }
  });
  return {
    markers,
  };
};

export default publisher;

