/* eslint-disable @typescript-eslint/no-unnecessary-condition */

import {
  GlobalVariables,
  DEFAULT_STUDIO_NODE_PREFIX,
  getIntentionPlanDebug,
  getSpeedSolverDebugIndex,
} from "@ares-utils";
import { Input, Messages } from "@vitruvian/voyager-type";
import { Messages as rosMessages } from "ros";
import { forEach } from "lodash";

export const inputs = ["/planning/planning_debug"];
export const config = {
  datatype: "voyager_data_msgs/CustomData",
  showOn3DPanel: false,
};
export const output = `/studio_node/planning/planning_debug/speed_opt_cost`;

function extractTrialNumbers(input: string): number[] {
  const matches = input.match(/\bon\s+(\d+)\s+trial\b/gi);

  return (
    matches
      ?.map((m) => {
        const numMatch = m.match(/\d+/);
        return numMatch ? parseInt(numMatch[0], 10) : NaN;
      })
      .filter((n) => !isNaN(n)) || []
  );
}

const createCurveConfig = (
  color: string,
): Messages.ares__CustomizationPlotData => ({
  lines: [],
  borderColor: color,
  borderWidth: 1.0,
  pointBackgroundColor: color,
  pointRadius: 1.5,
});

function distinctColorForIndex(index: number): string {
  if (index < 0) {
    return "hsl(0, 0%, 100%)";
  }

  const kGoldenRatio = 0.618033988749895;
  const kComplement = 1.0 - kGoldenRatio;

  const hue = ((index * kGoldenRatio) % 1) * 360;
  const saturation = 85;
  const lightness = 60 + 20 * ((index * kComplement) % 1);

  return `hsl(${hue.toFixed(2)}, ${saturation}%, ${lightness.toFixed(2)}%)`;
}

export const publisher = (
  messages: Record<string, Input<"/planning/planning_debug">>,
  globalVariables: GlobalVariables,
): Messages.voyager_data_msgs__CustomData => {
  const planningDebugMessage = messages[
    "/planning/planning_debug"
  ] as unknown as rosMessages.planner_pb__PlanningDebug;
  if (!planningDebugMessage) {
    return {};
  }

  const { behaviorReasonerDebug } = planningDebugMessage.message;

  const intentionPlanDebug = getIntentionPlanDebug(
    behaviorReasonerDebug,
    globalVariables,
  );
  if (!intentionPlanDebug) {
    return {};
  }

  const speedGeneratorDebug =
    intentionPlanDebug?.speedGeneratorDebug as Messages.planner__speed__pb__SpeedGeneratorDebug;

  const speedSolverDebugIndex = getSpeedSolverDebugIndex(
    behaviorReasonerDebug,
    globalVariables,
  );

  const speedSolverDebug =
    speedGeneratorDebug?.speedSolverDebugs[speedSolverDebugIndex];

  if (!speedSolverDebug) {
    return {};
  }

  const displayOptions = [
    {
      title: "normal cost",
      value: "normal cost",
      key: "normal cost",
      connectKey: "",
    },
    {
      title: "branch cost",
      value: "branch cost",
      key: "branch cost",
      connectKey: "",
    },
    {
      title: "warm start cost",
      value: "warm start cost",
      key: "warm start cost",
      connectKey: "",
    },
  ];

  const costDisplayOptions =
    (globalVariables.planning_speed_cost_display_options as string) ?? "";

  const { optDebug: speedOptDebug } = speedSolverDebug;
  let optimizerIteration: Record<string, unknown> = { " ": "NoOpt" };

  const iterTrials = extractTrialNumbers(
    (speedOptDebug as undefined as any)?.debugStr,
  );

  let optimizationStates = [];

  let optimizationCost: Record<string, number[]> = {
    // Reserved Cost Term
    speedAttractorCost: [],
    lengthAttractorCost: [],

    totalCost: [],
    stateBarrierCost: [],
    stateRepellerCost: [],
    stateStaticRangeCost: [],
    accelBarrierCost: [],
    jerkBarrierCost: [],
    minSpeedBarrierCost: [],
    maxSpeedBarrierCost: [],
    accelEffortCost: [],
    jerkEffortCost: [],
    lateralAccelEffortCost: [],
    positionAttractorCost: [],
    followerAttractorCost: [],
    jerkAttractorCost: [],
    dynamicRangeCost: [],
    passDynamicRangeCost: [],
    proximitySpeedCost: [],
    maxSpeedRepellerCost: [],
    lateralJerkRepellerCost: [],
