import { Input, Messages } from "ros";

type Output = Messages.voyager_data_msgs__CustomData;
type GlobalVariables = {
  id: number;
  tracked_object_selections?: string[];
  tracked_object_id?: string;
  trajectory_selections?: Array<{
    agentId: string;
    // 之前的 bag 中，trajectory 的 id 是固定为 0 的，所以需要依赖 index 判断。
    // 现在的 bag 中，trajectory 会有一个唯一 id，需要依赖这个 id 来判断。
    trajectoryId: string;
    index: string;
  }>;
};
type NodeConfig = {
  // description: "Set whether to use all frame data"
  // tips: "Using all frame data will greatly affect the performance. Please use 'frontFrameLength' and 'behindFrameLength' to limit the data size"
  // default: true
  needFrameData?: boolean;

  // description: "set how many frames before the current frame will be transmitted"
  frontFrameLength?: number;
  // description: "set how many frames after the current frame will be transmitted"
  behindFrameLength?: number;
};

type CustomPlotPoint = {
  x: number;
  y: number;
  borderColor?: string;
  value?: string | number;
  label?: string;
  labelColor?: string;
  labelSize?: number;
};

type TrajectoryPose = {
  timestamp: number;
  speed: number;
};

type BagPose = {
  timestamp: number;
  accForward: number;
  velX: number;
  velY: number;
  yaw: number;
};

const RelativeTimeInSecond = (
  target_in_msc: number,
  reference_in_msc: number,
): number => {
  const kSecondInMSC = 1000.0;
  return (target_in_msc - reference_in_msc) / kSecondInMSC;
};

export const inputs = [
  "/prediction/predicted_objects",
  "/planning/trajectory", // planning trajectory
  "/pose", //bag pose
];
export const config: NodeConfig = {
  needFrameData: false,
};

// If this value is the same as a built-in output topic, the built-in output topic will be overwrite.
// You can get all the built-in output topic names in 'builtin-nodes.json' file on the left toolbar.
const DEFAULT_STUDIO_NODE_PREFIX = "/studio_node/";
export const output = "/studio_node/conditional_behavior_prediction/pairs";

export type PredictionTableTransferData = {
  id: number;
  agentId: number;
  probability: number;
  yieldType: string;
  yieldProb: number;
  cbpType: string;
  importanceRank: number;
  generator: string;
  debugModal: string;
  debugNonDL: string;
};
const MAX_PROBABILITY_IN_PPM = 1e6;

// Populate 'Input' with a parameter to properly type your inputs, e.g. 'Input<"/your_input_topic">'
const publisher = (
  messages: Record<
    string,
    Input<"/prediction/predicted_objects" | "/planning/trajectory" | "/pose">
  >,
  globalVariables: GlobalVariables,
  blocks: any,
): Output => {
  const messagePrediction = messages[
    "/prediction/predicted_objects"
  ] as Input<"/prediction/predicted_objects">;

  if (!messagePrediction) {
    return {};
  }
  const agentList = messagePrediction.message.agentList;
  const selectedAgent = agentList.find(
    (agent) =>
      String(agent.trackedObject.id) ===
      String(globalVariables.tracked_object_selections?.[0]),
  );

  if (!selectedAgent) {
    return {};
  }

  const selectedAgentCBPyieldTrajs =
    selectedAgent?.conditionalTrajectories?.yieldCbpTrajsPair?.targetTrajectories.map(
      (trajectory, index) => {
        return {
          id: index,
          cbpType: "YIELD",
          agentId: selectedAgent.trackedObject.id,
          probability: trajectory.probabilityInPpm / MAX_PROBABILITY_IN_PPM,
          yieldType: trajectory.yieldIntention.yieldIntentionType,
          yieldProb: trajectory.yieldIntention.yieldProbability,
          generator: trajectory.trajectoryGeneratorType,
          debugModal: trajectory.debugModalName,
          debugNonDL: selectedAgent.debugNonDeepLearningOutput,
        };
      },
    );
  const selectedAgentCBPnotyieldTrajs =
    selectedAgent?.conditionalTrajectories?.notYieldCbpTrajsPair?.targetTrajectories.map(
      (trajectory, index) => {
        return {
          id: index,
          cbpType: "NOT_YIELD",
          agentId: selectedAgent.trackedObject.id,
          probability: trajectory.probabilityInPpm / MAX_PROBABILITY_IN_PPM,
          yieldType: trajectory.yieldIntention.yieldIntentionType,
          yieldProb: trajectory.yieldIntention.yieldProbability,
          generator: trajectory.trajectoryGeneratorType,
          debugModal: trajectory.debugModalName,
          debugNonDL: selectedAgent.debugNonDeepLearningOutput,
        };
      },
    );

  // cbp trajectories' speed.
  const yield_trajs_speed = [];
  const n_yield_trajs =
    selectedAgent?.conditionalTrajectories?.yieldCbpTrajsPair
      ?.targetTrajectories.length;
  let sortedYieldTrajIndices = Array.from(
    {
      length: n_yield_trajs,
    },
    (_, i) => i,
  );
  sortedYieldTrajIndices = sortedYieldTrajIndices.sort((x, y) => {
    return (
      selectedAgent.conditionalTrajectories.yieldCbpTrajsPair
        .targetTrajectories[y].probabilityInPpm -
      selectedAgent.conditionalTrajectories.yieldCbpTrajsPair
        .targetTrajectories[x].probabilityInPpm
    );
  });
  for (let i = 0; i < n_yield_trajs; ++i) {
    const speed: CustomPlotPoint[] = [];
    const traj_idx = sortedYieldTrajIndices[i];
    const traj =
      selectedAgent.conditionalTrajectories.yieldCbpTrajsPair
        .targetTrajectories[traj_idx];

    for (let j = 0; j < traj.trajPoses.length; ++j) {
      if (j < traj.trajPoses.length - 1) {
        speed.push({
          x: j,
          y: traj.trajPoses[j]?.speed,
        });
      }
      if (j == traj.trajPoses.length - 1) {
        speed.push({
          x: j,
          y: traj.trajPoses[j]?.speed,
          label:
            "#" +
            String(traj.id) +
            "@" +
            String(traj.probabilityInPpm / 1000000),
        });
      }
    }

    yield_trajs_speed.push({
      data: [speed],
    });
  }

  const ego_speed_when_target_yield: CustomPlotPoint[] = [];
  const ego_traj_when_target_yield =
    selectedAgent?.conditionalTrajectories?.yieldCbpTrajsPair.egoTrajectory;

  for (let k = 0; k < ego_traj_when_target_yield.trajPoses.length; ++k) {
    ego_speed_when_target_yield.push({
      x: k,
      y: ego_traj_when_target_yield.trajPoses[k]?.speed,
    });
  }

  const not_yield_trajs_speed = [];
  const n_not_yield_trajs =
    selectedAgent?.conditionalTrajectories?.notYieldCbpTrajsPair
      ?.targetTrajectories.length;
  let sortedNotYieldTrajIndices = Array.from(
    {
      length: n_not_yield_trajs,
    },
    (_, i) => i,
  );
  sortedNotYieldTrajIndices = sortedNotYieldTrajIndices.sort((x, y) => {
    return (
      selectedAgent.conditionalTrajectories.notYieldCbpTrajsPair
        .targetTrajectories[y].probabilityInPpm -
      selectedAgent.conditionalTrajectories.notYieldCbpTrajsPair
        .targetTrajectories[x].probabilityInPpm
    );
  });
  for (let i = 0; i < n_not_yield_trajs; ++i) {
    const speed: CustomPlotPoint[] = [];
    const traj_idx = sortedNotYieldTrajIndices[i];
    const traj =
      selectedAgent.conditionalTrajectories.notYieldCbpTrajsPair
        .targetTrajectories[traj_idx];

    for (let j = 0; j < traj.trajPoses.length; ++j) {
      if (j < traj.trajPoses.length - 1) {
        speed.push({
          x: j,
          y: traj.trajPoses[j]?.speed,
        });
      }
      if (j == traj.trajPoses.length - 1) {
        speed.push({
          x: j,
          y: traj.trajPoses[j]?.speed,
          label:
            "#" +
            String(traj.id) +
            "@" +
            String(traj.probabilityInPpm / 1000000),
        });
      }
    }

    not_yield_trajs_speed.push({
      data: [speed],
    });
  }

  const ego_speed_when_target_not_yield: CustomPlotPoint[] = [];
  const ego_traj_when_target_not_yield =
    selectedAgent.conditionalTrajectories.notYieldCbpTrajsPair.egoTrajectory;

  for (let k = 0; k < ego_traj_when_target_not_yield.trajPoses.length; ++k) {
    ego_speed_when_target_not_yield.push({
      x: k,
      y: ego_traj_when_target_not_yield.trajPoses[k]?.speed,
    });
  }

  return {
    ["yield"]: {
      trajectories: selectedAgentCBPyieldTrajs,
    },
    ["not_yield"]: {
      trajectories: selectedAgentCBPnotyieldTrajs,
    },
    yield_trajs_speed_list: yield_trajs_speed,
    ego_speed_list_when_target_yield: [{ data: [ego_speed_when_target_yield] }],
    not_yield_trajs_speed_list: not_yield_trajs_speed,
    ego_speed_list_when_target_not_yield: [
      { data: [ego_speed_when_target_not_yield] },
    ],
  };
};

export default publisher;

