            generator: trajectory.trajectoryGeneratorType,
            debugModal: trajectory.debugModalName,
            debugNonDL: selectedAgent.debugNonDeepLearningOutput,
        };
    });
    const selectedAgentCBPnotyieldTrajs = selectedAgent?.conditionalTrajectories?.notYieldCbpTrajsPair?.targetTrajectories.map((trajectory, index) => {
        return {
            id: index,
            cbpType: "NOT_YIELD",
            agentId: selectedAgent.trackedObject.id,
            probability: trajectory.probabilityInPpm / MAX_PROBABILITY_IN_PPM,
            yieldType: trajectory.yieldIntention.yieldIntentionType,
            yieldProb: trajectory.yieldIntention.yieldProbability,
            generator: trajectory.trajectoryGeneratorType,
            debugModal: trajectory.debugModalName,
            debugNonDL: selectedAgent.debugNonDeepLearningOutput,
        };
    });
    // cbp trajectories' speed.
    const yield_trajs_speed = [];
    const n_yield_trajs = selectedAgent?.conditionalTrajectories?.yieldCbpTrajsPair
        ?.targetTrajectories.length;
    let sortedYieldTrajIndices = Array.from({
        length: n_yield_trajs,
    }, (_, i) => i);
    sortedYieldTrajIndices = sortedYieldTrajIndices.sort((x, y) => {
        return (selectedAgent.conditionalTrajectories.yieldCbpTrajsPair
            .targetTrajectories[y].probabilityInPpm -
            selectedAgent.conditionalTrajectories.yieldCbpTrajsPair
                .targetTrajectories[x].probabilityInPpm);
    });
    for (let i = 0; i < n_yield_trajs; ++i) {
        const speed = [];
        const traj_idx = sortedYieldTrajIndices[i];
        const traj = selectedAgent.conditionalTrajectories.yieldCbpTrajsPair
            .targetTrajectories[traj_idx];
        for (let j = 0; j < traj.trajPoses.length; ++j) {
            if (j < traj.trajPoses.length - 1) {
                speed.push({
                    x: j,
                    y: traj.trajPoses[j]?.speed,
                });
            }
            if (j == traj.trajPoses.length - 1) {
                speed.push({
                    x: j,
                    y: traj.trajPoses[j]?.speed,
                    label: "#" +
                        String(traj.id) +
                        "@" +
                        String(traj.probabilityInPpm / 1000000),
                });
            }
        }
        yield_trajs_speed.push({
            data: [speed],
        });
    }
    const ego_speed_when_target_yield = [];
    const ego_traj_when_target_yield = selectedAgent?.conditionalTrajectories?.yieldCbpTrajsPair.egoTrajectory;
    for (let k = 0; k < ego_traj_when_target_yield.trajPoses.length; ++k) {
        ego_speed_when_target_yield.push({
            x: k,
            y: ego_traj_when_target_yield.trajPoses[k]?.speed,
        });
    }
    const not_yield_trajs_speed = [];
    const n_not_yield_trajs = selectedAgent?.conditionalTrajectories?.notYieldCbpTrajsPair
        ?.targetTrajectories.length;
    let sortedNotYieldTrajIndices = Array.from({
        length: n_not_yield_trajs,
    }, (_, i) => i);
    sortedNotYieldTrajIndices = sortedNotYieldTrajIndices.sort((x, y) => {
        return (selectedAgent.conditionalTrajectories.notYieldCbpTrajsPair
            .targetTrajectories[y].probabilityInPpm -
            selectedAgent.conditionalTrajectories.notYieldCbpTrajsPair
                .targetTrajectories[x].probabilityInPpm);
    });
    for (let i = 0; i < n_not_yield_trajs; ++i) {
        const speed = [];
        const traj_idx = sortedNotYieldTrajIndices[i];
        const traj = selectedAgent.conditionalTrajectories.notYieldCbpTrajsPair
            .targetTrajectories[traj_idx];
        for (let j = 0; j < traj.trajPoses.length; ++j) {
            if (j < traj.trajPoses.length - 1) {
                speed.push({
                    x: j,
                    y: traj.trajPoses[j]?.speed,
                });
            }
            if (j == traj.trajPoses.length - 1) {
                speed.push({
                    x: j,
                    y: traj.trajPoses[j]?.speed,
                    label: "#" +
                        String(traj.id) +
                        "@" +
                        String(traj.probabilityInPpm / 1000000),
                });
            }
        }
        not_yield_trajs_speed.push({
            data: [speed],
        });
    }
    const ego_speed_when_target_not_yield = [];
    const ego_traj_when_target_not_yield = selectedAgent.conditionalTrajectories.notYieldCbpTrajsPair.egoTrajectory;
    for (let k = 0; k < ego_traj_when_target_not_yield.trajPoses.length; ++k) {
        ego_speed_when_target_not_yield.push({
            x: k,
            y: ego_traj_when_target_not_yield.trajPoses[k]?.speed,
        });
    }
    return {
        ["yield"]: {
            trajectories: selectedAgentCBPyieldTrajs,
        },
        ["not_yield"]: {
            trajectories: selectedAgentCBPnotyieldTrajs,
        },
        yield_trajs_speed_list: yield_trajs_speed,
        ego_speed_list_when_target_yield: [{ data: [ego_speed_when_target_yield] }],
        not_yield_trajs_speed_list: not_yield_trajs_speed,
        ego_speed_list_when_target_not_yield: [
            { data: [ego_speed_when_target_not_yield] },
        ],
    };
};
exports.default = publisher;

