import { Input, Messages, Time } from "ros";

import {
  createRosMarker,
  RosMarker,
  RosMarkerTypes,
  createDeleteAllActionMarker,
} from "./rosMarkers";
import { Header, Point, Pose, Quaternion, RGBA } from "./types";
import { euler2Quaternions } from "./vectors";

type GlobalVariables = {
  id: number;
  predicted_cbp_pose: number;
  predicted_pose: number;
  predictedCBPYieldTrajectoryIds: number[];
  predictedCBPNotYieldTrajectoryIds: number[];
  tracked_object_selections?: string[];
  tracked_object_id?: string;
  trajectory_selections?: Array<{
    agentId: string;
    // 之前的 bag 中，trajectory 的 id 是固定为 0 的，所以需要依赖 index 判断。
    // 现在的 bag 中，trajectory 会有一个唯一 id，需要依赖这个 id 来判断。
    trajectoryId: string;
    index: string;
  }>;
};

export const inputs = ["/prediction/predicted_objects"];
export const output = "/studio_node/conditional_behavior_prediction/yield_pair";

const outputTrajectoryMarkers: RosMarker[] = [];

namespace utils {
  // 选中物体
  export const isSelectedAgent = (
    agent: Messages.prediction__pb__Agent,
    globalVariables: GlobalVariables,
  ): boolean => {
    return (
      String(agent.trackedObject.id) ===
      String(globalVariables.tracked_object_selections?.[0])
    );
  };
}
namespace custom {
  interface trajStyleSetting {
    color: RGBA;
  }
  export const trajStyleSettings: {
    [id: string]: trajStyleSetting;
  } = {};
  trajStyleSettings["yield"] = {
    color: { a: 1, r: 0, g: 1, b: 0 },
  };
  trajStyleSettings["not_yield"] = {
    color: { a: 1, r: 1, g: 0, b: 0 },
  };

  export const poseInterval = 10;

  function drawTrajectories(
    receiveTime: Time,
    agent_idx: number,
    traj_idx: number,
    trackedObject: Messages.voy__TrackedObject,
    trajs: Messages.prediction__pb__PredictedTrajectory,
    predicted_pose: number = -1,
    yield_type: String = "yield",
  ): RosMarker[] {
    const outputs: RosMarker[] = [];
    trajs.trajPoses.forEach((pose: any, index) => {
      if (
        index == predicted_pose ||
        (predicted_pose == -1 && index % 10 == 0)
      ) {
        const lineMarker = createRosMarker({
          header: {
            frame_id: "world",
            stamp: receiveTime,
            seq: 0,
          },
          type: RosMarkerTypes.CUBE,
          id: index + agent_idx * 1000 + traj_idx * 1000000,
          action: 0,
          pose: {
            position: {
              x: pose.xPos,
              y: pose.yPos,
              z: pose.zPos,
            },
            orientation: euler2Quaternions({
              yaw: pose.heading,
              pitch: 0,
              roll: 0,
            }),
          },
          scale: {
            x: trackedObject.length,
            y: trackedObject.width,
            z: trackedObject.height,
          },
          color: custom.trajStyleSettings[String(yield_type)].color,
          lifetime: { sec: 1, nsec: 0 },
          metadata: { cubeEdge: true, edgeLineWidth: 1.5 },
        });

        outputs.push(lineMarker);
      }
    });
    outputs.push(
      createRosMarker({
        header: {
          frame_id: "world",
          stamp: receiveTime,
          seq: 0,
        },
        type: RosMarkerTypes.LINE_STRIP,
        id: 300 + agent_idx * 1000 + traj_idx * 1000000,
        action: 0,
        points: trajs.trajPoses.map((pose) => {
          return { x: pose.xPos, y: pose.yPos, z: pose.zPos };
        }),
        color: custom.trajStyleSettings[String(yield_type)].color,
        lifetime: { sec: 1, nsec: 0 },
        metadata: { cubeEdge: true, edgeLineWidth: 1.5, lineType: "solid" },
      }),
    );
    return outputs;
  }

  export function drawTrajectoriesPair(
    receiveTime: Time,
    agent_idx: number,
    target_trackedObject: Messages.voy__TrackedObject,
    ego_trackedObject: Messages.voy__TrackedObject,
    conditionalTrajectories: any,
    predicted_pose: number = -1,
    selectedTrajIdxs: number[] = [0],
    yield_type: string = "yield",
  ): RosMarker[] {
    const trajectoriesPair =
      yield_type === String("yield")
        ? conditionalTrajectories.yieldCbpTrajsPair
        : conditionalTrajectories.notYieldCbpTrajsPair;
    if (!trajectoriesPair) {
      return [];
    }
    if (selectedTrajIdxs.length < 1) {
      return [];
    }
    const target_trajs = trajectoriesPair.targetTrajectories;
    const ego_traj = trajectoriesPair.egoTrajectory;

    const outputs: RosMarker[] = [];

    // For target agent.
    for (let i = 0; i < selectedTrajIdxs.length; ++i) {
      const traj_idx = selectedTrajIdxs[i];
      const markers = drawTrajectories(
        receiveTime,
        agent_idx,
        traj_idx,
        target_trackedObject,
        target_trajs[traj_idx],
        predicted_pose,
        yield_type,
      );

      // Append markers.
      extendInPlace(outputs, markers);
    }

    // For ego agent.
    const markers = drawTrajectories(
      receiveTime,
      agent_idx,
      -1,
      ego_trackedObject,
      ego_traj,
      predicted_pose,
      yield_type,
    );
    // Append markers.
    extendInPlace(outputs, markers);
    return outputs;
  }

  export function extendInPlace(target: RosMarker[], source: RosMarker[]) {
    for (let i = 0; i < source.length; ++i) {
      target.push(source[i]);
    }
  }
}

const publisher = (
  messages: Record<string, Input<"/prediction/predicted_objects">>,
  globalVariables: GlobalVariables,
): Messages.visualization_msgs__MarkerArray | undefined => {
  const message = messages["/prediction/predicted_objects"];

  if (!message) {
    return undefined;
  }

  const receiveTime = message.receiveTime;
  const agentList = message.message.agentList;

  outputTrajectoryMarkers.length = 0;
  outputTrajectoryMarkers.push(createDeleteAllActionMarker(receiveTime));

  for (let agent_idx = 0; agent_idx < agentList.length; ++agent_idx) {
    const agent = agentList[agent_idx];

    const selectedAgentIdx =
      globalVariables.trajectory_selections?.[0]?.["agentId"];
    if (
      String(agent.trackedObject.id) !==
      String(globalVariables.tracked_object_selections?.[0])
    ) {
      continue;
    }
    if (!agent.conditionalTrajectories) {
      continue;
    }

    // Draw Yield Pair.
    const selectedYieldTrajIdxs =
      globalVariables.predictedCBPYieldTrajectoryIds.filter((value: any) => {
        return value != null && value != undefined;
      });
    const yield_outputs = custom.drawTrajectoriesPair(
      receiveTime,
      agent_idx,
      agent.trackedObject,
      message.message.egoAgent.trackedObject,
      agent.conditionalTrajectories,
      globalVariables.predicted_cbp_pose,
      selectedYieldTrajIdxs,
      "yield",
    );
    custom.extendInPlace(outputTrajectoryMarkers, yield_outputs);

    // Draw Not Yield Pair.
    // const selectedNotYieldTrajIdxs =
    //   globalVariables.predictedCBPNotYieldTrajectoryIds.filter((value: any) => {
    //     return value != null && value != undefined;
    //   });
    // const not_yield_outputs = custom.drawTrajectoriesPair(
    //   receiveTime,
    //   agent_idx,
    //   agent.trackedObject,
    //   message.message.egoAgent.trackedObject,
    //   agent.conditionalTrajectories,
    //   globalVariables.predicted_cbp_pose,
    //   "not_yield"
    // );
    // custom.extendInPlace(outputTrajectoryMarkers, not_yield_outputs);
  }

  return {
    markers: outputTrajectoryMarkers,
  };
};

export default publisher;

