import { GlobalVariables, DEFAULT_STUDIO_NODE_PREFIX } from "@ares-utils";
import { Input, Messages } from "ros";

export const inputs = ["/planning/planning_debug"];
export const output = `${DEFAULT_STUDIO_NODE_PREFIX}planning/pull_over/selected_jump_in_candidate`;
export const config = {
  datatype: "voyager_data_msgs/CustomData",
  showOn3DPanel: false,
};

function FindKinematicJumpInGuidance(
  dest_debugs: Messages.planner__pb__DestinationMetaDebug[],
  dest_key: string,
): Messages.planner__pb__KinematicJumpInGuidanceDebug | undefined {
  // const selected_dest = dest_debugs.find((dest_debug) => {
  //   return dest_debug.key == dest_key;
  // });
  const selected_dest = dest_debugs[0];
  return selected_dest ? selected_dest.jumpInGuidanceDebug : undefined;
}

export const publisher = (
  message: { "/planning/planning_debug": Input<"/planning/planning_debug"> },
  globalVars: GlobalVariables,
): Messages.voyager_data_msgs__CustomData => {
  const debug_message = message["/planning/planning_debug"];
  if (!debug_message) {
    return { data: [] };
  }

  const pull_over_info_debug =
    debug_message.message.behaviorReasonerDebug.decoupledManeuvers[0]
      .pullOverInfoDebug;

  const selected_key = globalVars.pull_over_destination_candidate_key as string;

  const jump_in_guidance_message =
    pull_over_info_debug.jumpInGuidanceSearchDebug.globalSearchDebug;

  if (!jump_in_guidance_message) {
    return { data: [] };
  }
  const local_jump_in_guidance_message =
    pull_over_info_debug.jumpInGuidanceSearchDebug.localSearchDebug;

  const cost_debug = jump_in_guidance_message.jumpInPrimitives.find((curve) => {
    return curve.isSelectedCandidate;
  }).costingInfo as Messages.planner__pb__JumpInPrimitiveCostingInfoDebug;

  return {
    dest_key: selected_key,
    jump_in_guidance: jump_in_guidance_message,
    local_jump_in_guidance: local_jump_in_guidance_message,
    cost_types: Object.keys(cost_debug),
  };
};

