import {
  getIntentionPlanDebug,
  getSpeedSolverDebugIndex,
  getObjectId,
  getConstraints,
  GlobalVariables,
  DEFAULT_STUDIO_NODE_PREFIX,
  DropdownOption,
} from "@ares-utils";
import { Input, Messages } from "ros";
import { isUndefined, forEach, max, min, map } from "lodash";
import { filterMap } from "@foxglove/den/collection";
import { Messages as StaticVoyagerType } from "@vitruvian/voyager-type";

const kSelectAllConstraintsLabel = "Select All Constraints";

export const inputs = ["/planning/planning_debug"];
export const output = `${DEFAULT_STUDIO_NODE_PREFIX}planning/planning_debug/constraint_selector`;

export const publisher = (
  messages: Record<string, Input<"/planning/planning_debug">>,
  globalVariables: GlobalVariables,
): Messages.voyager_data_msgs__CustomData | undefined => {
  const message = messages[
    "/planning/planning_debug"
  ] as Input<"/planning/planning_debug">;

  if (!message) {
    return {};
  }

  const behaviorReasonerDebug = (message.message?.behaviorReasonerDebug ??
    {}) as unknown as StaticVoyagerType.planner__pb__BehaviorReasonersDebug;

  const intentionPlanDebug = getIntentionPlanDebug(
    behaviorReasonerDebug,
    globalVariables,
  );

  const speedGeneratorDebug =
    ((intentionPlanDebug?.speedGeneratorDebug as Messages.speed__pb__SpeedGeneratorDebug) ??
      {}) as unknown as StaticVoyagerType.planner__speed__pb__SpeedGeneratorDebug;

  const speedSolverDebugIndex = getSpeedSolverDebugIndex(
    behaviorReasonerDebug,
    globalVariables,
  );

  const solverDebug =
    speedGeneratorDebug?.speedSolverDebugs[speedSolverDebugIndex];

  const searchDebug = (solverDebug?.searchDebug ??
    {}) as unknown as StaticVoyagerType.planner__speed__pb__SpeedSearchDebug;

  const constraints = getConstraints(searchDebug, speedGeneratorDebug);
  const selector = getConstraintSelector(searchDebug, constraints);

  return {
    constraintSelector: selector.constraintSelector,
    fuzzyConstraintSelector: selector.fuzzyConstraintSelector,
  };
};

function getConstraintSelector(
  searchDebug:
    | StaticVoyagerType.planner__speed__pb__SpeedSearchDebug
    | undefined,
  constraints:
    | StaticVoyagerType.planner__speed__pb__PrimitiveConstraint[]
    | Messages.planner__speed__pb__Constraint[],
): {
  constraintSelector: DropdownOption[];
  fuzzyConstraintSelector: DropdownOption[];
} {
  if (!searchDebug) {
    return { constraintSelector: [], fuzzyConstraintSelector: [] };
  }

  const constraintSelector: DropdownOption[] = [];
  const fuzzyConstraintSelector: DropdownOption[] = [];
  const { dominantConstraintIx } = searchDebug;
  const isDominantConstraintExisted =
    dominantConstraintIx >= 0 && dominantConstraintIx < constraints?.length;

  if (isDominantConstraintExisted) {
    const dominantConstraintId = constraints?.[dominantConstraintIx]
      ?.uniqueConstraintId as string;
    constraintSelector.push({
      title: getDominantConstraintLabel(dominantConstraintId),
      value: dominantConstraintId,
      connectKey: getObjectId(dominantConstraintId),
    });
  }

  let objects = new Set<string>();

  const objPrefixRegex = /^obj-\d+/;
  const fuzzyRegexSet = new Set<{ rule: string; display: string }>();
  forEach(constraints, (constraint, index) => {
    const uniqueConstraintId = (constraint as undefined as any)
      ?.uniqueConstraintId as string;
    if (Number(index) !== searchDebug?.dominantConstraintIx) {
      constraintSelector.push({
        title: uniqueConstraintId,
        value: uniqueConstraintId,
        connectKey: getObjectId(uniqueConstraintId),
      });
    }

    const match = uniqueConstraintId.match(objPrefixRegex);
    if (match) {
      const prefix = match[0];
      const regexString = `^${prefix}`;
      fuzzyRegexSet.add({ rule: regexString, display: prefix });

      const objMatch = prefix.match(/^obj-(\d+)$/);
      if (objMatch) {
        objects.add(objMatch[1]);
      }
    }
  });

  fuzzyConstraintSelector.push({
    title: kSelectAllConstraintsLabel,
    value: `.*`,
    connectKey: Array.from(objects),
  });

  fuzzyRegexSet.forEach((regex) => {
    const match = regex.display.match(/^obj-(\d+)$/);
    fuzzyConstraintSelector.push({
      title: regex.display,
      value: regex.rule,
      connectKey: match ? match[1] : "",
    });
  });

  if (constraintSelector.length > 0) {
    const allObjectId = filterMap(constraintSelector, (selector) => {
      if (typeof selector.connectKey === "string") {
        return selector.connectKey;
      }
      return undefined;
    });
  }

  return {
    constraintSelector: constraintSelector,
    fuzzyConstraintSelector: fuzzyConstraintSelector,
  };
}

function getDominantConstraintLabel(dominantConstraintId = "") {
  return `Dominant Constraint(${dominantConstraintId})`;
}

