import {
  GlobalVariables,
  DEFAULT_STUDIO_NODE_PREFIX,
  getTrajectoryMetaDebug,
} from "@ares-utils";
import { Input, Messages } from "ros";

export const inputs = ["/planning/planning_debug"];
export const config = {
  datatype: "voyager_data_msgs/CustomData",
  showOn3DPanel: false,
};
export const output = `${DEFAULT_STUDIO_NODE_PREFIX}planning/pull_over/multi_dest_costing`;

function getShortString(str: string): string {
  const split = str.split("_");
  split.splice(0, 2);
  split[0] = Number(split[0]).toFixed(0);
  split[1] = Number(split[1]).toFixed(0);
  log(split);
  return split.join("\n");
}

export const publisher = (
  messages: Record<string, Input<"/planning/planning_debug">>,
  globalVariable: GlobalVariables,
): Messages.voyager_data_msgs__CustomData => {
  const planningDebugMessage = messages[
    "/planning/planning_debug"
  ] as Input<"/planning/planning_debug">;
  if (!planningDebugMessage) {
    return {};
  }

  const dest_debugs =
    planningDebugMessage.message.behaviorReasonerDebug.decoupledManeuvers[0]
      .trajectorySelectionDebug.pullOverSelectionDebug.destClusterDebugs;

  const field_names = Object.keys(
    dest_debugs[0].destSelectCosting.costingItems[0],
  );
  field_names.splice(0, 1);

  let candidateCostData: Record<string, unknown>[] = [];
  candidateCostData = [
    { item: "DestKey" },
    { item: "DestIdx" },
    { item: "DestSelectTotalCost" },
    { item: "" },
  ];

  const table_header_rows = candidateCostData.length;

  // Cost item col.
  dest_debugs[0].destSelectCosting.costingItems.forEach((cost_item) => {
    field_names.forEach((field_name, idx) => {
      const row_name = cost_item.costName + "|" + field_name;
      candidateCostData.push({ item: row_name });
    });
    candidateCostData.push({ item: "" });
  });

  dest_debugs.forEach((dest, dest_idx) => {
    const col_name = "dest " + dest_idx;
    candidateCostData[0][col_name] = (dest as any)?.destKey;
    candidateCostData[1][col_name] = (dest as any)?.destIdx;
    candidateCostData[2][col_name] = dest.destSelectTotalCost.toFixed(3);
    candidateCostData[3][col_name] = "";
    dest.destSelectCosting.costingItems.forEach((cost_item, cost_item_idx) => {
      field_names.forEach((field_name, field_idx) => {
        const val = eval(`cost_item.${field_name}`);
        candidateCostData[
          table_header_rows +
            cost_item_idx * (field_names.length + 1) +
            field_idx
        ][col_name] = typeof val === "number" ? val.toFixed(3) : "";
      });
      candidateCostData[
        table_header_rows +
          cost_item_idx * (field_names.length + 1) +
          field_names.length
      ][col_name] = "";
    });
  });

  return {
    candidateCostData,
  };
};

