import { Input, Messages } from "ros";
import {
  getAccurateDecoupledManeuver,
  GlobalVariables,
  ScriptConfig,
  MemoryCacheBlock,
  DEFAULT_STUDIO_NODE_PREFIX,
} from "@ares-utils";
import { Messages as StaticVoyagerType } from "@vitruvian/voyager-type";
type Output = Messages.voyager_data_msgs__CustomData;

type InputTopics = {
  "/planning/planning_debug": Input<"/planning/planning_debug">;
};

export const inputs = ["/planning/planning_debug"];
export const config: ScriptConfig = {
  frontFrameLength: 3,
  behindFrameLength: 0,
};

export const output = `${DEFAULT_STUDIO_NODE_PREFIX}planning/planning_debug/last_yield_state_barrier_x`;

function getPlanningDebugInfo(
  laneSequenceInfoAndIntentPlanDebug: StaticVoyagerType.planner__pb__LaneSequenceInfoAndIntentPlanDebug[],
  label?: string,
) {
  const labelLen = label?.length;
  for (const singleLaneSequencePlanDebug of laneSequenceInfoAndIntentPlanDebug) {
    for (const singleIntentionPlanDebug of singleLaneSequencePlanDebug.singleIntentionPlanDebug) {
      if (
        labelLen &&
        singleIntentionPlanDebug.candidateIdentifier.substring(
          0,
          labelLen - 1,
        ) === label.substring(0, labelLen - 1)
      ) {
        return {
          singleIntentionPlanDebug,
          singleLaneSequencePlanDebug,
        };
      }
    }
  }
  return undefined;
}

function getSpeedSolverDebug(
  planningDebug: StaticVoyagerType.planner__pb__PlanningDebug,
) {
  const behaviorReasonerDebug = planningDebug?.behaviorReasonerDebug;
  if (behaviorReasonerDebug === undefined) {
    return undefined;
  }
  const decoupledManeuver = getAccurateDecoupledManeuver(behaviorReasonerDebug);
  const selectedTrajectoryDebug =
    decoupledManeuver?.trajectorySelectionDebug.trajectoryMetaDebugs.find(
      (meta) => meta.isSelected,
    );
  const selectedTrajLabel = selectedTrajectoryDebug.label;
  const selectedTrajSpeedIx = selectedTrajectoryDebug.speedIx;
  const selectedPlanningDebugInfo = getPlanningDebugInfo(
    decoupledManeuver.singleLaneSequencePlanDebug,
    selectedTrajLabel,
  );

  const intentionPlanDebug =
    selectedPlanningDebugInfo?.singleIntentionPlanDebug;
  const speedGeneratorDebug =
    intentionPlanDebug?.speedGeneratorDebug as undefined as any as StaticVoyagerType.planner__speed__pb__SpeedGeneratorDebug;

  const speedSolverDebug =
    speedGeneratorDebug?.speedSolverDebugs?.[selectedTrajSpeedIx];

  return speedSolverDebug;
}

export const publisher = (
  messages: Record<string, Input<"/planning/planning_debug">>,
  globalVars: GlobalVariables,
  blocks: readonly (MemoryCacheBlock | undefined)[],
): Messages.ares__CustomizationPlot => {
  const lastYieldStateBarrierConfig: Messages.ares__CustomizationPlotData = {
    lines: [],
    borderColor: "#bbbbbb",
    borderWidth: 1.5,
    pointBackgroundColor: "#bbbbbb",
    pointRadius: 1.0,
  };

  const message = messages[
    "/planning/planning_debug"
  ] as Input<"/planning/planning_debug">;

  if (!message) {
    return {
      data: [lastYieldStateBarrierConfig],
    };
  }

  const lastYieldStateBarrierLine: Messages.ares__CustomizationPlotLine = {
    line: [],
  };

  const lastPlanningDebug = blocks[2]?.messagesByTopic[
    "/planning/planning_debug"
  ][0]
    ?.message as undefined as any as StaticVoyagerType.planner__pb__PlanningDebug;

  const lastSolverDebug = getSpeedSolverDebug(lastPlanningDebug);
  const lastOptDebug = lastSolverDebug?.optDebug;
  if (lastOptDebug === undefined) {
    return;
  }

  const lastStateBarriers = lastOptDebug?.potentialDebug?.stateBarriers;
  if (lastStateBarriers === undefined) {
    return;
  }

  const lastYieldBarrierX = lastStateBarriers.map(
    (item) => item.smallestYieldX,
  );
  lastYieldBarrierX.slice(1).forEach((y, i) => {
    lastYieldStateBarrierLine.line.push({ x: i * 0.1, y });
  });

  lastYieldStateBarrierConfig.lines.push(lastYieldStateBarrierLine);
  return {
    data: [lastYieldStateBarrierConfig],
  };
};

