import { GlobalVariables, DEFAULT_STUDIO_NODE_PREFIX } from "@ares-utils";
import { Input, Messages } from "ros";
import { forEach } from "lodash";

export const inputs = [
  "/planning/planning_debug",
  "/perception/tracked_object_list",
];

export const output = `${DEFAULT_STUDIO_NODE_PREFIX}planning/world_model/lane_blockage/temp_parked_signal`;
export const config = {
  datatype: "ares/VisualizationLabelArray",
  executeScriptWhenAnyMessageReceived: true,
};

let preTrackObjectMessage: Input<"/perception/tracked_object_list"> | undefined;
let prePlanningDebugMessage: Input<"/planning/planning_debug"> | undefined;

export const publisher = (
  messages: Record<
    string,
    Input<"/planning/planning_debug"> | Input<"/perception/tracked_object_list">
  >,
  globalVariables: GlobalVariables,
): Messages.ares__VisualizationLabelArray | undefined => {
  const planningDebugMessage = messages["/planning/planning_debug"];
  const trackedObjectMessage = messages["/perception/tracked_object_list"];

  if (planningDebugMessage) {
    prePlanningDebugMessage =
      planningDebugMessage as Input<"/planning/planning_debug">;
  }

  if (trackedObjectMessage) {
    preTrackObjectMessage =
      trackedObjectMessage as Input<"/perception/tracked_object_list">;
  }

  if (!prePlanningDebugMessage || !preTrackObjectMessage) {
    return;
  }

  const {
    message: { worldModelDebug },
    receiveTime,
  } = prePlanningDebugMessage;

  const laneBlockages =
    worldModelDebug?.laneBlockageDebug?.laneObjectBlockingInfo;

  const {
    message: { trackedObjects },
  } = preTrackObjectMessage;

  const labels: Messages.ares__VisualizationLabel[] = [];

  forEach(trackedObjects, (trackedObject) => {
    const allBlockingInfo = laneBlockages.filter(
      (blockage) => blockage.objectId == trackedObject.id,
    );

    // Only label the blockage with kTempParked signal.
    const tempIndex = allBlockingInfo.find(
      (blockage) => blockage.blockingType == "kTempParked",
    );
    if (allBlockingInfo.length == 0 || !tempIndex) {
      return;
    }

    // Generate label.
    var label = "";
    forEach(allBlockingInfo, (blockage) => {
      if (blockage.blockingType == "kTempParked") {
        label += `TempParked: ${blockage.laneId}\n`;
      } else {
        label += `SlowMoving: ${blockage.laneId}\n`;
      }
    });

    const { id, centerX, centerY, centerZ } = trackedObject;
    labels.push({
      header: { frame_id: "world", seq: 0, stamp: receiveTime },
      name: label,
      type: Messages.ares__VisualizationLabelType.PARKER_CAR,
      class: Messages.ares__VisualizationLabelClass.PLANNING,
      id: `${id}`,
      suffix: "",
      svg: "",
      centerX,
      centerY,
      centerZ,
      isHighlight:
        globalVariables.tracked_object_selections?.includes(`${id}`) ?? false,
    });
  });

  return {
    labels,
  };
};

