import { Input, Messages } from "ros";
import {
  getIntentionPlanDebug,
  GlobalVariables,
  createDeleteCurrentTopicMarkers,
} from "@ares-utils";

export const inputs = ["/planning/planning_debug"];
export const output =
  "/studio_node/planning/path_generator/primitives/path_smoother/sl_nudge_violation/left";

type Point = { x: number; y: number };
// 计算ray end point
const computeRayEndpoint = (
  reference: Point[],
  arclength: number,
  clearanceDistance: number,
  poseZ: number,
) => {
  const [rayStart, direction] = GetInterpPointAndDeriv(reference, arclength);
  const normalDir = { x: -direction.y, y: direction.x }; // Perpendicular direction

  return {
    x: rayStart.x + normalDir.x * clearanceDistance,
    y: rayStart.y + normalDir.y * clearanceDistance,
    z: poseZ + 2, // +1 是为了可视化方便，不被遮挡住
  };
};

// 基于arclength 计算 reference上对应的点和direction
const GetInterpPointAndDeriv = (
  reference: Point[],
  arclength: number,
): [Point, Point] => {
  let accumulatedLength = 0;
  let prevPoint = reference[0];

  // Calculate the total path length (arc length)
  for (let i = 1; i < reference.length; i++) {
    const currentPoint = reference[i];
    const segmentLength = Math.sqrt(
      Math.pow(currentPoint.x - prevPoint.x, 2) +
        Math.pow(currentPoint.y - prevPoint.y, 2),
    );
    accumulatedLength += segmentLength;
    prevPoint = currentPoint;
  }

  // 超出 total length, 则return last point and direction
  if (arclength >= accumulatedLength) {
    const lastPoint = reference[reference.length - 1];
    const dx =
      reference[reference.length - 1].x - reference[reference.length - 2].x;
    const dy =
      reference[reference.length - 1].y - reference[reference.length - 2].y;

    const magnitude = Math.sqrt(dx * dx + dy * dy);
    const direction =
      magnitude > 0 ? { x: dx / magnitude, y: dy / magnitude } : { x: 0, y: 0 };

    return [lastPoint, direction];
  }

  // Find the segment corresponding to the given arclength
  let currentLength = 0;
  for (let i = 1; i < reference.length; i++) {
    const currentPoint = reference[i];
    const segmentLength = Math.sqrt(
      Math.pow(currentPoint.x - reference[i - 1].x, 2) +
        Math.pow(currentPoint.y - reference[i - 1].y, 2),
    );

    if (currentLength + segmentLength >= arclength) {
      const interpolationFactor = (arclength - currentLength) / segmentLength;
      const prevPoint = reference[i - 1];

      const interpPoint: Point = {
        x: prevPoint.x + (currentPoint.x - prevPoint.x) * interpolationFactor,
        y: prevPoint.y + (currentPoint.y - prevPoint.y) * interpolationFactor,
      };

      const dx = currentPoint.x - prevPoint.x;
      const dy = currentPoint.y - prevPoint.y;
      const magnitude = Math.sqrt(dx * dx + dy * dy);
      const direction =
        magnitude > 0
          ? { x: dx / magnitude, y: dy / magnitude }
          : { x: 0, y: 0 };

      return [interpPoint, direction];
    }

    currentLength += segmentLength;
  }

  // If no suitable segment found, return last point and direction
  const lastPoint = reference[reference.length - 1];
  const dx =
    reference[reference.length - 1].x - reference[reference.length - 2].x;
  const dy =
    reference[reference.length - 1].y - reference[reference.length - 2].y;

  const magnitude = Math.sqrt(dx * dx + dy * dy);
  const direction =
    magnitude > 0 ? { x: dx / magnitude, y: dy / magnitude } : { x: 0, y: 0 };
  return [lastPoint, direction];
};

export const publisher = (
  messages: Record<string, Input<"/planning/planning_debug">>,
  globalVars: GlobalVariables,
): Messages.ares__VisualizationMarkerArray | undefined => {
  const message = messages[
    "/planning/planning_debug"
  ] as Input<"/planning/planning_debug">;

  if (!message) {
    return {
      markers: [],
    };
  }

  const {
    message: { behaviorReasonerDebug, pose },
    receiveTime,
  } = message;

  const markers: Messages.ares__VisualizationMarker[] = [
    createDeleteCurrentTopicMarkers(receiveTime),
  ];

  const intentionPlanDebug = getIntentionPlanDebug(
    behaviorReasonerDebug,
    globalVars,
  );
  if (!intentionPlanDebug) {
    return {
      markers,
    };
  }
  const pathSmootherDebug =
    intentionPlanDebug?.pathPlannerDebug?.pathSmootherDebug;
  const pathConstraintDebug =
    intentionPlanDebug?.pathPlannerDebug?.pathConstraintDebug;
  const reference =
    pathSmootherDebug?.decoupledPathPrimitivesDebug?.pathHeuristicPrimitive
      ?.referenceCurve.curve.segments[0].points;
  const agentClearanceExtractedData =
    pathConstraintDebug?.agentClearanceExtractedDataDebug;
  if (!agentClearanceExtractedData) {
    return {
      markers,
    };
  }
  const resolution = agentClearanceExtractedData.resolution;
  const arclengthRange = agentClearanceExtractedData.effectiveReferenceRange;
  const maxAbsLateralClearance =
    agentClearanceExtractedData.maxAbsLateralClearance;

  const leftCriticalData =
    agentClearanceExtractedData.leftCriticalClearanceWithGap;
  const leftComfortData =
    agentClearanceExtractedData.leftComfortClearanceWithGap;

  if (
    (leftCriticalData.length === 0 && leftComfortData.length === 0) ||
    !pose
  ) {
    return {
      markers,
    };
  }

  const generateRayEndpoints = (clearanceData: any[], skip_points: boolean) =>
    clearanceData.flatMap((clearanceData, index) => {
      if (skip_points && Math.abs(clearanceData) >= maxAbsLateralClearance) {
        return [];
      }
      return computeRayEndpoint(
        reference,
        index * resolution + arclengthRange.startPos,
        clearanceData,
        pose.z,
      );
    });

  const criticalPointMarkers: Messages.ares__VisualizationMarker = {
    header: {
      frame_id: "world",
      seq: 0,
      stamp: receiveTime,
    },
    type: Messages.ares__VisualizationMarkerTypes.POINTS,
    id: `agent_sl_nudge_critical_violation_left`,
    pose: {
      position: { x: 0, y: 0, z: 0 },
    },
    points: [pose, ...generateRayEndpoints(leftCriticalData, true)],
    color: {
      r: 1.0, // Red
      g: 0.5, // Green
      b: 0.0, // Blue
      a: 0.5, // 透明
    },
    pointMetadata: {
      radius: 2,
    },
    scale: { x: 10.0, y: 0, z: 0 },
  };

  const comfortPointMarkers: Messages.ares__VisualizationMarker = {
    header: {
      frame_id: "world",
      seq: 0,
      stamp: receiveTime,
    },
    type: Messages.ares__VisualizationMarkerTypes.POINTS,
    id: `agent_sl_nudge_comfort_violation_left`,
    pose: {
      position: { x: 0, y: 0, z: 0 },
    },
    points: [pose, ...generateRayEndpoints(leftComfortData, true)],
    color: {
      r: 1.0, // Red
      g: 1.0, // Green
      b: 1.0, // Blue
      a: 0.5, // 透明
    },
    pointMetadata: {
      radius: 2,
    },
    scale: { x: 10.0, y: 0, z: 0 },
  };

  const criticalLineMarkers: Messages.ares__VisualizationMarker = {
    header: {
      frame_id: "world",
      seq: 0,
      stamp: receiveTime,
    },
    type: Messages.ares__VisualizationMarkerTypes.LINE_STRIP,
    id: `agent_sl_nudge_left_critical_violation_line`,
    pose: {
      position: { x: 0, y: 0, z: 0 },
    },
    points: [...generateRayEndpoints(leftCriticalData, false)],
    color: {
      r: 1.0, // Red
      g: 0.27, // Green
      b: 1.0, // Blue
      a: 0.5, // 透明
    },
    lineMetadata: {
      lineWidth: 0.3,
      frustumCulled: false,
    },
  };

  const comfortLineMarkers: Messages.ares__VisualizationMarker = {
    header: {
      frame_id: "world",
      seq: 0,
      stamp: receiveTime,
    },
    type: Messages.ares__VisualizationMarkerTypes.LINE_STRIP,
    id: `agent_sl_nudge_left_comfort_violation_line`,
    pose: {
      position: { x: 0, y: 0, z: 0 },
    },
    points: [...generateRayEndpoints(leftComfortData, false)],
    color: {
      r: 1.0, // Red
      g: 1.0, // Green
      b: 1.0, // Blue
      a: 0.5, // 透明
    },
    lineMetadata: {
      lineWidth: 0.3,
      frustumCulled: false,
    },
  };

  markers.push(criticalPointMarkers);
  markers.push(comfortPointMarkers);
  markers.push(criticalLineMarkers);
  markers.push(comfortLineMarkers);
  return {
    markers,
  };
};

export default publisher;

