/* eslint-disable @typescript-eslint/no-unnecessary-condition */
/* ares-expose-source-code */
import {
  createDeleteCurrentTopicMarkers,
  getLoopedFlattenedPoints,
  Point,
} from "@ares-utils";
import { Input, Messages } from "@vitruvian/voyager-type";
import { isNil } from "lodash";

type Inputs = {
  "/planning/planning_debug": Input<"/planning/planning_debug">;
};
type Output = Messages.ares__VisualizationMarkerArray | undefined;

type SnapshotDebug = {
  occlusionGrid: {
    visibilityPolygonForLaneChange: Point[];
  };
};

export const inputs = ["/planning/planning_debug"];
export const config = {
  datatype: "ares/VisualizationMarkerArray",
};

export const output = "/studio_node/planning/occlusion/lc_visibility_polygon";
const topicKey = "/planning/planning_debug";

export const publisher = (messages: Inputs): Output => {
  const message = messages[topicKey];

  const {
    receiveTime,
    message: { pose, snapshotDebug },
  } = message;

  const lc_visibility_polygon_markers: Messages.ares__VisualizationMarker[] = [
    createDeleteCurrentTopicMarkers(receiveTime),
  ];

  if (isNil(pose)) {
    return;
  }

  const lc_visibility_polygon =
    (snapshotDebug as unknown as SnapshotDebug)?.occlusionGrid
      ?.visibilityPolygonForLaneChange ?? [];

  const flattenedPoints = getLoopedFlattenedPoints(
    lc_visibility_polygon,
    pose.z + 0.5,
  );
  // Create the marker in LINE_LOOP for the border of the visibility polygon.
  const lc_visibility_polygon_marker: Messages.ares__VisualizationMarker = {
    header: {
      frame_id: "world",
      stamp: receiveTime,
      seq: 0,
    },
    type: Messages.ares__VisualizationMarkerTypes.LINE_STRIP,
    action: 0,
    flattenedPoints,
    color: {
      r: 0.0,
      g: 1.0,
      b: 1.0,
      a: 1.0,
    },
    id: `lc_visibility_polygon`,
    lineMetadata: {
      lineWidth: 0.3,
    },
  };

  // Merge the occlusion area border maker to occlusion area markers.
  lc_visibility_polygon_markers.push(lc_visibility_polygon_marker);
  return {
    markers: lc_visibility_polygon_markers,
  };
};

