/* eslint-disable @typescript-eslint/no-unnecessary-condition */
/* ares-expose-source-code */
import { Input, Messages } from "ros";
import { Messages as StaticVoyagerType } from "@vitruvian/voyager-type";
import {
  GlobalVariables,
  DEFAULT_STUDIO_NODE_PREFIX,
  getIntentionPlanDebug,
  getSpeedSolverDebugIndex,
} from "@ares-utils";
import { isUndefined, forEach, max, min, map } from "lodash";

export const inputs = ["/planning/planning_debug"];
export const output = `${DEFAULT_STUDIO_NODE_PREFIX}planning/planning_debug/state_boundary_debug`;

export const publisher = (
  messages: Record<string, Input<"/planning/planning_debug">>,
  globalVariables: GlobalVariables,
): Messages.ares__CustomizationPlot => {
  const message = messages[
    "/planning/planning_debug"
  ] as Input<"/planning/planning_debug">;

  // State Barrier
  const passBarrierCurvesConfig: Messages.ares__CustomizationPlotData = {
    lines: [],
    borderColor: "#ff0000",
    borderWidth: 1.5,
    borderDash: [8, 8],
    pointBackgroundColor: "#ff0000",
    pointRadius: 1.0,
  };

  const yieldBarrierCurvesConfig: Messages.ares__CustomizationPlotData = {
    lines: [],
    borderColor: "#ff0000",
    borderWidth: 1.5,
    pointBackgroundColor: "#ff0000",
    pointRadius: 1.0,
  };

  // Branch State Barrier
  const branchPassBarrierCurvesConfig: Messages.ares__CustomizationPlotData = {
    lines: [],
    borderColor: "#8b0000",
    borderWidth: 1.5,
    borderDash: [8, 8],
    pointBackgroundColor: "#8b0000",
    pointRadius: 1.0,
  };

  const branchYieldBarrierCurvesConfig: Messages.ares__CustomizationPlotData = {
    lines: [],
    borderColor: "#8b0000",
    borderWidth: 1.5,
    pointBackgroundColor: "#8b0000",
    pointRadius: 1.0,
  };

  // State Repeller
  const passRepellerCurvesConfig: Messages.ares__CustomizationPlotData = {
    lines: [],
    borderColor: "#ff00ff",
    borderWidth: 1.5,
    borderDash: [8, 8],
    pointBackgroundColor: "#ff00ff",
    pointRadius: 1.0,
  };

  const yieldRepellerCurvesConfig: Messages.ares__CustomizationPlotData = {
    lines: [],
    borderColor: "#ff00ff",
    borderWidth: 1.5,
    pointBackgroundColor: "#ff00ff",
    pointRadius: 1.0,
  };

  const branchPassRepellerCurvesConfig: Messages.ares__CustomizationPlotData = {
    lines: [],
    borderColor: "#8b008b",
    borderWidth: 1.5,
    borderDash: [8, 8],
    pointBackgroundColor: "#8b008b",
    pointRadius: 1.0,
  };

  const branchYieldRepellerCurvesConfig: Messages.ares__CustomizationPlotData =
    {
      lines: [],
      borderColor: "#8b008b",
      borderWidth: 1.5,
      pointBackgroundColor: "#8b008b",
      pointRadius: 1.0,
    };

  if (!message) {
    return {
      data: [
        passBarrierCurvesConfig,
        yieldBarrierCurvesConfig,
        branchPassBarrierCurvesConfig,
        branchYieldBarrierCurvesConfig,
        passRepellerCurvesConfig,
        yieldRepellerCurvesConfig,
        branchPassRepellerCurvesConfig,
        branchYieldRepellerCurvesConfig,
      ],
    };
  }

  const behaviorReasonerDebug = (message.message?.behaviorReasonerDebug ??
    {}) as unknown as StaticVoyagerType.planner__pb__BehaviorReasonersDebug;

  const intentionPlanDebug = getIntentionPlanDebug(
    behaviorReasonerDebug,
    globalVariables,
  );

  const speedGeneratorDebug =
    intentionPlanDebug?.speedGeneratorDebug as Messages.speed__pb__SpeedGeneratorDebug;

  const speedSolverDebugIndex = getSpeedSolverDebugIndex(
    behaviorReasonerDebug,
    globalVariables,
  );

  const solverDebug =
    speedGeneratorDebug?.speedSolverDebugs[speedSolverDebugIndex];
  const kDt = 0.1;

  const passStateBarrierCurvesLine: Messages.ares__CustomizationPlotLine = {
    line: [],
  };

  const yieldStateBarrierCurvesLine: Messages.ares__CustomizationPlotLine = {
    line: [],
  };

  const branchPassStateBarrierCurvesLine: Messages.ares__CustomizationPlotLine =
    {
      line: [],
    };

  const branchYieldStateBarrierCurvesLine: Messages.ares__CustomizationPlotLine =
    {
      line: [],
    };

  const passStateRepellerCurvesLine: Messages.ares__CustomizationPlotLine = {
    line: [],
  };

  const yieldStateRepellerCurvesLine: Messages.ares__CustomizationPlotLine = {
    line: [],
  };

  const branchPassStateRepellerCurvesLine: Messages.ares__CustomizationPlotLine =
    {
      line: [],
    };

  const branchYieldStateRepellerCurvesLine: Messages.ares__CustomizationPlotLine =
    {
      line: [],
    };

  if (solverDebug) {
    const stateBarriers = solverDebug?.optDebug?.potentialDebug?.stateBarriers;
    const branchStateBarriers = (
      solverDebug?.optDebug?.potentialDebug as undefined as any
    )?.branchStateBarrier;
    const stateRepellers = (
      solverDebug?.optDebug?.potentialDebug as undefined as any
    )?.stateRepellers;
    const branchStateRepellers = (
      solverDebug?.optDebug?.potentialDebug as undefined as any
    )?.branchStateRepellers;

    if (stateBarriers != undefined) {
      for (let stateIx = 0; stateIx < stateBarriers.length; stateIx++) {
        const stateBarrier = stateBarriers[stateIx];
        const passX = (stateBarrier as unknown as any)?.largestPassX;
        if (passX) {
          passStateBarrierCurvesLine.line.push({
            x: stateIx * kDt,
            y: passX,
          });
        }

        const yieldX = (stateBarrier as unknown as any)?.smallestYieldX;
        if (yieldX) {
          yieldStateBarrierCurvesLine.line.push({
            x: stateIx * kDt,
            y: yieldX,
          });
        }
      }
    }

    if (branchStateBarriers != undefined) {
      for (let stateIx = 0; stateIx < branchStateBarriers.length; stateIx++) {
        const branchStateBarrier = branchStateBarriers[stateIx];
        const passX = (branchStateBarrier as unknown as any)?.largestPassX;
        if (passX) {
          branchPassStateBarrierCurvesLine.line.push({
            x: stateIx * kDt,
            y: passX,
          });
        }

        const yieldX = (branchStateBarrier as unknown as any)?.smallestYieldX;
        if (yieldX) {
          branchYieldStateBarrierCurvesLine.line.push({
            x: stateIx * kDt,
            y: yieldX,
          });
        }
      }
    }

    if (stateRepellers != undefined) {
      for (let stateIx = 0; stateIx < stateRepellers.length; stateIx++) {
        const stateRepeller = stateRepellers[stateIx];
        const passX = (stateRepeller as unknown as any)?.largestPassX;
        if (passX) {
          passStateRepellerCurvesLine.line.push({
            x: stateIx * kDt,
            y: passX,
          });
        }

        const yieldX = (stateRepeller as unknown as any)?.smallestYieldX;
        if (yieldX) {
          yieldStateRepellerCurvesLine.line.push({
            x: stateIx * kDt,
            y: yieldX,
          });
        }
      }
    }

    if (branchStateRepellers != undefined) {
      for (let stateIx = 0; stateIx < branchStateRepellers.length; stateIx++) {
        const branchStateRepeller = branchStateRepellers[stateIx];
        const passX = (branchStateRepeller as unknown as any)?.largestPassX;
        if (passX) {
          branchPassStateRepellerCurvesLine.line.push({
            x: stateIx * kDt,
            y: passX,
          });
        }

        const yieldX = (branchStateRepeller as unknown as any)?.smallestYieldX;
        if (yieldX) {
          branchYieldStateRepellerCurvesLine.line.push({
            x: stateIx * kDt,
            y: yieldX,
          });
        }
      }
    }
  }

  passBarrierCurvesConfig.lines.push(passStateBarrierCurvesLine);
  yieldBarrierCurvesConfig.lines.push(yieldStateBarrierCurvesLine);
  branchPassBarrierCurvesConfig.lines.push(branchPassStateBarrierCurvesLine);
  branchYieldBarrierCurvesConfig.lines.push(branchYieldStateBarrierCurvesLine);
  passRepellerCurvesConfig.lines.push(passStateRepellerCurvesLine);
  yieldRepellerCurvesConfig.lines.push(yieldStateRepellerCurvesLine);
  branchPassRepellerCurvesConfig.lines.push(branchPassStateRepellerCurvesLine);
  branchYieldRepellerCurvesConfig.lines.push(
    branchYieldStateRepellerCurvesLine,
  );

  return {
    data: [
      passBarrierCurvesConfig,
      yieldBarrierCurvesConfig,
      branchPassBarrierCurvesConfig,
      branchYieldBarrierCurvesConfig,
      passRepellerCurvesConfig,
      yieldRepellerCurvesConfig,
      branchPassRepellerCurvesConfig,
      branchYieldRepellerCurvesConfig,
    ],
  };
};

