// 数据源路径
// decoupledManeuver?.singleLaneSequencePlanDebug[:]?.intentionGeneratorDebug?.objectIntentions

import {
  getSingleLaneSequencePlanDebug,
  DEFAULT_STUDIO_NODE_PREFIX,
  GlobalVariables,
} from "@ares-utils";
import { Input, Messages } from "@vitruvian/voyager-type";
import { forEach } from "lodash";

export const inputs = ["/planning/planning_debug"];
export const output = `${DEFAULT_STUDIO_NODE_PREFIX}planning/planning_debug/intention_generator`;
export const config = {
  datatype: "voyager_data_msgs/CustomData",
  showOn3DPanel: false,
};

// 明确声明 IntentionObject 类型
interface IntentionObject {
  objectId: number;
  trajectoryType: any;
  globalBlockingState: any;
  trackedBlockingInfo: {
    blockingState: any;
  };
  blockingSequences: Array<{
    blockingState: string;
    range: {
      startIndex: number;
      endIndex: number;
    };
  }>;
  trajectoryBlockingInfos: Array<{
    blockingState: string;
  }>;
  effectiveRange: Array<{
    startIndex: number;
    endIndex: number;
  }>;
  reasonerId: any;
  reasoningInfo: any;
  yieldIntentionData?: {
    yieldProbability: number;
    consecutiveYieldCount: number;
  };
}

// 拼接后的字符串：{(38,87)}; (0 1 2 3)
function generateBlockingStateDebugString(
  object: IntentionObject,
  blockType: string,
): string {
  let blockingDebugStr = "{";
  forEach(object.blockingSequences, (blockingSequence) => {
    if (blockingSequence.blockingState === blockType) {
      blockingDebugStr += `(${blockingSequence.range.startIndex},${blockingSequence.range.endIndex})`;
    }
  });
  blockingDebugStr += "}; (";

  forEach(object.trajectoryBlockingInfos, (trajectoryBlockingInfo, index) => {
    if (trajectoryBlockingInfo.blockingState === blockType) {
      blockingDebugStr += `${index} `;
    }
  });

  blockingDebugStr += ")";
  return blockingDebugStr;
}

function generateEffectiveRangeDebugString(
  effectiveRange: Array<{ startIndex: number; endIndex: number }>,
) {
  let debug_str = effectiveRange.reduce((accu, effective) => {
    return accu + `(${effective.startIndex}, ${effective.endIndex})`;
  }, "{");
  debug_str += "}";
  return debug_str;
}

export const publisher = (
  messages: Record<string, Input<"/planning/planning_debug">>,
  globalVars: GlobalVariables,
): Messages.voyager_data_msgs__CustomData => {
  const message = messages[
    "/planning/planning_debug"
  ] as Input<"/planning/planning_debug">;
  if (!message) {
    return [];
  }

  const {
    message: { behaviorReasonerDebug },
  } = message;
  const singleLaneSequencePlanDebug = getSingleLaneSequencePlanDebug(
    behaviorReasonerDebug,
    globalVars,
  );
  if (!singleLaneSequencePlanDebug) {
    return [];
  }

  const objectIntentions =
    singleLaneSequencePlanDebug.intentionGeneratorDebug?.objectIntentions;
  if (!objectIntentions) {
    return [];
  }

  const trackedObjectId: string =
    globalVars.tracked_object_selections?.[0] ?? "";
  if (!trackedObjectId) {
    return [];
  }

  // 明确类型转换
  const intentionForTrackedObject = Object.values(objectIntentions).find(
    (obj: any) => obj.objectId === Number(trackedObjectId),
  ) as IntentionObject | undefined;

  if (!intentionForTrackedObject) {
    return [];
  }

  const {
    globalBlockingState,
    trajectoryType,
    effectiveRange,
    reasonerId,
    reasoningInfo,
    yieldIntentionData,
  } = intentionForTrackedObject;

  // 格式化 yieldIntentionData 为可读字符串
  const formatYieldIntentionData = (
    data: typeof intentionForTrackedObject.yieldIntentionData,
  ): string => {
    if (!data) return "N/A";
    return `prob: ${data.yieldProbability.toFixed(2)}, count: ${data.consecutiveYieldCount}`;
  };

  const objForTable = {
    trajectoryIntention: trajectoryType,
    globalBlockingState,
    trackedBlockingState:
      intentionForTrackedObject.trackedBlockingInfo.blockingState,
    effectiveRange: generateEffectiveRangeDebugString(effectiveRange),
    hardBlockingIndex: generateBlockingStateDebugString(
      intentionForTrackedObject,
      "HARD_BLOCKING",
    ),
    softBlockingIndex: generateBlockingStateDebugString(
      intentionForTrackedObject,
      "SOFT_BLOCKING",
    ),
    yieldIntentionData: formatYieldIntentionData(yieldIntentionData),
    reasonerID: reasonerId,
    reasoningInfos: reasoningInfo,
  };

  return [objForTable];
};

