// 数据源路径
// decoupledManeuver?.singleLaneSequencePlanDebug[:]?.intentionGeneratorDebug?.intentionSearcherDebug?.tunnelSearcherDebug?.groupAgents

import {
  GlobalVariables,
  DEFAULT_STUDIO_NODE_PREFIX,
  getSingleLaneSequencePlanDebug,
} from "@ares-utils";
import { Input, Messages } from "@vitruvian/voyager-type";

export const inputs = ["/planning/planning_debug"];
export const output = `${DEFAULT_STUDIO_NODE_PREFIX}planning/planning_debug/agent_group_info`;
export const config = {
  datatype: "voyager_data_msgs/CustomData",
  showOn3DPanel: false,
};

function getAgentIdsString(
  agents: Messages.planner__pb__GroupAgentInfo__AgentInfo[],
) {
  let agent_ids_str = "";
  agents.forEach((agent) => {
    const { objectId, _ } = agent.id;
    agent_ids_str += objectId + ",";
  });
  return agent_ids_str;
}

function getBorderPolygon(polygon: Messages.voy__Point2d[]) {
  const str = polygon.reduce((accu, point) => {
    return accu + `${point.x} ${point.y},`;
  }, "");

  return str.slice(0, -1);
}

export const publisher = (
  messages: Record<string, Input<"/planning/planning_debug">>,
  globalVars: GlobalVariables,
): Record<string, Messages.voyager_data_msgs__CustomData> => {
  const message = messages[
    "/planning/planning_debug"
  ] as Input<"/planning/planning_debug">;
  if (!message) {
    return {};
  }

  const {
    message: { behaviorReasonerDebug },
  } = message;
  const singleLaneSequencePlanDebug = getSingleLaneSequencePlanDebug(
    behaviorReasonerDebug,
    globalVars,
  );
  if (!singleLaneSequencePlanDebug) {
    return {};
  }

  const groupAgents =
    singleLaneSequencePlanDebug.intentionGeneratorDebug?.intentionSearcherDebug
      ?.tunnelSearcherDebug?.groupAgents ?? [];
  if (groupAgents.length === 0) {
    return {};
  }

  const resForTable = groupAgents.map((group) => ({
    "Group ID": group.groupId.objectId,
    "Agent Ids": getAgentIdsString(group.agents),
    "Contour Polygon": getBorderPolygon(group.groupBorderPolygon),
  }));

  return resForTable;
};

