/**
 * @file https://cooper.didichuxing.com/docs2/document/2202547566417
 * @remark refactor by jinfangfang
 */
/* eslint-disable @typescript-eslint/no-unnecessary-condition */
import {
  createDeleteAllActionMarker,
  AresMarker,
  AresMarkerTypes,
  createAresMarker,
  Point,
  getLoopedFlattenedPoints,
} from "@ares-utils";
import { Input, Messages } from "@vitruvian/voyager-type";

type Inputs = {
  "/planning/planning_debug": Input<"/planning/planning_debug">;
};
type Output = Messages.visualization_msgs__MarkerArray;

type SnapshotDebug = {
  occlusionGrid: {
    gridPolygon: Point[];
  };
};

export const inputs = ["/planning/planning_debug"];
export const config = {
  datatype: "visualization_msgs/MarkerArray",
};

export const output = "/studio_node/planning/occlusion/occlusion_grid_polygon";

const topicKey = "/planning/planning_debug";
export const publisher = (messages: Inputs): Output => {
  const message = messages[topicKey];
  const {
    receiveTime,
    message: { pose, snapshotDebug },
  } = message;

  const occlusion_grid_markers: AresMarker[] = [
    createDeleteAllActionMarker(receiveTime),
  ];

  const occlusion_grid_polygon =
    (snapshotDebug as unknown as SnapshotDebug)?.occlusionGrid?.gridPolygon ??
    [];
  const flattenedPoints = getLoopedFlattenedPoints(
    occlusion_grid_polygon,
    pose.z,
  );
  // Create the marker in LINE_LOOP for the border of the occlusion grid polygon.
  const occlusion_grid_polygon_marker: Partial<AresMarker> = {
    header: {
      frame_id: "world",
      stamp: receiveTime,
      seq: 0,
    },
    type: AresMarkerTypes.LINE_STRIP,
    action: 0,
    flattenedPoints,
    color: {
      r: 0.5,
      g: 0.0,
      b: 0.5,
      a: 1.0,
    },
    id: `occlusion_grid_polygon`,
    metadata: {
      lineWidth: 0.3,
    },
  };

  // Merge the occlusion grid polygon marker to occlusion grid markers.
  occlusion_grid_markers.push(createAresMarker(occlusion_grid_polygon_marker));

  return {
    markers: occlusion_grid_markers,
  };
};

