/* ares-expose-source-code */
/* eslint-disable @typescript-eslint/no-unnecessary-condition */
import {
  GlobalVariables,
  DEFAULT_STUDIO_NODE_PREFIX,
  CustomPlotPointConfig,
  getIntentionPlanDebug,
  getSpeedSolverDebugIndex,
  getSpeedProfile,
  getPerDiscomfortDebug,
} from "@ares-utils";
import { Input, Messages } from "@vitruvian/voyager-type";
import { isUndefined } from "lodash";

// NGA: Non gap align
// GA: gap align
type GapAlignType = "NGA" | "GA";

export const inputs = ["/planning/planning_debug"];
export const output = `${DEFAULT_STUDIO_NODE_PREFIX}planning/speed_discomfort_level_interation`;
export const config = {
  datatype: "voyager_data_msgs/CustomData",
  showOn3DPanel: false,
};

export const publisher = (
  messages: Record<string, Input<"/planning/planning_debug">>,
  globalVars: GlobalVariables,
): Messages.voyager_data_msgs__CustomData => {
  const message_p = messages[
    "/planning/planning_debug"
  ] as Input<"/planning/planning_debug">;

  const message = message_p.message;

  if (!message) {
    return {};
  }

  const behaviorReasonerDebug = message?.behaviorReasonerDebug;

  const intentionPlanDebug = getIntentionPlanDebug(
    behaviorReasonerDebug,
    globalVars,
  );

  const speedGeneratorDebug =
    intentionPlanDebug?.speedGeneratorDebug as Messages.planner__speed__pb__SpeedGeneratorDebug;

  const speedSolverDebugIndex = getSpeedSolverDebugIndex(
    behaviorReasonerDebug,
    globalVars,
  );

  const speedSolverDebug =
    speedGeneratorDebug?.speedSolverDebugs?.[speedSolverDebugIndex];

  const searchDebug =
    speedSolverDebug?.searchDebug as Messages.planner__speed__pb__SpeedSearchDebug;

  const planInitTimeInSec = speedSolverDebug?.planInitTimeInSec;

  const currentPerDiscomfortDebug = getPerDiscomfortDebug(
    searchDebug,
    globalVars?.planning_speed_discomforts_level,
  );
  const iterativeProfiles = currentPerDiscomfortDebug?.iterativeProfiles ?? [];

  return {
    discomfortsLevelIterations: iterativeProfiles ?? [],
    discomfortsLevelIterationData: getDiscomfortsLevelIterationData(
      currentPerDiscomfortDebug,
      iterativeProfiles,
      globalVars?.planning_speed_discomforts_iteration,
    ),
    intermediateSearchProfile: getIntermediateSearchProfile(
      iterativeProfiles,
      planInitTimeInSec,
      globalVars,
      currentPerDiscomfortDebug?.discomfortLevel,
    ),
  };
};

function getCurrentDiscomforts(
  discomforts: Messages.planner__speed__pb__PerDiscomfortDebug[],
  discomfortLevel: number,
) {
  for (let i = 0, len = discomforts.length; i < len; i++) {
    if (discomforts[i]?.discomfortLevel === discomfortLevel) {
      return discomforts[i];
    }
  }
  return undefined;
}

export function getCurrentLevelDiscomforts(
  searchDebug: Messages.planner__speed__pb__SpeedSearchDebug,
  level: number,
  type: GapAlignType,
): Messages.planner__speed__pb__PerDiscomfortDebug | undefined {
  if (type === "GA") {
    return getCurrentDiscomforts(searchDebug?.gapAlignDiscomforts, level);
  }
  if (type === "NGA") {
    return getCurrentDiscomforts(searchDebug?.discomforts, level);
  }
  return undefined;
}

function getDiscomfortsLevelIterationData(
  perDiscomfortDebug:
    | Messages.planner__speed__pb__PerDiscomfortDebug
    | undefined,
  iterativeProfile: Messages.planner__speed__pb__IterativeProfile[],
  iterationIndex?: string,
) {
  if (
    !iterativeProfile.length ||
    iterationIndex === "" ||
    isUndefined(iterationIndex)
  ) {
    return {};
  }

  const curIteration = iterativeProfile[Number(iterationIndex)];
  if (isUndefined(curIteration)) {
    return {};
  }

  return {
    t_brake: curIteration?.tBrake,
    t_conflict: curIteration?.tConflict,
    x_conflict: curIteration?.xConflict,
    x_resolve: curIteration?.xResolve,
    conflict_constraint_id: curIteration?.conflictConstraintId,
    conflict_constraint_ix: curIteration?.conflictConstraintIx,
    adjust_type: curIteration?.adjustType,
    adjust_for_tree_branch: curIteration?.adjustForTreeBranch,
    tree_switch_time_ix: (curIteration as any)?.treeSwitchTimeIx,
    total_iterations: iterativeProfile.length,
    slow_v_duration_in_no_block: perDiscomfortDebug?.slowVDurationInNoBlock,
  };
}

function getIntermediateSearchProfile(
  iterativeProfiles: Messages.planner__speed__pb__IterativeProfile[],
  planInitTimeInSec: number | undefined,
  globalVars: GlobalVariables,
  discomfortValue?: number,
): CustomPlotPointConfig[] {
  const iterationIndex = globalVars?.planning_speed_discomforts_iteration;
  if (isUndefined(iterationIndex) || iterationIndex === "") {
    return [];
  }

  const iterationInfoData: CustomPlotPointConfig[] = [];
  const curIterationIndex = Number(iterationIndex);
  if (curIterationIndex >= 0) {
    const curIterativeProfile = iterativeProfiles[curIterationIndex];
    const curIterativeProfileData = getSpeedProfile({
      profile: curIterativeProfile?.resultProfile,
      planInitTimeInSec,
      color: "cyan",
      showAtCurve: !!globalVars?.planning_show_at_curve,
      showVtCurve: !!globalVars?.planning_show_vt_curve,
      lineType: "solid",
      discomfortValue,
    });
    iterationInfoData.push(...curIterativeProfileData);
  }

  const preIterationIndex = curIterationIndex - 1;
  if (preIterationIndex >= 0) {
    const preIterativeProfile = iterativeProfiles[preIterationIndex];
    const preIterativeProfileData = getSpeedProfile({
      profile: preIterativeProfile?.resultProfile,
      planInitTimeInSec,
      color: "magenta",
      showAtCurve: !!globalVars?.planning_show_at_curve,
      showVtCurve: !!globalVars?.planning_show_vt_curve,
      lineType: "solid",
      discomfortValue,
    });
    iterationInfoData.push(...preIterativeProfileData);
  }
  return iterationInfoData;
}

