// This script is a tool which is employed to draw LINE_STRIP markers on the 3D panel.
// It accepts mulitple line strings formatted as:
//                    "x0 y0,x1 y1,x2 y2,...,xn yn"
// Users can enable the 'user_draw_line' option to visualize the result.
import { createRosMarker, RosMarkerTypes, RosMarker } from "./rosMarkers";

import { Messages } from "ros";

export const inputs = ["/planning/planning_debug"];
export const output = "/studio_node/user_draw_line";
export const config = {
  needFrameData: false,
};

////////////////////////
// Input line strings //
////////////////////////
const line_strs = [""];

type Point = { x: number; y: number; z: number };
type Output = Messages.visualization_msgs__MarkerArray | undefined;

// Converts linestring to point list.
function convertStringToPointArray(input: string): Point[] {
  const points: Point[] = [];
  const coordinates = input.split(",");

  coordinates.forEach((coord) => {
    const [x, y] = coord.split(" ").map(Number);
    points.push({ x, y, z: 0 });
  });
  return points;
}

const publisher = (): Output => {
  const line_markers: RosMarker[] = [];
  line_strs.forEach((line, index) => {
    const draw_line: Point[] = convertStringToPointArray(line);
    const line_marker: RosMarker = createRosMarker({
      header: {
        frame_id: "world",
        stamp: {
          sec: 0,
          nsec: 0,
        },
        seq: 0,
      },
      id: index,
      type: RosMarkerTypes.LINE_STRIP,
      points: draw_line,
      color: {
        r: 0.5,
        g: 0.5,
        b: 1,
        a: 1,
      },
      scale: {
        x: 0.3,
        y: 0.3,
        z: 0.3,
      },
    });
    line_markers.push(line_marker);
  });

  return {
    markers: line_markers,
  };
};

export default publisher;

