import { Input, Messages } from "ros";
import {
  GlobalVariables,
  ScriptConfig,
  MemoryCacheBlock,
  createDeleteCurrentTopicMarkers,
  COLOR_GREEN,
  COLOR_ORANGE,
  COLOR_GRAY,
  Color,
} from "@ares-utils";

function getOpenSpaceSearchDebug(
  open_space_debug: Messages.planner__pb__OpenSpacePlannerDebug,
): Messages.planner__pb__OpenSpaceSearchDebug | undefined {
  if (
    open_space_debug.sceneType === "PULLOUT" ||
    (open_space_debug as any)?.pullOutUnstuckTriggerDebug
      ?.openSpaceSearchDebug != null
  ) {
    return (open_space_debug as any)?.pullOutUnstuckTriggerDebug
      ?.openSpaceSearchDebug;
  }
  if (
    open_space_debug.sceneType === "PULLOVER" ||
    (open_space_debug as any)?.pullOverParkingPlannerDebug
      ?.openSpaceSearchDebug != null
  ) {
    return (open_space_debug as any)?.pullOverParkingPlannerDebug
      ?.openSpaceSearchDebug;
  }
  if (
    open_space_debug.sceneType === "REMOTE_ASSIST_BACKWARD" ||
    (open_space_debug as any)?.remoteAssistBackwardUnstuckPlannerDebug
      ?.openSpaceSearchDebug != null
  ) {
    return (open_space_debug as any)?.remoteAssistBackwardUnstuckPlannerDebug
      ?.openSpaceSearchDebug;
  }
  if (
    open_space_debug.sceneType === "REMOTE_ASSIST_BACKUP" ||
    (open_space_debug as any)?.remoteAssistBackupUnstuckPlannerDebug
      ?.openSpaceSearchDebug != null
  ) {
    return (open_space_debug as any)?.remoteAssistBackupUnstuckPlannerDebug
      ?.openSpaceSearchDebug;
  }
  if (
    open_space_debug.sceneType === "GENERAL_UNSTUCK" ||
    (open_space_debug as any)?.generalUnstuckPlannerDebug?.motionPlanDebug
      ?.openSpaceSearchDebug != null
  ) {
    return (open_space_debug as any)?.generalUnstuckPlannerDebug
      ?.motionPlanDebug?.openSpaceSearchDebug;
  }
  return undefined;
}

// These are the topics your script "subscribes" to. Ares will invoke your publisher function
// When any message is received on these topics.
// e.g. export const inputs: string[] = ["/pose", "/perception/tracked_object_list"]
export const inputs: string[] = ["/planning/planning_debug", "/pose"];

// The name of the topic published
// When data is rendered in ImagePanel, the name must start with "/image_marker/"
// When data is rendered in 3DPanel, the name must start with "/studio_node/"
export const output: `/${"studio_node" | "image_marker"}/${string}` =
  "/studio_node/planning/open_space/open_space_input";

// Configure the input and output when the code is executed
export const config: ScriptConfig = {};

// Used to overlap region upon other shapes.
const z_buffer = 0.1;

/**
 * This function is called with messages from your input topics.
 * The first argument is an event with the topic, receive time, and message.

 * @param messages According to the topic subscribed by "inputs", pass in the message corresponding to the topic.
 * @remarks Use the `Input<topicName>` helper to get the correct event type for your input topic messages.
 * @example
 * message: {
 *   "/pose": Input<"/pose">,
 *   "/perception/tracked_object_list": Input<"/perception/tracked_object_list">
 * }
 *
 * @param globalVariables Variables that can be accessed anywhere in the program, based on which the interactivity of the visual content can be configured
 * @see {@link https://cooper.didichuxing.com/knowledge/2199628491086/2199761277479} for more information
 *
 * @param blocks According to the topic subscribed by "inputs", all the messages of the corresponding topic in the bag are passed in
 *
 * @return the return format of the data is based on datatype
 */
const publisher = (
  messages: Record<string, Input<"/planning/planning_debug"> | Input<"/pose">>,
  globalVars: GlobalVariables,
): Messages.ares__VisualizationMarkerArray | undefined => {
  const message_debug = messages[
    "/planning/planning_debug"
  ] as Input<"/planning/planning_debug">;
  const message_pose = messages["/pose"] as Input<"/pose">;
  if (!message_debug || !message_pose) {
    return undefined;
  }

  const open_space_debug = getOpenSpaceSearchDebug(
    message_debug.message.behaviorReasonerDebug.decoupledManeuvers[0]
      .trajectorySelectionDebug.openSpacePlannerDebug,
  );

  if (open_space_debug === undefined || open_space_debug === null) {
    return undefined;
  }
  const pose_z = message_pose.message.z + z_buffer;

  const {
    receiveTime,
    message: {},
  } = message_debug;

  const markers: Messages.ares__VisualizationMarker[] = [
    createDeleteCurrentTopicMarkers(receiveTime),
  ];

  const motion_plan_problem_debug = open_space_debug.motionProblemDebug;

  // Draw start pose.
  const start_pose_marker: Messages.ares__VisualizationMarker = {
    header: {
      frame_id: "world",
      stamp: receiveTime,
      seq: 0,
    },
    id: "open_space_start_pose",
    type: Messages.ares__VisualizationMarkerTypes.LINE_STRIP,
    action: 0,
    points: motion_plan_problem_debug.startPoseInfoDebug.contour.points.map(
      (point) => {
        return { x: point.x, y: point.y, z: pose_z + 2.5 };
      },
    ),
    color: {
      r: 0,
      g: 1,
      b: 1,
      a: 1.0,
    },
    lineMetadata: {
      lineWidth: 0.4,
      closed: true,
    },
  };
  markers.push(start_pose_marker);

  // Draw target poses.
  motion_plan_problem_debug.targetPoseInfosDebug.forEach((target_pose, idx) => {
    const target_pose_marker: Messages.ares__VisualizationMarker = {
      header: {
        frame_id: "world",
        stamp: receiveTime,
        seq: 0,
      },
      id: "open_space_target_pose" + idx,
      type: Messages.ares__VisualizationMarkerTypes.LINE_STRIP,
      action: 0,
      points: target_pose.contour.points.map((point) => {
        return { x: point.x, y: point.y, z: pose_z + 3.0 };
      }),
      color: {
        r: 0,
        g: 0,
        b: 1,
        a: 1.0,
      },
      lineMetadata: {
        lineWidth: 0.4,
        closed: true,
      },
    };
    markers.push(target_pose_marker);
  });

  // Draw ROI.
  const roi_marker: Messages.ares__VisualizationMarker = {
    header: {
      frame_id: "world",
      stamp: receiveTime,
      seq: 0,
    },
    id: "open_space_roi",
    type: Messages.ares__VisualizationMarkerTypes.LINE_STRIP,
    action: 0,
    points: motion_plan_problem_debug.roiDebug.contour.points.map((point) => {
      return { x: point.x, y: point.y, z: pose_z };
    }),
    color: {
      r: 0.5,
      g: 0,
      b: 0,
      a: 1.0,
    },
    lineMetadata: {
      lineWidth: 0.1,
      closed: true,
    },
  };
  markers.push(roi_marker);

  // Draw contours.
  motion_plan_problem_debug.contoursDebug.forEach((contour, idx) => {
    const contour_marker: Messages.ares__VisualizationMarker = {
      header: {
        frame_id: "world",
        stamp: receiveTime,
        seq: 0,
      },
      id: "open_space_contour_" + idx,
      type: Messages.ares__VisualizationMarkerTypes.LINE_STRIP,
      action: 0,
      points: contour.polygon.points.map((point) => {
        return { x: point.x, y: point.y, z: pose_z - z_buffer - 1.0 };
      }),
      color: {
        r: 0.7,
        g: 0,
        b: 0,
        a: 1.0,
      },
      lineMetadata: {
        lineWidth: contour.requiredClearance.criticalRequiredGap * 2,
        closed: true,
      },
    };
    markers.push(contour_marker);
    const contour_clearance_marker: Messages.ares__VisualizationMarker = {
      header: {
        frame_id: "world",
        stamp: receiveTime,
        seq: 0,
      },
      id: "open_space_contour_clearance" + idx,
      type: Messages.ares__VisualizationMarkerTypes.LINE_STRIP,
      action: 0,
      points: contour.polygon.points.map((point) => {
        return { x: point.x, y: point.y, z: pose_z - z_buffer - 1.5 };
      }),
      color: {
        r: 1.0,
        g: 0,
        b: 0,
        a: 1.0,
      },
      lineMetadata: {
        lineWidth: contour.requiredClearance.comfortRequiredGap * 2,
        closed: true,
      },
    };
    markers.push(contour_clearance_marker);
  });

  // Draw boundaries.
  motion_plan_problem_debug.boundariesDebug.forEach((boundary, idx) => {
    const boundary_marker: Messages.ares__VisualizationMarker = {
      header: {
        frame_id: "world",
        stamp: receiveTime,
        seq: 0,
      },
      id: "open_space_bound_" + idx,
      type: Messages.ares__VisualizationMarkerTypes.LINE_STRIP,
      action: 0,
      points: boundary.curve.segments[0].points.map((point, idx) => {
        return { x: point.x, y: point.y, z: pose_z - z_buffer - 1.6 };
      }),
      color: {
        r: 0.7,
        g: 0.7,
        b: 0,
        a: 1.0,
      },
      lineMetadata: {
        lineWidth: boundary.requiredClearance.criticalRequiredGap * 2,
      },
    };
    markers.push(boundary_marker);
    const boundary_clearance_marker: Messages.ares__VisualizationMarker = {
      header: {
        frame_id: "world",
        stamp: receiveTime,
        seq: 0,
      },
      id: "open_space_bound_clearance_" + idx,
      type: Messages.ares__VisualizationMarkerTypes.LINE_STRIP,
      action: 0,
      points: boundary.curve.segments[0].points.map((point, idx) => {
        return { x: point.x, y: point.y, z: pose_z - z_buffer - 2.1 };
      }),
      color: {
        r: 1.0,
        g: 1.0,
        b: 0,
        a: 1.0,
      },
      lineMetadata: {
        lineWidth: boundary.requiredClearance.comfortRequiredGap * 2,
      },
    };
    markers.push(boundary_clearance_marker);
    const boundary_point_marker: Messages.ares__VisualizationMarker = {
      header: {
        frame_id: "world",
        stamp: receiveTime,
        seq: 0,
      },
      id: "open_space_bound_pt_" + idx,
      type: Messages.ares__VisualizationMarkerTypes.POINTS,
      points: boundary.curve.segments[0].points.map((point) => {
        return { x: point.x, y: point.y, z: pose_z };
      }),
      color: {
        r: 1,
        g: 1,
        b: 0,
        a: 1.0,
      },
      action: Messages.ares__VisualizationMarkerAction.ADD,
      lifetime: { sec: 0, nsec: 0 },
      scale: { x: 15, y: 0, z: 0 },
      pose: {
        position: { x: 0, y: 0, z: 0 },
        orientation: { x: 0, y: 0, z: 0, w: 1 },
      },
    };
    markers.push(boundary_point_marker);
  });

  return {
    markers,
  };
};

export default publisher;

