import { Input, Messages } from "ros";
import {
  GlobalVariables,
  ScriptConfig,
  MemoryCacheBlock,
  createDeleteCurrentTopicMarkers,
  COLOR_GREEN_YELLOW,
  COLOR_OLIVE,
  Color,
} from "@ares-utils";

function getOpenSpaceSearchDebug(
  open_space_debug: Messages.planner__pb__OpenSpacePlannerDebug,
): Messages.planner__pb__OpenSpaceSearchDebug | undefined {
  if (
    open_space_debug.sceneType === "PULLOUT" ||
    (open_space_debug as any)?.pullOutUnstuckTriggerDebug
      ?.openSpaceSearchDebug != null
  ) {
    return (open_space_debug as any)?.pullOutUnstuckTriggerDebug
      ?.openSpaceSearchDebug;
  }
  if (
    open_space_debug.sceneType === "PULLOVER" ||
    (open_space_debug as any)?.pullOverParkingPlannerDebug
      ?.openSpaceSearchDebug != null
  ) {
    return (open_space_debug as any)?.pullOverParkingPlannerDebug
      ?.openSpaceSearchDebug;
  }
  if (
    open_space_debug.sceneType === "REMOTE_ASSIST_BACKWARD" ||
    (open_space_debug as any)?.remoteAssistBackwardUnstuckPlannerDebug
      ?.openSpaceSearchDebug != null
  ) {
    return (open_space_debug as any)?.remoteAssistBackwardUnstuckPlannerDebug
      ?.openSpaceSearchDebug;
  }
  if (
    open_space_debug.sceneType === "REMOTE_ASSIST_BACKUP" ||
    (open_space_debug as any)?.remoteAssistBackupUnstuckPlannerDebug
      ?.openSpaceSearchDebug != null
  ) {
    return (open_space_debug as any)?.remoteAssistBackupUnstuckPlannerDebug
      ?.openSpaceSearchDebug;
  }
  if (
    open_space_debug.sceneType === "GENERAL_UNSTUCK" ||
    (open_space_debug as any)?.generalUnstuckPlannerDebug?.motionPlanDebug
      ?.openSpaceSearchDebug != null
  ) {
    return (open_space_debug as any)?.generalUnstuckPlannerDebug
      ?.motionPlanDebug?.openSpaceSearchDebug;
  }
  return undefined;
}

// These are the topics your script "subscribes" to. Ares will invoke your publisher function
// When any message is received on these topics.
// e.g. export const inputs: string[] = ["/pose", "/perception/tracked_object_list"]
export const inputs: string[] = ["/planning/planning_debug", "/pose"];

// The name of the topic published
// When data is rendered in ImagePanel, the name must start with "/image_marker/"
// When data is rendered in 3DPanel, the name must start with "/studio_node/"
export const output: `/${"studio_node" | "image_marker"}/${string}` =
  "/studio_node/planning/open_space/open_space_search";

// Configure the input and output when the code is executed
export const config: ScriptConfig = {};

// Used to overlap region upon other shapes.
const z_buffer = 3;

/**
 * This function is called with messages from your input topics.
 * The first argument is an event with the topic, receive time, and message.

 * @param messages According to the topic subscribed by "inputs", pass in the message corresponding to the topic.
 * @remarks Use the `Input<topicName>` helper to get the correct event type for your input topic messages.
 * @example
 * message: {
 *   "/pose": Input<"/pose">,
 *   "/perception/tracked_object_list": Input<"/perception/tracked_object_list">
 * }
 *
 * @param globalVariables Variables that can be accessed anywhere in the program, based on which the interactivity of the visual content can be configured
 * @see {@link https://cooper.didichuxing.com/knowledge/2199628491086/2199761277479} for more information
 *
 * @param blocks According to the topic subscribed by "inputs", all the messages of the corresponding topic in the bag are passed in
 *
 * @return the return format of the data is based on datatype
 */
const publisher = (
  messages: Record<string, Input<"/planning/planning_debug"> | Input<"/pose">>,
  globalVars: GlobalVariables,
): Messages.ares__VisualizationMarkerArray | undefined => {
  const message_debug = messages[
    "/planning/planning_debug"
  ] as Input<"/planning/planning_debug">;
  const message_pose = messages["/pose"] as Input<"/pose">;
  if (!message_debug || !message_pose) {
    return undefined;
  }

  const open_space_debug = getOpenSpaceSearchDebug(
    message_debug.message.behaviorReasonerDebug.decoupledManeuvers[0]
      .trajectorySelectionDebug.openSpacePlannerDebug,
  );

  if (open_space_debug === undefined || open_space_debug === null) {
    return undefined;
  }

  const pose_z = message_pose.message.z + z_buffer;

  const {
    receiveTime,
    message: {},
  } = message_debug;

  const markers: Messages.ares__VisualizationMarker[] = [
    createDeleteCurrentTopicMarkers(receiveTime),
  ];

  // Draw control space sampled nodes.
  open_space_debug?.searchDebug.nodeDebug.forEach((node, idx) => {
    const node_marker: Messages.ares__VisualizationMarker = {
      header: {
        frame_id: "world",
        stamp: receiveTime,
        seq: 0,
      },
      id: "open_space_node_" + idx,
      type: Messages.ares__VisualizationMarkerTypes.POINTS,
      action: 0,
      points: [
        { x: node.state.position.x, y: node.state.position.y, z: pose_z + 1.0 },
      ],
      color: {
        r: 1.0,
        g: 0.5,
        b: 0.0,
        a: 1.0,
      },
      pointMetadata: {
        radius: 8,
      },
    };
    markers.push(node_marker);
  });
  // Draw RSP diversities.
  const rs_paths = open_space_debug?.searchDebug?.reedsSheepPathDebug;
  if (rs_paths != undefined) {
    rs_paths.forEach((path, idx) => {
      const path_segs = partitionPath(path.pathSegment);
      // Temp: for hard code selecting only.
      const ratio = rs_paths.length > 1 ? idx / (rs_paths.length - 1) : 0.0;
      const color = {
        r: ratio,
        g: 1.0 - ratio,
        b: 0.0,
        a: 1.0,
      };
      path_segs.forEach((seg, seg_idx) => {
        const path_marker: Messages.ares__VisualizationMarker = {
          header: {
            frame_id: "world",
            stamp: receiveTime,
            seq: 0,
          },
          id: "open_space_path_" + idx + "_" + seg_idx,
          type: Messages.ares__VisualizationMarkerTypes.LINE_STRIP,
          action: 0,
          points: seg.states.map((state) => {
            return {
              x: state.position.x,
              y: state.position.y,
              z: pose_z + 1.0,
            };
          }),
          color: color,
          lineMetadata: {
            lineWidth: 0.1,
          },
        };
        markers.push(path_marker);
      });
    });
  }

  return {
    markers,
  };
};

export default publisher;

function ComputeDistance(
  pt1: Messages.math__pb__Point2d,
  pt2: Messages.math__pb__Point2d,
): number {
  return Math.sqrt(
    (pt1.x - pt2.x) * (pt1.x - pt2.x) + (pt1.y - pt2.y) * (pt1.y - pt2.y),
  );
}

function partitionPath(
  path: Messages.planner__pb__OpenSpacePathSegmentDebug,
): Messages.planner__pb__OpenSpacePathSegmentDebug[] {
  var path_outs: Messages.planner__pb__OpenSpacePathSegmentDebug[] = [];
  for (var idx = 0; idx < path.states.length; ++idx) {
    if (
      idx == 0 ||
      path.states[idx].steeringAngle != path.states[idx - 1].steeringAngle ||
      path.states[idx].isForward != path.states[idx - 1].isForward
    ) {
      path_outs.push({ states: [path.states[idx]] });
      continue;
    }
    path_outs[path_outs.length - 1].states.push(path.states[idx]);
  }
  return path_outs;
}

