export const inputs = ["/planning/planning_debug"];

export const output = `${DEFAULT_STUDIO_NODE_PREFIX}planning/isLastFrameFinished`;
export const config = {
  datatype: "voyager_data_msgs/CustomData",
  showOn3DPanel: false,
};

export const publisher = (
  messages: Record<string, Input<"/planning/planning_debug">>,
  globalVars: GlobalVariables,
): Record<string, Messages.voyager_data_msgs__CustomData> => {
  const message_p = messages[
    "/planning/planning_debug"
  ] as Input<"/planning/planning_debug">;

  const message = message_p.message;

  if (!message) {
    return {};
  }

  const pathFrameViewDebug = (
    message as unknown as rosMessages.__planner__pb__PlanningDebug
  )?.pathFrameViewDebug;
  const previousFrame = pathFrameViewDebug?.previousFrame;
  const lastFinishedFrame = pathFrameViewDebug?.lastFinishedFrame;
  const isLastFrameFinished = Number(previousFrame == lastFinishedFrame);

  return {
    isLastFrameFinished: isLastFrameFinished,
  };
};

