import { Input, Messages } from "ros";
import { Messages as StaticVoyagerType } from "@vitruvian/voyager-type";
import {
  GlobalVariables,
  DEFAULT_STUDIO_NODE_PREFIX,
  getIntentionPlanDebug,
  getSpeedSolverDebugIndex,
  getConstraints,
} from "@ares-utils";
import { isUndefined, forEach, max, min, map } from "lodash";

const kDt = 0.1;
export const inputs = ["/planning/planning_debug"];
export const output = `${DEFAULT_STUDIO_NODE_PREFIX}planning/planning_debug/position_attractor_x`;

export const publisher = (
  messages: Record<string, Input<"/planning/planning_debug">>,
  globalVariables: GlobalVariables,
): Messages.ares__CustomizationPlot => {
  const message = messages[
    "/planning/planning_debug"
  ] as Input<"/planning/planning_debug">;

  const positionAttractorXCurvesConfig: Messages.ares__CustomizationPlotData = {
    lines: [],
    borderColor: "#DB7093",
    borderWidth: 1.5,
    pointBackgroundColor: "#DB7093",
    pointRadius: 1.5,
  };

  const behaviorReasonerDebug = (message.message?.behaviorReasonerDebug ??
    {}) as unknown as StaticVoyagerType.planner__pb__BehaviorReasonersDebug;

  const intentionPlanDebug = getIntentionPlanDebug(
    behaviorReasonerDebug,
    globalVariables,
  );

  const speedGeneratorDebug =
    intentionPlanDebug?.speedGeneratorDebug as Messages.speed__pb__SpeedGeneratorDebug;

  const speedSolverDebugIndex = getSpeedSolverDebugIndex(
    behaviorReasonerDebug,
    globalVariables,
  );

  const solverDebug =
    speedGeneratorDebug?.speedSolverDebugs[speedSolverDebugIndex];

  if (!message) {
    return { data: [positionAttractorXCurvesConfig] };
  }

  if (solverDebug) {
    const positionAttractorXCurvesLine: Messages.ares__CustomizationPlotLine = {
      line: [],
    };

    solverDebug?.optDebug?.potentialDebug?.positionAttractors?.forEach(
      (positionAttractor) => {
        positionAttractorXCurvesLine.line.push({
          x: positionAttractor.stateIx * kDt,
          y: positionAttractor.x,
        });
      },
    );
    positionAttractorXCurvesConfig.lines.push(positionAttractorXCurvesLine);
  }

  return { data: [positionAttractorXCurvesConfig] };
};

