import { Input, Messages } from "ros";
import {
  euler2Quaternions,
  createDeleteCurrentTopicMarkers,
} from "@ares-utils";

type InputTopics = {
  "/planning/planning_debug": Input<"/planning/planning_debug">;
  "/studio_node/perception/tracking/tracking_output/tracked_object/normal": Input<any>;
};

type Output = Messages.ares__VisualizationMarkerArray;

export const inputs = [
  "/planning/planning_debug",
  "/studio_node/perception/tracking/tracking_output/tracked_object/normal",
];

export const output =
  "/studio_node/planning/world_model/object_filtering_debug";

export const config = {};

const COLORS_BY_REASON: Record<string, Messages.std_msgs__ColorRGBA> = {
  ignored_by_distance: { r: 1.0, g: 0.85, b: 0.2, a: 1.0 },
  off_road: { r: 1.0, g: 0.75, b: 0.15, a: 1.0 },
  ignored_by_fpobstacle: { r: 1.0, g: 0.95, b: 0.3, a: 1.0 },
  ignored_by_outside_relevant_driving_area: { r: 0.4, g: 0.2, b: 0.6, a: 1.0 }, // deep purple
};

const TEXT_COLOR: Messages.std_msgs__ColorRGBA = {
  r: 1,
  g: 0,
  b: 0,
  a: 1,
};

const publisher = (
  topics: InputTopics,
  globalVars: Record<string, any>,
): Output => {
  const planningDebug = topics["/planning/planning_debug"];
  const perceptionInput =
    topics[
      "/studio_node/perception/tracking/tracking_output/tracked_object/normal"
    ];
  const markers: Messages.ares__VisualizationMarker[] = [];

  // Extract ignore reason map and relevant driving area contours (from planning debug)
  if (planningDebug?.message?.worldModelDebug?.plannerObjectDebug) {
    const debug = planningDebug.message.worldModelDebug.plannerObjectDebug;
    const ignoreReasonMap = new Map<number, string>();

    debug.offRoadObjectDebug?.ignoredOffroadObjects?.forEach((id) => {
      ignoreReasonMap.set(id, "off_road");
    });

    debug.ignoredByFpobstacleTrackerObjects?.forEach((id) => {
      ignoreReasonMap.set(id, "ignored_by_fpobstacle");
    });

    debug.objectsOutsideRelevantDrivingArea?.irrelevantObjects?.forEach(
      (obj: { objectId: number }) => {
        if (typeof obj?.objectId === "number") {
          ignoreReasonMap.set(
            obj.objectId,
            "ignored_by_outside_relevant_driving_area",
          );
        }
      },
    );

    globalVars.ignoreReasonMap = ignoreReasonMap;

    // Extract relevant driving area contours (array of polygons)
    const contours: Array<{ points: Array<{ x: number; y: number }> }> =
      debug.objectsOutsideRelevantDrivingArea?.relevantDrivingAreaContours ??
      [];
    globalVars.relevantDrivingAreaContours = contours.map((poly) =>
      Array.isArray(poly.points)
        ? poly.points.map((pt) => ({
            x: pt.x ?? 0,
            y: pt.y ?? 0,
          }))
        : [],
    );
  }

  if (!perceptionInput) return { markers };

  const { receiveTime, message: perceptionMsg } = perceptionInput;
  const ignoreReasonMap = globalVars.ignoreReasonMap;

  // Get a Z for the contour visualization (from a "cube" marker, if any)
  const zFromCube = perceptionMsg.markers.find((m) =>
    m.id?.toLowerCase().includes("cube"),
  )?.pose?.position?.z;
  if (typeof zFromCube === "number") {
    globalVars.relevantDrivingAreaContourZ = zFromCube;
  }
  const baseZ = globalVars.relevantDrivingAreaContourZ ?? 0;

  markers.push(createDeleteCurrentTopicMarkers(receiveTime));

  perceptionMsg.markers.forEach((marker) => {
    const rawId = marker.id?.toString();
    if (!rawId?.toLowerCase().includes("cube")) return;

    const match = rawId.match(/(\d+)$/);
    const id = match ? parseInt(match[1], 10) : undefined;
    const ignoreType = id !== undefined ? ignoreReasonMap?.get(id) : undefined;
    if (!ignoreType) return;

    const markerColor = COLORS_BY_REASON[ignoreType] || {
      r: 0.6,
      g: 0.6,
      b: 0.6,
      a: 1,
    };

    const markerCopy = {
      ...marker,
      id: `${ignoreType}_${id}`,
      pose: {
        position: { ...marker.pose?.position },
        orientation: { ...marker.pose?.orientation },
      },
      scale: {
        x: (marker.scale?.x ?? 1) * 1.1,
        y: (marker.scale?.y ?? 1) * 1.1,
        z: (marker.scale?.z ?? 1) * 1.1,
      },
      color: markerColor,
    };

    markers.push(markerCopy);

    const textMarker: Messages.ares__VisualizationMarker = {
      header: { frame_id: "world", stamp: receiveTime, seq: 0 },
      type: Messages.ares__VisualizationMarkerTypes.TEXT,
      ns: "ignored_object_text",
      id: `text_${ignoreType}_${id}`,
      pose: {
        position: {
          x: marker.pose.position.x,
          y: marker.pose.position.y,
          z: marker.pose.position.z + 2.5,
        },
        orientation: { x: 0, y: 0, z: 0, w: 1 },
      },
      scale: { x: 1.5, y: 0, z: 0 },
      color: TEXT_COLOR,
      textMetadata: {
        text: `${ignoreType}: ${id}`,
        convertType: Messages.ares__TextConvertType.TEXT_3D_SPRITE,
      },
    };

    // markers.push(textMarker); // Uncomment to enable text labels
  });

  // Draw all drivable area contours (multiple polygons)
  const contourPolygons: Array<Array<{ x: number; y: number }>> =
    globalVars.relevantDrivingAreaContours;
  if (Array.isArray(contourPolygons)) {
    contourPolygons.forEach((contourPoints, idx) => {
      if (Array.isArray(contourPoints) && contourPoints.length > 1) {
        const lineStripMarker: Messages.ares__VisualizationMarker = {
          header: { frame_id: "world", stamp: receiveTime, seq: 0 },
          type: Messages.ares__VisualizationMarkerTypes.LINE_STRIP,
          ns: "drivable_area",
          id: `drivable_area_contour_${idx}`,
          pose: {
            position: { x: 0, y: 0, z: 0 },
            orientation: { x: 0, y: 0, z: 0, w: 1 },
          },
          scale: { x: 0.3, y: 0, z: 0 },
          color: { r: 0.2, g: 0.8, b: 1.0, a: 1.0 },
          points: contourPoints.map((pt) => ({ x: pt.x, y: pt.y, z: baseZ })),
        };

        // Close the loop if needed
        const first = contourPoints[0];
        const last = contourPoints[contourPoints.length - 1];
        if (first.x !== last.x || first.y !== last.y) {
          lineStripMarker.points.push({ x: first.x, y: first.y, z: baseZ });
        }

        markers.push(lineStripMarker);
      }
    });
  }

  return { markers };
};

export default publisher;

