        debug.offRoadObjectDebug?.ignoredOffroadObjects?.forEach((id) => {
            ignoreReasonMap.set(id, "off_road");
        });
        debug.ignoredByFpobstacleTrackerObjects?.forEach((id) => {
            ignoreReasonMap.set(id, "ignored_by_fpobstacle");
        });
