        const contours = debug.objectsOutsideRelevantDrivingArea?.relevantDrivingAreaContours ??
            [];
        globalVars.relevantDrivingAreaContours = contours.map((poly) => Array.isArray(poly.points)
            ? poly.points.map((pt) => ({
                x: pt.x ?? 0,
                y: pt.y ?? 0,
            }))
            : []);
    }
