    const ignoreReasonMap = globalVars.ignoreReasonMap;
    // Get a Z for the contour visualization (from a "cube" marker, if any)
    const zFromCube = perceptionMsg.markers.find((m) => m.id?.toLowerCase().includes("cube"))?.pose?.position?.z;
    if (typeof zFromCube === "number") {
        globalVars.relevantDrivingAreaContourZ = zFromCube;
    }
