        if (!rawId?.toLowerCase().includes("cube"))
            return;
        const match = rawId.match(/(\d+)$/);
        const id = match ? parseInt(match[1], 10) : undefined;
        const ignoreType = id !== undefined ? ignoreReasonMap?.get(id) : undefined;
        if (!ignoreType)
            return;
        const markerColor = COLORS_BY_REASON[ignoreType] || {
            r: 0.6,
            g: 0.6,
            b: 0.6,
            a: 1,
        };
        const markerCopy = {
            ...marker,
            id: `${ignoreType}_${id}`,
            pose: {
                position: { ...marker.pose?.position },
                orientation: { ...marker.pose?.orientation },
            },
            scale: {
                x: (marker.scale?.x ?? 1) * 1.1,
                y: (marker.scale?.y ?? 1) * 1.1,
                z: (marker.scale?.z ?? 1) * 1.1,
            },
            color: markerColor,
        };
