            id: `text_${ignoreType}_${id}`,
            pose: {
                position: {
                    x: marker.pose.position.x,
                    y: marker.pose.position.y,
                    z: marker.pose.position.z + 2.5,
                },
                orientation: { x: 0, y: 0, z: 0, w: 1 },
            },
            scale: { x: 1.5, y: 0, z: 0 },
            color: TEXT_COLOR,
            textMetadata: {
                text: `${ignoreType}: ${id}`,
                convertType: ros_1.Messages.ares__TextConvertType.TEXT_3D_SPRITE,
            },
