import { getZOffset, ZOffsetUnit } from "@ares-utils";
import { Input, Messages } from "@vitruvian/voyager-type";
import { isNil } from "lodash";

import type { GlobalVariables } from "@ares-utils";
import { DEFAULT_STUDIO_NODE_PREFIX } from "@ares-utils";

import { AresMarker, createDeleteAllActionMarker } from "@ares-utils";
import {
  getIntentionPlanDebug,
  deprecatedGetMarkersBySegments,
} from "@ares-utils";

export const inputs = ["/pose", "/planning/planning_debug"];
export const outputs = [
  {
    name: `${DEFAULT_STUDIO_NODE_PREFIX}planning/pull_over/probing_attraction_polyline`,
    datatype: "visualization_msgs/MarkerArray",
    alias: "pull_over_probing_attraction_polyline",
  },
];

export const publisher = (
  messages: Record<string, Input<"/planning/planning_debug"> | Input<"/pose">>,
  globalVars: GlobalVariables,
): Record<string, Messages.visualization_msgs__MarkerArray> => {
  const message = messages[
    "/planning/planning_debug"
  ] as Input<"/planning/planning_debug">;
  const message_P = messages["/pose"] as Input<"/pose">;
  if (!message || !message_P) {
    return {};
  }
  const { message: pose } = message_P;
  if (isNil(pose)) {
    return {
      [`${DEFAULT_STUDIO_NODE_PREFIX}planning/pull_over/probing_attraction_polyline`]:
        {
          markers: [createDeleteAllActionMarker(message.receiveTime)],
        },
    };
  }
  const z = pose.z;
  const {
    message: { timestamp, behaviorReasonerDebug },
  } = message;

  const intentionPlanDebug = getIntentionPlanDebug(
    behaviorReasonerDebug,
    globalVars,
  );
  if (!intentionPlanDebug) {
    return {};
  }

  const pull_over_probing_attraction_polyline =
    intentionPlanDebug?.pathPlannerDebug?.pathConstraintDebug
      ?.pullOverProbingAttractionPolyline;
  const markersArr: AresMarker[] = deprecatedGetMarkersBySegments({
    segments: pull_over_probing_attraction_polyline?.segments ?? [],
    id: "pull_over_probing_attraction_polyline",
    timestamp,
    z: z + getZOffset(ZOffsetUnit.UPPER),
    color: { r: 1, g: 0, b: 1, a: 1.0 },
    lineWidth: 0.2,
  });

  return {
    [`${DEFAULT_STUDIO_NODE_PREFIX}planning/pull_over/probing_attraction_polyline`]:
      {
        markers: [
          createDeleteAllActionMarker(message.receiveTime),
          ...markersArr,
        ],
      },
  };
};

