import { Input, Messages } from "ros";
import {
  DEFAULT_STUDIO_NODE_PREFIX,
  GlobalVariables,
  euler2Quaternions,
  createDeleteCurrentTopicMarkers,
  SELECTED_COLOR,
} from "@ares-utils";

export const inputs = ["/labeled/perception/tracked_object_list"];
export const output = `${DEFAULT_STUDIO_NODE_PREFIX}perception/tracking/tracking_output/gt_tracked_object/`;
export const config = {
  datatype: "ares/VisualizationMarkerArray",
};

const GROUND_TRUTH_COLOR = {
  a: 1,
  r: 0.094,
  g: 0.56,
  b: 1,
};

type UserGlobalVariables = GlobalVariables & {
  currentSelectedObjectId: string;
  displayTrackedObjectId: boolean;
};

const genCubeMarker = (receiveTime, trackedObj, isSelected) => {
  const marker: Messages.ares__VisualizationMarker = {
    header: {
      frame_id: "world",
      stamp: receiveTime,
      seq: 0,
    },
    type: Messages.ares__VisualizationMarkerTypes.CUBE,
    id: `labeled_track_${trackedObj.id}`,
    action: Messages.ares__VisualizationMarkerAction.ADD,
    lifetime: { sec: 0, nsec: 0 },
    edge: true,
    fill: true,
    pose: {
      position: {
        x: trackedObj.centerX,
        y: trackedObj.centerY,
        z: trackedObj.centerZ,
      },
      orientation: euler2Quaternions({
        yaw: trackedObj.heading,
        pitch: 0,
        roll: 0,
      }),
    },
    scale: {
      x: trackedObj.length,
      y: trackedObj.width,
      z: trackedObj.height == 0 ? 0.1 : trackedObj.height,
    },
    labelInInteractivePanel: `type: ${trackedObj.objectType}`,
    bubbleTextOnHover: trackedObj.id,
    hoverBubblePos: {
      x: trackedObj.centerX,
      y: trackedObj.centerY,
      z: trackedObj.centerZ,
    },
    enableInteraction: true,
    nameInSelectionMenu: "labeled_tracked_object",
    color: isSelected ? SELECTED_COLOR : GROUND_TRUTH_COLOR,
    edgeColor: GROUND_TRUTH_COLOR,
  };
  return marker;
};

const genShapeMarker = (
  receiveTime,
  pose,
  trackedObj,
  isSelected,
): Messages.ares__VisualizationMarker => {
  if (!trackedObj) {
    return;
  }

  const marker: Messages.ares__VisualizationMarker = {
    header: { frame_id: "world", seq: 0, stamp: receiveTime },
    type: Messages.ares__VisualizationMarkerTypes.SHAPE,
    ns: `${trackedObj.height}`,
    id: `labeled_track_${trackedObj.id}`,
    points: trackedObj.contour.map((point) => {
      return { ...point, z: 0 };
    }),
    pose: { position: { x: 0, y: 0, z: pose.z } },
    color: isSelected ? SELECTED_COLOR : GROUND_TRUTH_COLOR,
    fill: true,
    edge: true,
    labelInInteractivePanel: `type: ${trackedObj.objectType}`,
    bubbleTextOnHover: trackedObj.id,
    hoverBubblePos: {
      x: trackedObj.centerX,
      y: trackedObj.centerY,
      z: pose.z,
    },
    nameInSelectionMenu: "labeled_tracked_object",
    edgeColor: GROUND_TRUTH_COLOR,
    enableInteraction: true,
  };

  return marker;
};

const genTextMarker = (
  timestamp,
  pose,
  trackedObj,
): Messages.ares__VisualizationMarker => {
  if (!trackedObj) {
    return;
  }
  const textMarker: Messages.ares__VisualizationMarker = {
    header: { frame_id: "world", seq: 0, stamp: { sec: timestamp, nsec: 0 } },
    type: Messages.ares__VisualizationMarkerTypes.TEXT,
    ns: "",
    id: `id_${trackedObj.id}`,
    pose: {
      position: {
        x: trackedObj.centerX,
        y: trackedObj.centerY,
        z: pose.z,
      },
      orientation: euler2Quaternions({
        yaw: 0,
        pitch: 0,
        roll: 0,
      }),
    },
    scale: { x: 1.5, y: 0, z: 0 },
    color: { r: 1, g: 1, b: 1, a: 1 },
    textMetadata: {
      text: trackedObj.id,
      convertType: Messages.ares__TextConvertType.TEXT_3D_SPRITE,
    } as Messages.ares__VisualizationMarker["textMetadata"],
  };
  return textMarker;
};

const publisher = (
  messages: Record<string, Input<"/labeled/perception/tracked_object_list">>,
  globalVariables: UserGlobalVariables,
): Messages.ares__VisualizationMarkerArray => {
  const message = messages["/labeled/perception/tracked_object_list"];
  if (!message) {
    return {
      markers: [],
    };
  }

  const {
    receiveTime,
    message: { timestamp, pose, trackedObjects },
  } = message;

  const { currentSelectedObjectId, displayTrackedObjectId } = globalVariables;

  const markers: Messages.ares__VisualizationMarker[] = [
    createDeleteCurrentTopicMarkers(receiveTime),
  ];

  trackedObjects.forEach((obj) => {
    const currentMarkerId = `labeled_track_${obj.id}`;
    const isTrackObjSelected: boolean =
      currentMarkerId === currentSelectedObjectId;

    if (obj.contour.length) {
      markers.push(genShapeMarker(receiveTime, pose, obj, isTrackObjSelected));
    } else {
      markers.push(genCubeMarker(receiveTime, obj, isTrackObjSelected));
    }
    if (displayTrackedObjectId) {
      markers.push(genTextMarker(timestamp, pose, obj));
    }
  });
  return {
    markers,
  };
};

export default publisher;

