/* ares-expose-source-code */
import {
  GlobalVariables,
  DEFAULT_STUDIO_NODE_PREFIX,
  variableConcat,
  getIntentionPlanDebug,
  getSpeedSolverDebugIndex,
} from "@ares-utils";
import { Input, Messages } from "@vitruvian/voyager-type";
import { Messages as rosMessages } from "ros";
import { forEach, isNil, isUndefined, last, map } from "lodash";

import { filterMap } from "@foxglove/den/collection";

export interface speed__pb__cautiousAccelLimiterPerObject {
  objectId: number;
  accelLimits: rosMessages.speed__pb__SpeedLimitForArcLength[];
}

const kReferenceProfileDiscomfortTextX = 70;
const kReferenceProfileDiscomfortTextY = 60;

type speedLimitType = "min" | "max";

export const inputs = ["/planning/planning_debug"];
export const output = `${DEFAULT_STUDIO_NODE_PREFIX}planning/speed_limit`;
export const config = {
  datatype: "voyager_data_msgs/CustomData",
  showOn3DPanel: false,
};

export const publisher = (
  messages: Record<string, Input<"/planning/planning_debug">>,
  globalVars: GlobalVariables,
): Record<string, Messages.voyager_data_msgs__CustomData> => {
  const message_p = messages[
    "/planning/planning_debug"
  ] as Input<"/planning/planning_debug">;

  const message = message_p.message;

  if (!message) {
    return {};
  }

  const intentionPlanDebug = getIntentionPlanDebug(
    message.behaviorReasonerDebug,
    globalVars,
  );

  const speedGeneratorDebug =
    intentionPlanDebug?.speedGeneratorDebug as rosMessages.speed__pb__SpeedGeneratorDebug;

  const speedSolverDebugIndex = getSpeedSolverDebugIndex(
    message.behaviorReasonerDebug,
    globalVars,
  );

  const searchDebug =
    speedGeneratorDebug?.speedSolverDebugs[speedSolverDebugIndex]?.searchDebug;

  const roadLimiter = searchDebug?.speedLimiters?.roadLimiter;

  const lateralKineticSpeedLimiter =
    searchDebug?.speedLimiters?.lateralKineticLimiter;

  const totalArclengthList = getTotalArcLengthList(
    speedGeneratorDebug?.inputPath?.poses ?? [],
  );

  const maxArclength = last(totalArclengthList) ?? 0;

  return {
    // TODO: 我们不推荐将原始数据与plot数据从一个script中输出
    objectIds: getCautiousObjectIds(searchDebug?.speedLimiters),
    // Road limits(max discomfort)[solid]
    roadLimitsMaxDiscomfort: {
      pointBorderColor: "red",
      lines: getRoadLimitsDiscomfort(roadLimiter, maxArclength, "max"),
    },
    // Road limits(min discomfort)[dashed]
    roadLimitsMinDiscomfort: {
      pointBorderColor: "red",
      lines: getRoadLimitsDiscomfort(roadLimiter, maxArclength, "min"),
    },
    // Lateral kinetic limit(max discomfort)[solid]
    lateralKineticLimitMax: {
      lines: [
        {
          line: displayDiscomfortLateralKineticSpeedLimits(
            lateralKineticSpeedLimiter,
            totalArclengthList,
            "max",
          ),
        },
      ],
    },
    // Lateral kinetic limit(min discomfort)[dashed]
    lateralKineticLimitMin: {
      lines: [
        {
          line: displayDiscomfortLateralKineticSpeedLimits(
            lateralKineticSpeedLimiter,
            totalArclengthList,
            "min",
          ),
        },
      ],
    },
    // Reference profile speed
    referenceProfileSpeed: {
      lines: [
        {
          line: displayReferenceProfileSpeed(searchDebug),
        },
      ],
    },
    // Reference profile acceleration
    referenceProfileAccel: {
      lines: [
        {
          line: displayReferenceProfileAccel(searchDebug),
        },
      ],
    },
    // Cautious driving limits(max discomfort)[solid]
    cautiousDrivingLimitsMax: {
      lines: displayDiscomfortCautiousDrivingSpeedLimits(
        searchDebug,
        maxArclength,
        totalArclengthList,
        "max",
        globalVars,
      ),
    },
    // Cautious driving limits(min discomfort)[dashed]
    cautiousDrivingLimitsMin: {
      lines: displayDiscomfortCautiousDrivingSpeedLimits(
        searchDebug,
        maxArclength,
        totalArclengthList,
