function displayDefaultRoadSpeedLimit(
  roadLimiter: Messages.planner__speed__pb__RoadSpeedLimiter,
  maxArclength: number,
): Messages.ares__CustomizationPlotLine {
  return {
    line: [
      {
        x: 0,
        y: roadLimiter.defaultSpeedLimit,
      },
      {
        x: maxArclength,
        y: roadLimiter.defaultSpeedLimit,
      },
    ],
  };
}

function displayDiscomfortRoadSpeedLimits(
  roadLimiter: Messages.planner__speed__pb__RoadSpeedLimiter,
  maxArclength: number,
  type: speedLimitType,
): Messages.ares__CustomizationPlotLine[] {
  const speedLimits = roadLimiter?.speedLimitsForArclength?.speedLimits ?? [];
  return filterMap(speedLimits, (speedLimit) => {
    return {
      line: plotSpeedLimitForArclength(
        speedLimit,
        maxArclength,
        type === "max"
          ? speedLimit?.speedLimit?.maxDiscomfortV
          : speedLimit?.speedLimit?.minDiscomfortV,
      ),
    };
  });
}

function plotSpeedLimitForArclength(
  speedLimit: Messages.planner__speed__pb__SpeedLimitForArcLength,
  maxArclength: number,
  speed: number,
): Messages.ares__CustomizationPlotPoint[] {
  if (
    speedLimit.endArclengthM > 0 &&
    speedLimit.startArclengthM < maxArclength
  ) {
    return [
      {
        x: Math.max(0, speedLimit?.startArclengthM ?? 0),
        y: speed,
      },
      {
        x: Math.min(maxArclength, speedLimit?.endArclengthM ?? 0),
        y: speed,
      },
    ];
  }
  return [];
}

function plotAccelLimitForArclength(
  accelLimit: rosMessages.speed__pb__AccelLimitForArcLength,
  maxArclength: number,
  speed: number,
): Messages.ares__CustomizationPlotPoint[] {
  if (
    accelLimit.endArclengthM > 0 &&
    accelLimit.startArclengthM < maxArclength
  ) {
    return [
      {
        x: Math.max(0, accelLimit?.startArclengthM ?? 0),
        y: speed,
      },
      {
        x: Math.min(maxArclength, accelLimit?.endArclengthM ?? 0),
        y: speed,
      },
    ];
  }
  return [];
}

function displayReferenceProfileSpeed(
  searchDebug: rosMessages.speed__pb__SpeedSearchDebug | undefined,
): Messages.ares__CustomizationPlotPoint[] {
  if (!searchDebug) {
    return [];
  }
  const points: Messages.ares__CustomizationPlotPoint[] = map(
    searchDebug?.selectedReference?.profile?.states,
    (state) => ({
      x: state.x,
      y: state.v,
    }),
  );
  return points;
}

function displayReferenceProfileAccel(
  searchDebug: rosMessages.speed__pb__SpeedSearchDebug | undefined,
): Messages.ares__CustomizationPlotPoint[] {
  if (!searchDebug) {
    return [];
  }
  const points: Messages.ares__CustomizationPlotPoint[] = map(
    searchDebug?.selectedReference?.profile?.states,
    (state) => ({
      x: state.x,
      y: state.a,
    }),
  );
  return points;
}

function getTotalArcLengthList(poses: Messages.planner__pb__PathPose[]) {
  const arcLength = [0];
  for (let i = 1, len = poses.length ?? 1; i < len; i++) {
    const { xPos: preXPos, yPos: preYPos } = poses[
      i
    ] as Messages.planner__pb__PathPose;
    const { xPos: nextXPos, yPos: nextYPos } = poses[
      i - 1
    ] as Messages.planner__pb__PathPose;
    const x = preXPos - nextXPos;
    const y = preYPos - nextYPos;
    const sumlen = Math.sqrt(Math.pow(x, 2) + Math.pow(y, 2));
    arcLength.push((last(arcLength) ?? 0) + sumlen);
  }
  return arcLength;
}

function getRoadLimitsDiscomfort(
  roadLimiter: Messages.planner__speed__pb__RoadSpeedLimiter | undefined,
  maxArclength: number,
  type: speedLimitType,
): Messages.ares__CustomizationPlotLine[] {
  if (!roadLimiter) {
    return [];
  }

  const roadLimitsMaxDiscomfort: Messages.ares__CustomizationPlotLine[] = [];
  if (roadLimiter?.isDefaultSpeedLimit) {
    roadLimitsMaxDiscomfort.push(
      displayDefaultRoadSpeedLimit(roadLimiter, maxArclength),
    );
  } else {
    const maxDiscomfortRoadSpeedLimits = displayDiscomfortRoadSpeedLimits(
      roadLimiter,
      maxArclength,
      type,
    );
    if (maxDiscomfortRoadSpeedLimits !== undefined) {
      variableConcat(roadLimitsMaxDiscomfort, maxDiscomfortRoadSpeedLimits);
    }
  }
  return roadLimitsMaxDiscomfort;
}

function displayDiscomfortLateralKineticSpeedLimits(
  lateralKineticSpeedLimiter:
    | Messages.planner__speed__pb__SpeedLimitsForIndex
    | undefined,
  totalArclengthList: number[],
  type: speedLimitType,
): Messages.ares__CustomizationPlotPoint[] {
  const discomfortLateralKineticSpeedLimits = map(
    lateralKineticSpeedLimiter?.speedLimits ?? [],
    (speedLimit) => {
      const arcLength = totalArclengthList?.[speedLimit?.ix];
      return {
        x: arcLength ?? NaN,
        y:
          type === "max"
            ? speedLimit?.speedLimit?.maxDiscomfortV
            : speedLimit?.speedLimit?.minDiscomfortV,
      };
    },
  );
  return discomfortLateralKineticSpeedLimits.length
    ? discomfortLateralKineticSpeedLimits
    : [];
}

function displayDiscomfortCautiousDrivingSpeedLimits(
  searchDebug: rosMessages.speed__pb__SpeedSearchDebug | undefined,
  maxArclength: number,
  path: number[],
  type: speedLimitType,
  globalVars: GlobalVariables,
): Messages.ares__CustomizationPlotLine[] {
  if (!searchDebug) {
    return [];
  }

  const physicalBoundarySpeedLimits = getPhysicalBoundarySpeedLimits(
    searchDebug,
    path,
    type,
    globalVars,
  );

  let discomfortCautiousDrivingSpeedLimits: Messages.ares__CustomizationPlotLine[] =
    [];

  if (searchDebug?.speedLimiters?.cautiousDrivingLimiter?.speedLimits) {
    discomfortCautiousDrivingSpeedLimits =
      displayDiscomfortCautiousDrivingSpeedLimitsForOldBag(
        searchDebug,
        maxArclength,
        type,
      );
  } else {
    discomfortCautiousDrivingSpeedLimits =
      displayDiscomfortCautiousDrivingSpeedLimitsForNewBag(
        searchDebug,
        maxArclength,
        type,
        globalVars,
      );
  }

  return variableConcat(
    discomfortCautiousDrivingSpeedLimits,
    physicalBoundarySpeedLimits,
  );
}

// 兼容老bag的数据
function displayDiscomfortCautiousDrivingSpeedLimitsForOldBag(
  searchDebug: rosMessages.speed__pb__SpeedSearchDebug,
  maxArclength: number,
  type: speedLimitType,
): Messages.ares__CustomizationPlotLine[] {
  return map(
    searchDebug?.speedLimiters?.cautiousDrivingLimiter?.speedLimits ?? [],
    (speedLimit) => {
      return {
        line: plotSpeedLimitForArclength(
          speedLimit,
          maxArclength,
          type === "max"
            ? speedLimit?.speedLimit?.maxDiscomfortV
            : speedLimit?.speedLimit?.minDiscomfortV,
        ),
      };
    },
  );
}

function displayDiscomfortCautiousDrivingSpeedLimitsForNewBag(
  searchDebug: rosMessages.speed__pb__SpeedSearchDebug,
  maxArclength: number,
  type: speedLimitType,
  globalVars: GlobalVariables,
): Messages.ares__CustomizationPlotLine[] {
  if (!globalVars.planning_speed_limiter_select_object_ids) {
    return [];
  }
  return filterMap(
    searchDebug?.speedLimiters?.cautiousSpeedLimiterPerObject ?? [],
    (obj) => {
      if (
        globalVars.planning_speed_limiter_select_object_ids?.includes(
          `${obj.objectId}`,
        )
      ) {
        return {
          line: map(obj.speedLimits, (speedLimit) => {
            return plotSpeedLimitForArclength(
              speedLimit,
              maxArclength,
              type === "max"
                ? speedLimit?.speedLimit?.maxDiscomfortV
                : speedLimit?.speedLimit?.minDiscomfortV,
            );
          }).flat(),
        };
      } else {
        return;
      }
    },
  ) as Messages.ares__CustomizationPlotLine[];
}

function displayDiscomfortCautiousDrivingAccelLimits(
  searchDebug: rosMessages.speed__pb__SpeedSearchDebug | undefined,
  maxArclength: number,
  type: speedLimitType,
  globalVars: GlobalVariables,
): Messages.ares__CustomizationPlotLine[] {
  if (!searchDebug) {
    return [];
  }
  if (!globalVars.planning_speed_limiter_select_object_ids) {
    return [];
  }

  // For backward compatibility.
  const cautiousAccelLimiterPerObject = (
    searchDebug?.speedLimiters as unknown as {
      cautiousAccelLimiterPerObject?: speed__pb__cautiousAccelLimiterPerObject[];
    }
  )?.cautiousAccelLimiterPerObject;

  if (isUndefined(cautiousAccelLimiterPerObject)) {
    return [];
  }
  return filterMap(cautiousAccelLimiterPerObject, (obj) => {
    if (
      globalVars.planning_speed_limiter_select_object_ids?.includes(
        `${obj.objectId}`,
      )
    ) {
      return {
        line: map(obj.accelLimits, (accelLimit) => {
          return plotAccelLimitForArclength(
            accelLimit,
            maxArclength,
            type === "max"
              ? last(accelLimit?.accelLimit?.values)
              : accelLimit?.accelLimit?.values?.[0],
          );
        }).flat(),
      };
    } else {
      return;
    }
  }) as Messages.ares__CustomizationPlotLine[];
}

function displayDiscomfortTrajectoryGuiderSpeedLimits(
  trajectoryGuiderLimiter:
    | Messages.planner__speed__pb__SpeedLimitsForArcLength
    | undefined,
  maxArclength: number,
  type: speedLimitType,
): Messages.ares__CustomizationPlotLine[] {
  if (!trajectoryGuiderLimiter) {
    return [];
  }

  const speedLimits = trajectoryGuiderLimiter?.speedLimits ?? [];
  return filterMap(speedLimits, (speedLimit) => {
    return {
      line: plotSpeedLimitForArclength(
        speedLimit,
        maxArclength,
        type === "max"
          ? speedLimit?.speedLimit?.maxDiscomfortV
          : speedLimit?.speedLimit?.minDiscomfortV,
      ),
    };
  });
}

function displayReferenceProfileLimits(
  searchDebug: rosMessages.speed__pb__SpeedSearchDebug | undefined,
  path: number[],
): Messages.ares__CustomizationPlotLine[] {
  const qPoints = [];
  let referenceProfileLimits = (searchDebug as undefined as any)
    ?.referenceProfileLimits;
  if (referenceProfileLimits == undefined) {
    const refLimitsPerDiscomfort = (searchDebug as undefined as any)
      ?.refLimitsPerDiscomfort;
    if (refLimitsPerDiscomfort != undefined) {
      const discomfort = searchDebug?.selectedReference?.discomfortValue;
      const discomfortIndex = Math.round(discomfort / 0.25) + 1;
      referenceProfileLimits = refLimitsPerDiscomfort[discomfortIndex];
    }
  }

  for (
    let i = referenceProfileLimits?.egoRaIx ?? 0, len = path.length;
    i < len;
    i++
  ) {
    const arcLength = path[i];
    qPoints.push({
      x: arcLength ?? NaN,
      y: referenceProfileLimits?.speedLimits?.[i] ?? NaN,
    });
  }

  const lastPoint = last(qPoints);
  const textInfo = {
    x: (lastPoint?.x ?? kReferenceProfileDiscomfortTextX) - 10,
    y: kReferenceProfileDiscomfortTextY,
    label: `Reference Profile at discomfort ${referenceProfileLimits?.discomfortValue}`,
    labelColor: "white",
  };
  return [
    {
      line: qPoints,
    },
    {
      line: [textInfo],
    },
  ];
}

function getPhysicalBoundaryLabel(
  physicalBoundaryCautiousLimiter: Messages.planner__speed__pb__CautiousBoundarySpeedLimiter,
) {
  return physicalBoundaryCautiousLimiter.side === "kLeft"
    ? "Left physical boundary"
    : "Right physical boundary";
}

function getCautiousObjectIds(
  speedLimiters: rosMessages.speed__pb__SpeedLimiters | undefined,
) {
  if (isUndefined(speedLimiters)) {
    return [];
  }

  const cautiousObjectIds: { id: string }[] = [];

  forEach(
    speedLimiters.cautiousSpeedLimiterPerObject,
    (cautiousSpeedLimiterPerObject) => {
      cautiousObjectIds.push({
        id: `${cautiousSpeedLimiterPerObject?.objectId}`,
      });
    },
  );

  const cautiousAccelLimiterPerObject = (
    speedLimiters as unknown as {
      cautiousAccelLimiterPerObject?: speed__pb__cautiousAccelLimiterPerObject[];
    }
  )?.cautiousAccelLimiterPerObject;

  forEach(cautiousAccelLimiterPerObject, (cautiousAccelLimiterPerObject) => {
    cautiousObjectIds.push({
      id: `${cautiousAccelLimiterPerObject?.objectId}`,
    });
  });

  forEach(
    speedLimiters.physicalBoundaryCautiousLimiter,
    (physicalBoundaryCautiousLimiter) => {
      cautiousObjectIds.push({
        id: getPhysicalBoundaryLabel(physicalBoundaryCautiousLimiter),
      });
    },
  );

  return cautiousObjectIds;
}

function isChecked(globalVars: GlobalVariables, id: string) {
  return globalVars.planning_speed_limiter_select_object_ids!.includes(`${id}`);
}

function displayPhysicalBoundarySpeedLimits(
  speedLimits: Messages.planner__speed__pb__SpeedLimitsForIndex,
  path: number[],
  type: speedLimitType,
): Messages.ares__CustomizationPlotPoint[] {
  const speedLimitsForIndex = speedLimits?.speedLimits ?? [];
  const qPoints: Messages.ares__CustomizationPlotPoint[] = [];
  forEach(speedLimitsForIndex, (speedLimitForIx, index) => {
    // If the indexes are not adjacent to each other, then the speed limits are
    // not continuous. We need to split the speed limit plot if the speed limits
    // are not continuous.
    const preIx = speedLimitsForIndex?.[index - 1]?.ix;
    if (index > 0 && preIx !== undefined && speedLimitForIx.ix > preIx + 1) {
      qPoints.push({ x: NaN, y: NaN });
    }

    const arcLength = path?.[speedLimitForIx.ix];
    const y =
      type === "max"
        ? speedLimitForIx?.speedLimit?.maxDiscomfortV
        : speedLimitForIx?.speedLimit?.minDiscomfortV;
    if (Number.isFinite(y) && !isNil(y)) {
      qPoints.push({
        x: arcLength as number,
        y,
      });
    }
  });
  return qPoints;
}

function getPhysicalBoundarySpeedLimits(
  searchDebug: rosMessages.speed__pb__SpeedSearchDebug,
  path: number[],
  type: speedLimitType,
  globalVars: GlobalVariables,
): Messages.ares__CustomizationPlotLine[] {
  if (isUndefined(searchDebug?.speedLimiters)) {
    return [];
  }
  const physicalBoundaryCautiousLimiter =
    searchDebug?.speedLimiters?.physicalBoundaryCautiousLimiter;
  const lines: Messages.ares__CustomizationPlotLine[] = [];
  forEach(physicalBoundaryCautiousLimiter, (limiter) => {
    if (isChecked(globalVars, getPhysicalBoundaryLabel(limiter))) {
      lines.push({
        line: displayPhysicalBoundarySpeedLimits(
          limiter?.speedLimits,
          path,
          type,
        ),
      });
    }
  });
  return lines;
}

