import { Input, Messages } from "ros";
import {
  GlobalVariables,
  ScriptConfig,
  MemoryCacheBlock,
  createDeleteCurrentTopicMarkers,
  EgoStore,
  getPoseLerpeInfo,
  euler2Quaternions,
  mixValue,
} from "@ares-utils";
import { findIndex } from "lodash";

// These are the topics your script "subscribes" to. Ares will invoke your publisher function
// When any message is received on these topics.
// e.g. export const inputs: string[] = ["/pose", "/perception/tracked_object_list"]
export const inputs: string[] = ["/planning/planning_debug", "/pose"];

// The name of the topic published
// When data is rendered in ImagePanel, the name must start with "/image_marker/"
// When data is rendered in 3DPanel, the name must start with "/studio_node/"
export const output: `/${"studio_node" | "image_marker"}/${string}` =
  "/studio_node/planning/pull_over/pull_over_environment";

// Configure the input and output when the code is executed
export const config: ScriptConfig = {};

// Used to overlap region upon other shapes.
const z_buffer = 0.1;

// Draw looped contour as the LINE_LOOP seems not work.
function drawContour(
  points: Messages.voy__Point2d[],
  pose_z: number,
): Messages.ares__Vec3[] {
  const vis_points: Messages.ares__Vec3[] = [];
  if (!points || points.length == 0) {
    return [];
  }
  for (let i = 0; i < points.length; i++) {
    vis_points.push({ x: points[i].x, y: points[i].y, z: pose_z });
  }
  vis_points.push({ x: points[0].x, y: points[0].y, z: pose_z });
  return vis_points;
}

/**
 * This function is called with messages from your input topics.
 * The first argument is an event with the topic, receive time, and message.

 * @param messages According to the topic subscribed by "inputs", pass in the message corresponding to the topic.
 * @remarks Use the `Input<topicName>` helper to get the correct event type for your input topic messages.
 * @example
 * message: {
 *   "/pose": Input<"/pose">,
 *   "/perception/tracked_object_list": Input<"/perception/tracked_object_list">
 * }
 *
 * @param globalVariables Variables that can be accessed anywhere in the program, based on which the interactivity of the visual content can be configured
 * @see {@link https://cooper.didichuxing.com/knowledge/2199628491086/2199761277479} for more information
 *
 * @param blocks According to the topic subscribed by "inputs", all the messages of the corresponding topic in the bag are passed in
 *
 * @return the return format of the data is based on datatype
 */
const publisher = (
  messages: Record<string, Input<"/planning/planning_debug"> | Input<"/pose">>,
  globalVars: GlobalVariables,
): Messages.ares__VisualizationMarkerArray => {
  const message_debug = messages[
    "/planning/planning_debug"
  ] as Input<"/planning/planning_debug">;
  const message_pose = messages["/pose"] as Input<"/pose">;
  if (!message_debug || !message_pose) {
    return undefined;
  }

  const pose_z = message_pose.message.z + z_buffer;

  const {
    receiveTime,
    message: {},
  } = message_debug;

  const markers: Messages.ares__VisualizationMarker[] = [
    createDeleteCurrentTopicMarkers(receiveTime),
  ];

  const pull_over_environment_debug =
    message_debug.message.behaviorReasonerDebug.decoupledManeuvers[0]
      .pullOverInfoDebug.pullOverEnvironmentDebug;
  if (!pull_over_environment_debug) {
    return undefined;
  }

  // Draw left boundary
  var left_boundary =
    pull_over_environment_debug.pullOverEnvironmentGeomDebug.leftBoundary;

  if (left_boundary != null) {
    const left_boundary_vis: Messages.ares__VisualizationMarker = {
      header: {
        frame_id: "world",
        stamp: receiveTime,
        seq: 0,
      },
      id: "left_boundary",
      type: Messages.ares__VisualizationMarkerTypes.LINE_STRIP,
      action: 0,
      points: left_boundary.segments[0].points.map((point) => {
        return { x: point.x, y: point.y, z: pose_z };
      }),
      color: {
        r: 1,
        g: 1,
        b: 0,
        a: 1.0,
      },
      lineMetadata: {
        lineWidth: 0.25,
      },
    };
    markers.push(left_boundary_vis);
  }

  // Draw center line
  var center_line =
    pull_over_environment_debug.pullOverEnvironmentGeomDebug.nominalPath;
  if (center_line != null) {
    const center_line_vis: Messages.ares__VisualizationMarker = {
      header: {
        frame_id: "world",
        stamp: receiveTime,
        seq: 0,
      },
      id: "center_line",
      type: Messages.ares__VisualizationMarkerTypes.LINE_STRIP,
      action: 0,
      points: center_line.segments[0].points.map((point) => {
        return { x: point.x, y: point.y, z: pose_z };
      }),
      color: {
        r: 1,
        g: 0,
        b: 1,
        a: 1.0,
      },
      lineMetadata: {
        lineWidth: 0.25,
      },
    };
    markers.push(center_line_vis);
  }

  // Draw right boundary.
  var right_boundary =
    pull_over_environment_debug.pullOverEnvironmentGeomDebug.rightBoundary;

  if (right_boundary != null) {
    const right_boundary_vis: Messages.ares__VisualizationMarker = {
      header: {
        frame_id: "world",
        stamp: receiveTime,
        seq: 0,
      },
      id: "right_boundary",
      type: Messages.ares__VisualizationMarkerTypes.LINE_STRIP,
      action: 0,
      points: right_boundary.segments[0].points.map((point) => {
        return { x: point.x, y: point.y, z: pose_z };
      }),
      color: {
        r: 1,
        g: 0,
        b: 0,
        a: 1.0,
      },
      lineMetadata: {
        lineWidth: 0.25,
      },
    };
    markers.push(right_boundary_vis);
  }

  // Draw pull over scene context.
  const scene_context_debug = pull_over_environment_debug.sceneContextDebug;
  if (scene_context_debug != null) {
    // Draw stationary agents.
    const stationary_objects_debug = scene_context_debug.stationaryObjects;
    if (stationary_objects_debug != null) {
      stationary_objects_debug.forEach((object) => {
        if (object.contour === null) {
          return;
        }
        const agent_marker: Messages.ares__VisualizationMarker = {
          header: {
            frame_id: "world",
            stamp: receiveTime,
            seq: 0,
          },
          id: `agent${object.objectId}`,
          type: Messages.ares__VisualizationMarkerTypes.LINE_STRIP,
          action: 0,
          points: drawContour(object.contour.points, pose_z),
          color: {
            r: 1,
            g: 0,
            b: 0,
            a: 1.0,
          },
          lineMetadata: {
            lineWidth: 0.5,
          },
        };

        markers.push(agent_marker);
      });
    }

    // Draw construction zones.
    const construction_zones_debug = scene_context_debug.constructionZones;
    if (construction_zones_debug != null) {
      construction_zones_debug.forEach((zone) => {
        if (zone.contour === null) {
          return;
        }
        const agent_marker: Messages.ares__VisualizationMarker = {
          header: {
            frame_id: "world",
            stamp: receiveTime,
            seq: 0,
          },
          id: `agent${zone.objectId}`,
          type: Messages.ares__VisualizationMarkerTypes.LINE_STRIP,
          action: 0,
          points: drawContour(zone.contour.points, pose_z),
          color: {
            r: 1,
            g: 1,
            b: 0,
            a: 1.0,
          },
          lineMetadata: {
            lineWidth: 0.5,
          },
        };

        markers.push(agent_marker);
      });
    }

    // Draw dynamic objects.
    const dynamic_objects_debug = scene_context_debug.dynamicObjects;
    if (dynamic_objects_debug != null) {
      dynamic_objects_debug.forEach((object) => {
        if (object.contour === null) {
          return;
        }
        const agent_marker: Messages.ares__VisualizationMarker = {
          header: {
            frame_id: "world",
            stamp: receiveTime,
            seq: 0,
          },
          id: `agent${object.objectId}`,
          type: Messages.ares__VisualizationMarkerTypes.LINE_STRIP,
          action: 0,
          points: drawContour(object.contour.points, pose_z),
          color: {
            r: 0,
            g: 1,
            b: 0,
            a: 1.0,
          },
          lineMetadata: {
            lineWidth: 0.5,
          },
        };

        markers.push(agent_marker);
      });
    }
  }

  return { markers };
};

export default publisher;

