  "/studio_node/planning/path_generator/primitives/path_smoother/new_attraction_manager";

type Vec3 = { x: number; y: number; z: number };

// 基于 arclength 计算 reference 上对应的点和 direction
const GetInterpPointAndDeriv = (
  reference: Vec3[],
  arclength: number,
): [Vec3, Vec3] => {
  let accumulatedLength = 0;

  // 计算整条曲线长度
  for (let i = 1; i < reference.length; i++) {
    const currentPoint = reference[i];
    const prevPoint = reference[i - 1];
    const segmentLength = Math.sqrt(
      Math.pow(currentPoint.x - prevPoint.x, 2) +
        Math.pow(currentPoint.y - prevPoint.y, 2),
    );
    accumulatedLength += segmentLength;
  }

  // 超出总长度，返回最后一个点和方向
  if (arclength >= accumulatedLength) {
    const lastPoint = reference[reference.length - 1];
    const prev = reference[reference.length - 2];
    const dx = lastPoint.x - prev.x;
    const dy = lastPoint.y - prev.y;
    const magnitude = Math.sqrt(dx * dx + dy * dy);
    const direction =
      magnitude > 0
        ? { x: dx / magnitude, y: dy / magnitude, z: 0 }
        : { x: 0, y: 0, z: 0 };
    return [lastPoint, direction];
  }

  // 查找对应区间
  let currentLength = 0;
  for (let i = 1; i < reference.length; i++) {
    const currentPoint = reference[i];
    const prevPoint = reference[i - 1];
    const segmentLength = Math.sqrt(
      Math.pow(currentPoint.x - prevPoint.x, 2) +
        Math.pow(currentPoint.y - prevPoint.y, 2),
    );

    if (currentLength + segmentLength >= arclength) {
      const interpolationFactor = (arclength - currentLength) / segmentLength;

      const interpPoint: Vec3 = {
        x: prevPoint.x + (currentPoint.x - prevPoint.x) * interpolationFactor,
        y: prevPoint.y + (currentPoint.y - prevPoint.y) * interpolationFactor,
        z: 0,
      };

      const dx = currentPoint.x - prevPoint.x;
      const dy = currentPoint.y - prevPoint.y;
      const magnitude = Math.sqrt(dx * dx + dy * dy);
      const direction =
        magnitude > 0
          ? { x: dx / magnitude, y: dy / magnitude, z: 0 }
          : { x: 0, y: 0, z: 0 };

      return [interpPoint, direction];
    }

    currentLength += segmentLength;
  }

  const lastPoint = reference[reference.length - 1];
  const prev = reference[reference.length - 2];
  const dx = lastPoint.x - prev.x;
  const dy = lastPoint.y - prev.y;
  const magnitude = Math.sqrt(dx * dx + dy * dy);
  const direction =
    magnitude > 0
      ? { x: dx / magnitude, y: dy / magnitude, z: 0 }
      : { x: 0, y: 0, z: 0 };
  return [lastPoint, direction];
};

export const publisher = (
  messages: Record<string, Input<"/planning/planning_debug">>,
  globalVars: GlobalVariables,
): Messages.ares__VisualizationMarkerArray | undefined => {
  const message = messages[
    "/planning/planning_debug"
  ] as Input<"/planning/planning_debug">;

  if (!message) {
    return { markers: [] };
  }

  const {
    message: { behaviorReasonerDebug, pose },
    receiveTime,
  } = message;

  const markers: Messages.ares__VisualizationMarker[] = [
    createDeleteCurrentTopicMarkers(receiveTime),
  ];

  const intentionPlanDebug = getIntentionPlanDebug(
    behaviorReasonerDebug,
    globalVars,
  );
  if (!intentionPlanDebug) {
    return { markers };
  }

  const pathSmootherDebug =
    intentionPlanDebug?.pathPlannerDebug?.pathSmootherDebug;

  const attractionSegments =
    pathSmootherDebug?.decoupledPathPrimitivesDebug?.pathHeuristicPrimitive
      ?.attractions?.attractionSegments;

  if (!attractionSegments) {
    return { markers };
  }

  attractionSegments.forEach((segment: any, segIdx: number) => {
    // 取出 polyline 点 (必须补 z)
    const reference: Vec3[] =
      segment.rawAttractionPolyline?.segments?.[0]?.points?.map((p: any) => ({
        x: p.x,
        y: p.y,
        z: p.z ?? 0,
      })) || [];

    if (reference.length < 2) return;

    const ranges = segment.attractionRanges || [];

    ranges.forEach((range: any, rangeIdx: number) => {
      const arcStart = range.activeArclengthRange?.startPos || 0;
      const arcEnd = range.activeArclengthRange?.endPos || 0;
      const lateralStart = range.lateralRange?.startPos || 0; // 右偏移
      const lateralEnd = range.lateralRange?.endPos || 0; // 左偏移

      const sampleStep = 1.5; // 采样间隔
      const leftPoints: Vec3[] = [];
      const rightPoints: Vec3[] = [];

      for (let s = arcStart; s <= arcEnd; s += sampleStep) {
        const [center, dir] = GetInterpPointAndDeriv(reference, s);
        const normal = { x: -dir.y, y: dir.x };

        rightPoints.push({
          x: center.x + normal.x * lateralStart,
          y: center.y + normal.y * lateralStart,
          z: pose.z + 5,
        });

        leftPoints.push({
          x: center.x + normal.x * lateralEnd,
          y: center.y + normal.y * lateralEnd,
          z: pose.z + 5,
        });
      }
      // 手动 push 最后一个点
      {
        const [center, dir] = GetInterpPointAndDeriv(reference, arcEnd);
        const normal = { x: -dir.y, y: dir.x };

        rightPoints.push({
          x: center.x + normal.x * lateralStart,
          y: center.y + normal.y * lateralStart,
          z: pose.z + 5,
        });

        leftPoints.push({
          x: center.x + normal.x * lateralEnd,
          y: center.y + normal.y * lateralEnd,
          z: pose.z + 5,
        });
      }

      markers.push(
        {
          header: { frame_id: "world", seq: 0, stamp: receiveTime },
          type: Messages.ares__VisualizationMarkerTypes.LINE_STRIP,
          id: `attraction_right_${segIdx}_${rangeIdx}`,
          pose: { position: { x: 0, y: 0, z: 0 } },
          points: rightPoints,
          color: { r: 0.3, g: 1.0, b: 0.0, a: 1.0 },
          lineMetadata: { lineWidth: 0.2, frustumCulled: false },
        },
        {
          header: { frame_id: "world", seq: 0, stamp: receiveTime },
          type: Messages.ares__VisualizationMarkerTypes.LINE_STRIP,
          id: `attraction_left_${segIdx}_${rangeIdx}`,
          pose: { position: { x: 0, y: 0, z: 0 } },
          points: leftPoints,
          color: { r: 0.3, g: 1, b: 0, a: 1.0 },
          lineMetadata: { lineWidth: 0.2, frustumCulled: false },
        },
      );
    });
  });

  return { markers };
};

export default publisher;

