import {
  createDeleteCurrentTopicMarkers,
  COLOR_RED,
  COLOR_GREEN,
  GlobalVariables,
} from "@ares-utils";
import { Input, Messages } from "ros";

export const inputs = ["/planning/planning_debug"];
export const output =
  "/studio_node/planning/assist/waypoint_assist_extended_drawable_lane_sequence";
export const config = {
  datatype: "ares/VisualizationMarkerArray",
};

export const publisher = (
  messages: Record<string, Input<"/planning/planning_debug">>,
  globalVariables: GlobalVariables,
): Messages.ares__VisualizationMarkerArray | undefined => {
  const planningDebug = messages["/planning/planning_debug"];

  // 访问嵌套字段（注意proto的下划线命名）
  const extendedDrawableLaneSeq =
    planningDebug?.message?.behaviorReasonerDebug?.laneSequenceGenerator
      ?.waypointAssistExtendedDrawableAreaDebug?.laneSequence;

  if (!extendedDrawableLaneSeq?.length) return;

  const { receiveTime } = planningDebug;
  const markers: Messages.ares__VisualizationMarker[] = [
    createDeleteCurrentTopicMarkers(receiveTime),
  ];

  // 定义通用标记参数
  const MARKER_HEADER: Messages.std_msgs__Header = {
    frame_id: "world",
    stamp: {
      sec: receiveTime.sec || 0,
      nsec: receiveTime.nsec || 0,
    },
    seq: 0,
  };
  const zz = planningDebug.message?.pose?.z;
  extendedDrawableLaneSeq.forEach((lane, laneIdx) => {
    // 处理边框绘制
    if (lane.laneBorder) {
      // 生成边框路径
      const edgeMarker: Messages.ares__VisualizationMarker = {
        header: MARKER_HEADER,
        type: Messages.ares__VisualizationMarkerTypes.LINE_STRIP,
        ns: `drawable_lane_border_${laneIdx}`,
        id: `border_${laneIdx}`,
        scale: { x: 0.1, y: 0, z: zz }, // 线宽仅需x分量
        color: { r: 0, g: 0.7, b: 255, a: 1 }, // 绿色边框
        pose: {
          position: { x: 0, y: 0, z: zz },
          orientation: { x: 0, y: 0, z: zz, w: 1 },
        },
        points: lane.laneBorder.points.map((p) => ({
          x: p.x,
          y: p.y,
          z: zz,
        })),
      };
      markers.push(edgeMarker);
    }
  });
  return { markers };
};

