        "violatedConstraintIxsOnScrTimeMap" in candidate
          ? ((candidate as any).violatedConstraintIxsOnScrTimeMap ?? [])
          : [];
      const violatedConstraintDecisionsOnScrTimeMap =
        "violatedConstraintDecisionsOnScrTimeMap" in candidate
          ? ((candidate as any).violatedConstraintDecisionsOnScrTimeMap ?? [])
          : [];
      const violatedConstraintIxs = candidate.violatedConstraintIxs ?? [];
      const violatedConstraintDecisions =
        "violatedConstraintDecisions" in candidate
          ? ((candidate as any).violatedConstraintDecisions ?? [])
          : [];
      const earliestViolatedConflictTimeIxOnScrTimeMap =
