          "constraint ID":
            typeof earliestViolatedConflictCixOnScrTimeMap === "number" &&
            constraints
              ? constraints[earliestViolatedConflictCixOnScrTimeMap]
                  ?.uniqueConstraintId
              : earliestViolatedConflictCixOnScrTimeMap,
        },
