        "collision risk results:": candidate.collisionRiskInfos,
        "perturb types:": candidate.perturbTypes,
        "max st-severity violated constraint ID:":
          constraints[candidate?.evalResult?.cIx]?.uniqueConstraintId,
        "st-eval result:": candidate.evalResult,
      };
    },
  );

