  const perturbations =
    "agentPerturbations" in (realTimeConflictResolverDebug ?? {})
      ? (realTimeConflictResolverDebug as any).agentPerturbations?.map(
          (perturb: any) => ({
            "constraint ID:": constraints
              ? constraints[perturb.constraintIx]?.uniqueConstraintId
              : [],
            "perturb types:": perturb.perturbTypes,
            "perturb debug string": perturb.perturbDebugStr,
          }),
        )
      : "old bag: agentPerturbations field not available.";

  return {
    "Last cycle executed SCR type": conflictResolverDebug.previousResult,
    "Early return (skip calculation)":
      conflictResolverDebug.earlyReturnWithoutCalculation,
    "Candidate rejection debug string":
      "candidateRejectDebugStr" in (realTimeConflictResolverDebug ?? {})
        ? (realTimeConflictResolverDebug as any).candidateRejectDebugStr
        : "old bag: candidateRejectDebugStr field not available.",
    "Risk debug string": conflictResolverDebug.riskEvalDebugStr,
    "St-eval debug string": conflictResolverDebug.stEvalDebugStr,
    candidates,
    perturbations,
  };
};

