/* ares-expose-source-code */
import {
  DEFAULT_STUDIO_NODE_PREFIX,
  COLOR_YELLOW,
  COLOR_SILVER,
  euler2Quaternions,
  createDeleteCurrentTopicMarkers,
} from "@ares-utils";
import { Input, Messages } from "ros";

export const inputs = ["/planning/seed", "/perception/tracked_object_list"];
export const output = `${DEFAULT_STUDIO_NODE_PREFIX}planning/behavior/lane_change/selected_gap`;
export const config = {
  datatype: "ares/VisualizationMarkerArray",
  executeScriptWhenAnyMessageReceived: true,
};

const createSelectedGapMarker = (
  ns: string,
  timestamp: number,
  sequenceNumber: number,
  trackObject: Messages.voy__TrackedObject,
  id: string,
  points: Messages.ares__Vec3[],
): Messages.ares__VisualizationMarker => ({
  header: {
    frame_id: "world",
    stamp: {
      sec: timestamp,
      nsec: 0,
    },
    seq: sequenceNumber,
  },
  ns,
  id,
  action: 0,
  type: Messages.ares__VisualizationMarkerTypes.SHAPE,
  points,
  pose: {
    position: { x: 0, y: 0, z: trackObject.centerZ + trackObject.height / 2 },
    orientation: euler2Quaternions({ yaw: 0, pitch: 0, roll: 0 }),
  },
  color: COLOR_YELLOW,
  fill: true,
  edge: true,
});

const createSelectedGapMarkerForNonGapAlignInPreparation = (
  ns: string,
  timestamp: number,
  sequenceNumber: number,
  trackObject: Messages.voy__TrackedObject,
  id: string,
  points: Messages.ares__Vec3[],
): Messages.ares__VisualizationMarker => ({
  header: {
    frame_id: "world",
    stamp: {
      sec: timestamp,
      nsec: 0,
    },
    seq: sequenceNumber,
  },
  ns,
  id,
  action: 0,
  type: Messages.ares__VisualizationMarkerTypes.SHAPE,
  points,
  pose: {
    position: { x: 0, y: 0, z: trackObject.centerZ + trackObject.height / 2 },
    orientation: euler2Quaternions({ yaw: 0, pitch: 0, roll: 0 }),
  },
  color: COLOR_SILVER,
  fill: true,
  edge: true,
});

let preTrackObjectMessage: Input<"/perception/tracked_object_list"> | undefined;
let prePlanningSeedMessage: Input<"/planning/seed"> | undefined;

const getOffsetCoordinates = (
  trackObject: Messages.voy__TrackedObject,
  width: number,
  length: number,
) => {
  const { centerX, centerY, centerZ, height, boxHeading } = trackObject;
  const cosValue = Math.cos(boxHeading);
  const sinValue = Math.sin(boxHeading);

  return {
    x: centerX + (length / 2) * cosValue - (width / 2) * sinValue,
    y: centerY + (width / 2) * cosValue + (length / 2) * sinValue,
    z: centerZ + height / 2,
  };
};

export const publisher = (
  messages: Record<
    string,
    Input<"/planning/seed"> | Input<"/perception/tracked_object_list">
  >,
): Messages.ares__VisualizationMarkerArray | undefined => {
  const plannigSeedMessage = messages["/planning/seed"];
  const trackedObjectMessage = messages["/perception/tracked_object_list"];

  if (plannigSeedMessage) {
    prePlanningSeedMessage = plannigSeedMessage as Input<"/planning/seed">;
  }

  if (trackedObjectMessage) {
    preTrackObjectMessage =
      trackedObjectMessage as Input<"/perception/tracked_object_list">;
  }

  if (!prePlanningSeedMessage || !preTrackObjectMessage) {
    return;
  }

  const {
    message: { behaviorSeed, timestamp, sequenceNumber },
    receiveTime,
  } = prePlanningSeedMessage;

  const {
    message: { trackedObjects },
  } = preTrackObjectMessage;
  const markers: Messages.ares__VisualizationMarker[] = [
    createDeleteCurrentTopicMarkers(receiveTime),
  ];

  // eslint-disable-next-line @typescript-eslint/no-unnecessary-condition
  if (!behaviorSeed?.decoupledLaneFollowManeuverSeed) {
    return {
      markers,
    };
  }

  const {
    decoupledLaneFollowManeuverSeed: {
      selectedLaneChangeState,
      speedSeed,
      selectionSeed: { laneChangeSelectionSeed },
    },
  } = behaviorSeed;

  if (!speedSeed?.lcGuideSeed[0]?.isValid) {
    return {
      markers,
    };
  }

  const isInPreparation =
    selectedLaneChangeState === "LANE_CHANGE_STATE_PREPARATION";
  const gapSelectorInfo = (
    laneChangeSelectionSeed as {
      poseCollisionRisk: number;
      lcRisk: number;
      selectedLaneChangeGapInfo: Messages.planner__pb__SelectedLaneChangeGapInfo;
      gapSelectorInfo?: {
        isAligningGap?: boolean;
        isNonGapAlignWithGap: boolean;
        selectedLcGuideSeed: Messages.speed__pb__SpeedSolverLcGuideSeed;
      };
    }
  )?.gapSelectorInfo;
  const isAligningGap = gapSelectorInfo?.isAligningGap ?? true;

  const { leadObjId, tailObjId } = speedSeed.lcGuideSeed[0];

  const leadObj = trackedObjects.find((object) => object.id === leadObjId);
  if (leadObj) {
    const { width, length } = leadObj;
    const points = [
      getOffsetCoordinates(leadObj, -width, -length),
      getOffsetCoordinates(leadObj, width, -length),
      getOffsetCoordinates(leadObj, 0, -2 * length),
    ];
    if (isInPreparation && !isAligningGap) {
      markers.push(
        createSelectedGapMarkerForNonGapAlignInPreparation(
          "lead_obj",
          timestamp,
          sequenceNumber,
          leadObj,
          "planning_speed_seed_lead_obj",
          points,
        ),
      );
    } else {
      markers.push(
        createSelectedGapMarker(
          "lead_obj",
          timestamp,
          sequenceNumber,
          leadObj,
          "planning_speed_seed_lead_obj",
          points,
        ),
      );
    }
  }

  const tailObj = trackedObjects.find((object) => object.id === tailObjId);
  if (tailObj) {
    const { width, length } = tailObj;
    const points = [
      getOffsetCoordinates(tailObj, width, length),
      getOffsetCoordinates(tailObj, -width, length),
      getOffsetCoordinates(tailObj, 0, 2 * length),
    ];
    if (isInPreparation && !isAligningGap) {
      markers.push(
        createSelectedGapMarkerForNonGapAlignInPreparation(
          "tail_obj",
          timestamp,
          sequenceNumber,
          tailObj,
          "planning_speed_seed_tail_obj",
          points,
        ),
      );
    } else {
      markers.push(
        createSelectedGapMarker(
          "tail_obj",
          timestamp,
          sequenceNumber,
          tailObj,
          "planning_speed_seed_tail_obj",
          points,
        ),
      );
    }
  }

  return {
    markers,
  };
};

