import { Input, Messages } from "ros";
import { createRosMarker, RosMarkerTypes } from "./rosMarkers";
import { euler2Quaternions } from "./vectors";

export const inputs = ["/planning/planning_debug"];
export const config = {};
export const output =
  "/studio_node/planning/pull_over/lane_change_coordination/lane_change_request/latest_lane_change_plan";

export const publisher = (
  messages: Record<string, Input<"/planning/planning_debug">>,
): Messages.visualization_msgs__MarkerArray | undefined => {
  const msg = messages["/planning/planning_debug"];
  if (!msg) return undefined;

  const receiveTime = msg.receiveTime;

  const decoupledManeuvers =
    msg.message.behaviorReasonerDebug?.decoupledManeuvers;

  const deleteAllMarker = createRosMarker({
    header: { frame_id: "world", seq: 0, stamp: receiveTime },
    ns: "latest_lane_change_plan",
    id: 0,
    type: RosMarkerTypes.SPHERE,
    action: 3, // DELETEALL
    pose: {
      position: { x: 0, y: 0, z: 0 },
      orientation: euler2Quaternions({ yaw: 0, pitch: 0, roll: 0 }),
    },
    scale: { x: 0, y: 0, z: 0 },
    color: { r: 0, g: 0, b: 0, a: 0 },
  });

  if (!decoupledManeuvers?.length) {
    return { markers: [deleteAllMarker] };
  }

  const latestSegments: {
    start: { x: number; y: number };
    end: { x: number; y: number };
  }[] = [];

  decoupledManeuvers.forEach((dm) => {
    const poi = dm.pullOverInfoDebug;
    if (!poi) return;

    const external = poi.externalSignalDebug;
    const lccd = external?.lcCoordinationDebug;
    const coord = lccd?.coordination;
    const latestPlan = coord?.lcRequest?.latestLaneChangePlan;
    if (!latestPlan?.laneChangeSegments?.length) return;

    latestPlan.laneChangeSegments.forEach((seg) => {
      if (seg?.start && seg?.end) {
        latestSegments.push({
          start: { x: seg.start.x, y: seg.start.y },
          end: { x: seg.end.x, y: seg.end.y },
        });
      }
    });
  });

  if (!latestSegments.length) {
    return { markers: [deleteAllMarker] };
  }

  const markers: Messages.visualization_msgs__Marker[] = [];

  // 先清空上一帧
  markers.push(deleteAllMarker);

  // 再画这一帧
  markers.push(
    ...latestSegments.flatMap((seg, idx) => {
      const startPt = seg.start;
      const endPt = seg.end;
      const baseId = 20000 + idx * 20;

      return [
        // 起点圆点
        createRosMarker({
          header: { frame_id: "world", seq: 0, stamp: receiveTime },
          id: baseId,
          type: RosMarkerTypes.SPHERE,
          action: 0,
          pose: {
            position: { x: startPt.x, y: startPt.y, z: 5.0 },
            orientation: euler2Quaternions({ yaw: 0, pitch: 0, roll: 0 }),
          },
          color: { r: 1, g: 0, b: 0, a: 1 }, // 红色
          scale: { x: 0.8, y: 0.8, z: 0.8 },
        }),
        // 起点标签 S[idx]
        createRosMarker({
          header: { frame_id: "world", seq: 0, stamp: receiveTime },
          id: baseId + 1,
          type: RosMarkerTypes.TEXT,
          text: `S[${idx}]`,
          action: 0,
          pose: {
            position: { x: startPt.x - 2.5, y: startPt.y, z: 5.3 },
            orientation: euler2Quaternions({ yaw: 0, pitch: 0, roll: 0 }),
          },
          color: { r: 1, g: 0, b: 0, a: 1 },
          scale: { x: 0, y: 0, z: 0.5 },
        }),
        // 终点圆点
        createRosMarker({
          header: { frame_id: "world", seq: 0, stamp: receiveTime },
          id: baseId + 2,
          type: RosMarkerTypes.SPHERE,
          action: 0,
          pose: {
            position: { x: endPt.x, y: endPt.y, z: 5.0 },
            orientation: euler2Quaternions({ yaw: 0, pitch: 0, roll: 0 }),
          },
          color: { r: 1, g: 0, b: 0, a: 1 }, // 红色
          scale: { x: 0.8, y: 0.8, z: 0.8 },
        }),
        // 终点标签 E[idx]
        createRosMarker({
          header: { frame_id: "world", seq: 0, stamp: receiveTime },
          id: baseId + 3,
          type: RosMarkerTypes.TEXT,
          text: `E[${idx}]`,
          action: 0,
          pose: {
            position: { x: endPt.x + 2.5, y: endPt.y, z: 5.3 },
            orientation: euler2Quaternions({ yaw: 0, pitch: 0, roll: 0 }),
          },
          color: { r: 1, g: 0, b: 0, a: 1 },
          scale: { x: 0, y: 0, z: 0.5 },
        }),
        // 连线
        createRosMarker({
          header: { frame_id: "world", seq: 0, stamp: receiveTime },
          id: baseId + 4,
          type: RosMarkerTypes.LINE_STRIP,
          action: 0,
          points: [
            { x: startPt.x, y: startPt.y, z: 5.0 },
            { x: endPt.x, y: endPt.y, z: 5.0 },
          ],
          color: { r: 1, g: 0, b: 0, a: 1 },
          scale: { x: 0.2, y: 0, z: 0 },
        }),
      ];
    }),
  );

  return { markers };
};

export default publisher;

