// 数据源路径
// decoupledManeuver?.singleLaneSequencePlanDebug[:]?.intentionGeneratorDebug?.intentionSearcherDebug?.searchBasedDecisionResults[0]?.speedDeciderDebug?.stRolloutDecisions

import {
  DEFAULT_STUDIO_NODE_PREFIX,
  getSingleLaneSequencePlanDebug,
  getSearchBasedDecisionResultDebug,
  GlobalVariables,
} from "@ares-utils";
import { Input, Messages } from "@vitruvian/voyager-type";
import { Messages as rosMessages } from "ros";

export const inputs = ["/planning/planning_debug"];
export const config = {
  datatype: "voyager_data_msgs/CustomData",
  showOn3dPanel: false,
};
export const output = `${DEFAULT_STUDIO_NODE_PREFIX}planning/planning_debug/speed_profile`;

function GetObjectTrajectoryIDString(
  decision: Messages.planner__pb__SamplingBasedSpeedDeciderDebug__STRolloutDecision,
  index: number,
) {
  const groupId = `idx: ${index}`;

  return {
    [groupId]: getAgentPolygon(decision.agentDecisions),
  };
}

enum SpeedCostType {
  kSpeedLimitViolationCost = 0,
  kProgressCost = 1,
  kMaxJerCost = 2,
  kAccumulatedJerkCost = 3,
  kLateralAccelCost = 4,
  kObstacleCollisionCost = 5,
  kReasoningStRegionCollisionCost = 6,
  kHumanLikenessCost = 7,
}

function getAgentPolygon(agents: Messages.planner__pb__AgentDecision[]) {
  return agents.map((agent) => {
    const agentId = `obj_id:${agent.id.objectId}, traj_id:${agent.id.trajectoryId}`;

    return {
      "Object Trajectory ID": agentId,
      "Pass State": agent.passState,
      "Effective Range": `[${agent.effectiveRange.startIndex}, ${agent.effectiveRange.endIndex}]`,
    };
  });
}

function getCostMapString(
  decision: Messages.planner__pb__SamplingBasedSpeedDeciderDebug__STRolloutDecision,
  isAggressive: boolean,
) {
  const costItems = isAggressive
    ? (decision as rosMessages.planner__pb__STRolloutDecision)
        .aggressiveCostItems
    : decision.costItems;
  const str = costItems.reduce((accu, item, index) => {
    return accu + `${SpeedCostType[index]}:${item.toFixed(2)},`;
  }, "");

  return str.slice(0, -1);
}

export const publisher = (
  messages: Record<string, Input<"/planning/planning_debug">>,
  globalVars: GlobalVariables,
): Messages.voyager_data_msgs__CustomData => {
  const message = messages[
    "/planning/planning_debug"
  ] as Input<"/planning/planning_debug">;
  if (!message) {
    return {};
  }

  const {
    message: { behaviorReasonerDebug },
  } = message;
  const singleLaneSequencePlanDebug = getSingleLaneSequencePlanDebug(
    behaviorReasonerDebug,
    globalVars,
  );
  if (!singleLaneSequencePlanDebug) {
    return {};
  }

  const searchBasedDecisionResult = getSearchBasedDecisionResultDebug(
    behaviorReasonerDebug,
    globalVars,
  );

  var isAggressive: boolean;

  searchBasedDecisionResult.decisionResults.map((decisionResult) => {
    const rosDecisionResult =
      decisionResult as any as rosMessages.planner__pb__DecisionResult;
    if (
      rosDecisionResult.candidateIdentifier ==
      globalVars.planning_speed_candidateIdentifier
    ) {
      isAggressive = rosDecisionResult.isAggressive;
    }
  });

  const stRolloutDecisions =
    searchBasedDecisionResult?.speedDeciderDebug?.stRolloutDecisions ?? [];

  if (stRolloutDecisions.length === 0) {
    return {};
  }

  const resForTable = stRolloutDecisions.map((decision, index) => ({
    "Object Trajectory ID": GetObjectTrajectoryIDString(decision, index),
    "Rollout id": index,
    "Total Cost": isAggressive
      ? (
          decision as rosMessages.planner__pb__STRolloutDecision
        ).aggressiveTotalCost.toFixed(2)
      : decision.totalCost.toFixed(2),
    "Detail Cost": getCostMapString(decision, isAggressive),
  }));

  return resForTable;
};

