import { Input, Messages } from "ros";
import {
  GlobalVariables,
  getIntentionPlanDebug,
  getSpeedSolverDebugIndex,
  euler2Quaternions,
  createDeleteCurrentTopicMarkers,
  ScriptConfig,
} from "@ares-utils";

// --- Configuration ---

declare module "ros" {
  interface TopicsToMessageDefinition {
    "/studio_node/drawing/collision_risk_cubes": Messages.ares__VisualizationMarkerArray;
  }
}

export const inputs: string[] = ["/planning/planning_debug"];
export const output =
  "/studio_node/planning/speed_generator/risk_model_collision";
export const config: ScriptConfig = {};

// --- Drawing & Data Constants ---

const EGO_COLOR = {
  a: 0.75,
  r: 0,
  g: 0.62,
  b: 1,
};
const AGENT_COLOR = {
  a: 0.5,
  r: 1,
  g: 0.5,
  b: 0.5,
};
const COLLISION_POINT_COLOR = {
  a: 1.0,
  r: 1,
  g: 1,
  b: 1,
};
const EGO_DIMENSIONS = { length: 4.8, width: 2.0, height: 1.6 };

interface PlotPose {
  x: number;
  y: number;
  z: number;
  yaw: number;
  length: number;
  width: number;
  height: number;
}

/**
 * Filters candidates based on dropdown selections and extracts pose information.
 * @param candidates The list of `ConflictResolvingCandidateDebug` from the ROS message.
 * @param selectedCandidates The list of candidate type names from the global variable.
 * @param selectedPerturbs The list of perturbation type names from the global variable.
 * @param target Specifies whether to extract 'ego', 'agent', or 'collision' coordinates.
 * @returns A list of `PlotPose` objects ready for drawing.
 */
const getPlotPose = (
  candidates:
    | readonly Messages.speed__pb__ConflictResolvingCandidateDebug[]
    | undefined,
  selectedCandidates: string[] | undefined,
  selectedPerturbs: string[] | undefined,
  target: "ego" | "agent" | "collision",
): PlotPose[] => {
  const poses: PlotPose[] = [];

  if (!candidates || !selectedCandidates || !selectedPerturbs) {
    return poses;
  }

  candidates.forEach((candidate) => {
    // Check 1: Does the candidate's TYPE match any selected candidate?
    const isCandidateMatch = selectedCandidates.includes(
      candidate.candidateType,
    );

    if (isCandidateMatch) {
      // Check 2: Iterate through the perturbations to find matches and use their index.
      (candidate.perturbTypes ?? []).forEach((perturbType, index) => {
        // If the current perturbation type is one of the selected ones...
        if (selectedPerturbs.includes(perturbType)) {
          // ...then get the collision info at the SAME INDEX.
          const info = candidate.collisionRiskInfos?.[index];
          if (!info) {
            return; // Skip if there's no corresponding collision info.
          }

          if (target === "ego") {
            poses.push({
              x: info.egoPose.xPos,
              y: info.egoPose.yPos,
              z: info.egoPose.zPos ?? 0,
              yaw: info.egoPose.heading,
              length: EGO_DIMENSIONS.length,
              width: EGO_DIMENSIONS.width,
              height: EGO_DIMENSIONS.height,
            });
          } else if (target === "agent" && info.agent) {
            // For agent
            poses.push({
              x: info.agent.centerX,
              y: info.agent.centerY,
              z: info.agent.centerZ ?? info.agentPose?.zPos ?? 0,
              yaw: info.agent.heading,
              length: info.agent.length,
              width: info.agent.width,
              height: info.agent.height,
            });
          } else if (target === "collision") {
            const collisionPosition = (info as any)["collisionPosition"];
            const center = collisionPosition?.collisionCenter;
            if (center) {
              poses.push({
                x: center.x,
                y: center.y,
                z: 35, // Hardcoded height to stay visible above road level
                yaw: 0,
                length: 0.1,
                width: 0.5,
                height: 0.5,
              });
            }
          }
        }
      });
    }
  });

  return poses;
};

const publisher = (
  messages: {
    "/planning/planning_debug": Input<"/planning/planning_debug">;
  },
  globalVars: GlobalVariables,
): Messages.ares__VisualizationMarkerArray => {
  const planningDebugInput = messages["/planning/planning_debug"];
  const receiveTime = planningDebugInput?.receiveTime;

  const markers: Messages.ares__VisualizationMarker[] = [];
  if (receiveTime) {
    markers.push(createDeleteCurrentTopicMarkers(receiveTime));
  }

  const selectedCandidates = globalVars.PerturbCandidate as
    | string[]
    | undefined;
  const selectedPerturbs = globalVars.SelectedPerturbType as
    | string[]
    | undefined;

  if (
    !receiveTime ||
    !selectedCandidates ||
    selectedCandidates.length === 0 ||
    !selectedPerturbs ||
    selectedPerturbs.length === 0
  ) {
    return { markers };
  }

  const message = planningDebugInput.message;
  if (!message) {
    return { markers };
  }

  // --- Data Extraction ---
  const behaviorReasonerDebug = message?.behaviorReasonerDebug;
  const speedSolverDebugIndex = getSpeedSolverDebugIndex(
    behaviorReasonerDebug,
    globalVars,
  );
  const intentionPlanDebug = getIntentionPlanDebug(
    behaviorReasonerDebug,
    globalVars,
  );
  const realTimeSpeedGeneratorDebug =
    intentionPlanDebug?.speedGeneratorDebug as Messages.speed__pb__SpeedGeneratorDebug;
  const realTimeConflictResolverDebug =
    realTimeSpeedGeneratorDebug?.speedSolverDebugs?.[speedSolverDebugIndex]
      ?.searchDebug?.conflictResolverDebug;
  const candidates = realTimeConflictResolverDebug?.candidates;

  // --- Get Data for Plotting ---
  const ego_coordinates = getPlotPose(
    candidates,
    selectedCandidates,
    selectedPerturbs,
    "ego",
  );
  const agent_coordinates = getPlotPose(
    candidates,
    selectedCandidates,
    selectedPerturbs,
    "agent",
  );
  const collision_coordinates = getPlotPose(
    candidates,
    selectedCandidates,
    selectedPerturbs,
    "collision",
  );

  // Use the Z from the first agent found, or default to 0 if no agents were found.
  // This is a hack for finding the proper ego pose.z as ego's z pose is not properly
  // populated in the conflict resolver debug and is set to be always 0.
  const agentZForEgo =
    agent_coordinates.length > 0 ? agent_coordinates[0].z : 0;

  // --- Drawing Logic ---
  collision_coordinates.forEach((pose, index) => {
    markers.push({
      header: { frame_id: "world", stamp: receiveTime, seq: 0 },
      type: Messages.ares__VisualizationMarkerTypes.POINT,
      id: `collision_point_${index}`,
      action: Messages.ares__VisualizationMarkerAction.ADD,
      lifetime: { sec: 0, nsec: 0 },
      edge: false,
      fill: true,
      pose: {
        position: { x: pose.x, y: pose.y, z: pose.z },
        orientation: euler2Quaternions({ yaw: pose.yaw, pitch: 0, roll: 0 }),
      },
      scale: { x: pose.length, y: pose.width, z: pose.height },
      color: COLLISION_POINT_COLOR,
      edgeColor: { a: 1.0, r: 1, g: 0.93, b: 0.16 },
    });
  });

  ego_coordinates.forEach((pose, index) => {
    markers.push({
      header: { frame_id: "world", stamp: receiveTime, seq: 0 },
      type: Messages.ares__VisualizationMarkerTypes.CUBE,
      id: `ego_risk_pose_${index}`,
      action: Messages.ares__VisualizationMarkerAction.ADD,
      lifetime: { sec: 0, nsec: 0 },
      edge: true,
      fill: true,
      pose: {
        position: { x: pose.x, y: pose.y, z: agentZForEgo },
        orientation: euler2Quaternions({ yaw: pose.yaw, pitch: 0, roll: 0 }),
      },
      scale: { x: pose.length, y: pose.width, z: pose.height },
      color: EGO_COLOR,
    });
  });

  agent_coordinates.forEach((pose, index) => {
    markers.push({
      header: { frame_id: "world", stamp: receiveTime, seq: 0 },
      type: Messages.ares__VisualizationMarkerTypes.CUBE,
      id: `agent_risk_pose_${index}`,
      action: Messages.ares__VisualizationMarkerAction.ADD,
      lifetime: { sec: 0, nsec: 0 },
      edge: true,
      fill: true,
      pose: {
        position: { x: pose.x, y: pose.y, z: pose.z },
        orientation: euler2Quaternions({ yaw: pose.yaw, pitch: 0, roll: 0 }),
      },
      scale: { x: pose.length, y: pose.width, z: pose.height },
      color: AGENT_COLOR,
    });
  });

  return { markers };
};

export default publisher;

