import { Input, Messages } from "ros";
import {
  getIntentionPlanDebug,
  GlobalVariables,
  createDeleteCurrentTopicMarkers,
} from "@ares-utils";

export const inputs = ["/planning/planning_debug"];
export const output: `/${"studio_node" | "image_marker"}/${string}` =
  "/studio_node/planning/pull_over/env_hb_lateral_occupied_range";

type Point = { x: number; y: number };

// 计算ray end point
const computeRayEndpoint = (
  reference: Point[],
  arclength: number,
  clearanceDistance: number,
  poseZ: number,
) => {
  const [rayStart, direction] = GetInterpPointAndDeriv(reference, arclength);
  const normalDir = { x: -direction.y, y: direction.x }; // Perpendicular direction

  return {
    x: rayStart.x + normalDir.x * clearanceDistance,
    y: rayStart.y + normalDir.y * clearanceDistance,
    z: poseZ + 1, // Adjust Z for visualization
  };
};

// 基于arclength 计算 reference上对应的点和direction
const GetInterpPointAndDeriv = (
  reference: Point[],
  arclength: number,
): [Point, Point] => {
  let accumulatedLength = 0;
  let prevPoint = reference[0];

  // Calculate the total path length (arc length)
  for (let i = 1; i < reference.length; i++) {
    const currentPoint = reference[i];
    const segmentLength = Math.sqrt(
      Math.pow(currentPoint.x - prevPoint.x, 2) +
        Math.pow(currentPoint.y - prevPoint.y, 2),
    );
    accumulatedLength += segmentLength;
    prevPoint = currentPoint;
  }

  // 超出 total length, 则return last point and direction
  if (arclength >= accumulatedLength) {
    const lastPoint = reference[reference.length - 1];
    const dx =
      reference[reference.length - 1].x - reference[reference.length - 2].x;
    const dy =
      reference[reference.length - 1].y - reference[reference.length - 2].y;

    const magnitude = Math.sqrt(dx * dx + dy * dy);
    const direction =
      magnitude > 0 ? { x: dx / magnitude, y: dy / magnitude } : { x: 0, y: 0 };

    return [lastPoint, direction];
  }

  // Find the segment corresponding to the given arclength
  let currentLength = 0;
  for (let i = 1; i < reference.length; i++) {
    const currentPoint = reference[i];
    const segmentLength = Math.sqrt(
      Math.pow(currentPoint.x - reference[i - 1].x, 2) +
        Math.pow(currentPoint.y - reference[i - 1].y, 2),
    );

    if (currentLength + segmentLength >= arclength) {
      const interpolationFactor = (arclength - currentLength) / segmentLength;
      const prevPoint = reference[i - 1];

      const interpPoint: Point = {
        x: prevPoint.x + (currentPoint.x - prevPoint.x) * interpolationFactor,
        y: prevPoint.y + (currentPoint.y - prevPoint.y) * interpolationFactor,
      };

      const dx = currentPoint.x - prevPoint.x;
      const dy = currentPoint.y - prevPoint.y;
      const magnitude = Math.sqrt(dx * dx + dy * dy);
      const direction =
        magnitude > 0
          ? { x: dx / magnitude, y: dy / magnitude }
          : { x: 0, y: 0 };

      return [interpPoint, direction];
    }

    currentLength += segmentLength;
  }

  // If no suitable segment found, return last point and direction
  const lastPoint = reference[reference.length - 1];
  const dx =
    reference[reference.length - 1].x - reference[reference.length - 2].x;
  const dy =
    reference[reference.length - 1].y - reference[reference.length - 2].y;

  const magnitude = Math.sqrt(dx * dx + dy * dy);
  const direction =
    magnitude > 0 ? { x: dx / magnitude, y: dy / magnitude } : { x: 0, y: 0 };
  return [lastPoint, direction];
};

export const publisher = (
  messages: Record<string, Input<"/planning/planning_debug">>,
  globalVars: GlobalVariables,
): Messages.ares__VisualizationMarkerArray | undefined => {
  const message = messages[
    "/planning/planning_debug"
  ] as Input<"/planning/planning_debug">;
  if (!message) {
    return {
      markers: [],
    };
  }

  const {
    message: { behaviorReasonerDebug, pose },
    receiveTime,
  } = message;
  const markers: Messages.ares__VisualizationMarker[] = [
    createDeleteCurrentTopicMarkers(receiveTime),
  ];
  const intentionPlanDebug = getIntentionPlanDebug(
    behaviorReasonerDebug,
    globalVars,
  );
  if (!intentionPlanDebug) {
    return {
      markers,
    };
  }

  const pull_over_environment_debug =
    message.message.behaviorReasonerDebug.decoupledManeuvers[0]
      .pullOverInfoDebug.pullOverEnvironmentDebug;

  const reference =
    pull_over_environment_debug.pullOverEnvironmentGeomDebug.nominalPath
      .segments[0].points;

  const lateralOccupiedRangeData =
    pull_over_environment_debug.sceneContextDebug.lateralOccupiedRangeDebug;
  const resolution = lateralOccupiedRangeData.resolution;
  const arclengthRange = lateralOccupiedRangeData.effectiveReferenceRange;
  const occupiedRanges = lateralOccupiedRangeData.occupiedRangesList;

  if (occupiedRanges.length == 0 || !pose) {
    return {
      markers,
    };
  }

  const generateOccupiedRangeEndpoints = (occupiedRanges: any[]) => {
    return occupiedRanges.flatMap((occupiedRangesObj, index) => {
      const ranges = occupiedRangesObj.occupiedRanges;
      return ranges.flatMap((range: { startPos: number; endPos: number }) => {
        // 对于每个range，生成start pos和end pos两个点
        const endpoints: { x: number; y: number; z: number }[] = [];
        // 计算start pos对应的点
        endpoints.push(
          computeRayEndpoint(
            reference,
            index * resolution + arclengthRange.startPos,
            range.startPos,
            pose.z,
          ) as { x: number; y: number; z: number },
        );

        // 计算end pos对应的点
        endpoints.push(
          computeRayEndpoint(
            reference,
            index * resolution + arclengthRange.startPos,
            range.endPos,
            pose.z,
          ) as { x: number; y: number; z: number },
        );

        return endpoints;
      });
    });
  };

  // Create raycasting markers for right clearance data
  const lateralOccupiedRangesMarkers: Messages.ares__VisualizationMarker = {
    header: {
      frame_id: "world",
      seq: 0,
      stamp: receiveTime,
    },
    type: Messages.ares__VisualizationMarkerTypes.POINTS,
    id: `lateral_occupied_ranges`,
    pose: {
      position: { x: 0, y: 0, z: 0 },
    },
    points: [...generateOccupiedRangeEndpoints(occupiedRanges)],
    color: {
      r: 0.0, // Red
      g: 1.0, // Green
      b: 0.0, // Blue
      a: 1, // 透明
    },
    pointMetadata: {
      radius: 3,
    },
    scale: { x: 1.0, y: 0, z: 0 },
  };

  markers.push(lateralOccupiedRangesMarkers);

  return {
    markers,
  };
};

export default publisher;

