import { Input, Messages } from "ros";
import { createDeleteCurrentTopicMarkers } from "@ares-utils";
export const inputs = ["/planning/seed"];
export const output = "/studio_node/planning/assist/trimmed_reference_points";
export const config = {};

const COLOR_1 = {
  a: 1.5,
  r: 1,
  g: 0.62,
  b: 0,
};

const publisher = (messages: {
  "/planning/seed": Input<"/planning/seed">;
}): Messages.ares__VisualizationMarkerArray => {
  const message = messages["/planning/seed"];
  if (!message) {
    return {
      markers: [],
    };
  }

  const message_p = message.message;
  if (!message_p) {
    return;
  }

  const { receiveTime } = message;

  const markers: Messages.ares__VisualizationMarker[] = [
    createDeleteCurrentTopicMarkers(receiveTime),
  ];
  const points: Messages.ares__Vec3[] = [];
  const zz = 1;
  message_p?.behaviorSeed?.decoupledLaneFollowManeuverSeed?.selectedWaypointAssistSeed?.referencePoints?.forEach(
    (point) => {
      points.push({
        x: point.x,
        y: point.y,
        z: zz,
      });
    },
  );
  markers.push({
    header: {
      frame_id: "world",
      stamp: receiveTime,
      seq: 0,
    },
    type: Messages.ares__VisualizationMarkerTypes.POINTS,
    id: `trimmed_reference_points`,
    action: Messages.ares__VisualizationMarkerAction.ADD,
    lifetime: { sec: 0, nsec: 0 },
    scale: { x: 15, y: 0, z: 0 },
    color: COLOR_1,
    pose: {
      position: { x: 0, y: 0, z: 0 },
      orientation: { x: 0, y: 0, z: 0, w: 1 },
    },
    points,
  });

  return {
    markers,
  };
};

export default publisher;

