                tunnel_idx = decisionDebug.searchBasedDecisionResultIndex;
            }
        }
    }
    if (tunnel_idx === -1) {
        return { markers };
    }
    explored_tunnels[tunnel_idx].passages.forEach((tunnel_passage, t_idx) => {
        const p_idx = tunnel_passage?.passageIndex;
        const start_point = tunnel_passage?.startPoint;
        const end_point = tunnel_passage?.endPoint;
        const passage = all_slices[t_idx].passages[p_idx];
        const tunnelMarker = {
            header: {
                stamp: planningDebug.receiveTime,
                frame_id: "world",
                seq: 0,
            },
            id: `explored_result-select-${t_idx}-${p_idx}`,
            type: ros_1.Messages.ares__VisualizationMarkerTypes.LINE_STRIP,
            points: [
                { ...passage?.startPoint, z: markerZ },
                { ...passage?.endPoint, z: markerZ },
            ],
            color: SELECT_TUNNEL_COLOR,
            scale: {
                x: 0.1,
                y: 0.1,
                z: 0.1,
            },
        };
