import { Input, Messages } from "ros";
import {
  GlobalVariables,
  ScriptConfig,
  MemoryCacheBlock,
  createDeleteCurrentTopicMarkers,
  getSingleLaneSequencePlanDebug,
  getSearchBasedDecisionResultDebug,
} from "@ares-utils";

// These are the topics your script "subscribes" to. Ares will invoke your publisher function
// When any message is received on these topics.
// e.g. export const inputs: string[] = ["/pose", "/perception/tracked_object_list"]
export const inputs: string[] = ["/planning/planning_debug"];

// The name of the topic published
// When data is rendered in ImagePanel, the name must start with "/image_marker/"
// When data is rendered in 3DPanel, the name must start with "/studio_node/"
export const output: `/${"studio_node" | "image_marker"}/${string}` =
  "/studio_node/planning/behavior/agent_intention/tunnel_explore_geo";

// Configure the input and output when the code is executed
export const config: ScriptConfig = {};

/**
 * This function is called with messages from your input topics.
 * The first argument is an event with the topic, receive time, and message.

 * @param messages According to the topic subscribed by "inputs", pass in the message corresponding to the topic.
 * @remarks Use the `Input<topicName>` helper to get the correct event type for your input topic messages.
 * @example
 * message: {
 *   "/pose": Input<"/pose">,
 *   "/perception/tracked_object_list": Input<"/perception/tracked_object_list">
 * }
 *
 * @param globalVariables Variables that can be accessed anywhere in the program, based on which the interactivity of the visual content can be configured
 * @see {@link https://cooper.didichuxing.com/knowledge/2199628491086/2199761277479} for more information
 *
 * @param blocks According to the topic subscribed by "inputs", all the messages of the corresponding topic in the bag are passed in
 *
 * @return the return format of the data is based on datatype
 */

export const publisher = (
  messages: {
    "/planning/planning_debug": Input<"/planning/planning_debug">;
  },
  globalVars: GlobalVariables,
  blocks: readonly (MemoryCacheBlock | undefined)[],
): Messages.ares__VisualizationMarkerArray => {
  const planningDebug = messages["/planning/planning_debug"];
  const markers: Messages.ares__VisualizationMarker[] = [
    createDeleteCurrentTopicMarkers(planningDebug.receiveTime),
  ];
  if (!planningDebug) {
    return { markers };
  }

  const pose = planningDebug.message.pose;
  const singleLaneSequencePlanDebug = getSingleLaneSequencePlanDebug(
    planningDebug.message.behaviorReasonerDebug as any,
    globalVars,
  );

  if (!singleLaneSequencePlanDebug) {
    return { markers };
  }

  const searchBasedDecision = getSearchBasedDecisionResultDebug(
    planningDebug.message.behaviorReasonerDebug as any,
    globalVars,
  );
  if (!searchBasedDecision) {
    return { markers };
  }

  const tunnelExplorerDebug =
    singleLaneSequencePlanDebug?.intentionGeneratorDebug?.intentionSearcherDebug
      ?.drivableTunnelExplorerDebug;
  if (!tunnelExplorerDebug) {
    return { markers };
  }

  const GEOMETRY_COLOR = { r: 0.8, g: 0.3, b: 0.5, a: 1.0 };

  let markerZ = pose.z + 5.1;
  let reachableZ = pose.z + 5.2;
  const all_slices = tunnelExplorerDebug.slices ?? [];
  const explored_tunnels = tunnelExplorerDebug.exploredTunnels ?? [];
  if (!explored_tunnels) {
    return { markers };
  }

  // Find the tunnel index corresponding to the selected trajectory.
  let tunnel_idx = -1;
  if (searchBasedDecision.decisionResults.length !== 0) {
    for (const decisionDebug of searchBasedDecision.decisionResults) {
      if (
        decisionDebug.candidateIdentifier ===
        globalVars.planning_speed_candidateIdentifier
      ) {
        tunnel_idx = decisionDebug.searchBasedDecisionResultIndex;
      }
    }
  }
  if (tunnel_idx === -1) {
    return { markers };
  }

  // Add reference path and boundary.
  const referencePathMarker: Messages.ares__VisualizationMarker = {
    header: {
      stamp: planningDebug.receiveTime,
      frame_id: "world",
      seq: 0,
    },
    id: `explored_result-reference_path`,
    type: Messages.ares__VisualizationMarkerTypes.LINE_STRIP,
    points: explored_tunnels[tunnel_idx].estimatedPath.segments[0].points.map(
      (point) => ({ ...point, z: markerZ }),
    ),
    color: GEOMETRY_COLOR,
    scale: {
      x: 0.1,
      y: 0.1,
      z: 0.1,
    },
  };
  markers.push(referencePathMarker);
  const leftCorridorMarker: Messages.ares__VisualizationMarker = {
    header: {
      stamp: planningDebug.receiveTime,
      frame_id: "world",
      seq: 0,
    },
    id: `explored_result-left-corridor`,
    type: Messages.ares__VisualizationMarkerTypes.LINE_STRIP,
    points: explored_tunnels[tunnel_idx].leftBoundary.segments[0].points.map(
      (point) => ({ ...point, z: markerZ }),
    ),
    color: GEOMETRY_COLOR,
    scale: {
      x: 0.1,
      y: 0.1,
      z: 0.1,
    },
  };
  markers.push(leftCorridorMarker);
  const rightCorridorMarker: Messages.ares__VisualizationMarker = {
    header: {
      stamp: planningDebug.receiveTime,
      frame_id: "world",
      seq: 0,
    },
    id: `explored_result-right-corridor`,
    type: Messages.ares__VisualizationMarkerTypes.LINE_STRIP,
    points: explored_tunnels[tunnel_idx].rightBoundary.segments[0].points.map(
      (point) => ({ ...point, z: markerZ }),
    ),
    color: GEOMETRY_COLOR,
    scale: {
      x: 0.1,
      y: 0.1,
      z: 0.1,
    },
  };
  markers.push(rightCorridorMarker);

  return {
    markers: markers,
  };
};

