import {
  getAccurateDecoupledManeuver,
  GlobalVariables,
  DEFAULT_STUDIO_NODE_PREFIX,
} from "@ares-utils";
import { Input, Messages } from "@vitruvian/voyager-type";
import { Messages as rosMessages } from "ros";
import { map, last, isUndefined, forEach } from "lodash";

export const inputs = ["/planning/planning_debug"];

export const output = `${DEFAULT_STUDIO_NODE_PREFIX}planning/longitudinal_comfort_policy_debug`;
export const config = {
  datatype: "voyager_data_msgs/CustomData",
  showOn3DPanel: false,
};

function getPlanningDebugInfo(
  laneSequenceInfoAndIntentPlanDebug: Messages.planner__pb__LaneSequenceInfoAndIntentPlanDebug[],
  label?: string,
) {
  const labelLen = label?.length;
  for (const singleLaneSequencePlanDebug of laneSequenceInfoAndIntentPlanDebug) {
    for (const singleIntentionPlanDebug of singleLaneSequencePlanDebug.singleIntentionPlanDebug) {
      if (
        labelLen &&
        singleIntentionPlanDebug.candidateIdentifier.substring(
          0,
          labelLen - 1,
        ) === label.substring(0, labelLen - 1)
      ) {
        return {
          singleIntentionPlanDebug,
          singleLaneSequencePlanDebug,
        };
      }
    }
  }
  return undefined;
}

export const publisher = (
  messages: Record<string, Input<"/planning/planning_debug">>,
  globalVars: GlobalVariables,
): Record<string, Messages.voyager_data_msgs__CustomData> => {
  const planningEnableOverlapV2 =
    globalVars.planning_enable_overlap_v2 ?? false;
  const message_p = messages[
    "/planning/planning_debug"
  ] as Input<"/planning/planning_debug">;

  const message = message_p.message;

  if (!message) {
    return {};
  }

  const behaviorReasonerDebug = message?.behaviorReasonerDebug;
  const decoupledManeuver = getAccurateDecoupledManeuver(behaviorReasonerDebug);
  const selectedTrajectoryDebug =
    decoupledManeuver?.trajectorySelectionDebug.trajectoryMetaDebugs.find(
      (meta) => meta.isSelected,
    );
  if (selectedTrajectoryDebug == undefined) {
    return {};
  }

  const speedReasoningPolicies = (selectedTrajectoryDebug as unknown as any)
    ?.speedReasoningPolicies;
  const longitudinalComfortPolicy =
    speedReasoningPolicies?.longitudinalComfortPolicy;

  const totalCost = longitudinalComfortPolicy?.totalCost;
  const jerkCost = longitudinalComfortPolicy?.jerkCost;
  const accelDiffCost = longitudinalComfortPolicy?.accelDiffCost;
  const accelCost = longitudinalComfortPolicy?.accelCost;

  return {
    totalCost: totalCost,
    jerkCost: jerkCost,
    accelDiffCost: accelDiffCost,
    accelCost: accelCost,
    originTotalCost: jerkCost + accelCost + accelDiffCost,
  };
};

