import {
  GlobalVariables,
  DEFAULT_STUDIO_NODE_PREFIX,
  getIntentionPlanDebug,
  getSpeedSolverDebugIndex,
} from "@ares-utils";
import { Input, Messages } from "ros";
import { Messages as StaticVoyagerType } from "@vitruvian/voyager-type";
import { isUndefined, forEach, max, min, map } from "lodash";

const kDt = 0.1;

export const output = `${DEFAULT_STUDIO_NODE_PREFIX}planning/planning_debug/speed_profile_vs_plot`;
export const config = {
  datatype: "voyager_data_msgs/CustomData",
  showOn3DPanel: false,
};

export const inputs = ["/planning/planning_debug"];

export const publisher = (
  messages: Record<string, Input<"/planning/planning_debug">>,
  globalVariables: GlobalVariables,
): Messages.voyager_data_msgs__CustomData => {
  const message = messages[
    "/planning/planning_debug"
  ] as Input<"/planning/planning_debug">;

  const behaviorReasonerDebug = (message.message?.behaviorReasonerDebug ??
    {}) as unknown as StaticVoyagerType.planner__pb__BehaviorReasonersDebug;

  const intentionPlanDebug = getIntentionPlanDebug(
    behaviorReasonerDebug,
    globalVariables,
  );

  const speedGeneratorDebug =
    intentionPlanDebug?.speedGeneratorDebug as Messages.speed__pb__SpeedGeneratorDebug;

  const speedSolverDebugIndex = getSpeedSolverDebugIndex(
    behaviorReasonerDebug,
    globalVariables,
  );

  const speedSolverDebug = speedGeneratorDebug?.speedSolverDebugs?.[
    speedSolverDebugIndex
  ] as Messages.speed__pb__SpeedSolverDebug;

  if (!speedSolverDebug) {
    return {};
  }

  const planInitTimeInSec = speedSolverDebug?.planInitTimeInSec;
  const optDebug =
    speedSolverDebug?.optDebug as Messages.speed__pb__SpeedOptDebug;
  const warmStartDebug = optDebug?.warmStartDebug;

  const iteration = optDebug?.allIterProfiles;
  const iterationForBranch = (optDebug as undefined as any)
    ?.allIterProfilesForBranch;
  const finalIterIndex = isUndefined(iteration) ? 0 : iteration.length - 1;
  let iterationIndex = !globalVariables.planning_speed_profile_iteration_index
    ? 0
    : (globalVariables.planning_speed_profile_iteration_index ?? 0);

  const potentialDebug = optDebug?.potentialDebug;

  if (iterationIndex > finalIterIndex) {
    iterationIndex = finalIterIndex;
  }

  const finalIterOptProfileStates = isUndefined(iteration)
    ? []
    : (iteration?.[finalIterIndex]?.states ?? []);

  const finalIterOptProfileStatesForBranch = isUndefined(iterationForBranch)
    ? []
    : (iterationForBranch?.[finalIterIndex]?.states ?? []);

  return {
    finalOptProfile: getProfileVsByStates({
      states: finalIterOptProfileStates,
      planInitTimeInSec,
      globalVariables,
      color: "#00FF00",
    }),
  };
};

type ProfileDataByStates = {
  states: Messages.speed__pb__State[];
  planInitTimeInSec: number;
  color: string;
  globalVariables: GlobalVariables;
};

function getProfileVsByStates({
  states,
  planInitTimeInSec,
  color,
  globalVariables,
}: ProfileDataByStates): Messages.ares__CustomizationPlotData {
  const vsData: Messages.ares__CustomizationPlotData[] = [];

  const vsPlotDataConfig: Messages.ares__CustomizationPlotData = {
    lines: [],
    borderColor: color,
    pointBackgroundColor: color,
    borderWidth: 1.5,
  };
  const vsLine: Messages.ares__CustomizationPlotLine = {
    line: states.map((state) => {
      return {
        x: state.x,
        y: state.v,
      };
    }),
  };
  vsPlotDataConfig.lines.push(vsLine);

  return vsPlotDataConfig;
}

