// Function to calculate the PDF of a normal distribution
function normalPDF(x, mean, stdDev) {
    const exponent = -Math.pow(x - mean, 2) / (2 * Math.pow(stdDev, 2));
    return (1 / (stdDev * Math.sqrt(2 * Math.PI))) * Math.exp(exponent);
}
// Helper function to process stochastic process data and generate plot segments
function processStochasticProcess(stochasticProcess, yRange, maxY, timeOffset, valueOffset, prefix, outputDict) {
    const timeSamples = stochasticProcess?.timeSamples;
    const mixtureModels = stochasticProcess?.gaussianMixtureModel_1dSamples?.gaussianMixtureModel_1ds;
    if (mixtureModels === undefined || timeSamples === undefined) {
        return;
    }
    const pdfMatrix = [];
    const muMatrix = [];
    const stdMatrix = [];
    timeSamples.forEach((_, index) => {
        const mixtureModel = mixtureModels[index];
        let pdf = [];
        muMatrix.push(0);
        stdMatrix.push(0);
        yRange.forEach((_) => {
            pdf.push(0);
        });
        if (mixtureModel &&
            mixtureModel.weights &&
            mixtureModel.gaussianModel_1ds) {
            mixtureModel.weights.forEach((weight, modelIndex) => {
                const model = mixtureModel.gaussianModel_1ds[modelIndex];
                if (model) {
                    const currentPdf = yRange.map((value) => weight *
                        normalPDF(value, model.mu - valueOffset, model.std + (model.std == 0 ? 1e-2 : 0)));
                    muMatrix[index] = muMatrix[index] + weight * (model.mu - valueOffset);
                    stdMatrix[index] =
                        stdMatrix[index] + weight * weight * model.std * model.std;
                    pdf = pdf.map((item, pdfIndex) => {
                        return item + currentPdf[pdfIndex];
                    });
                }
            });
        }
        stdMatrix[index] = Math.sqrt(stdMatrix[index]);
        pdfMatrix.push(pdf);
    });
    const maxLogPdf = Math.log10(Math.max(...pdfMatrix.flat()));
    const minLogPdf = Math.log10(Math.min(...pdfMatrix.flat()) + 1e-10);
    const displaySegments = [];
    cividisColormap.forEach((_) => {
        displaySegments.push([]);
    });
    timeSamples.forEach((time, index) => {
        pdfMatrix[index].forEach((pdfValue, yIndex) => {
            if (yIndex + 1 == yRange.length) {
                return;
            }
            const segment = [];
            const startY = yRange[yIndex];
            const endY = yRange[yIndex + 1];
            if (startY > maxY) {
                return;
            }
            const logPdf = Math.log10(pdfValue);
            const ratio = (logPdf - minLogPdf) / (maxLogPdf - minLogPdf);
            const colorIndex = Math.min(Math.max(0, Math.floor(cividisColormap.length * ratio)), cividisColormap.length - 1);
            segment.push({ x: time - timeOffset, y: startY });
            segment.push({ x: time - timeOffset, y: endY });
            displaySegments[colorIndex].push(segment);
        });
    });
    const muSegments = [];
    muMatrix.forEach((mu, index) => {
        const time = timeSamples[index];
        if (mu > maxY) {
            return;
        }
        muSegments.push({ x: time - timeOffset, y: mu });
    });
    const stdSegments = [];
    stdMatrix.forEach((std, index) => {
        const time = timeSamples[index];
        const mu = muMatrix[index];
        const startY = mu - std;
        const endY = mu + std;
        if (startY > maxY) {
            return;
        }
        const segment = [];
        segment.push({ x: time - timeOffset, y: startY });
        segment.push({ x: time - timeOffset, y: endY });
        stdSegments.push(segment);
    });
    // Add color segments to output dict with prefix
    displaySegments.forEach((segments, colorIndex) => {
        if (colorIndex == 0) {
            return;
        }
        outputDict[`${prefix}color_${colorIndex}`] = {
            borderColor: cividisColormap[colorIndex],
            pointBackgroundColor: cividisColormap[colorIndex],
            data: segments,
        };
    });
    // Add mu and std segments with prefix
    outputDict[`${prefix}mu_segments`] = {
        borderColor: "orange",
        pointBackgroundColor: "orange",
        data: [muSegments],
    };
    outputDict[`${prefix}std_segments`] = {
        borderColor: "orange",
        pointBackgroundColor: "orange",
        data: stdSegments,
    };
}
const publisher = (message, globalVars, blocks) => {
    if (!globalVars.is_show_human_likeness_plot) {
        return {};
    }
    // Generate an array of y values for arc-length (0 to 160 meters)
    const yArcLength = [];
    for (let i = 0; i <= 160; i += 0.8) {
        yArcLength.push(i);
    }
    // Generate an array of y values for lateral offset (-10 to 10 meters)
    const yLateral = [];
    for (let i = -10; i <= 10; i += 0.1) {
        yLateral.push(i);
    }
    const message_p = message["/planning/planning_debug"];
    const internal_message = message_p.message;
    if (!internal_message) {
        return {};
    }
    const { behaviorReasonerDebug } = internal_message;
    const singleLaneSequencePlanDebug = (0, _ares_utils_1.getSingleLaneSequencePlanDebug)(behaviorReasonerDebug, globalVars);
    const intentionGeneratorDebug = singleLaneSequencePlanDebug?.intentionGeneratorDebug;
    const intentionSearcherDebug = intentionGeneratorDebug?.intentionSearcherDebug;
    const stRolloutHumanLikenessHelperDebug = intentionSearcherDebug?.stRolloutHumanLikenessHelperDebug;
    // Get arc-length stochastic process (original)
    const stochasticProcess_1d = stRolloutHumanLikenessHelperDebug?.stochasticProcess_1d;
    // Get lateral stochastic process (new)
    const stochasticProcessLateral = stRolloutHumanLikenessHelperDebug?.stochasticProcessLateral;
    const upperBound = intentionGeneratorDebug?.speedUpperBound;
    let maxArcLengthY = 0.0;
    upperBound.states.forEach((state) => {
        maxArcLengthY = Math.max(maxArcLengthY, state.x);
    });
    const outputDict = {};
    // Process arc-length data (original, no prefix)
    if (stochasticProcess_1d) {
        const timeSamples = stochasticProcess_1d.timeSamples;
        const mixtureModels = stochasticProcess_1d.gaussianMixtureModel_1dSamples
            ?.gaussianMixtureModel_1ds;
        if (timeSamples && mixtureModels && mixtureModels.length > 0) {
            const arclengthOffset = mixtureModels[0].gaussianModel_1ds[0]?.mu || 0;
            const timeOffset = timeSamples[0] || 0;
            processStochasticProcess(stochasticProcess_1d, yArcLength, maxArcLengthY, timeOffset, arclengthOffset, "", // no prefix for original arc-length data
            outputDict);
        }
    }
    // Process lateral data (new, with "lateral_" prefix)
    if (stochasticProcessLateral) {
        const lateralTimeSamples = stochasticProcessLateral.timeSamples;
        const lateralMixtureModels = stochasticProcessLateral.gaussianMixtureModel_1dSamples
            ?.gaussianMixtureModel_1ds;
        if (lateralTimeSamples &&
            lateralMixtureModels &&
            lateralMixtureModels.length > 0) {
            const lateralOffset = 0;
            const lateralTimeOffset = lateralTimeSamples[0] || 0;
            // For lateral, we use a fixed max range since lateral offset is typically small
            const maxLateralY = 10.0;
            processStochasticProcess(stochasticProcessLateral, yLateral, maxLateralY, lateralTimeOffset, lateralOffset, "lateral_", // prefix for lateral data
            outputDict);
        }
    }
    return outputDict;
};
exports.default = publisher;

