import {
  GlobalVariables,
  DEFAULT_STUDIO_NODE_PREFIX,
  variableConcat,
  getIntentionPlanDebug,
  getSpeedSolverDebugIndex,
} from "@ares-utils";
import { Input, Messages } from "@vitruvian/voyager-type";
import { Messages as rosMessages } from "ros";
import { forEach, isNil, isUndefined, last, map } from "lodash";

import { filterMap } from "@foxglove/den/collection";

export const inputs = ["/planning/planning_debug"];
export const output = `${DEFAULT_STUDIO_NODE_PREFIX}planning/reference_profile_trajectory`;
export const config = {
  datatype: "voyager_data_msgs/CustomData",
  showOn3DPanel: false,
};

export const publisher = (
  messages: Record<string, Input<"/planning/planning_debug">>,
  globalVars: GlobalVariables,
): Record<string, Messages.voyager_data_msgs__CustomData> => {
  const message_p = messages[
    "/planning/planning_debug"
  ] as Input<"/planning/planning_debug">;

  const message = message_p.message;

  if (!message) {
    return {};
  }

  const intentionPlanDebug = getIntentionPlanDebug(
    message.behaviorReasonerDebug,
    globalVars,
  );

  const speedGeneratorDebug =
    intentionPlanDebug?.speedGeneratorDebug as rosMessages.speed__pb__SpeedGeneratorDebug;

  const speedSolverDebugIndex = getSpeedSolverDebugIndex(
    message.behaviorReasonerDebug,
    globalVars,
  );

  const searchDebug =
    speedGeneratorDebug?.speedSolverDebugs[speedSolverDebugIndex]?.searchDebug;

  return {
    // Reference profile Jerk.
    jerk: displayJerk(searchDebug),
    // Reference profile steering rate.
    steeringRate: displaySteeringRate(searchDebug),
    // Reference profile lateral acceleration.
    absLatAccel: displayAbsLatAccel(searchDebug),
    // Reference profile juke.
    absJuke: displayAbsJuke(searchDebug),
  };
};

function displaySteeringRate(
  searchDebug: rosMessages.speed__pb__SpeedSearchDebug | undefined,
): Messages.ares__IndexPlot {
  if (!searchDebug) {
    return { data: [] };
  }
  const poses = searchDebug?.selectedReference?.poses;
  return {
    data: poses.map((pose) => pose.steeringRate),
  };
}

function displayAbsLatAccel(
  searchDebug: rosMessages.speed__pb__SpeedSearchDebug | undefined,
): Messages.ares__IndexPlot {
  if (!searchDebug) {
    return { data: [] };
  }
  const poses = searchDebug?.selectedReference?.poses;
  return {
    data: poses.map((pose) => pose.absLatAccel),
  };
}

function displayAbsJuke(
  searchDebug: rosMessages.speed__pb__SpeedSearchDebug | undefined,
): Messages.ares__IndexPlot {
  if (!searchDebug) {
    return { data: [] };
  }
  const poses = searchDebug?.selectedReference?.poses;
  return {
    data: poses.map((pose) => pose.absJuke),
  };
}

function displayJerk(
  searchDebug: rosMessages.speed__pb__SpeedSearchDebug | undefined,
): Messages.ares__IndexPlot {
  if (!searchDebug) {
    return { data: [] };
  }
  const poses = searchDebug?.selectedReference?.poses;
  return {
    data: poses.map((pose) => pose.jerk),
  };
}

