import { Input, Messages } from "ros";
import {
  GlobalVariables,
  ScriptConfig,
  MemoryCacheBlock,
  createDeleteCurrentTopicMarkers,
} from "@ares-utils";

export const inputs: string[] = ["/planning/planning_debug"];

export const output: `/${"studio_node" | "image_marker"}/${string}` =
  "/studio_node/mdp_trajectory";

export const config: ScriptConfig = {};

const pointColor = {
  a: 0.75,
  r: 1,
  g: 1,
  b: 1,
};

const lineColor = {
  a: 0.75,
  r: 1,
  g: 1,
  b: 1,
};

const publisher = (
  message: {
    "/planning/trajectory": Input<"/planning/trajectory">;
  },
  globalVars: GlobalVariables,
  blocks: readonly (MemoryCacheBlock | undefined)[],
): Messages.ares__VisualizationMarkerArray => {
  const messageP = message[
    "/planning/planning_debug"
  ] as Input<"/planning/planning_debug">;

  const planningDebugMessage = messageP.message;

  const markers: Messages.ares__VisualizationMarker[] = [
    createDeleteCurrentTopicMarkers(messageP.receiveTime),
  ];

  if (!planningDebugMessage) {
    return { markers };
  }

  const trajectoryPositions: Messages.ares__Vec3[] = [];
  const trajectoryColors: Messages.ares__Color[] = [];

  const mdpTrajectory = (planningDebugMessage as undefined as any)
    ?.worldModelDebug?.mdpGuiderDebug?.outputDebug?.mdpTrajectory;

  for (let index = 0; index < mdpTrajectory.length; index++) {
    const point = mdpTrajectory[index];
    trajectoryColors.push(lineColor);
    trajectoryPositions.push({
      x: point.x,
      y: point.y,
      z: 21.0,
    });
  }

  const marker: Messages.ares__VisualizationMarker = {
    header: {
      frame_id: "world",
      seq: 0,
      stamp: messageP.receiveTime,
    },
    id: "mdpTraj",
    type: Messages.ares__VisualizationMarkerTypes.LINE_STRIP,
    points: trajectoryPositions,
    colors: trajectoryColors,
    lineMetadata: {
      lineWidth: 0.5,
      frustumCulled: false,
    },
  };

  const markerPoints: Messages.ares__VisualizationMarker = {
    header: {
      frame_id: "world",
      stamp: messageP.receiveTime,
      seq: 0,
    },
    type: Messages.ares__VisualizationMarkerTypes.POINTS,
    id: `mdpTrajPoints`,
    action: Messages.ares__VisualizationMarkerAction.ADD,
    lifetime: { sec: 0, nsec: 0 },
    scale: { x: 15, y: 0, z: 0 },
    color: pointColor,
    pose: {
      position: { x: 0, y: 0, z: 0 },
      orientation: { x: 0, y: 0, z: 0, w: 1 },
    },
    points: trajectoryPositions,
  };

  markers.push(marker);
  markers.push(markerPoints);

  return {
    markers,
  };
};

export default publisher;

