// This example shows how to use nodePlayground to simply perform data processing for use by Plot of customization mode.
// @see {@link https://cooper.didichuxing.com/knowledge/share/page/SociEekW3kHl} for more information
import { Input, Messages } from "ros";
import {
  GlobalVariables,
  MemoryCacheBlock,
  scatterColorMap,
  Color,
  scatterColorMapLen,
  DEFAULT_STUDIO_NODE_PREFIX,
} from "@ares-utils";

function GetCost(
  cost: Messages.planner__pb__JumpInPrimitiveCostingInfoDebug,
  cost_type: keyof Messages.planner__pb__JumpInCurveCostingInfoDebug,
): any {
  var cost_val = cost?.[cost_type];

  return Math.max(Math.min(cost_val, 100.0), 0.0);
}

function ShouldShowSpecificJumpInCurve(
  sample_decision: Messages.planner__pb__JumpInCurveSampleDecisionDebug,
  show_specific_jump_in_start_lon_pos: number | undefined,
  show_specific_jump_in_end_lon_pos: number | undefined,
  show_specific_jump_in_end_lat_pos: number | undefined,
): boolean {
  if (
    show_specific_jump_in_start_lon_pos != undefined &&
    show_specific_jump_in_start_lon_pos != sample_decision.startPtLonPos
  ) {
    return false;
  }
  if (
    show_specific_jump_in_end_lon_pos != undefined &&
    show_specific_jump_in_end_lon_pos != sample_decision.endPtLonPos
  ) {
    return false;
  }
  if (
    show_specific_jump_in_end_lat_pos != undefined &&
    show_specific_jump_in_end_lat_pos != sample_decision.endPtLatPos
  ) {
    return false;
  }
  return true;
}

const lastColor = scatterColorMap[scatterColorMapLen - 1] as Color;
const firstColor = scatterColorMap[0] as Color;
const getColor = (
  value: number,
  maxCost: number,
  minCost: number,
  alpha: number,
) => {
  if (maxCost === minCost) {
    return `rgb(${firstColor.r},${firstColor.g},${firstColor.b}, ${alpha})`;
  }
  const colorVal =
    ((value - minCost) / (maxCost - minCost)) * scatterColorMapLen;
  if (colorVal >= scatterColorMapLen) {
    return `rgb(${lastColor.r},${lastColor.g},${lastColor.b}, ${alpha})`;
  }
  if (colorVal === 0) {
    return `rgb(${firstColor.r},${firstColor.g},${firstColor.b}, ${alpha} )`;
  }
  if (Math.ceil(colorVal) === scatterColorMapLen) {
    return `rgb(${lastColor.r},${lastColor.g},${lastColor.b}, ${alpha} )`;
  }

  const preColor = scatterColorMap?.[Math.floor(colorVal)] as Color;
  const nextColor = scatterColorMap?.[Math.ceil(colorVal)] as Color;
  const r = (preColor.r + nextColor?.r) / 2;
  const g = (preColor.g + nextColor?.g) / 2;
  const b = (preColor.b + nextColor?.b) / 2;
  return `rgb(${r}, ${g}, ${b}, ${alpha})`;
};

function FindKinematicJumpInGuidance(
  dest_debugs: Messages.planner__pb__DestinationMetaDebug[],
  dest_key: string | undefined,
): Messages.planner__pb__KinematicJumpInGuidanceDebug | undefined {
  const selected_dest = dest_debugs[1];
  // const selected_dest = dest_debugs.find((dest_debug) => {
  //   return dest_debug.key == dest_key;
  // });
  return selected_dest ? selected_dest.jumpInGuidanceDebug : undefined;
}

// These are the topics your script "subscribes" to. Ares will invoke your publisher function
// when any message is received on these topics.
// e.g. export const inputs: string[] = ["/pose", "/perception/tracked_object_list"]
export const inputs: string[] = ["/planning/planning_debug"];
// The name of the topic published
// When data is rendered in ImagePanel, the name must start with "/image_marker/"
