import {
  GlobalVariables,
  DEFAULT_STUDIO_NODE_PREFIX,
  getSingleLaneSequencePlanDebug,
  getSearchBasedDecisionResultDebug,
  getIntentionDecisionResultDebugFromSearchBasedDebug,
} from "@ares-utils";
import { Input, Messages } from "ros";
import { filter, forEach, isNil } from "lodash";

const max = Infinity;
const min = -Infinity;
const kErrorTolerance = 1e-6;

// Basic settings for ForbiddenRegionInfoDebug widget.
const kSTSegmentSampledPointNumber = 10;

type PolyCubicSegment = {
  a: number;
  b: number;
  c: number;
  d: number;
  xMin: number;
  xMax: number;
};

type STRollout = {
  stCurve: PolyCubicSegment[];
};

type SpatialRange = {
  time: number;
  start: number;
  end: number;
};

type STRegion = {
  startingSpatialRange: SpatialRange;
  endingSpatialRange: SpatialRange;
};

type Id = {
  objectId: number;
  trajectoryId: number;
};

export const inputs = ["/planning/planning_debug"];
export const output = `${DEFAULT_STUDIO_NODE_PREFIX}planning/sampling_based_speed_decider`;
export const config = {
  datatype: "voyager_data_msgs/CustomData",
  showOn3DPanel: false,
};

export const publisher = (
  messages: Record<string, Input<"/planning/planning_debug">>,
  globalVars: GlobalVariables,
): Record<string, Messages.ares__CustomizationPlotData> => {
  const message_p = messages[
    "/planning/planning_debug"
  ] as Input<"/planning/planning_debug">;
  const message = message_p.message;

  if (!message) {
    return {};
  }

  const { behaviorReasonerDebug } = message;
  const singleLaneSequencePlanDebug = getSingleLaneSequencePlanDebug(
    behaviorReasonerDebug as any,
    globalVars,
  );
  if (!singleLaneSequencePlanDebug) {
    return {};
  }

  const searchBasedDecisionResult = getSearchBasedDecisionResultDebug(
    behaviorReasonerDebug as any,
    globalVars,
  );

  if (!searchBasedDecisionResult) {
    return {};
  }

  const intentionGeneratorDebug =
    singleLaneSequencePlanDebug?.intentionGeneratorDebug;
  const speedDeciderDebug = searchBasedDecisionResult?.speedDeciderDebug;

  if (!speedDeciderDebug) {
    return {};
  }

  const finalDecisionResult =
    getIntentionDecisionResultDebugFromSearchBasedDebug(
      searchBasedDecisionResult,
      globalVars,
    );

  const selectedRolloutIndex =
    finalDecisionResult != null
      ? finalDecisionResult.rolloutIndex
      : speedDeciderDebug.minCostStRolloutDecisionIdx;

  const {
    stRollouts = [],
    speedSearchStRollouts = [],
    minCostStRollouts = [],
    highlightStRollouts = [],
    softStRegion = [],
    hardStRegion = [],
    softLtRegion = [],
    hardLtRegion = [],
    reasoningStRegion = [],
  } = displaySTRolloutDecisionPlot(
    speedDeciderDebug as any,
    globalVars,
    selectedRolloutIndex,
  );

  const speedBound = getSpeedBound(
    intentionGeneratorDebug?.speedLowerBound as SpeedPbProfile,
    intentionGeneratorDebug?.speedUpperBound as SpeedPbProfile,
  );

  return {
    stRollouts: {
      borderColor: "green",
      pointBackgroundColor: "green",
      lines: stRollouts,
    },
    speedSearchStRollouts: {
      borderColor: "yellow",
      pointBackgroundColor: "yellow",
      lines: speedSearchStRollouts,
    },
    minCostStRollouts: {
      borderColor: "red",
      pointBackgroundColor: "red",
      lines: minCostStRollouts,
    },
    highlightStRollouts: {
      borderColor: "cyan",
      pointBackgroundColor: "cyan",
      lines: highlightStRollouts,
    },
    softStRegion: {
      borderColor: "white",
      borderDash: [3, 3],
      pointBackgroundColor: "white",
      lines: softStRegion,
    },
    hardStRegion: {
      borderColor: "#C19A6B",
      borderDash: [3, 3],
      pointBackgroundColor: "#C19A6B",
      lines: hardStRegion,
    },
    softLtRegion: {
      borderColor: "white",
      borderDash: [3, 3],
      pointBackgroundColor: "white",
      lines: softLtRegion,
    },
    hardLtRegion: {
      borderColor: "#C19A6B",
      borderDash: [3, 3],
      pointBackgroundColor: "#C19A6B",
      lines: hardLtRegion,
    },
    reasoningStRegion: {
      borderColor: "gray",
      pointBackgroundColor: "gray",
      lines: reasoningStRegion,
    },
    speedBound: {
      borderColor: "#4C95EA",
      pointBackgroundColor: "#4C95EA",
      lines: speedBound,
    },
  };
};

const getIsInRange = (val: number) => {
  return min - kErrorTolerance <= val && val <= max + kErrorTolerance;
};

function getSTRolloutPoints(rollout: STRollout) {
  const stRolloutPoints: Messages.ares__CustomizationPlotPoint[] = [];
  forEach(rollout?.stCurve, (stCurve) => {
    const timeResolutionS =
      (stCurve.xMax - stCurve.xMin) / kSTSegmentSampledPointNumber;
    for (let i = 0; i <= kSTSegmentSampledPointNumber; ++i) {
      const t = Math.min(stCurve.xMax, stCurve.xMin + i * timeResolutionS);

      if (getIsInRange(t)) {
        const s =
          stCurve.a * Math.pow(t, 3) +
          stCurve.b * Math.pow(t, 2) +
          stCurve.c * t +
          stCurve.d;
        stRolloutPoints.push({
          x: t,
          y: s,
        });
      }
    }
  });
  return stRolloutPoints;
}

function displaySTRolloutDecisionPlot(
  debug: Messages.planner__pb__SamplingBasedSpeedDeciderDebug,
  globalVars: GlobalVariables,
  selectedRolloutIndex: number,
): {
  stRollouts: Messages.ares__CustomizationPlotLine[];
  speedSearchStRollouts: Messages.ares__CustomizationPlotLine[];
  minCostStRollouts: Messages.ares__CustomizationPlotLine[];
  highlightStRollouts: Messages.ares__CustomizationPlotLine[];
  softStRegion: Messages.ares__CustomizationPlotLine[];
  hardStRegion: Messages.ares__CustomizationPlotLine[];
  softLtRegion: Messages.ares__CustomizationPlotLine[];
  hardLtRegion: Messages.ares__CustomizationPlotLine[];
  reasoningStRegion: Messages.ares__CustomizationPlotLine[];
} {
  const highlightIdx: number = (globalVars.planning_rollout_id as number) ?? -1;
  const stRollouts: Messages.ares__CustomizationPlotLine[] = [];
  debug?.stRolloutDecisions
    .filter((rollout, index) => {
      return !rollout?.stRollout.isFromSpeedSearch && index !== highlightIdx;
    })
    .forEach((stRolloutDecision) => {
      const stRollout = getSTRolloutPoints(
        stRolloutDecision?.stRollout as STRollout,
      );
      stRollouts.push({
        line: stRollout,
      });
    });
  const speedSearchStRollouts: Messages.ares__CustomizationPlotLine[] = [];
  debug?.stRolloutDecisions
    .filter((rollout, index) => {
      return rollout?.stRollout.isFromSpeedSearch && index !== highlightIdx;
    })
    .forEach((stRolloutDecision) => {
      const stRollout = getSTRolloutPoints(
        stRolloutDecision?.stRollout as STRollout,
      );
      speedSearchStRollouts.push({
        line: stRollout,
      });
    });
  const highlightStRollouts: Messages.ares__CustomizationPlotLine[] = [];
  debug?.stRolloutDecisions
    .filter((_, index) => {
      return index === highlightIdx;
    })
    .forEach((stRolloutDecision) => {
      const stRollout = getSTRolloutPoints(
        stRolloutDecision?.stRollout as STRollout,
      );
      highlightStRollouts.push({
        line: stRollout,
      });
    });
  const minCostStRollout = getSTRolloutPoints(
    debug?.stRolloutDecisions?.[selectedRolloutIndex]?.stRollout as STRollout,
  );

  const softStRegion: Messages.ares__CustomizationPlotLine[] = [];
  debug?.agentStRegions?.forEach((agentStRegion) => {
    if (
      (!globalVars.tracked_object_selections ||
        globalVars.tracked_object_selections.length === 0 ||
        globalVars.tracked_object_selections.includes(
          `${agentStRegion?.id?.objectId}`,
        )) &&
      agentStRegion.blockingState !== "HARD_BLOCKING"
    ) {
      getStRegion(
        agentStRegion?.stRegions ?? [],
        agentStRegion?.id,
        softStRegion,
        agentStRegion.blockingState,
      );
    }
  });

  const hardStRegion: Messages.ares__CustomizationPlotLine[] = [];
  debug?.agentStRegions?.forEach((agentStRegion) => {
    if (
      (!globalVars.tracked_object_selections ||
        globalVars.tracked_object_selections.length === 0 ||
        globalVars.tracked_object_selections.includes(
          `${agentStRegion?.id?.objectId}`,
        )) &&
      agentStRegion.blockingState === "HARD_BLOCKING"
    ) {
      getStRegion(
        agentStRegion?.stRegions ?? [],
        agentStRegion?.id,
        hardStRegion,
        agentStRegion.blockingState,
      );
    }
  });

  // Soft lateral regions (L-T plot)
  const softLtRegion: Messages.ares__CustomizationPlotLine[] = [];
  debug?.agentStRegions?.forEach((agentStRegion) => {
    if (
      (!globalVars.tracked_object_selections ||
        globalVars.tracked_object_selections.length === 0 ||
        globalVars.tracked_object_selections.includes(
          `${agentStRegion?.id?.objectId}`,
        )) &&
      agentStRegion.blockingState !== "HARD_BLOCKING"
    ) {
      getStRegion(
        (agentStRegion?.lateralStRegions as any) ?? [],
        agentStRegion?.id,
        softLtRegion,
        agentStRegion.blockingState,
      );
    }
  });

  // Hard lateral regions (L-T plot)
  const hardLtRegion: Messages.ares__CustomizationPlotLine[] = [];
  debug?.agentStRegions?.forEach((agentStRegion) => {
    if (
      (!globalVars.tracked_object_selections ||
        globalVars.tracked_object_selections.length === 0 ||
        globalVars.tracked_object_selections.includes(
          `${agentStRegion?.id?.objectId}`,
        )) &&
      agentStRegion.blockingState === "HARD_BLOCKING"
    ) {
      getStRegion(
        agentStRegion?.lateralStRegions ?? [],
        agentStRegion?.id,
        hardLtRegion,
        agentStRegion.blockingState,
      );
    }
  });

  const reasoningStRegionData: Messages.ares__CustomizationPlotLine[] = [];
  forEach(debug?.reasoningStRegions ?? [], (reasoningStRegion) => {
    getReasoningStRegion(reasoningStRegion, reasoningStRegionData);
  });

  return {
    stRollouts,
    speedSearchStRollouts,
    minCostStRollouts: [
      {
        line: minCostStRollout,
      },
    ],
    highlightStRollouts,
    softStRegion,
    hardStRegion,
    softLtRegion,
    hardLtRegion,
    reasoningStRegion: reasoningStRegionData,
  };
}

// 四个点连成四边形
function getIntervalSampleWithSTRegion(
  stRegion: STRegion,
): Messages.ares__CustomizationPlotPoint[] {
  return [
    {
      x: stRegion.startingSpatialRange.time,
      y: stRegion.startingSpatialRange.start,
    },
    {
      x: stRegion.startingSpatialRange.time,
      y: stRegion.startingSpatialRange.end,
    },
    {
      x: stRegion.endingSpatialRange.time,
      y: stRegion.endingSpatialRange.end,
    },
    {
      x: stRegion.endingSpatialRange.time,
      y: stRegion.endingSpatialRange.start,
    },
    {
      x: stRegion.startingSpatialRange.time,
      y: stRegion.startingSpatialRange.start,
    },
  ];
}

function getSTRegionTextPosition(
  startingSpatialRange: Messages.planner__pb__SpatialRange,
  endingSpatialRange: Messages.planner__pb__SpatialRange,
) {
  const x = getHalfValue(startingSpatialRange?.time, endingSpatialRange?.time);
  const y = getHalfValue(
    getHalfValue(startingSpatialRange?.start, startingSpatialRange?.end),
    getHalfValue(endingSpatialRange?.start, endingSpatialRange?.end),
  );
  return { x, y };
}

function getReasoningStRegion(
  reasoningStRegion: Messages.planner__pb__ReasoningSTRegion,
  reasoningStRegionResult: Messages.ares__CustomizationPlotLine[] = [],
) {
  const res = getIntervalSampleWithSTRegion(
    reasoningStRegion?.stRegion as STRegion,
  );
  reasoningStRegionResult.push({
    line: res,
  });

  const { startingSpatialRange, endingSpatialRange } =
    reasoningStRegion?.stRegion as STRegion;

  const { x, y } = getSTRegionTextPosition(
    startingSpatialRange as any,
    endingSpatialRange as any,
  );

  reasoningStRegionResult.push({
    line: [
      {
        x,
        y,
        label: reasoningStRegion.regionName,
        labelColor:
          reasoningStRegion.blockingState === "HARD_BLOCKING" ? "red" : "white",
      },
    ],
  });
}

function getStRegion(
  stRegions: STRegion[],
  id: Id,
  stRegionResult: Messages.ares__CustomizationPlotLine[] = [],
  blockingState: string,
) {
  filter(
    stRegions,
    (stRegion) =>
      !isNil(stRegion.startingSpatialRange) &&
      !isNil(stRegion.endingSpatialRange),
  ).forEach((stRegion, index) => {
    const res = getIntervalSampleWithSTRegion(stRegion);
    if (index === 0) {
      const startingSpatialRange = stRegion.startingSpatialRange;
      const endingSpatialRange =
        stRegions[stRegions.length - 1]?.endingSpatialRange;
      const { x, y } = getSTRegionTextPosition(
        startingSpatialRange as any,
        endingSpatialRange as Messages.planner__pb__SpatialRange,
      );
      stRegionResult.push({
        line: [
          {
            x,
            y,
            label: `obj_id:${id.objectId},traj_id:${id.trajectoryId} `,
            labelColor: blockingState === "HARD_BLOCKING" ? "#C19A6B" : "white",
          },
        ],
      });
    }
    stRegionResult.push({
      line: res,
    });
  });
}

function getHalfValue(a: number, b: number) {
  return 0.5 * (a + b);
}

function getSpeedProfilePoints(states: Messages.speed__pb__State[] = []) {
  return states.map((state) => ({
    x: state.t,
    y: state.x,
  }));
}

type SpeedPbProfile = {
  states: Messages.speed__pb__State[];
};

function getSpeedBound(
  speedLowerBound: SpeedPbProfile,
  speedUpperBound: SpeedPbProfile,
): Messages.ares__CustomizationPlotLine[] {
  const lowerBound = getSpeedProfilePoints(speedLowerBound.states);
  const upperBound = getSpeedProfilePoints(speedUpperBound.states);

  return [
    {
      line: lowerBound,
    },
    {
      line: [{ x: NaN, y: NaN }],
    },
    {
      line: upperBound,
    },
  ];
}

