import {
  GlobalVariables,
  ScriptConfig,
  DEFAULT_STUDIO_NODE_PREFIX,
} from "@ares-utils";
import { Input, Messages } from "ros";

export const inputs = [
  "/planning/planning_debug",
  "/planning/open_space_search_debug",
];
export const output = `${DEFAULT_STUDIO_NODE_PREFIX}planning/open_space/open_space_search_info`;
export const config = {
