      open_space_search_debug?.message?.candidateSearchDebugs.find(
        (candidate) => {
          return (
            candidate?.targetPoseIndex ==
            (globalVars.open_space_target_pose_index as number)
          );
        },
      );
    open_space_debug_info.resultDebug =
      open_space_search_debug?.message?.candidateResultDebugs.find(
        (candidate) => {
          return (
            candidate.targetPoseIndex == globalVars.open_space_target_pose_index
          );
        },
      );
  }

  globalVars.open_space_search_info = open_space_debug_info;
  const example_cost_debug = open_space_debug_info?.searchDebug?.nodeDebug.find(
    (node) => {
