    },
  )?.costingInfo;
  const cost_type =
    example_cost_debug !== null && example_cost_debug !== undefined
      ? Object.keys(example_cost_debug)
      : undefined;

  return {
    cost_type: cost_type,
    data: open_space_debug_info,
    best_target_pose_index: best_target_pose_index,
  };
};

